CREATE OR REPLACE FUNCTION private.assert_collection_read_scope(p_cell_id uuid DEFAULT NULL::uuid, p_cell_name text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
declare
  v_profile_role text;
  v_profile_cell text;
  v_managed_cells text[];
  v_cell_from_id text;
  v_cell_from_name text;
  v_requested_cell text;
begin
  if auth.role() = 'service_role' then
    return;
  end if;

  if auth.uid() is null
     or not (
       public.has_permission('view_collection')
       or public.has_permission('register_production')
       or public.has_permission('view_traceability')
       or public.has_permission('view_dashboards')
     ) then
    raise exception 'COLLECTION_VIEW_PERMISSION_REQUIRED' using errcode = '42501';
  end if;

  select role, cell, coalesce(managed_cells, '{}'::text[])
    into v_profile_role, v_profile_cell, v_managed_cells
  from public.profiles
  where id = auth.uid()
    and active is true;

  if not found then
    raise exception 'ACTIVE_PROFILE_REQUIRED' using errcode = '42501';
  end if;

  if p_cell_id is not null then
    select name into v_cell_from_id
    from public.cells
    where id = p_cell_id;

    if not found then
      raise exception 'COLLECTION_CELL_NOT_FOUND' using errcode = '22023';
    end if;
  end if;

  if nullif(btrim(p_cell_name), '') is not null then
    select name into v_cell_from_name
    from public.cells
    where lower(btrim(name)) = lower(btrim(p_cell_name))
    order by active desc, name
    limit 1;

    if not found then
      raise exception 'COLLECTION_CELL_NOT_FOUND' using errcode = '22023';
    end if;
  end if;

  if v_cell_from_id is not null
     and v_cell_from_name is not null
     and lower(btrim(v_cell_from_id)) <> lower(btrim(v_cell_from_name)) then
    raise exception 'COLLECTION_CELL_FILTER_MISMATCH' using errcode = '22023';
  end if;

  v_requested_cell := coalesce(v_cell_from_id, v_cell_from_name);

  if v_requested_cell is not null then
    if not public.profile_can_access_cell(v_requested_cell) then
      raise exception 'COLLECTION_OUTSIDE_CELL_SCOPE' using errcode = '42501';
    end if;
    return;
  end if;

  -- Admins e perfis gerenciais sem escopo explícito podem consultar a visão
  -- global. Operadores e qualquer perfil já limitado a células devem filtrar.
  if v_profile_role = 'admin' then
    return;
  end if;

  if v_profile_role = 'operator'
     or array_length(v_managed_cells, 1) is not null
     or nullif(btrim(v_profile_cell), '') is not null then
    raise exception 'COLLECTION_CELL_SCOPE_REQUIRED' using errcode = '42501';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION private.enqueue_collection_projection_v3(p_client_event_id text, p_reading_id uuid, p_piece_id uuid, p_lot_id uuid, p_cell_id uuid, p_machine_id uuid, p_operator_id uuid, p_shift_snapshot text, p_step_code text, p_decision text, p_quantity integer, p_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pgmq', 'pg_temp'
AS $function$
DECLARE
  v_outbox_id uuid;
  v_message_id bigint;
  v_existing_message_id bigint;
BEGIN
  INSERT INTO public.collection_projection_outbox (
    client_event_id, projection_revision, projection_kind, previous_decision,
    reading_id, piece_id, lot_id, cell_id, machine_id,
    operator_id, shift_snapshot, step_code, decision, quantity, payload
  ) VALUES (
    p_client_event_id, 0, 'decision', NULL,
    p_reading_id, p_piece_id, p_lot_id, p_cell_id, p_machine_id,
    p_operator_id, p_shift_snapshot, p_step_code, p_decision,
    greatest(coalesce(p_quantity, 1), 1), coalesce(p_payload, '{}'::jsonb)
  )
  ON CONFLICT (client_event_id, projection_revision) DO UPDATE
  SET client_event_id = excluded.client_event_id
  RETURNING id, queue_message_id
  INTO v_outbox_id, v_existing_message_id;

  IF v_existing_message_id IS NOT NULL THEN
    RETURN v_outbox_id;
  END IF;

  SELECT pgmq.send(
    'collection_projection_v3',
    jsonb_build_object(
      'outbox_id', v_outbox_id,
      'client_event_id', p_client_event_id,
      'pipeline_version', 3
    )
  ) INTO v_message_id;

  UPDATE public.collection_projection_outbox
  SET queue_message_id = coalesce(queue_message_id, v_message_id)
  WHERE id = v_outbox_id;

  RETURN v_outbox_id;
END;
$function$

CREATE OR REPLACE FUNCTION private.process_collection_batch_v3(p_worker_id text, p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'extensions', 'pgmq', 'realtime', 'pg_temp'
AS $function$
DECLARE
  v_worker_id text := left(coalesce(nullif(btrim(p_worker_id), ''), ''), 160);
  v_item record;
  v_piece public.production_pieces%ROWTYPE;
  v_lot public.production_lots%ROWTYPE;
  v_order public.production_orders%ROWTYPE;
  v_existing_event public.production_collection_events%ROWTYPE;
  v_existing_reading public.production_stage_readings%ROWTYPE;
  v_validation jsonb;
  v_result jsonb;
  v_results jsonb := '[]'::jsonb;
  v_decision text;
  v_reason_code text;
  v_message text;
  v_step_code text;
  v_reading_id uuid;
  v_outbox_id uuid;
  v_finished_at timestamptz;
  v_started_at timestamptz;
  v_next_step text;
  v_completed_steps text[];
  v_found_current boolean;
  v_broadcast_enabled boolean := false;
  v_retryable boolean;
  v_backoff_ms integer;
  v_sqlstate text;
  v_error_message text;
  v_error_context text;
  v_dead_letter_message_id bigint;
  v_finalized_count integer := 0;
  v_input_count integer;
  v_lock_timeout_ms integer := 500;
  v_statement_timeout_ms integer := 5000;
  v_lock_started_at timestamptz;
  v_lock_wait_ms numeric(14,3) := 0;
  i integer;
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION 'SERVICE_ROLE_REQUIRED'
      USING ERRCODE = '42501';
  END IF;

  IF v_worker_id = '' THEN
    RAISE EXCEPTION 'COLLECTION_WORKER_ID_REQUIRED'
      USING ERRCODE = '22023';
  END IF;

  IF jsonb_typeof(p_items) <> 'array' THEN
    RAISE EXCEPTION 'COLLECTION_BATCH_ITEMS_INVALID'
      USING ERRCODE = '22023';
  END IF;

  v_input_count := jsonb_array_length(p_items);
  IF v_input_count < 1 OR v_input_count > 25 THEN
    RAISE EXCEPTION 'COLLECTION_PROCESSING_BATCH_SIZE_INVALID'
      USING ERRCODE = '22023';
  END IF;

  SELECT
    greatest(100, least(coalesce(
      private.try_collection_bigint_v3(flag.rollout_scope ->> 'lock_timeout_ms'), 500
    ), 2000))::integer,
    greatest(1000, least(coalesce(
      private.try_collection_bigint_v3(flag.rollout_scope ->> 'statement_timeout_ms'), 5000
    ), 15000))::integer
  INTO v_lock_timeout_ms, v_statement_timeout_ms
  FROM private.collection_pipeline_flags flag
  WHERE flag.flag_name = 'collection_pipeline_v3_worker'
    AND flag.enabled IS TRUE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'COLLECTION_PIPELINE_V3_WORKER_DISABLED'
      USING ERRCODE = '55000';
  END IF;

  PERFORM set_config('lock_timeout', v_lock_timeout_ms::text || 'ms', true);
  PERFORM set_config('statement_timeout', v_statement_timeout_ms::text || 'ms', true);

  SELECT coalesce(flag.enabled, false)
  INTO v_broadcast_enabled
  FROM private.collection_pipeline_flags flag
  WHERE flag.flag_name = 'collection_pipeline_v3_broadcast';

  -- Toda resolução de recibo, peça, lote, pedido e etapa ocorre antes da
  -- primeira escrita do mini-lote. O lock posterior relê somente a peça.
  CREATE TEMP TABLE pg_temp.collection_v3_decision_input
  ON COMMIT DROP
  AS
  WITH messages AS (
    SELECT
      item.ordinality::integer AS ordinal,
      item.value ->> 'queue_name' AS queue_name,
      private.try_collection_bigint_v3(item.value ->> 'msg_id') AS msg_id,
      greatest(1, coalesce(private.try_collection_bigint_v3(item.value ->> 'read_ct'), 1))::integer AS read_ct,
      private.try_collection_timestamptz_v3(item.value ->> 'enqueued_at') AS queue_enqueued_at,
      private.try_collection_uuid_v3(item.value -> 'message' ->> 'receipt_id') AS receipt_id_from_message,
      item.value -> 'message' ->> 'client_event_id' AS client_event_id_from_message
    FROM jsonb_array_elements(p_items) WITH ORDINALITY item(value, ordinality)
  )
  SELECT
    messages.*,
    receipt.id AS receipt_id,
    receipt.client_event_id,
    receipt.tag_lida AS raw_value,
    receipt.reader_type,
    receipt.timestamp_leitura AS captured_at_client,
    receipt.received_at_db,
    receipt.device_id,
    receipt.operator_session_id,
    receipt.operator_id,
    receipt.cell_id,
    cell.name AS cell_name,
    receipt.machine_id,
    machine.name AS machine_name,
    session.shift_snapshot,
    receipt.source_mode,
    greatest(1, least(coalesce(
      private.try_collection_bigint_v3(receipt.payload ->> 'quantity'), 1
    ), 100))::integer AS quantity,
    resolution.match_count,
    resolution.piece_id,
    piece.lot_id,
    coalesce(piece.production_order_id, lot.production_order_id, lot.order_id) AS production_order_id,
    public.resolve_production_stage_for_cell(receipt.cell_id, cell.name) AS step_code,
    operator_row.name AS operator_name,
    piece.pcp_import_batch_id,
    piece.current_stage AS prelock_current_stage,
    piece.route_steps AS prelock_route_steps,
    piece.completed_steps AS prelock_completed_steps,
    lot.lot_code,
    coalesce(production_order.order_number, production_order.order_code) AS order_number,
    production_order.load_number,
    production_order.customer_name
  FROM messages
  LEFT JOIN public.coletas_producao receipt
    ON receipt.id = messages.receipt_id_from_message
   AND receipt.client_event_id = messages.client_event_id_from_message
   AND receipt.pipeline_version = 3
  LEFT JOIN public.cells cell ON cell.id = receipt.cell_id
  LEFT JOIN public.production_machines machine ON machine.id = receipt.machine_id
  LEFT JOIN public.operator_sessions session ON session.id = receipt.operator_session_id
  LEFT JOIN public.operators operator_row ON operator_row.id = receipt.operator_id
  LEFT JOIN LATERAL (
    SELECT
      count(*)::integer AS match_count,
      (array_agg(candidate.id ORDER BY candidate.id))[1] AS piece_id
    FROM (
      SELECT direct_piece.id
      FROM public.production_pieces direct_piece
      WHERE upper(direct_piece.piece_uid) = upper(receipt.tag_lida)
         OR upper(direct_piece.traceability_code) = upper(receipt.tag_lida)
      UNION
      SELECT tag.piece_id
      FROM public.production_tags tag
      WHERE tag.active IS TRUE
        AND tag.piece_id IS NOT NULL
        AND upper(tag.tag_value) = upper(receipt.tag_lida)
    ) candidate
  ) resolution ON true
  LEFT JOIN public.production_pieces piece ON piece.id = resolution.piece_id
  LEFT JOIN public.production_lots lot ON lot.id = piece.lot_id
  LEFT JOIN public.production_orders production_order
    ON production_order.id = coalesce(piece.production_order_id, lot.production_order_id, lot.order_id);

  FOR v_item IN
    SELECT *
    FROM pg_temp.collection_v3_decision_input
    ORDER BY piece_id NULLS LAST, client_event_id NULLS LAST, ordinal
  LOOP
    v_started_at := clock_timestamp();
    v_sqlstate := NULL;
    v_error_message := NULL;
    v_error_context := NULL;
    v_reading_id := NULL;
    v_outbox_id := NULL;
    v_decision := NULL;
    v_reason_code := NULL;
    v_message := NULL;
    v_step_code := NULL;
    v_validation := NULL;
    v_lock_started_at := NULL;
    v_lock_wait_ms := 0;
    v_existing_event := NULL;
    v_existing_reading := NULL;
    v_piece := NULL;
    v_lot := NULL;
    v_order := NULL;

    UPDATE public.collection_processing_attempts
    SET processing_started_at = v_started_at
    WHERE client_event_id = v_item.client_event_id
      AND attempt_number = v_item.read_ct
      AND processing_started_at IS NULL
      AND processing_finished_at IS NULL;

    BEGIN
      IF v_item.queue_name NOT IN ('collection_live_v3', 'collection_replay_v3')
         OR v_item.msg_id IS NULL THEN
        RAISE EXCEPTION 'COLLECTION_QUEUE_MESSAGE_INVALID'
          USING ERRCODE = '22023';
      END IF;

      IF v_item.receipt_id IS NULL THEN
        RAISE EXCEPTION 'COLLECTION_RECEIPT_NOT_FOUND'
          USING ERRCODE = 'P0002';
      END IF;

      IF v_item.client_event_id IS DISTINCT FROM v_item.client_event_id_from_message THEN
        RAISE EXCEPTION 'COLLECTION_QUEUE_RECEIPT_MISMATCH'
          USING ERRCODE = '22023';
      END IF;

      IF NOT EXISTS (
        SELECT 1
        FROM public.coletas_producao receipt
        WHERE receipt.id = v_item.receipt_id
          AND receipt.worker_id = v_worker_id
          AND receipt.status_sincronizacao = 'processando'
      ) THEN
        RAISE EXCEPTION 'COLLECTION_RECEIPT_LEASE_MISMATCH'
          USING ERRCODE = '55P03';
      END IF;

      UPDATE public.coletas_producao
      SET processing_started_at = v_started_at,
          updated_at = v_started_at
      WHERE id = v_item.receipt_id;

      SELECT event.*
      INTO v_existing_event
      FROM public.production_collection_events event
      WHERE event.client_event_id = v_item.client_event_id
        AND event.pipeline_version = 3;

      IF v_existing_event.id IS NOT NULL
         AND v_existing_event.result_status IN (
           'approved', 'rejected', 'blocked', 'duplicated', 'pending_review'
         ) THEN
        v_finished_at := clock_timestamp();
        v_result := coalesce(v_existing_event.result_payload, '{}'::jsonb)
          || jsonb_build_object(
            'client_event_id', v_item.client_event_id,
            'decision', v_existing_event.result_status,
            'reason_code', coalesce(v_existing_event.final_reason_code, 'IDEMPOTENT_REPLAY'),
            'reading_id', v_existing_event.reading_id,
            'piece_id', v_existing_event.piece_id,
            'lot_id', v_existing_event.lot_id,
            'step_code', v_existing_event.operation_name,
            'committed_at', v_existing_event.decision_committed_at,
            'idempotent_replay', true
          );

        UPDATE public.coletas_producao
        SET status_sincronizacao = 'sincronizada',
            resultado = v_result,
            erro = NULL,
            retryable = false,
            processado_em = coalesce(v_existing_event.decision_committed_at, v_finished_at),
            decision_committed_at = coalesce(v_existing_event.decision_committed_at, v_finished_at),
            processing_duration_ms = extract(epoch FROM (v_finished_at - v_started_at)) * 1000,
            lease_expires_at = NULL,
            worker_id = NULL,
            updated_at = v_finished_at
        WHERE id = v_item.receipt_id;

        PERFORM pgmq.archive(v_item.queue_name, v_item.msg_id);

        UPDATE public.collection_processing_attempts
        SET processing_finished_at = v_finished_at,
            processing_duration_ms = extract(epoch FROM (v_finished_at - v_started_at)) * 1000,
            reason_code = 'IDEMPOTENT_REPLAY',
            retryable = false,
            lock_wait_ms = v_lock_wait_ms
        WHERE client_event_id = v_item.client_event_id
          AND attempt_number = v_item.read_ct
          AND processing_finished_at IS NULL;

        v_results := v_results || jsonb_build_array(v_result);
        v_finalized_count := v_finalized_count + 1;
        CONTINUE;
      END IF;

      IF coalesce(v_item.match_count, 0) = 0 THEN
        v_decision := 'rejected';
        v_reason_code := 'PIECE_NOT_FOUND';
        v_message := 'Peça não localizada para o código informado.';
        v_step_code := v_item.step_code;
      ELSIF v_item.match_count > 1 THEN
        v_decision := 'pending_review';
        v_reason_code := 'PIECE_IDENTIFIER_AMBIGUOUS';
        v_message := 'O código corresponde a mais de uma peça e requer revisão.';
        v_step_code := v_item.step_code;
      ELSE
        -- Lock estritamente por peça e em ordem estável do mini-lote.
        v_lock_started_at := clock_timestamp();
        PERFORM pg_advisory_xact_lock(hashtextextended(v_item.piece_id::text, 0));
        v_lock_wait_ms := extract(
          epoch FROM (clock_timestamp() - v_lock_started_at)
        ) * 1000;

        SELECT piece.*
        INTO v_piece
        FROM public.production_pieces piece
        WHERE piece.id = v_item.piece_id
        FOR UPDATE;

        IF v_piece.id IS NULL THEN
          RAISE EXCEPTION 'COLLECTION_PIECE_DISAPPEARED'
            USING ERRCODE = 'P0002';
        END IF;

        -- Rechecagem após o lock fecha a corrida de duas entregas idênticas.
        SELECT event.*
        INTO v_existing_event
        FROM public.production_collection_events event
        WHERE event.client_event_id = v_item.client_event_id
          AND event.pipeline_version = 3;

        IF v_existing_event.id IS NOT NULL THEN
          v_finished_at := clock_timestamp();
          v_result := coalesce(v_existing_event.result_payload, '{}'::jsonb)
            || jsonb_build_object('idempotent_replay', true);

          UPDATE public.coletas_producao
          SET status_sincronizacao = 'sincronizada',
              resultado = v_result,
              retryable = false,
              processado_em = coalesce(v_existing_event.decision_committed_at, v_finished_at),
              decision_committed_at = coalesce(v_existing_event.decision_committed_at, v_finished_at),
              lease_expires_at = NULL,
              worker_id = NULL,
              updated_at = v_finished_at
          WHERE id = v_item.receipt_id;

          PERFORM pgmq.archive(v_item.queue_name, v_item.msg_id);
          UPDATE public.collection_processing_attempts
          SET processing_finished_at = v_finished_at,
              processing_duration_ms = extract(epoch FROM (v_finished_at - v_started_at)) * 1000,
              reason_code = 'IDEMPOTENT_REPLAY',
              retryable = false,
              lock_wait_ms = v_lock_wait_ms
          WHERE client_event_id = v_item.client_event_id
            AND attempt_number = v_item.read_ct
            AND processing_finished_at IS NULL;
          v_results := v_results || jsonb_build_array(v_result);
          v_finalized_count := v_finalized_count + 1;
          CONTINUE;
        END IF;

        SELECT lot.* INTO v_lot
        FROM public.production_lots lot
        WHERE lot.id = v_piece.lot_id;

        SELECT production_order.* INTO v_order
        FROM public.production_orders production_order
        WHERE production_order.id = coalesce(
          v_piece.production_order_id,
          v_lot.production_order_id,
          v_lot.order_id
        );

        v_step_code := public.resolve_production_stage_for_cell(v_item.cell_id, v_item.cell_name);
        IF v_step_code IS NULL THEN
          v_decision := 'blocked';
          v_reason_code := 'TARGET_STEP_UNRESOLVED';
          v_message := 'A célula autenticada não possui etapa produtiva resolvida.';
        ELSE
          v_validation := public.validar_fluxo_da_peca(v_piece.id, v_step_code);

          IF coalesce((v_validation ->> 'success')::boolean, false)
             AND coalesce(v_validation ->> 'status', 'approved') <> 'duplicated' THEN
            SELECT reading.*
            INTO v_existing_reading
            FROM public.production_stage_readings reading
            WHERE reading.piece_id = v_piece.id
              AND reading.step_name = v_step_code
              AND reading.production_cycle = 1
              AND reading.status = 'approved'
            ORDER BY reading.created_at, reading.id
            LIMIT 1;

            IF v_existing_reading.id IS NOT NULL THEN
              v_decision := 'duplicated';
              v_reason_code := 'PIECE_STAGE_ALREADY_APPROVED';
              v_message := 'Peça já aprovada nesta etapa; nenhum efeito produtivo foi duplicado.';
            ELSE
              v_decision := 'approved';
              v_reason_code := 'APPROVED';
              v_message := coalesce(v_validation ->> 'message', 'Peça aprovada para a etapa.');
            END IF;
          ELSIF v_validation ->> 'status' = 'duplicated' THEN
            v_decision := 'duplicated';
            v_reason_code := 'PIECE_STAGE_ALREADY_APPROVED';
            v_message := coalesce(v_validation ->> 'message', 'Peça já aprovada nesta etapa.');
          ELSE
            v_decision := 'blocked';
            v_reason_code := 'PRODUCTION_FLOW_BLOCKED';
            v_message := coalesce(v_validation ->> 'message', 'Fluxo produtivo bloqueado.');
          END IF;
        END IF;
      END IF;

      IF v_piece.id IS NOT NULL AND v_piece.lot_id IS NOT NULL THEN
        INSERT INTO public.production_stage_readings (
          client_event_id, tag_value, tag_type, reader_type, station_name, cell_name,
          operator, shift, date, hour, item_id, piece_id, lot_id, production_order_id,
          step_name, quantity, status, event_type, operator_id, machine_id, machine_name,
          lot_code, load_number, order_number, customer_name, environment_name,
          operation_name, piece_code, production_cycle, pipeline_version
        ) VALUES (
          v_item.client_event_id, v_piece.piece_uid,
          CASE WHEN v_item.reader_type = 'manual' THEN 'manual' ELSE 'barcode' END,
          v_item.reader_type, v_item.machine_name, v_item.cell_name,
          v_item.operator_name, v_item.shift_snapshot,
          v_item.captured_at_client::date,
          to_char(v_item.captured_at_client, 'HH24:MI'),
          v_piece.legacy_production_lot_item_id, v_piece.id, v_piece.lot_id,
          v_piece.production_order_id, v_step_code, v_item.quantity,
          v_decision,
          CASE v_decision
            WHEN 'approved' THEN 'approved_scan'
            WHEN 'duplicated' THEN 'duplicated_scan'
            ELSE 'wrong_step'
          END,
          v_item.operator_id, v_item.machine_id, v_item.machine_name,
          v_lot.lot_code, v_order.load_number,
          coalesce(v_order.order_number, v_order.order_code), v_order.customer_name,
          v_piece.environment, v_step_code, v_piece.traceability_code, 1, 3
        )
        RETURNING id INTO v_reading_id;
      END IF;

      IF v_decision = 'approved' THEN
        v_completed_steps := coalesce(v_piece.completed_steps, '{}'::text[]);
        IF NOT (v_step_code = ANY(v_completed_steps)) THEN
          v_completed_steps := array_append(v_completed_steps, v_step_code);
        END IF;

        v_next_step := NULL;
        v_found_current := false;
        IF array_length(v_piece.route_steps, 1) IS NOT NULL THEN
          FOR i IN 1..array_length(v_piece.route_steps, 1) LOOP
            IF v_found_current THEN
              v_next_step := v_piece.route_steps[i];
              EXIT;
            END IF;
            IF lower(v_piece.route_steps[i]) = lower(v_step_code) THEN
              v_found_current := true;
            END IF;
          END LOOP;
        END IF;

        UPDATE public.production_pieces
        SET completed_steps = v_completed_steps,
            current_stage = coalesce(v_next_step, 'Concluída'),
            status = CASE WHEN v_next_step IS NULL THEN 'completed' ELSE 'in_progress' END,
            updated_at = clock_timestamp()
        WHERE id = v_piece.id;
      END IF;

      v_finished_at := clock_timestamp();
      v_result := jsonb_strip_nulls(jsonb_build_object(
        'success', v_decision = 'approved',
        'client_event_id', v_item.client_event_id,
        'decision', v_decision,
        'status', v_decision,
        'reason_code', v_reason_code,
        'message', v_message,
        'reading_id', v_reading_id,
        'piece_id', v_piece.id,
        'lot_id', v_piece.lot_id,
        'step_code', v_step_code,
        'committed_at', v_finished_at
      ));

      INSERT INTO public.production_collection_events (
        client_event_id, raw_value, normalized_value, reader_type,
        operator_id, operator_name, cell_name, shift, date, hour,
        status, result_status, reading_id, lot_id, production_order_id,
        error_message, payload, created_at_client, processed_at,
        machine_id, machine_name, piece_id, device_id, pcp_import_batch_id,
        result_payload, attempt_count, last_attempt_at, operator_session_id,
        cell_id, shift_snapshot, server_received_at, pipeline_version,
        decision_committed_at, final_reason_code, operation_name
      ) VALUES (
        v_item.client_event_id, v_item.raw_value, v_item.raw_value, v_item.reader_type,
        v_item.operator_id, v_item.operator_name, v_item.cell_name, v_item.shift_snapshot,
        v_item.captured_at_client::date, to_char(v_item.captured_at_client, 'HH24:MI'),
        CASE WHEN v_decision = 'approved' THEN 'synced' ELSE 'ignored' END,
        v_decision, v_reading_id, v_piece.lot_id, v_piece.production_order_id,
        CASE WHEN v_decision = 'approved' THEN NULL ELSE v_message END,
        '{}'::jsonb, v_item.captured_at_client, v_finished_at,
        v_item.machine_id, v_item.machine_name, v_piece.id, v_item.device_id,
        v_piece.pcp_import_batch_id, v_result, v_item.read_ct, v_finished_at,
        v_item.operator_session_id, v_item.cell_id, v_item.shift_snapshot,
        v_item.received_at_db, 3, v_finished_at, v_reason_code, v_step_code
      )
      ON CONFLICT (client_event_id) DO NOTHING;

      v_outbox_id := private.enqueue_collection_projection_v3(
        v_item.client_event_id,
        v_reading_id,
        v_piece.id,
        v_piece.lot_id,
        v_item.cell_id,
        v_item.machine_id,
        v_item.operator_id,
        v_item.shift_snapshot,
        v_step_code,
        v_decision,
        v_item.quantity,
        jsonb_strip_nulls(jsonb_build_object(
          'device_id', v_item.device_id,
          'source_mode', v_item.source_mode,
          'reason_code', v_reason_code,
          'committed_at', v_finished_at
        ))
      );

      UPDATE public.coletas_producao
      SET status_sincronizacao = 'sincronizada',
          resultado = v_result,
          erro = NULL,
          retryable = false,
          final_reason_code = v_reason_code,
          processado_em = v_finished_at,
          decision_committed_at = v_finished_at,
          processing_duration_ms = extract(epoch FROM (v_finished_at - v_started_at)) * 1000,
          lease_expires_at = NULL,
          worker_id = NULL,
          last_error_code = NULL,
          last_error_at = NULL,
          updated_at = v_finished_at
      WHERE id = v_item.receipt_id;

      PERFORM pgmq.archive(v_item.queue_name, v_item.msg_id);

      UPDATE public.collection_processing_attempts
      SET processing_finished_at = v_finished_at,
          processing_duration_ms = extract(epoch FROM (v_finished_at - v_started_at)) * 1000,
          reason_code = v_reason_code,
          retryable = false,
          lock_wait_ms = v_lock_wait_ms
      WHERE client_event_id = v_item.client_event_id
        AND attempt_number = v_item.read_ct
        AND processing_finished_at IS NULL;

      IF v_broadcast_enabled
         AND to_regprocedure('realtime.send(jsonb,text,text,boolean)') IS NOT NULL THEN
        PERFORM realtime.send(
          jsonb_build_object(
            'client_event_id', v_item.client_event_id,
            'state', upper(v_decision),
            'decision', v_decision,
            'reason_code', v_reason_code,
            'reading_id', v_reading_id,
            'committed_at', v_finished_at
          ),
          'collection.finalized',
          'collection:device:' || v_item.device_id,
          true
        );

        PERFORM realtime.send(
          jsonb_build_object(
            'client_event_id', v_item.client_event_id,
            'state', upper(v_decision),
            'decision', v_decision,
            'reason_code', v_reason_code,
            'reading_id', v_reading_id,
            'committed_at', v_finished_at
          ),
          'collection.finalized',
          'collection:event:' || v_item.client_event_id,
          true
        );

        UPDATE public.coletas_producao
        SET broadcasted_at = v_finished_at,
            updated_at = v_finished_at
        WHERE id = v_item.receipt_id;
      END IF;

      v_results := v_results || jsonb_build_array(v_result);
      v_finalized_count := v_finalized_count + 1;

    EXCEPTION WHEN OTHERS THEN
      GET STACKED DIAGNOSTICS
        v_sqlstate = RETURNED_SQLSTATE,
        v_error_message = MESSAGE_TEXT,
        v_error_context = PG_EXCEPTION_CONTEXT;

      v_finished_at := clock_timestamp();
      IF v_lock_started_at IS NOT NULL AND v_lock_wait_ms = 0 THEN
        v_lock_wait_ms := extract(
          epoch FROM (v_finished_at - v_lock_started_at)
        ) * 1000;
      END IF;
      v_retryable := private.collection_v3_is_retryable_sqlstate(v_sqlstate);

      IF v_retryable AND coalesce(v_item.read_ct, 1) < 5 THEN
        v_backoff_ms := private.collection_v3_backoff_ms(
          coalesce(v_item.client_event_id, v_item.client_event_id_from_message),
          v_item.read_ct
        );

        PERFORM pgmq.set_vt(
          v_item.queue_name,
          v_item.msg_id,
          greatest(1, ceil(v_backoff_ms / 1000.0)::integer)
        );

        UPDATE public.coletas_producao
        SET status_sincronizacao = 'recebida',
            retryable = true,
            erro = left(v_error_message, 500),
            last_error_code = v_sqlstate,
            last_error_at = v_finished_at,
            next_attempt_at = v_finished_at + make_interval(secs => v_backoff_ms / 1000.0),
            lease_expires_at = NULL,
            worker_id = NULL,
            updated_at = v_finished_at
        WHERE id = v_item.receipt_id;

        UPDATE public.collection_processing_attempts
        SET processing_finished_at = v_finished_at,
            processing_duration_ms = extract(epoch FROM (v_finished_at - v_started_at)) * 1000,
            sqlstate = v_sqlstate,
            reason_code = 'RETRY_SCHEDULED',
            retryable = true,
            backoff_ms = v_backoff_ms,
            lock_wait_ms = v_lock_wait_ms,
            error_message = left(v_error_message, 500)
        WHERE client_event_id = v_item.client_event_id
          AND attempt_number = v_item.read_ct
          AND processing_finished_at IS NULL;

        v_result := jsonb_build_object(
          'client_event_id', coalesce(v_item.client_event_id, v_item.client_event_id_from_message),
          'decision', 'retrying',
          'reason_code', v_sqlstate,
          'message', 'Falha transitória; nova tentativa agendada.',
          'retry_in_ms', v_backoff_ms
        );
      ELSE
        SELECT pgmq.send(
          'collection_dead_letter_v3',
          jsonb_strip_nulls(jsonb_build_object(
            'kind', 'decision',
            'source_queue', v_item.queue_name,
            'source_message_id', v_item.msg_id,
            'receipt_id', v_item.receipt_id,
            'client_event_id', coalesce(v_item.client_event_id, v_item.client_event_id_from_message),
            'attempts', coalesce(v_item.read_ct, 1),
            'sqlstate', v_sqlstate,
            'reason_code', CASE WHEN v_retryable THEN 'RETRY_EXHAUSTED' ELSE 'PERMANENT_PROCESSING_ERROR' END,
            'failed_at', v_finished_at
          ))
        ) INTO v_dead_letter_message_id;

        PERFORM pgmq.archive(v_item.queue_name, v_item.msg_id);

        v_result := jsonb_build_object(
          'success', false,
          'client_event_id', coalesce(v_item.client_event_id, v_item.client_event_id_from_message),
          'decision', 'dead_lettered',
          'status', 'dead_lettered',
          'reason_code', CASE WHEN v_retryable THEN 'RETRY_EXHAUSTED' ELSE v_sqlstate END,
          'message', 'A leitura foi preservada para revisão operacional.',
          'committed_at', v_finished_at
        );

        UPDATE public.coletas_producao
        SET status_sincronizacao = 'erro',
            retryable = false,
            erro = left(v_error_message, 500),
            resultado = v_result,
            final_reason_code = CASE WHEN v_retryable THEN 'RETRY_EXHAUSTED' ELSE v_sqlstate END,
            last_error_code = v_sqlstate,
            last_error_at = v_finished_at,
            processado_em = v_finished_at,
            dead_lettered_at = v_finished_at,
            processing_duration_ms = extract(epoch FROM (v_finished_at - v_started_at)) * 1000,
            lease_expires_at = NULL,
            worker_id = NULL,
            updated_at = v_finished_at
        WHERE id = v_item.receipt_id;

        UPDATE public.collection_processing_attempts
        SET processing_finished_at = v_finished_at,
            processing_duration_ms = extract(epoch FROM (v_finished_at - v_started_at)) * 1000,
            sqlstate = v_sqlstate,
            reason_code = CASE WHEN v_retryable THEN 'RETRY_EXHAUSTED' ELSE 'PERMANENT_PROCESSING_ERROR' END,
            retryable = false,
            lock_wait_ms = v_lock_wait_ms,
            error_message = left(v_error_message, 500)
        WHERE client_event_id = v_item.client_event_id
          AND attempt_number = v_item.read_ct
          AND processing_finished_at IS NULL;

        IF v_broadcast_enabled
           AND v_item.device_id IS NOT NULL
           AND to_regprocedure('realtime.send(jsonb,text,text,boolean)') IS NOT NULL THEN
          PERFORM realtime.send(
            jsonb_build_object(
              'client_event_id', coalesce(v_item.client_event_id, v_item.client_event_id_from_message),
              'state', 'DEAD_LETTERED',
              'reason_code', CASE WHEN v_retryable THEN 'RETRY_EXHAUSTED' ELSE v_sqlstate END,
              'committed_at', v_finished_at
            ),
            'collection.dead_lettered',
            'collection:device:' || v_item.device_id,
            true
          );
        END IF;

        v_finalized_count := v_finalized_count + 1;
      END IF;

      v_results := v_results || jsonb_build_array(v_result);
    END;
  END LOOP;

  UPDATE private.collection_worker_heartbeats
  SET heartbeat_at = clock_timestamp(),
      finished_at = clock_timestamp(),
      finalized_count = v_finalized_count,
      last_error_code = NULL
  WHERE worker_id = v_worker_id;

  RETURN v_results;
END;
$function$

CREATE OR REPLACE FUNCTION private.restore_collection_v3_projection_triggers()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_registry private.collection_projection_trigger_registry%ROWTYPE;
  v_installed_name text;
  v_relation_sql text;
  v_restored_count integer := 0;
BEGIN
  -- Um rollback operacional nunca pode deixar workers v3 produzindo fatos ou
  -- projeções enquanto os triggers síncronos originais são restaurados.
  UPDATE private.collection_pipeline_flags
  SET enabled = false,
      updated_at = clock_timestamp()
  WHERE flag_name IN (
    'collection_pipeline_v3_worker',
    'collection_pipeline_v3_projection'
  );

  FOR v_registry IN
    SELECT registry.*
    FROM private.collection_projection_trigger_registry registry
    WHERE registry.relation_name = 'public.production_stage_readings'::regclass
      AND registry.guard_installed IS TRUE
    ORDER BY registry.trigger_name
    FOR UPDATE
  LOOP
    IF cardinality(v_registry.installed_trigger_names) = 0
       OR NOT (v_registry.trigger_name = ANY(v_registry.installed_trigger_names)) THEN
      RAISE EXCEPTION 'COLLECTION_V3_TRIGGER_REGISTRY_INVALID: %',
        v_registry.trigger_name;
    END IF;

    SELECT format('%I.%I', namespace.nspname, relation.relname)
    INTO v_relation_sql
    FROM pg_class relation
    JOIN pg_namespace namespace ON namespace.oid = relation.relnamespace
    WHERE relation.oid = v_registry.relation_name;

    IF v_relation_sql IS NULL THEN
      RAISE EXCEPTION 'COLLECTION_V3_TRIGGER_RELATION_MISSING: %',
        v_registry.relation_name::text;
    END IF;

    -- Somente nomes que esta migration registrou como instalados podem ser
    -- removidos. O registry e os dados produtivos nunca são apagados.
    FOREACH v_installed_name IN ARRAY v_registry.installed_trigger_names
    LOOP
      EXECUTE format(
        'DROP TRIGGER IF EXISTS %I ON %s',
        v_installed_name,
        v_relation_sql
      );
    END LOOP;

    EXECUTE v_registry.original_definition;

    UPDATE private.collection_projection_trigger_registry registry
    SET installed_trigger_names = '{}'::text[],
        guard_installed = false,
        restored_at = clock_timestamp()
    WHERE registry.trigger_name = v_registry.trigger_name;

    v_restored_count := v_restored_count + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'restored', true,
    'restored_trigger_count', v_restored_count,
    'worker_enabled', false,
    'projection_enabled', false,
    'restored_at', clock_timestamp()
  );
END;
$function$

CREATE OR REPLACE FUNCTION private.validate_replacement_operator_session_v2(p_session_token text, p_device_id text, p_require_context boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
declare
  v_session public.operator_sessions%rowtype;
  v_operator public.operators%rowtype;
  v_cell public.cells%rowtype;
  v_machine public.production_machines%rowtype;
  v_now timestamptz := clock_timestamp();
begin
  if auth.uid() is null then
    return jsonb_build_object('success', false, 'reason_code', 'AUTH_REQUIRED', 'message', 'Autenticacao do sistema expirada.');
  end if;

  select session_row.*
  into v_session
  from public.operator_sessions session_row
  where session_row.token_hash = encode(extensions.digest(coalesce(p_session_token, ''), 'sha256'), 'hex')
    and session_row.auth_user_id = auth.uid()
    and session_row.device_id = btrim(coalesce(p_device_id, ''))
  order by session_row.started_at desc
  limit 1;

  if v_session.id is null then
    return jsonb_build_object('success', false, 'reason_code', 'SESSION_INVALID', 'message', 'Sessao operacional nao localizada para este dispositivo.');
  end if;

  select operator_row.*
  into v_operator
  from public.operators operator_row
  where operator_row.id = v_session.operator_id;

  if v_operator.id is null
     or v_operator.active is not true
     or coalesce(v_operator.login_enabled, true) is not true
     or v_operator.replacement_enabled is not true then
    return jsonb_build_object(
      'success', false,
      'reason_code', 'REPLACEMENT_ACCESS_DENIED',
      'message', 'Colaborador sem liberacao para realizar baixas de reposicao.'
    );
  end if;

  if p_require_context is not true then
    return jsonb_build_object('success', true, 'operator_id', v_operator.id);
  end if;

  if v_session.cell_id is null then
    return jsonb_build_object('success', false, 'reason_code', 'CONTEXT_REQUIRED', 'message', 'Selecione a celula e o posto de reposicao.');
  end if;

  select cell.* into v_cell
  from public.cells cell
  where cell.id = v_session.cell_id and cell.active is true;

  if v_cell.id is null or not exists (
    select 1
    from public.operator_cell_assignments assignment
    where assignment.operator_id = v_operator.id
      and assignment.cell_id = v_session.cell_id
      and assignment.active is true
      and assignment.valid_from <= v_now
      and (assignment.valid_until is null or assignment.valid_until > v_now)
  ) then
    return jsonb_build_object('success', false, 'reason_code', 'OPERATOR_UNAUTHORIZED', 'message', 'Colaborador nao autorizado para esta celula.');
  end if;

  if v_session.machine_id is not null then
    select machine.* into v_machine
    from public.production_machines machine
    where machine.id = v_session.machine_id;

    if v_machine.id is null
       or v_machine.active is not true
       or v_machine.allows_replacement is not true
       or lower(btrim(v_machine.cell_name)) <> lower(btrim(v_cell.name)) then
      return jsonb_build_object('success', false, 'reason_code', 'MACHINE_UNAUTHORIZED', 'message', 'Posto inativo ou nao habilitado para reposicao nesta celula.');
    end if;

    if exists (
      select 1
      from public.operator_machine_assignments assignment
      where assignment.operator_id = v_operator.id
        and assignment.active is true
        and assignment.valid_from <= v_now
        and (assignment.valid_until is null or assignment.valid_until > v_now)
    ) and not exists (
      select 1
      from public.operator_machine_assignments assignment
      where assignment.operator_id = v_operator.id
        and assignment.machine_id = v_session.machine_id
        and assignment.active is true
        and assignment.valid_from <= v_now
        and (assignment.valid_until is null or assignment.valid_until > v_now)
    ) then
      return jsonb_build_object('success', false, 'reason_code', 'OPERATOR_UNAUTHORIZED', 'message', 'Colaborador nao autorizado para este posto.');
    end if;
  end if;

  return jsonb_build_object(
    'success', true,
    'operator_id', v_operator.id,
    'cell_id', v_session.cell_id,
    'machine_id', v_session.machine_id
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.wake_collection_inbox_worker(p_source text DEFAULT 'database'::text, p_limit integer DEFAULT 60)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'vault', 'net', 'pg_temp'
AS $function$
DECLARE
  v_url text;
  v_secret text;
  v_request_id bigint;
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.coletas_producao inbox
    WHERE inbox.pipeline_version = 2
      AND (
        (
          inbox.status_sincronizacao = 'recebida'
          AND coalesce(inbox.next_attempt_at, '-infinity'::timestamptz)
              <= clock_timestamp()
        ) OR (
          inbox.status_sincronizacao = 'processando'
          AND coalesce(inbox.lease_expires_at, '-infinity'::timestamptz)
              <= clock_timestamp()
        )
      )
  ) THEN
    RETURN NULL;
  END IF;

  SELECT decrypted_secret INTO v_url
  FROM vault.decrypted_secrets
  WHERE name = 'acprod_collection_worker_url'
  LIMIT 1;

  SELECT decrypted_secret INTO v_secret
  FROM vault.decrypted_secrets
  WHERE name = 'acprod_collection_worker_secret'
  LIMIT 1;

  IF v_url IS NULL OR v_secret IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT net.http_post(
    url := v_url,
    body := jsonb_build_object(
      'source', coalesce(nullif(btrim(p_source), ''), 'database'),
      'limit', greatest(1, least(coalesce(p_limit, 60), 100)),
      'concurrency', 8,
      'max_rounds', 5
    ),
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-cron-secret', v_secret
    ),
    timeout_milliseconds := 30000
  ) INTO v_request_id;

  RETURN v_request_id;
END;
$function$

CREATE OR REPLACE FUNCTION private.wake_collection_v3_worker(p_worker_kind text, p_source text DEFAULT 'database'::text, p_limit integer DEFAULT 25)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'vault', 'net', 'pgmq', 'pg_temp'
AS $function$
DECLARE
  v_url_name text;
  v_flag_name text;
  v_url text;
  v_secret text;
  v_request_id bigint;
  v_has_work boolean := false;
  v_lease_owner text := 'wake:' || gen_random_uuid()::text;
BEGIN
  IF p_worker_kind = 'decision' THEN
    v_url_name := 'acprod_collection_v3_decision_url';
    v_flag_name := 'collection_pipeline_v3_worker';
    SELECT EXISTS (
      SELECT 1 FROM pgmq.q_collection_live_v3 queue WHERE queue.vt <= clock_timestamp()
      UNION ALL
      SELECT 1 FROM pgmq.q_collection_replay_v3 queue WHERE queue.vt <= clock_timestamp()
    ) INTO v_has_work;
  ELSIF p_worker_kind = 'projection' THEN
    v_url_name := 'acprod_collection_v3_projection_url';
    v_flag_name := 'collection_pipeline_v3_projection';
    SELECT EXISTS (
      SELECT 1 FROM pgmq.q_collection_projection_v3 queue WHERE queue.vt <= clock_timestamp()
    ) INTO v_has_work;
  ELSE
    RAISE EXCEPTION 'COLLECTION_V3_WORKER_KIND_INVALID' USING ERRCODE = '22023';
  END IF;

  IF NOT v_has_work OR NOT EXISTS (
    SELECT 1 FROM private.collection_pipeline_flags flag
    WHERE flag.flag_name = v_flag_name AND flag.enabled IS TRUE
  ) THEN
    RETURN NULL;
  END IF;

  IF current_setting('acprod.collection_v3_wake_' || p_worker_kind, true) = 'sent' THEN
    RETURN NULL;
  END IF;
  PERFORM set_config('acprod.collection_v3_wake_' || p_worker_kind, 'sent', true);

  -- Reserva distribuída antes do HTTP: triggers e cron concorrentes são coalescidos.
  IF NOT private.try_acquire_collection_worker_lease_v3(
    p_worker_kind, v_lease_owner, 45
  ) THEN
    RETURN NULL;
  END IF;

  SELECT decrypted_secret INTO v_url
  FROM vault.decrypted_secrets WHERE name = v_url_name LIMIT 1;
  SELECT decrypted_secret INTO v_secret
  FROM vault.decrypted_secrets
  WHERE name = 'acprod_collection_worker_secret' LIMIT 1;

  IF v_url IS NULL OR v_secret IS NULL THEN
    DELETE FROM private.collection_worker_leases_v3
    WHERE worker_kind = p_worker_kind AND lease_owner = v_lease_owner;
    RETURN NULL;
  END IF;

  SELECT net.http_post(
    url := v_url,
    body := jsonb_build_object(
      'source', coalesce(nullif(btrim(p_source), ''), 'database'),
      'limit', greatest(5, least(coalesce(p_limit, 25), 25)),
      'max_rounds', 5,
      'lease_owner', v_lease_owner
    ),
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-cron-secret', v_secret
    ),
    timeout_milliseconds := 30000
  ) INTO v_request_id;

  RETURN v_request_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.acquire_collection_worker_lease_v3(p_worker_kind text, p_lease_owner text, p_ttl_seconds integer DEFAULT 45)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private', 'pg_temp'
AS $function$
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION 'SERVICE_ROLE_REQUIRED' USING ERRCODE = '42501';
  END IF;
  RETURN private.try_acquire_collection_worker_lease_v3(
    p_worker_kind, p_lease_owner, p_ttl_seconds
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_delete_operator(p_operator_id uuid, p_confirmation text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
DECLARE
  v_operator public.operators%ROWTYPE;
  v_actor_name text;
  v_actor_email text;
BEGIN
  IF auth.uid() IS NULL OR public.get_my_role() <> 'admin' THEN
    RAISE EXCEPTION 'Apenas administradores podem excluir operadores.';
  END IF;

  SELECT * INTO v_operator
  FROM public.operators
  WHERE id = p_operator_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Operador não encontrado.';
  END IF;

  IF btrim(COALESCE(p_confirmation, '')) <> v_operator.name THEN
    RAISE EXCEPTION 'Confirmação inválida. Digite exatamente o nome do operador.';
  END IF;

  SELECT name, email INTO v_actor_name, v_actor_email
  FROM public.profiles WHERE id = auth.uid();

  INSERT INTO public.system_audit_logs (
    user_id, user_name, user_email, user_role, action, entity,
    entity_id, entity_label, page, route, method, old_value, success
  ) VALUES (
    auth.uid(), v_actor_name, v_actor_email, 'admin', 'delete', 'operator',
    v_operator.id::text, v_operator.name, 'Gestão de Operadores', '/operadores',
    'RPC', jsonb_build_object('name', v_operator.name, 'login_name', v_operator.login_name), true
  );

  DELETE FROM public.operators WHERE id = p_operator_id;

  RETURN jsonb_build_object('success', true, 'deleted_id', p_operator_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_update_user_password(target_user_id uuid, new_password text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
DECLARE
  calling_user_id uuid;
  calling_user_role text;
BEGIN
  -- 1. Obter o ID do usuário logado
  calling_user_id := auth.uid();

  -- Se não estiver logado, barrar imediatamente
  IF calling_user_id IS NULL THEN
    RAISE EXCEPTION 'Não autenticado.' USING ERRCODE = '42501';
  END IF;

  -- 2. Verificar se o chamador é administrador
  SELECT role INTO calling_user_role
  FROM public.profiles
  WHERE id = calling_user_id;

  -- Se não for admin e não for o próprio usuário, barrar
  IF calling_user_role != 'admin' AND calling_user_id != target_user_id THEN
    RAISE EXCEPTION 'Acesso negado. Apenas administradores podem alterar senhas de outros usuários.' USING ERRCODE = '42501';
  END IF;

  -- 3. Atualizar a senha usando o pgcrypto no schema extensions
  UPDATE auth.users
  SET 
    encrypted_password = extensions.crypt(new_password, extensions.gen_salt('bf', 10)),
    updated_at = now()
  WHERE id = target_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Usuário não encontrado.' USING ERRCODE = 'P0002';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_upsert_operator_v2(p_operator_id uuid, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_result jsonb; v_operator_id uuid; v_replacement_enabled boolean; v_cell_ids uuid[];
  v_shift_start time := COALESCE(NULLIF(p_data->>'shift_start_time', '')::time, '06:00:00'::time);
  v_shift_end time := COALESCE(NULLIF(p_data->>'shift_end_time', '')::time, '14:00:00'::time);
  v_timezone text := COALESCE(NULLIF(btrim(p_data->>'timezone'), ''), 'America/Sao_Paulo'); v_operator_json jsonb;
BEGIN
  IF auth.uid() IS NULL OR NOT public.can_manage_operators() THEN RETURN jsonb_build_object('success',false,'error','Sem permissão para gerenciar colaboradores.'); END IF;
  IF v_shift_start = v_shift_end THEN RETURN jsonb_build_object('success',false,'error','O início e o término do turno não podem ser iguais.'); END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_timezone_names tz WHERE tz.name = v_timezone) THEN RETURN jsonb_build_object('success',false,'error','Fuso horário inválido.'); END IF;
  SELECT COALESCE(array_agg(DISTINCT value::uuid), ARRAY[]::uuid[]) INTO v_cell_ids FROM jsonb_array_elements_text(COALESCE(p_data->'cell_ids','[]'::jsonb));
  IF p_operator_id IS NOT NULL THEN PERFORM 1 FROM public.operators op WHERE op.id=p_operator_id FOR UPDATE; END IF;
  IF NOT public.can_manage_operator_scope(p_operator_id,v_cell_ids) THEN RETURN jsonb_build_object('success',false,'error','Sem permissão para gerenciar colaboradores neste escopo.'); END IF;
  v_result := public.admin_upsert_operator(p_operator_id,COALESCE(p_data,'{}'::jsonb));
  IF COALESCE((v_result->>'success')::boolean,false) IS NOT TRUE THEN RETURN v_result; END IF;
  v_operator_id := NULLIF(v_result #>> '{operator,id}','')::uuid;
  IF v_operator_id IS NULL THEN RETURN jsonb_build_object('success',false,'error','O cadastro não retornou um colaborador válido.'); END IF;
  IF COALESCE(p_data,'{}'::jsonb) ? 'replacement_enabled' THEN v_replacement_enabled := COALESCE((p_data->>'replacement_enabled')::boolean,false);
  ELSE SELECT replacement_enabled INTO v_replacement_enabled FROM public.operators WHERE id=v_operator_id; END IF;
  UPDATE public.operators SET shift_start_time=v_shift_start,shift_end_time=v_shift_end,timezone=v_timezone,replacement_enabled=COALESCE(v_replacement_enabled,false) WHERE id=v_operator_id;
  SELECT to_jsonb(op)-'registration'-'registration_normalized'-'credential_hash' INTO v_operator_json FROM public.operators op WHERE op.id=v_operator_id;
  RETURN jsonb_set(v_result,'{operator}',v_operator_json,true);
EXCEPTION WHEN invalid_text_representation THEN RETURN jsonb_build_object('success',false,'error','Um dado ou vínculo informado possui formato inválido.');
END; $function$

CREATE OR REPLACE FUNCTION public.admin_upsert_operator(p_operator_id uuid, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_operator public.operators%ROWTYPE;
  v_existing public.operators%ROWTYPE;
  v_cell_ids uuid[];
  v_machine_ids uuid[];
  v_primary_cell_id uuid;
  v_primary_machine_id uuid;
  v_name text := btrim(coalesce(p_data ->> 'name', ''));
  v_login text := lower(btrim(coalesce(p_data ->> 'login_name', '')));
  v_registration text := nullif(btrim(coalesce(p_data ->> 'registration', '')), '');
  v_shift text := nullif(btrim(coalesce(p_data ->> 'shift', '')), '');
  v_shift_start_time time;
  v_shift_end_time time;
  v_timezone text := coalesce(nullif(btrim(p_data ->> 'timezone'), ''), 'America/Sao_Paulo');
  v_replacement_enabled boolean := false;
  v_active boolean := coalesce(nullif(p_data ->> 'active', '')::boolean, true);
  v_primary_cell_name text;
  v_invalid_count integer;
BEGIN
  IF NOT public.can_manage_operators() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Sem permissão para gerenciar operadores.');
  END IF;

  IF p_operator_id IS NOT NULL THEN
    SELECT * INTO v_existing
    FROM public.operators
    WHERE id = p_operator_id;
  END IF;

  v_shift := coalesce(v_shift, v_existing.shift);
  v_active := coalesce(nullif(p_data ->> 'active', '')::boolean, v_existing.active, true);

  IF v_name = '' OR v_login = '' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Nome e login são obrigatórios.');
  END IF;

  IF v_login !~ '^[a-z0-9.]+$' THEN
    RETURN jsonb_build_object('success', false, 'error', 'O login aceita apenas letras minúsculas, números e pontos.');
  END IF;

  v_shift_start_time := coalesce(
    nullif(p_data ->> 'shift_start_time', '')::time,
    v_existing.shift_start_time,
    CASE
      WHEN lower(coalesce(v_shift, '')) LIKE '%3%' THEN '22:00:00'::time
      WHEN lower(coalesce(v_shift, '')) LIKE '%2%' THEN '14:00:00'::time
      ELSE '06:00:00'::time
    END
  );

  v_shift_end_time := coalesce(
    nullif(p_data ->> 'shift_end_time', '')::time,
    v_existing.shift_end_time,
    CASE
      WHEN lower(coalesce(v_shift, '')) LIKE '%3%' THEN '06:00:00'::time
      WHEN lower(coalesce(v_shift, '')) LIKE '%2%' THEN '22:00:00'::time
      ELSE '14:00:00'::time
    END
  );

  v_timezone := coalesce(nullif(btrim(p_data ->> 'timezone'), ''), v_existing.timezone, 'America/Sao_Paulo');
  v_replacement_enabled := coalesce(
    nullif(p_data ->> 'replacement_enabled', '')::boolean,
    v_existing.replacement_enabled,
    false
  );

  IF v_shift_start_time = v_shift_end_time THEN
    RETURN jsonb_build_object('success', false, 'error', 'O horário inicial não pode ser igual ao horário final.');
  END IF;

  BEGIN
    PERFORM clock_timestamp() AT TIME ZONE v_timezone;
  EXCEPTION WHEN invalid_parameter_value THEN
    RETURN jsonb_build_object('success', false, 'error', 'Fuso horário inválido.');
  END;

  SELECT coalesce(array_agg(DISTINCT value::uuid), ARRAY[]::uuid[])
  INTO v_cell_ids
  FROM jsonb_array_elements_text(coalesce(p_data -> 'cell_ids', '[]'::jsonb));

  SELECT coalesce(array_agg(DISTINCT value::uuid), ARRAY[]::uuid[])
  INTO v_machine_ids
  FROM jsonb_array_elements_text(coalesce(p_data -> 'machine_ids', '[]'::jsonb));

  v_primary_cell_id := nullif(p_data ->> 'primary_cell_id', '')::uuid;
  v_primary_machine_id := nullif(p_data ->> 'primary_machine_id', '')::uuid;

  IF cardinality(v_cell_ids) = 0 OR v_primary_cell_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Vincule ao menos uma célula e defina a célula principal.');
  END IF;

  IF NOT (v_primary_cell_id = ANY(v_cell_ids)) THEN
    RETURN jsonb_build_object('success', false, 'error', 'A célula principal deve estar entre as células autorizadas.');
  END IF;

  SELECT count(*)
  INTO v_invalid_count
  FROM unnest(v_cell_ids) requested(cell_id)
  LEFT JOIN public.cells cell
    ON cell.id = requested.cell_id
   AND cell.active = true
  WHERE cell.id IS NULL;

  IF v_invalid_count > 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Uma ou mais células são inválidas ou estão inativas.');
  END IF;

  SELECT count(*)
  INTO v_invalid_count
  FROM unnest(v_machine_ids) requested(machine_id)
  LEFT JOIN public.production_machines machine
    ON machine.id = requested.machine_id
   AND machine.active = true
  LEFT JOIN public.cells cell
    ON lower(btrim(cell.name)) = lower(btrim(machine.cell_name))
   AND cell.id = ANY(v_cell_ids)
  WHERE machine.id IS NULL OR cell.id IS NULL;

  IF v_invalid_count > 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Uma máquina selecionada não pertence às células autorizadas.');
  END IF;

  IF v_primary_machine_id IS NOT NULL
     AND NOT (v_primary_machine_id = ANY(v_machine_ids)) THEN
    RETURN jsonb_build_object('success', false, 'error', 'A máquina principal deve estar entre as máquinas autorizadas.');
  END IF;

  SELECT name INTO v_primary_cell_name
  FROM public.cells
  WHERE id = v_primary_cell_id;

  IF p_operator_id IS NULL THEN
    IF v_registration IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error', 'A matrícula é obrigatória para um novo operador.');
    END IF;

    INSERT INTO public.operators (
      name, role, active, registration, login_name, primary_cell, cells, shift,
      shift_start_time, shift_end_time, timezone, replacement_enabled,
      login_enabled, primary_cell_id, primary_machine_id
    ) VALUES (
      v_name, 'operator', v_active, v_registration, v_login, v_primary_cell_name,
      ARRAY(SELECT name FROM public.cells WHERE id = ANY(v_cell_ids) ORDER BY name),
      v_shift, v_shift_start_time, v_shift_end_time, v_timezone, v_replacement_enabled,
      true, v_primary_cell_id, v_primary_machine_id
    )
    RETURNING * INTO v_operator;
  ELSE
    UPDATE public.operators
    SET name = v_name,
        login_name = v_login,
        registration = coalesce(v_registration, registration),
        primary_cell = v_primary_cell_name,
        cells = ARRAY(SELECT name FROM public.cells WHERE id = ANY(v_cell_ids) ORDER BY name),
        shift = v_shift,
        shift_start_time = v_shift_start_time,
        shift_end_time = v_shift_end_time,
        timezone = v_timezone,
        replacement_enabled = v_replacement_enabled,
        active = v_active,
        login_enabled = v_active,
        primary_cell_id = v_primary_cell_id,
        primary_machine_id = v_primary_machine_id,
        deactivated_at = CASE WHEN v_active THEN NULL ELSE coalesce(deactivated_at, clock_timestamp()) END,
        deactivated_by = CASE WHEN v_active THEN NULL ELSE auth.uid() END
    WHERE id = p_operator_id
    RETURNING * INTO v_operator;

    IF v_operator.id IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error', 'Operador não encontrado.');
    END IF;
  END IF;

  UPDATE public.operator_cell_assignments
  SET active = false,
      valid_until = clock_timestamp(),
      is_primary = false,
      updated_at = clock_timestamp()
  WHERE operator_id = v_operator.id
    AND active = true;

  INSERT INTO public.operator_cell_assignments (
    operator_id, cell_id, is_primary, active, valid_from, valid_until, assigned_by
  )
  SELECT v_operator.id, requested.cell_id, requested.cell_id = v_primary_cell_id,
         true, clock_timestamp(), NULL, auth.uid()
  FROM unnest(v_cell_ids) AS requested(cell_id);

  UPDATE public.operator_machine_assignments
  SET active = false,
      valid_until = clock_timestamp(),
      is_primary = false,
      updated_at = clock_timestamp()
  WHERE operator_id = v_operator.id
    AND active = true;

  INSERT INTO public.operator_machine_assignments (
    operator_id, machine_id, is_primary, active, valid_from, valid_until, assigned_by
  )
  SELECT v_operator.id, requested.machine_id, requested.machine_id = v_primary_machine_id,
         true, clock_timestamp(), NULL, auth.uid()
  FROM unnest(v_machine_ids) AS requested(machine_id);

  RETURN jsonb_build_object(
    'success', true,
    'operator', to_jsonb(v_operator)
      - 'registration'
      - 'registration_normalized'
      - 'credential_hash'
  );
EXCEPTION
  WHEN unique_violation THEN
    RETURN jsonb_build_object('success', false, 'error', 'Login ou matrícula já está em uso por outro operador.');
  WHEN invalid_text_representation THEN
    RETURN jsonb_build_object('success', false, 'error', 'Um dos dados informados possui formato inválido.');
END;
$function$

CREATE OR REPLACE FUNCTION public.advance_piece_stage(p_piece_id uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_piece       production_pieces%ROWTYPE;
  v_user_id     uuid;
  v_role        text;
  v_to_stage    text;
  v_from_stage  text;
  v_operator_id uuid;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Autenticação necessária.');
  END IF;

  v_role := get_my_role();
  IF v_role NOT IN ('admin', 'manager', 'operator') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Permissão insuficiente.');
  END IF;

  SELECT * INTO v_piece FROM production_pieces WHERE id = p_piece_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Peça não encontrada.');
  END IF;

  IF v_piece.is_blocked THEN
    RETURN jsonb_build_object('success', false, 'error', 'Peça bloqueada: ' || COALESCE(v_piece.block_reason, 'sem motivo informado'));
  END IF;

  IF v_piece.status IN ('cancelled', 'shipped') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Peça com status ' || v_piece.status || ' não pode avançar etapas.');
  END IF;

  v_from_stage := v_piece.current_stage;
  v_to_stage   := COALESCE(NULLIF(p_payload->>'to_stage', ''), v_from_stage);
  v_operator_id := (p_payload->>'operator_id')::uuid;

  UPDATE production_pieces SET
    current_stage = v_to_stage,
    status = CASE
      WHEN v_to_stage = 'shipped'   THEN 'shipped'
      WHEN v_to_stage = 'completed' THEN 'completed'
      ELSE 'in_progress'
    END,
    updated_at = now()
  WHERE id = p_piece_id;

  INSERT INTO production_events (
    piece_id,
    traceability_code,
    production_order_id,
    lot_id,
    event_type,
    from_stage,
    to_stage,
    cell_name,
    device_id,
    operator_id,
    event_status,
    notes,
    metadata
  ) VALUES (
    v_piece.id,
    v_piece.traceability_code,
    v_piece.production_order_id,
    v_piece.lot_id,
    'stage_advance',
    v_from_stage,
    v_to_stage,
    p_payload->>'cell_name',
    p_payload->>'device_id',
    v_operator_id,
    'accepted',
    p_payload->>'notes',
    COALESCE(p_payload->'metadata', '{}'::jsonb)
  );

  RETURN jsonb_build_object(
    'success',       true,
    'piece_id',      v_piece.id,
    'from_stage',    v_from_stage,
    'to_stage',      v_to_stage,
    'new_status',    CASE
      WHEN v_to_stage = 'shipped'   THEN 'shipped'
      WHEN v_to_stage = 'completed' THEN 'completed'
      ELSE 'in_progress'
    END
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.approve_piece_replacement(p_order_id uuid, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'realtime', 'pg_temp'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_user_role text := public.get_my_role();
  v_user_name text := coalesce(
    nullif(current_setting('request.jwt.claims', true)::jsonb ->> 'email', ''),
    v_user_id::text,
    'service_role'
  );
  v_order public.replacement_orders%ROWTYPE;
  v_original public.production_pieces%ROWTYPE;
  v_lot public.production_lots%ROWTYPE;
  v_production_order public.production_orders%ROWTYPE;
  v_production_order_id uuid;
  v_replacement_piece_id uuid;
  v_replacement_uid text;
  v_internal_traceability text;
  v_barcode text;
  v_priority text := coalesce(nullif(p_payload ->> 'priority', ''), 'normal');
  v_route text[];
  v_route_codes text[] := '{}'::text[];
  v_route_value text;
  v_step_code text;
  v_first_step text;
  v_first_cell public.cells%ROWTYPE;
BEGIN
  IF auth.role() <> 'service_role' AND v_user_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED' USING ERRCODE = '42501';
  END IF;

  IF NOT public.can_manage_replacement_actions() THEN
    RAISE EXCEPTION 'REPLACEMENT_APPROVAL_PERMISSION_REQUIRED'
      USING ERRCODE = '42501';
  END IF;

  SELECT *
  INTO v_order
  FROM public.replacement_orders
  WHERE id = p_order_id
  FOR UPDATE;

  IF v_order.id IS NULL THEN
    RAISE EXCEPTION 'Ordem de reposição não encontrada.';
  END IF;

  IF v_order.replacement_piece_id IS NOT NULL
     AND v_order.status IN ('approved','released','in_production','completed') THEN
    RETURN jsonb_build_object(
      'success', true,
      'idempotent', true,
      'order_id', v_order.id,
      'status', v_order.status,
      'replacement_piece_id', v_order.replacement_piece_id,
      'replacement_barcode', v_order.replacement_barcode,
      'automatic_entries', 0,
      'approved_cells', '[]'::jsonb,
      'next_step', (
        SELECT piece.current_stage
        FROM public.production_pieces piece
        WHERE piece.id = v_order.replacement_piece_id
      )
    );
  END IF;

  IF v_order.status NOT IN ('requested','under_review') THEN
    RAISE EXCEPTION 'Status atual inválido para aprovação: %', v_order.status;
  END IF;

  SELECT *
  INTO v_original
  FROM public.production_pieces
  WHERE id = v_order.original_piece_id
  FOR UPDATE;

  IF v_original.id IS NULL THEN
    RAISE EXCEPTION 'Peça original não encontrada.';
  END IF;
  IF v_original.lot_id IS NULL THEN
    RAISE EXCEPTION 'A peça original não possui lote vinculado.';
  END IF;

  SELECT * INTO v_lot
  FROM public.production_lots
  WHERE id = v_original.lot_id;

  v_production_order_id := coalesce(
    v_original.production_order_id,
    v_lot.production_order_id,
    v_lot.order_id
  );

  SELECT * INTO v_production_order
  FROM public.production_orders
  WHERE id = v_production_order_id;

  v_barcode := coalesce(
    nullif(v_order.replacement_barcode, ''),
    nullif(v_original.traceability_code, ''),
    nullif(v_original.piece_uid, ''),
    nullif(v_original.piece_code, '')
  );

  IF v_barcode IS NULL THEN
    RAISE EXCEPTION 'A peça original não possui código de barras rastreável.';
  END IF;

  v_route := coalesce(v_original.route_steps, '{}'::text[]);
  IF cardinality(v_route) = 0 THEN
    v_route := ARRAY[]::text[];
    IF coalesce(v_original.requires_cut, false) THEN v_route := array_append(v_route, 'cut'); END IF;
    IF coalesce(v_original.requires_edge, false) THEN v_route := array_append(v_route, 'edge'); END IF;
    IF coalesce(v_original.requires_cnc, false) THEN v_route := array_append(v_route, 'cnc'); END IF;
    IF coalesce(v_original.requires_joinery, false) THEN v_route := array_append(v_route, 'joinery'); END IF;
    IF coalesce(v_original.requires_separation, false) THEN v_route := array_append(v_route, 'separation'); END IF;
    IF coalesce(v_original.requires_packaging, false) THEN v_route := array_append(v_route, 'packaging'); END IF;
  END IF;

  FOREACH v_route_value IN ARRAY v_route LOOP
    v_step_code := public.normalize_replacement_step_code(v_route_value);
    IF v_step_code IS NOT NULL AND NOT (v_step_code = ANY(v_route_codes)) THEN
      v_route_codes := array_append(v_route_codes, v_step_code);
    END IF;
  END LOOP;

  IF cardinality(v_route_codes) = 0 THEN
    v_route_codes := ARRAY['cut'];
    v_route := ARRAY['cut'];
  END IF;

  v_first_step := v_route_codes[1];
  v_replacement_uid := v_barcode || '.REP.' || upper(substr(replace(v_order.id::text, '-', ''), 1, 8));
  v_internal_traceability := v_replacement_uid;

  INSERT INTO public.production_pieces (
    piece_uid, piece_code, traceability_code, piece_name, description,
    production_order_id, lot_id, lot_item_id, item_id,
    legacy_lot_item_id, legacy_production_lot_item_id,
    sequence_number, total_in_lot, is_active,
    module_name, environment, environment_name,
    material, thickness, color, width, height, length, grain_direction,
    edge_front, edge_back, edge_left, edge_right,
    requires_cut, requires_edge, requires_cnc, requires_joinery,
    requires_separation, requires_packaging,
    current_stage, status, source_origin, is_rework, original_piece_id,
    is_replacement, production_status, replacement_status,
    route_template_id, route_steps, completed_steps,
    lot_code, order_number, customer_name, pcp_import_batch_id, created_by
  ) VALUES (
    v_replacement_uid, v_barcode, v_internal_traceability,
    v_original.piece_name, v_original.description,
    v_production_order_id, v_original.lot_id,
    v_original.lot_item_id, v_original.item_id,
    v_original.legacy_lot_item_id, v_original.legacy_production_lot_item_id,
    v_original.sequence_number, v_original.total_in_lot, true,
    v_original.module_name, v_original.environment, v_original.environment_name,
    v_original.material, v_original.thickness, v_original.color,
    v_original.width, v_original.height, v_original.length, v_original.grain_direction,
    v_original.edge_front, v_original.edge_back, v_original.edge_left, v_original.edge_right,
    v_original.requires_cut, v_original.requires_edge, v_original.requires_cnc,
    v_original.requires_joinery, v_original.requires_separation, v_original.requires_packaging,
    v_first_step, 'in_progress', 'replacement', false, v_original.id,
    true, 'approved', 'in_production',
    v_original.route_template_id, v_route, '{}'::text[],
    coalesce(v_original.lot_code, v_order.lot_code, v_lot.lot_code),
    coalesce(v_original.order_number, v_order.order_number, v_production_order.order_number, v_production_order.order_code),
    coalesce(v_original.customer_name, v_order.customer_name, v_production_order.customer_name),
    v_original.pcp_import_batch_id, v_user_id
  )
  RETURNING id INTO v_replacement_piece_id;

  UPDATE public.production_tags
  SET active = false,
      updated_at = clock_timestamp()
  WHERE upper(tag_value) = upper(v_barcode)
    AND active IS TRUE;

  INSERT INTO public.production_tags (
    lot_id, item_id, piece_id, tag_value, tag_type, tag_format,
    barcode_value, active, created_at, updated_at
  ) VALUES (
    v_original.lot_id,
    coalesce(v_original.legacy_production_lot_item_id, v_original.lot_item_id),
    v_replacement_piece_id,
    v_barcode,
    'barcode',
    'custom',
    v_barcode,
    true,
    clock_timestamp(),
    clock_timestamp()
  );

  UPDATE public.production_pieces
  SET replacement_status = 'in_production',
      updated_at = clock_timestamp()
  WHERE id = v_original.id;

  UPDATE public.replacement_orders
  SET status = 'released',
      replacement_piece_id = v_replacement_piece_id,
      replacement_barcode = v_barcode,
      approver_id = v_user_id,
      approved_at = clock_timestamp(),
      released_at = clock_timestamp(),
      completed_at = NULL,
      priority = v_priority,
      approved_cells = '[]'::jsonb,
      approval_entry_count = 0,
      updated_at = clock_timestamp()
  WHERE id = p_order_id;

  INSERT INTO public.replacement_action_audit_logs (
    replacement_order_id, replacement_code, action,
    performed_by, performed_by_name, performed_by_role,
    status_before, status_after,
    original_piece_id, replacement_piece_id,
    current_stage_before, current_stage_after,
    metadata
  ) VALUES (
    v_order.id, v_order.replacement_code, 'approved_for_production',
    v_user_id, v_user_name, v_user_role,
    v_order.status, 'released',
    v_original.id, v_replacement_piece_id,
    v_original.current_stage, v_first_step,
    jsonb_build_object(
      'priority', v_priority,
      'automatic_entries', 0,
      'approved_cells', '[]'::jsonb,
      'barcode', v_barcode,
      'route_steps', to_jsonb(v_route_codes),
      'source', 'replacement_approval_without_automatic_entries'
    )
  );

  SELECT *
  INTO v_first_cell
  FROM public.cells cell
  WHERE cell.active IS TRUE
    AND public.replacement_cell_matches_step(cell.name, v_first_step)
  ORDER BY cell.name
  LIMIT 1;

  BEGIN
    PERFORM realtime.send(
      jsonb_build_object(
        'replacement_order_id', v_order.id,
        'replacement_piece_id', v_replacement_piece_id,
        'replacement_code', v_order.replacement_code,
        'barcode', v_barcode,
        'status', 'released',
        'current_step', v_first_step,
        'automatic_entries', 0,
        'occurred_at', clock_timestamp()
      ),
      'replacement_available',
      'replacement:global',
      true
    );

    IF v_first_cell.id IS NOT NULL THEN
      PERFORM realtime.send(
        jsonb_build_object(
          'replacement_order_id', v_order.id,
          'replacement_piece_id', v_replacement_piece_id,
          'replacement_code', v_order.replacement_code,
          'barcode', v_barcode,
          'status', 'released',
          'cell_id', v_first_cell.id,
          'cell_name', v_first_cell.name,
          'current_step', v_first_step,
          'occurred_at', clock_timestamp()
        ),
        'replacement_available',
        'replacement:cell:' || v_first_cell.id::text,
        true
      );
    END IF;
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  RETURN jsonb_build_object(
    'success', true,
    'order_id', p_order_id,
    'status', 'released',
    'replacement_piece_id', v_replacement_piece_id,
    'replacement_uid', v_replacement_uid,
    'replacement_barcode', v_barcode,
    'automatic_entries', 0,
    'approved_cells', '[]'::jsonb,
    'completed_steps', '[]'::jsonb,
    'next_step', v_first_step,
    'destination_cell_id', v_first_cell.id,
    'destination_cell_name', v_first_cell.name,
    'message', 'Reposição aprovada e enviada ao posto da primeira etapa.'
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.assert_collection_projection_schema_v3()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
DECLARE
  v_missing text[];
BEGIN
  SELECT array_agg(required.column_name ORDER BY required.column_name)
  INTO v_missing
  FROM (VALUES
    ('approval_status'), ('client_event_id'), ('corrected_at'),
    ('corrected_by'), ('correction_reason'), ('created_at'), ('updated_at')
  ) required(column_name)
  WHERE NOT EXISTS (
    SELECT 1 FROM pg_attribute attribute
    WHERE attribute.attrelid = 'public.production_entries'::regclass
      AND attribute.attname = required.column_name
      AND attribute.attnum > 0
      AND NOT attribute.attisdropped
  );

  IF coalesce(cardinality(v_missing), 0) > 0 THEN
    RAISE EXCEPTION 'COLLECTION_PROJECTION_SCHEMA_MISMATCH: %', array_to_string(v_missing, ',')
      USING ERRCODE = '42703';
  END IF;
  IF to_regprocedure('private.process_collection_projection_batch_v3(text,jsonb)') IS NULL THEN
    RAISE EXCEPTION 'COLLECTION_PROJECTION_FUNCTION_MISSING' USING ERRCODE = '42883';
  END IF;

  RETURN jsonb_build_object('ok', true, 'checked_at', clock_timestamp());
END;
$function$

CREATE OR REPLACE FUNCTION public.audit_table_changes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_profile record;
  v_old_full jsonb := NULL;
  v_new_full jsonb := NULL;
  v_old_diff jsonb := NULL;
  v_new_diff jsonb := NULL;
  v_changed_fields text[] := '{}'::text[];
  v_entity_id text;
  v_excluded_fields text[] := ARRAY[
    'updated_at',
    'state_version',
    'progress_percent',
    'produced_quantity',
    'approved_quantity',
    'pending_quantity',
    'payload',
    'result_payload',
    'raw_cells',
    'broadcasted_at',
    'broadcast_error',
    'lot_state_version'
  ];
BEGIN
  SELECT profile.name, profile.email, profile.role
  INTO v_profile
  FROM public.profiles profile
  WHERE profile.id = (SELECT auth.uid())
  LIMIT 1;

  IF TG_OP IN ('UPDATE', 'DELETE') THEN
    v_old_full := to_jsonb(OLD) - v_excluded_fields;
  END IF;
  IF TG_OP IN ('INSERT', 'UPDATE') THEN
    v_new_full := to_jsonb(NEW) - v_excluded_fields;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    SELECT
      COALESCE(jsonb_object_agg(new_pair.key, new_pair.value), '{}'::jsonb),
      COALESCE(
        array_agg(new_pair.key ORDER BY new_pair.key),
        '{}'::text[]
      )
    INTO v_new_diff, v_changed_fields
    FROM jsonb_each(v_new_full) new_pair
    WHERE v_old_full -> new_pair.key IS DISTINCT FROM new_pair.value;

    IF cardinality(v_changed_fields) = 0 THEN
      RETURN NEW;
    END IF;

    SELECT COALESCE(jsonb_object_agg(old_pair.key, old_pair.value), '{}'::jsonb)
    INTO v_old_diff
    FROM jsonb_each(v_old_full) old_pair
    WHERE old_pair.key = ANY(v_changed_fields);
  ELSIF TG_OP = 'INSERT' THEN
    v_new_diff := v_new_full;
    v_changed_fields := ARRAY(SELECT jsonb_object_keys(v_new_full));
  ELSE
    v_old_diff := v_old_full;
    v_changed_fields := ARRAY(SELECT jsonb_object_keys(v_old_full));
  END IF;

  v_entity_id := CASE
    WHEN TG_OP = 'DELETE' THEN v_old_full ->> 'id'
    ELSE v_new_full ->> 'id'
  END;

  INSERT INTO public.system_audit_logs (
    user_id,
    user_name,
    user_email,
    user_role,
    action,
    entity,
    entity_id,
    old_value,
    new_value,
    metadata,
    created_at
  )
  VALUES (
    (SELECT auth.uid()),
    v_profile.name,
    v_profile.email,
    v_profile.role,
    lower(TG_OP),
    TG_TABLE_NAME,
    v_entity_id,
    v_old_diff,
    v_new_diff,
    jsonb_build_object(
      'trigger', true,
      'table', TG_TABLE_NAME,
      'changed_fields', v_changed_fields
    ),
    now()
  );

  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$function$

CREATE OR REPLACE FUNCTION public.authorize_special_release(p_piece_id uuid, p_stage text, p_reason text, p_justification text, p_impact text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_piece record;
  v_user_id uuid;
  v_role text;
  v_new_completed_steps text[];
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Autenticação necessária.');
  END IF;

  v_role := public.get_my_role();
  IF v_role NOT IN ('admin', 'manager') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Apenas Administradores ou Gestores podem autorizar Liberação Especial.');
  END IF;

  SELECT * INTO v_piece FROM public.production_pieces WHERE id = p_piece_id;
  IF v_piece.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Peça não encontrada.');
  END IF;

  -- Registrar na tabela de exceções
  INSERT INTO public.flow_exceptions (
    piece_id, skipped_stage, reason, justification, impact, authorized_by
  ) VALUES (
    p_piece_id, p_stage, p_reason, p_justification, p_impact, v_user_id
  );

  -- Adicionar etapa liberada ao completed_steps da peça
  IF NOT (p_stage = ANY(v_piece.completed_steps)) THEN
    v_new_completed_steps := array_append(v_piece.completed_steps, p_stage);
  ELSE
    v_new_completed_steps := v_piece.completed_steps;
  END IF;

  UPDATE public.production_pieces SET
    completed_steps = v_new_completed_steps,
    is_blocked = false,
    block_reason = NULL,
    updated_at = now()
  WHERE id = p_piece_id;

  -- Gravar evento de correção
  INSERT INTO public.production_events (
    piece_id, traceability_code, production_order_id, lot_id,
    event_type, from_stage, to_stage, event_status, notes
  ) VALUES (
    v_piece.id, v_piece.traceability_code, v_piece.production_order_id, v_piece.lot_id,
    'correction', v_piece.current_stage, p_stage, 'accepted', 'Liberação Especial: ' || p_justification
  );

  RETURN jsonb_build_object('success', true, 'piece_id', p_piece_id, 'stage_released', p_stage);
END;
$function$

