CREATE OR REPLACE FUNCTION public.block_piece(p_piece_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_piece    production_pieces%ROWTYPE;
  v_user_id  uuid;
  v_role     text;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Autenticação necessária.');
  END IF;

  v_role := get_my_role();
  IF v_role NOT IN ('admin', 'manager') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Apenas admin ou manager podem bloquear peças.');
  END IF;

  IF TRIM(COALESCE(p_reason, '')) = '' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Motivo de bloqueio é obrigatório.');
  END IF;

  SELECT * INTO v_piece FROM production_pieces WHERE id = p_piece_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Peça não encontrada.');
  END IF;

  UPDATE production_pieces SET
    is_blocked   = true,
    block_reason = p_reason,
    blocked_at   = now(),
    blocked_by   = v_user_id,
    status       = 'blocked',
    updated_at   = now()
  WHERE id = p_piece_id;

  INSERT INTO production_events (
    piece_id, traceability_code, production_order_id, lot_id,
    event_type, from_stage, to_stage, event_status, notes
  ) VALUES (
    v_piece.id, v_piece.traceability_code, v_piece.production_order_id, v_piece.lot_id,
    'block', v_piece.current_stage, v_piece.current_stage, 'accepted', p_reason
  );

  RETURN jsonb_build_object(
    'success',      true,
    'piece_id',     v_piece.id,
    'piece_uid',    v_piece.piece_uid,
    'block_reason', p_reason
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.calcular_integridade_do_lote_impl(p_lot_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_lot record;
  v_total_pieces bigint;
  v_approved_pieces bigint;
  v_pending_pieces bigint := 0;
  v_blocked_pieces bigint;
  v_rejected_pieces bigint;
  v_rework_pieces bigint;
  v_replacement_pieces bigint;
  v_packed_pieces bigint;

  v_integrity_percent numeric(5,2) := 0.00;
  v_has_open_replacements boolean := false;
  v_has_open_reworks boolean := false;

  v_bottleneck text := 'Nenhum';
  v_most_pending_stage text := 'Nenhuma';
  v_can_close boolean := false;
BEGIN
  SELECT * INTO v_lot FROM public.production_lots WHERE id = p_lot_id;
  IF v_lot.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Lote não encontrado.');
  END IF;

  -- Contagens de peças canônicas
  SELECT COUNT(*),
         COUNT(*) FILTER (
           WHERE NOT EXISTS (
             SELECT 1
             FROM unnest(COALESCE(piece.route_steps, '{}'::text[])) route_step
             WHERE NOT (
               route_step = ANY(COALESCE(piece.completed_steps, '{}'::text[]))
             )
               AND COALESCE((
                 SELECT policy.traceable_collection_required
                 FROM public.production_stage_policies policy
                 WHERE policy.stage_code = route_step
               ), true)
           )
         )
  INTO v_total_pieces, v_approved_pieces
  FROM public.production_pieces piece
  WHERE piece.lot_id = p_lot_id
    AND piece.status <> 'cancelled'
    AND piece.status <> 'replaced';

  SELECT COUNT(*) FILTER (WHERE is_blocked = true),
         COUNT(*) FILTER (WHERE status = 'rejected'),
         COUNT(*) FILTER (WHERE status = 'rework_pending' OR status = 'rework_in_progress' OR rework_status = 'in_progress'),
         COUNT(*) FILTER (WHERE status = 'replacement_in_production' OR status = 'replacement_requested' OR replacement_status = 'in_production'),
         COUNT(*) FILTER (WHERE status = 'packed' OR packaging_status = 'packed')
  INTO v_blocked_pieces, v_rejected_pieces, v_rework_pieces, v_replacement_pieces, v_packed_pieces
  FROM public.production_pieces WHERE lot_id = p_lot_id AND status <> 'cancelled' AND status <> 'replaced';

  -- Contar peças que possuem etapas pendentes na rota
  DECLARE
    v_piece record;
    v_step text;
    v_is_pending boolean;
  BEGIN
    FOR v_piece IN SELECT * FROM public.production_pieces WHERE lot_id = p_lot_id AND status <> 'cancelled' AND status <> 'replaced' LOOP
      v_is_pending := false;
      IF v_piece.route_steps IS NOT NULL THEN
        FOREACH v_step IN ARRAY v_piece.route_steps LOOP
          IF NOT (v_step = ANY(COALESCE(v_piece.completed_steps, '{}'::text[])))
             AND COALESCE((
               SELECT policy.traceable_collection_required
               FROM public.production_stage_policies policy
               WHERE policy.stage_code = v_step
             ), true)
          THEN
            v_is_pending := true;
          END IF;
        END LOOP;
      END IF;
      IF v_is_pending THEN
        v_pending_pieces := v_pending_pieces + 1;
      END IF;
    END LOOP;
  END;

  -- Calcular percentual
  IF v_total_pieces > 0 THEN
    v_integrity_percent := ROUND((v_approved_pieces::numeric / v_total_pieces::numeric) * 100, 2);
  ELSE
    v_integrity_percent := 100.00;
  END IF;

  -- Checar ordens em aberto
  IF EXISTS (SELECT 1 FROM public.replacement_orders WHERE lot_id = p_lot_id AND status IN ('Reposição solicitada', 'Reposição em produção')) THEN
    v_has_open_replacements := true;
  END IF;
  IF EXISTS (SELECT 1 FROM public.rework_orders o JOIN public.production_pieces p ON p.id = o.original_piece_id WHERE p.lot_id = p_lot_id AND o.status IN ('pending', 'in_progress')) THEN
    v_has_open_reworks := true;
  END IF;

  -- O lote só pode ser fechado se todas as peças estão aprovadas, nenhuma pendência de rota, e nenhuma ordem em aberto
  IF v_approved_pieces = v_total_pieces AND v_pending_pieces = 0 AND NOT v_has_open_replacements AND NOT v_has_open_reworks AND v_blocked_pieces = 0 AND v_rejected_pieces = 0 THEN
    v_can_close := true;
  END IF;

  -- Determinar o gargalo (etapa obrigatória com mais peças acumuladas/não-concluídas)
  DECLARE
    v_stage_count record;
  BEGIN
    SELECT step_name, COUNT(*) as c INTO v_stage_count
    FROM (
      SELECT unnest(route_steps) as step_name
      FROM public.production_pieces
      WHERE lot_id = p_lot_id AND status <> 'cancelled' AND status <> 'replaced'
    ) r
    WHERE step_name NOT IN (
      SELECT unnest(COALESCE(completed_steps, '{}'::text[]))
      FROM public.production_pieces
      WHERE lot_id = p_lot_id AND status <> 'cancelled' AND status <> 'replaced'
    )
      AND COALESCE((
        SELECT policy.traceable_collection_required
        FROM public.production_stage_policies policy
        WHERE policy.stage_code = step_name
      ), true)
    GROUP BY step_name
    ORDER BY c DESC LIMIT 1;

    IF v_stage_count.step_name IS NOT NULL THEN
      SELECT name INTO v_most_pending_stage FROM public.routing_steps WHERE code = v_stage_count.step_name;
      v_most_pending_stage := COALESCE(v_most_pending_stage, v_stage_count.step_name);
      v_bottleneck := v_most_pending_stage || ' (' || v_stage_count.c || ' peças)';
    END IF;
  END;

  RETURN jsonb_build_object(
    'success', true,
    'lot_id', p_lot_id,
    'lot_code', v_lot.lot_code,
    'total_pieces', v_total_pieces,
    'approved_pieces', v_approved_pieces,
    'pending_pieces', v_pending_pieces,
    'blocked_pieces', v_blocked_pieces,
    'rejected_pieces', v_rejected_pieces,
    'rework_pieces', v_rework_pieces,
    'replacement_pieces', v_replacement_pieces,
    'packed_pieces', v_packed_pieces,
    'integrity_percent', v_integrity_percent,
    'has_open_replacements', v_has_open_replacements,
    'has_open_reworks', v_has_open_reworks,
    'bottleneck', v_bottleneck,
    'most_pending_stage', v_most_pending_stage,
    'can_close', v_can_close
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.calcular_integridade_do_lote(p_lot_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if auth.role() <> 'service_role'
     and not (
       public.has_permission('manage_lot_integrity')
       or public.has_permission('view_integrity_logs')
       or public.has_permission('view_traceability')
       or public.has_permission('view_pcp')
     ) then
    raise exception 'LOT_INTEGRITY_PERMISSION_REQUIRED' using errcode = '42501';
  end if;

  return public.calcular_integridade_do_lote_impl(p_lot_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.calculate_lot_status(p_lot_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
DECLARE
  v_total_items integer;
  v_completed   integer;
  v_scrap       integer;
  v_blocked     integer;
  v_in_progress integer;
  v_result      text;
BEGIN
  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE status = 'completed'),
    COUNT(*) FILTER (WHERE status = 'scrap'),
    COUNT(*) FILTER (WHERE status = 'blocked'),
    COUNT(*) FILTER (WHERE status = 'in_progress')
  INTO v_total_items, v_completed, v_scrap, v_blocked, v_in_progress
  FROM lot_items
  WHERE lot_id = p_lot_id;

  IF v_total_items = 0 THEN RETURN 'released'; END IF;
  IF v_blocked > 0 THEN RETURN 'blocked'; END IF;
  IF v_completed = v_total_items THEN RETURN 'completed'; END IF;
  IF v_in_progress > 0 THEN RETURN 'in_progress'; END IF;
  IF v_completed > 0 THEN RETURN 'partial'; END IF;
  RETURN 'planned';
END;
$function$

CREATE OR REPLACE FUNCTION public.can_manage_operator_scope(p_operator_id uuid, p_requested_cell_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_role text;
  v_primary_cell text;
  v_target_has_assignments boolean;
BEGIN
  IF (SELECT auth.uid()) IS NULL OR NOT public.can_manage_operators() THEN
    RETURN false;
  END IF;

  SELECT profile.role
  INTO v_role
  FROM public.profiles profile
  WHERE profile.id = (SELECT auth.uid())
    AND profile.active IS DISTINCT FROM false;

  IF v_role = 'admin' THEN
    RETURN true;
  END IF;

  IF p_requested_cell_ids IS NOT NULL AND EXISTS (
    SELECT 1
    FROM unnest(p_requested_cell_ids) requested(cell_id)
    LEFT JOIN public.cells cell ON cell.id = requested.cell_id AND cell.active IS TRUE
    WHERE cell.id IS NULL
       OR NOT public.profile_can_access_cell(cell.name)
  ) THEN
    RETURN false;
  END IF;

  IF p_operator_id IS NULL THEN
    RETURN true;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.operators operator WHERE operator.id = p_operator_id) THEN
    RETURN false;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.operator_cell_assignments assignment
    WHERE assignment.operator_id = p_operator_id
      AND assignment.active IS TRUE
  )
  INTO v_target_has_assignments;

  IF v_target_has_assignments THEN
    RETURN NOT EXISTS (
      SELECT 1
      FROM public.operator_cell_assignments assignment
      JOIN public.cells cell ON cell.id = assignment.cell_id
      WHERE assignment.operator_id = p_operator_id
        AND assignment.active IS TRUE
        AND NOT public.profile_can_access_cell(cell.name)
    );
  END IF;

  SELECT operator.primary_cell
  INTO v_primary_cell
  FROM public.operators operator
  WHERE operator.id = p_operator_id;

  RETURN public.current_profile_has_global_cell_access()
    OR public.profile_can_access_cell(v_primary_cell);
END;
$function$

CREATE OR REPLACE FUNCTION public.cancel_customer_cover(p_cover_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_operator uuid := auth.uid();
BEGIN
  IF v_operator IS NULL OR public.get_my_role() NOT IN ('admin','manager') THEN
    RAISE EXCEPTION 'Permissão insuficiente para cancelar capa de cliente.' USING ERRCODE = '42501';
  END IF;

  UPDATE public.customer_covers
  SET status = 'cancelled', notes = COALESCE(notes, '') || E'\nCancelado: ' || p_reason
  WHERE id = p_cover_id;

  -- Desvincular lotes para que possam ser reagrupados se necessário
  UPDATE public.production_lots
  SET customer_cover_id = NULL
  WHERE customer_cover_id = p_cover_id;

  -- Registrar evento
  INSERT INTO public.customer_cover_events (cover_id, event_type, operator_id, metadata)
  VALUES (p_cover_id, 'cancelled', v_operator, jsonb_build_object('reason', p_reason));

  RETURN jsonb_build_object('success', true);
END;
$function$

CREATE OR REPLACE FUNCTION public.cancel_piece_replacement_impl(p_order_id uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE v_reason text := p_payload->>'reason';
BEGIN
  UPDATE public.replacement_orders SET status='cancelled',cancelled_at=now(),notes=COALESCE(notes,'')||' | Cancelado: '||COALESCE(v_reason,'Sem motivo informado'),updated_at=now() WHERE id=p_order_id;
  RETURN jsonb_build_object('success',true,'status','cancelled');
END;
$function$

CREATE OR REPLACE FUNCTION public.cancel_piece_replacement(p_order_id uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if not (select public.can_manage_quality()) then
    raise exception 'QUALITY_PERMISSION_REQUIRED' using errcode = '42501';
  end if;
  return public.cancel_piece_replacement_impl(p_order_id, p_payload);
end;
$function$

CREATE OR REPLACE FUNCTION public.cancel_piece(p_piece_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_piece   production_pieces%ROWTYPE;
  v_user_id uuid;
  v_role    text;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Autenticação necessária.');
  END IF;

  v_role := get_my_role();
  IF v_role NOT IN ('admin', 'manager') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Apenas admin ou manager podem cancelar peças.');
  END IF;

  IF TRIM(COALESCE(p_reason, '')) = '' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Motivo de cancelamento é obrigatório.');
  END IF;

  SELECT * INTO v_piece FROM production_pieces WHERE id = p_piece_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Peça não encontrada.');
  END IF;

  IF v_piece.status = 'shipped' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Peça já expedida não pode ser cancelada.');
  END IF;

  UPDATE production_pieces SET
    status     = 'cancelled',
    is_blocked = true,
    block_reason = 'CANCELADA: ' || p_reason,
    updated_at = now()
  WHERE id = p_piece_id;

  INSERT INTO production_events (
    piece_id, traceability_code, production_order_id, lot_id,
    event_type, from_stage, to_stage, event_status, notes
  ) VALUES (
    v_piece.id, v_piece.traceability_code, v_piece.production_order_id, v_piece.lot_id,
    'cancel', v_piece.current_stage, 'cancelled', 'accepted', p_reason
  );

  RETURN jsonb_build_object(
    'success',  true,
    'piece_id', v_piece.id,
    'piece_uid', v_piece.piece_uid,
    'reason',   p_reason
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.canonical_stage_label(p_stage text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_str text := LOWER(TRIM(COALESCE(p_stage, '')));
BEGIN
  IF v_str IN ('cut', 'corte') THEN RETURN 'Corte'; END IF;
  IF v_str IN ('edge', 'borda', 'bordo') THEN RETURN 'Borda'; END IF;
  IF v_str IN ('drill', 'furacao', 'furação') THEN RETURN 'Furação'; END IF;
  IF v_str IN ('cnc', 'usinagem cnc', 'usinagem') THEN RETURN 'Usinagem CNC'; END IF;
  IF v_str IN ('joinery', 'marcenaria') THEN RETURN 'Marcenaria'; END IF;
  IF v_str IN ('separation', 'separacao', 'separação') THEN RETURN 'Separação'; END IF;
  IF v_str IN ('packaging', 'embalagem') THEN RETURN 'Embalagem'; END IF;
  IF v_str IN ('shipping', 'expedicao', 'expedição') THEN RETURN 'Expedição'; END IF;
  IF v_str IN ('created', 'criada') THEN RETURN 'Criada'; END IF;
  IF v_str IN ('completed', 'concluida', 'concluída') THEN RETURN 'Concluída'; END IF;
  RETURN INITCAP(v_str);
END;
$function$

CREATE OR REPLACE FUNCTION public.canonicalize_rejection_context()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_stage text;
  v_reading record;
begin
  if tg_table_name = 'production_stage_readings' then
    if new.status in ('rejected', 'pending_review') then
      v_stage := public.resolve_production_stage_for_cell(null, new.cell_name);
      if v_stage is not null then
        new.step_name := v_stage;
        new.operation_name := v_stage;
      end if;
    end if;
    return new;
  end if;

  if tg_table_name = 'quality_nonconformities' then
    v_stage := public.resolve_production_stage_for_cell(new.cell_id, new.cell_name);
    if v_stage is not null then
      new.stage_name := v_stage;
    end if;
    return new;
  end if;

  v_stage := public.resolve_production_stage_for_cell(new.origin_cell_id, new.origin_cell_name);

  if v_stage is null and new.original_piece_id is not null then
    select reading.step_name, reading.cell_name
      into v_reading
    from public.production_stage_readings reading
    where reading.piece_id = new.original_piece_id
      and reading.status in ('rejected', 'pending_review')
    order by reading.created_at desc, reading.id desc
    limit 1;

    v_stage := public.resolve_production_stage_for_cell(null, v_reading.cell_name);
    v_stage := coalesce(v_stage, public.normalize_replacement_step_code(v_reading.step_name));
    new.origin_cell_name := coalesce(nullif(new.origin_cell_name, ''), v_reading.cell_name);
  end if;

  if new.origin_cell_id is null and nullif(new.origin_cell_name, '') is not null then
    select cell.id into new.origin_cell_id
    from public.cells cell
    where public.normalize_production_name(cell.name)
      = public.normalize_production_name(new.origin_cell_name)
    order by coalesce(cell.active, true) desc, cell.created_at
    limit 1;
  end if;

  if v_stage is not null then
    new.rejection_stage := v_stage;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_collection_batch_v3(p_worker_id text, p_limit integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pgmq', 'pg_temp'
AS $function$
DECLARE
  v_worker_id text := left(coalesce(nullif(btrim(p_worker_id), ''), gen_random_uuid()::text), 160);
  v_limit integer := greatest(5, least(coalesce(p_limit, 10), 25));
  v_live_limit integer;
  v_replay_limit integer;
  v_live jsonb := '[]'::jsonb;
  v_replay jsonb := '[]'::jsonb;
  v_spill jsonb := '[]'::jsonb;
  v_claimed jsonb := '[]'::jsonb;
  v_now timestamptz := clock_timestamp();
  v_worker_enabled boolean := false;
  v_broadcast_enabled boolean := false;
  v_claim_count integer := 0;
  v_broadcast_row record;
BEGIN
  SELECT coalesce(flag.enabled, false)
  INTO v_worker_enabled
  FROM private.collection_pipeline_flags flag
  WHERE flag.flag_name = 'collection_pipeline_v3_worker';

  IF NOT coalesce(v_worker_enabled, false) THEN
    RETURN '[]'::jsonb;
  END IF;

  SELECT coalesce(flag.enabled, false)
  INTO v_broadcast_enabled
  FROM private.collection_pipeline_flags flag
  WHERE flag.flag_name = 'collection_pipeline_v3_broadcast';

  IF (
    SELECT count(*)
    FROM private.collection_projection_trigger_registry registry
    WHERE registry.guard_installed IS TRUE
  ) < 3 THEN
    RAISE EXCEPTION 'COLLECTION_V3_TRIGGER_GUARDS_REQUIRED'
      USING ERRCODE = '55000';
  END IF;

  v_live_limit := greatest(1, ceil(v_limit * 0.8)::integer);
  v_replay_limit := greatest(1, v_limit - v_live_limit);

  SELECT coalesce(jsonb_agg(to_jsonb(message_row)), '[]'::jsonb)
  INTO v_live
  FROM pgmq.read('collection_live_v3', 45, v_live_limit) AS message_row;

  SELECT coalesce(jsonb_agg(to_jsonb(message_row)), '[]'::jsonb)
  INTO v_replay
  FROM pgmq.read('collection_replay_v3', 45, v_replay_limit) AS message_row;

  -- A proporção 4:1 vale quando as duas filas têm trabalho. Capacidade ociosa
  -- de uma delas é cedida à outra, evitando limitar live a 80% ou drenar replay
  -- a apenas 20% quando não há competição.
  IF jsonb_array_length(v_live) + jsonb_array_length(v_replay) < v_limit THEN
    IF jsonb_array_length(v_live) < v_live_limit THEN
      SELECT coalesce(jsonb_agg(to_jsonb(message_row)), '[]'::jsonb)
      INTO v_spill
      FROM pgmq.read(
        'collection_replay_v3',
        45,
        v_limit - jsonb_array_length(v_live) - jsonb_array_length(v_replay)
      ) AS message_row;
      v_replay := v_replay || v_spill;
    ELSIF jsonb_array_length(v_replay) < v_replay_limit THEN
      SELECT coalesce(jsonb_agg(to_jsonb(message_row)), '[]'::jsonb)
      INTO v_spill
      FROM pgmq.read(
        'collection_live_v3',
        45,
        v_limit - jsonb_array_length(v_live) - jsonb_array_length(v_replay)
      ) AS message_row;
      v_live := v_live || v_spill;
    END IF;
  END IF;

  SELECT coalesce(jsonb_agg(item.payload), '[]'::jsonb)
  INTO v_claimed
  FROM (
    SELECT jsonb_set(value, '{queue_name}', '"collection_live_v3"'::jsonb, true) AS payload
    FROM jsonb_array_elements(v_live)
    UNION ALL
    SELECT jsonb_set(value, '{queue_name}', '"collection_replay_v3"'::jsonb, true) AS payload
    FROM jsonb_array_elements(v_replay)
  ) item;

  v_claim_count := jsonb_array_length(v_claimed);

  WITH claimed AS (
    SELECT
      item.value ->> 'queue_name' AS queue_name,
      private.try_collection_bigint_v3(item.value ->> 'msg_id') AS msg_id,
      greatest(1, coalesce(private.try_collection_bigint_v3(item.value ->> 'read_ct'), 1))::integer AS attempt_number,
      private.try_collection_timestamptz_v3(item.value ->> 'enqueued_at') AS enqueued_at,
      private.try_collection_uuid_v3(item.value -> 'message' ->> 'receipt_id') AS receipt_id,
      item.value -> 'message' ->> 'client_event_id' AS client_event_id
    FROM jsonb_array_elements(v_claimed) item(value)
  ), updated AS (
    UPDATE public.coletas_producao receipt
    SET status_sincronizacao = 'processando',
        claimed_at = v_now,
        lease_expires_at = v_now + interval '45 seconds',
        worker_id = v_worker_id,
        attempt_count = greatest(receipt.attempt_count, claimed.attempt_number),
        queue_delay_ms = extract(epoch FROM (v_now - coalesce(receipt.enqueued_at, receipt.received_at_db))) * 1000,
        updated_at = v_now
    FROM claimed
    WHERE receipt.id = claimed.receipt_id
      AND receipt.client_event_id = claimed.client_event_id
      AND receipt.pipeline_version = 3
    RETURNING receipt.client_event_id, receipt.queue_delay_ms
  )
  INSERT INTO public.collection_processing_attempts (
    client_event_id,
    attempt_number,
    worker_id,
    queue_name,
    claimed_at,
    queue_delay_ms
  )
  SELECT
    claimed.client_event_id,
    claimed.attempt_number,
    v_worker_id,
    claimed.queue_name,
    v_now,
    updated.queue_delay_ms
  FROM claimed
  JOIN updated USING (client_event_id)
  ON CONFLICT (client_event_id, attempt_number) DO NOTHING;

  INSERT INTO private.collection_worker_heartbeats (
    worker_id, worker_kind, invocation_id, started_at, heartbeat_at,
    finished_at, claimed_count, finalized_count, last_error_code
  ) VALUES (
    v_worker_id, 'decision', split_part(v_worker_id, ':', 2), v_now, v_now,
    NULL, v_claim_count, 0, NULL
  )
  ON CONFLICT (worker_id) DO UPDATE
  SET heartbeat_at = excluded.heartbeat_at,
      finished_at = NULL,
      claimed_count = excluded.claimed_count,
      finalized_count = 0,
      last_error_code = NULL;

  IF v_broadcast_enabled
     AND to_regprocedure('realtime.send(jsonb,text,text,boolean)') IS NOT NULL THEN
    FOR v_broadcast_row IN
      SELECT receipt.client_event_id, receipt.device_id, receipt.cell_id
      FROM public.coletas_producao receipt
      WHERE receipt.worker_id = v_worker_id
        AND receipt.pipeline_version = 3
        AND receipt.status_sincronizacao = 'processando'
    LOOP
      IF v_broadcast_row.device_id IS NOT NULL THEN
        PERFORM realtime.send(
          jsonb_build_object(
            'client_event_id', v_broadcast_row.client_event_id,
            'state', 'PROCESSING',
            'processing_started_at', v_now
          ),
          'collection.processing',
          'collection:device:' || v_broadcast_row.device_id,
          true
        );
      END IF;
    END LOOP;
  END IF;

  RETURN v_claimed;
END;
$function$

CREATE OR REPLACE FUNCTION public.claim_collection_projection_batch_v3(p_worker_id text, p_limit integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pgmq', 'pg_temp'
AS $function$
DECLARE
  v_worker_id text := left(coalesce(nullif(btrim(p_worker_id), ''), gen_random_uuid()::text), 160);
  v_limit integer := greatest(5, least(coalesce(p_limit, 10), 25));
  v_claimed jsonb := '[]'::jsonb;
  v_now timestamptz := clock_timestamp();
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM private.collection_pipeline_flags flag
    WHERE flag.flag_name = 'collection_pipeline_v3_projection'
      AND flag.enabled IS TRUE
  ) THEN
    RETURN '[]'::jsonb;
  END IF;

  SELECT coalesce(jsonb_agg(
    jsonb_set(to_jsonb(message_row), '{queue_name}', '"collection_projection_v3"'::jsonb, true)
  ), '[]'::jsonb)
  INTO v_claimed
  FROM pgmq.read('collection_projection_v3', 60, v_limit) AS message_row;

  WITH claimed AS (
    SELECT
      private.try_collection_uuid_v3(item.value -> 'message' ->> 'outbox_id') AS outbox_id,
      greatest(1, coalesce(private.try_collection_bigint_v3(item.value ->> 'read_ct'), 1))::integer AS read_ct
    FROM jsonb_array_elements(v_claimed) item(value)
  )
  UPDATE public.collection_projection_outbox outbox
  SET attempt_count = greatest(outbox.attempt_count, claimed.read_ct),
      available_at = v_now
  FROM claimed
  WHERE outbox.id = claimed.outbox_id
    AND outbox.projected_at IS NULL
    AND outbox.dead_lettered_at IS NULL;

  INSERT INTO private.collection_worker_heartbeats (
    worker_id, worker_kind, invocation_id, started_at, heartbeat_at,
    finished_at, claimed_count, finalized_count, last_error_code
  ) VALUES (
    v_worker_id, 'projection', split_part(v_worker_id, ':', 2), v_now, v_now,
    NULL, jsonb_array_length(v_claimed), 0, NULL
  )
  ON CONFLICT (worker_id) DO UPDATE
  SET heartbeat_at = excluded.heartbeat_at,
      finished_at = NULL,
      claimed_count = excluded.claimed_count,
      finalized_count = 0,
      last_error_code = NULL;

  RETURN v_claimed;
END;
$function$

CREATE OR REPLACE FUNCTION public.cleanup_capacity_fixture_v3(p_run_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
DECLARE
  v_sessions integer;
  v_operators integer;
  v_machines integer;
  v_pieces integer;
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION 'SERVICE_ROLE_REQUIRED' USING ERRCODE = '42501';
  END IF;

  UPDATE public.operator_sessions session
  SET ended_at = coalesce(ended_at, clock_timestamp()),
      end_reason = coalesce(end_reason, 'capacity_test_cleanup')
  WHERE session.operator_id IN (
    SELECT entity_id FROM private.capacity_test_fixture_objects
    WHERE run_id = p_run_id AND entity_kind = 'operator'
  ) AND session.ended_at IS NULL;
  GET DIAGNOSTICS v_sessions = ROW_COUNT;

  UPDATE public.operators operator_row
  SET active = false, login_enabled = false,
      deactivated_at = coalesce(deactivated_at, clock_timestamp())
  WHERE operator_row.id IN (
    SELECT entity_id FROM private.capacity_test_fixture_objects
    WHERE run_id = p_run_id AND entity_kind = 'operator'
  );
  GET DIAGNOSTICS v_operators = ROW_COUNT;

  UPDATE public.production_machines machine
  SET active = false, updated_at = clock_timestamp()
  WHERE machine.id IN (
    SELECT entity_id FROM private.capacity_test_fixture_objects
    WHERE run_id = p_run_id AND entity_kind = 'machine' AND created_by_test IS TRUE
  );
  GET DIAGNOSTICS v_machines = ROW_COUNT;

  UPDATE public.production_pieces piece
  SET status = 'cancelled', is_active = false, production_status = 'CAPTEST_ARCHIVED', updated_at = clock_timestamp()
  WHERE piece.id IN (
    SELECT entity_id FROM private.capacity_test_fixture_objects
    WHERE run_id = p_run_id AND entity_kind = 'production_piece'
  );
  GET DIAGNOSTICS v_pieces = ROW_COUNT;

  UPDATE public.production_lots SET status='cancelled', updated_at=clock_timestamp()
  WHERE id IN (SELECT entity_id FROM private.capacity_test_fixture_objects WHERE run_id=p_run_id AND entity_kind='production_lot');
  UPDATE public.production_orders SET status='cancelled', updated_at=clock_timestamp()
  WHERE id IN (SELECT entity_id FROM private.capacity_test_fixture_objects WHERE run_id=p_run_id AND entity_kind='production_order');

  RETURN jsonb_build_object('run_id',p_run_id,'sessions_ended',v_sessions,'operators_disabled',v_operators,'machines_disabled',v_machines,'pieces_archived',v_pieces);
END;
$function$

CREATE OR REPLACE FUNCTION public.collect_replacement_stage_v2(p_session_token text, p_barcode text, p_client_event_id uuid, p_device_id text, p_created_at_client timestamp with time zone, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
declare
  v_auth_user_id uuid := auth.uid();
  v_now timestamptz := clock_timestamp();
  v_code text := btrim(coalesce(p_barcode, ''));
  v_device_id text := btrim(coalesce(p_device_id, ''));
  v_session public.operator_sessions%rowtype;
  v_operator public.operators%rowtype;
  v_cell public.cells%rowtype;
  v_machine public.production_machines%rowtype;
  v_order public.replacement_orders%rowtype;
  v_replacement_piece public.production_pieces%rowtype;
  v_original_piece public.production_pieces%rowtype;
  v_route text[];
  v_completed text[];
  v_expected_code text;
  v_expected_label text;
  v_current_code text;
  v_next_code text;
  v_next_label text;
  v_current_position integer;
  v_expected_position integer;
  v_is_last boolean := false;
  v_reading_id uuid;
  v_existing_result jsonb;
  v_result jsonb;
  v_lot_result jsonb;
  v_next_cell_id uuid;
  v_offline_reconciliation boolean := coalesce((p_payload ->> 'queued_offline')::boolean, false);
begin
  if v_auth_user_id is null then
    return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'AUTH_REQUIRED', 'message', 'Autenticacao do sistema expirada.');
  end if;
  if v_code = '' then
    return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'EMPTY_BARCODE', 'message', 'Codigo de barras nao informado.');
  end if;
  if p_client_event_id is null then
    return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'CLIENT_EVENT_REQUIRED', 'message', 'Identificador idempotente da leitura nao informado.');
  end if;
  if v_device_id = '' then
    return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'DEVICE_REQUIRED', 'message', 'Dispositivo do posto nao identificado.');
  end if;

  select event.result_payload into v_existing_result
  from public.production_collection_events event
  where event.client_event_id = p_client_event_id::text;
  if v_existing_result is not null then
    return v_existing_result || jsonb_build_object('idempotent', true);
  end if;

  select * into v_session
  from public.operator_sessions session_row
  where session_row.token_hash = encode(extensions.digest(coalesce(p_session_token, ''), 'sha256'), 'hex')
    and session_row.auth_user_id = v_auth_user_id
  for update;

  if v_session.id is null then
    return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'SESSION_INVALID', 'message', 'Sessao operacional nao localizada para este usuario.');
  end if;
  if v_session.revoked_at is not null then
    return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'SESSION_REVOKED', 'message', 'Sessao operacional revogada. Realize novo login.');
  end if;
  if v_session.ended_at is not null then
    return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'SESSION_ENDED', 'message', 'Sessao operacional encerrada. Realize novo login.');
  end if;
  if v_session.device_id is distinct from v_device_id then
    return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'DEVICE_MISMATCH', 'message', 'A sessao pertence a outro dispositivo.');
  end if;
  if v_session.expires_at <= v_now and not (
    v_offline_reconciliation
    and p_created_at_client is not null
    and p_created_at_client <= v_session.expires_at
    and v_now <= coalesce(v_session.sync_grace_until, v_session.expires_at + interval '24 hours')
  ) then
    return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'SESSION_EXPIRED', 'message', 'Sessao operacional expirada. Realize novo login.');
  end if;
  if v_session.cell_id is null then
    return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'CONTEXT_REQUIRED', 'message', 'Selecione a celula e o posto antes de bipar.');
  end if;

  select * into v_operator from public.operators where id = v_session.operator_id;
  if v_operator.id is null or v_operator.active is not true or coalesce(v_operator.login_enabled, true) is not true then
    return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'OPERATOR_INACTIVE', 'message', 'Operador inativo ou sem acesso a coleta.');
  end if;

  select * into v_cell from public.cells where id = v_session.cell_id and active = true;
  if v_cell.id is null then
    return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'WRONG_CELL', 'message', 'Celula da sessao inativa ou inexistente.');
  end if;

  if not exists (
    select 1 from public.operator_cell_assignments assignment
    where assignment.operator_id = v_operator.id
      and assignment.cell_id = v_cell.id
      and assignment.active = true
      and assignment.valid_from <= v_now
      and (assignment.valid_until is null or assignment.valid_until > v_now)
  ) then
    return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'OPERATOR_UNAUTHORIZED', 'message', 'Operador nao autorizado para esta celula.');
  end if;

  if v_session.machine_id is not null then
    select * into v_machine from public.production_machines where id = v_session.machine_id;
    if v_machine.id is null
       or v_machine.active is not true
       or v_machine.allows_replacement is not true then
      return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'MACHINE_INACTIVE', 'message', 'Maquina inativa ou nao habilitada para reposicao.');
    end if;
    if lower(btrim(v_machine.cell_name)) <> lower(btrim(v_cell.name)) then
      return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'WRONG_MACHINE', 'message', 'Maquina nao pertence a celula da sessao.');
    end if;
    if exists (
      select 1 from public.operator_machine_assignments assignment
      where assignment.operator_id = v_operator.id
        and assignment.active = true
        and assignment.valid_from <= v_now
        and (assignment.valid_until is null or assignment.valid_until > v_now)
    ) and not exists (
      select 1 from public.operator_machine_assignments assignment
      where assignment.operator_id = v_operator.id
        and assignment.machine_id = v_machine.id
        and assignment.active = true
        and assignment.valid_from <= v_now
        and (assignment.valid_until is null or assignment.valid_until > v_now)
    ) then
      return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'OPERATOR_UNAUTHORIZED', 'message', 'Operador nao autorizado para esta maquina.');
    end if;
  end if;

  if exists (
    select 1 from public.workstation_operator_authorizations authz
    where authz.is_active = true
      and authz.training_validated = true
      and authz.valid_from <= v_now
      and (authz.valid_until is null or authz.valid_until > v_now)
      and (authz.cell_id = v_cell.id or authz.machine_id = v_session.machine_id)
  ) and not exists (
    select 1 from public.workstation_operator_authorizations authz
    where authz.operator_id = v_operator.id
      and authz.is_active = true
      and authz.training_validated = true
      and authz.valid_from <= v_now
      and (authz.valid_until is null or authz.valid_until > v_now)
      and (authz.cell_id = v_cell.id or authz.machine_id = v_session.machine_id)
      and (authz.shift is null or authz.shift = v_session.shift_snapshot)
  ) then
    return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'OPERATOR_UNAUTHORIZED', 'message', 'Operador sem autorizacao vigente para o posto.');
  end if;

  select replacement.* into v_order
  from public.replacement_orders replacement
  join public.production_pieces piece on piece.id = replacement.replacement_piece_id
  where replacement.replacement_piece_id is not null
    and (
      replacement.replacement_barcode = v_code
      or replacement.replacement_code = v_code
      or piece.piece_uid = v_code
      or piece.traceability_code = v_code
      or piece.piece_code = v_code
      or piece.id::text = v_code
    )
  order by case when replacement.status in ('released', 'in_production') then 0 else 1 end,
           replacement.created_at desc
  limit 1;

  if v_order.id is null then
    if exists (
      select 1
      from public.replacement_orders replacement
      join public.production_pieces original_piece on original_piece.id = replacement.original_piece_id
      where original_piece.piece_uid = v_code
         or original_piece.traceability_code = v_code
         or original_piece.piece_code = v_code
         or original_piece.id::text = v_code
    ) then
      return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'ORIGINAL_PIECE_NOT_ALLOWED', 'message', 'Bipe a etiqueta da peca substituta. A peca original permanece reprovada.');
    end if;
    return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'CODE_NOT_FOUND', 'message', 'Codigo inexistente ou sem ordem de reposicao vinculada.');
  end if;

  select * into v_order from public.replacement_orders where id = v_order.id for update;
  perform 1
  from public.production_pieces piece
  where piece.id in (v_order.original_piece_id, v_order.replacement_piece_id)
  order by piece.id
  for update;
  select * into v_replacement_piece from public.production_pieces where id = v_order.replacement_piece_id;
  select * into v_original_piece from public.production_pieces where id = v_order.original_piece_id;

  if v_order.status in ('cancelled', 'Cancelada') then
    return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'ORDER_CANCELLED', 'message', 'Ordem de reposicao cancelada.');
  end if;
  if v_order.status in ('completed', 'Finalizada') then
    return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'STAGE_ALREADY_COMPLETED', 'message', 'Reposicao ja concluida.');
  end if;
  if v_order.status not in ('released', 'in_production') then
    return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'ORDER_NOT_RELEASED', 'message', 'Ordem ainda nao foi liberada pela gestao.');
  end if;
  if v_replacement_piece.id is null or v_replacement_piece.is_replacement is not true
     or v_replacement_piece.original_piece_id is distinct from v_original_piece.id then
    return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'INVALID_REPLACEMENT_PIECE', 'message', 'Peca substituta invalida ou sem vinculo com a original.');
  end if;
  if v_replacement_piece.is_blocked is true or v_replacement_piece.status = 'blocked' then
    return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'PIECE_BLOCKED', 'message', coalesce(v_replacement_piece.block_reason, 'Peca bloqueada para producao.'));
  end if;
  if v_replacement_piece.lot_id is null then
    return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'LOT_NOT_FOUND', 'message', 'Peca substituta sem lote produtivo.');
  end if;

  v_route := coalesce(v_replacement_piece.route_steps, v_original_piece.route_steps, array[]::text[]);
  v_completed := coalesce(v_replacement_piece.completed_steps, array[]::text[]);
  v_current_code := public.normalize_replacement_step_code(v_cell.name);

  select route.code, route.ord::integer, public.canonical_stage_label(route.step)
  into v_expected_code, v_expected_position, v_expected_label
  from (
    select step, public.normalize_replacement_step_code(step) as code, ord
    from unnest(v_route) with ordinality route_step(step, ord)
  ) route
  where not exists (
    select 1 from unnest(v_completed) completed_step
    where public.normalize_replacement_step_code(completed_step) = route.code
  )
  order by route.ord
  limit 1;

  if v_expected_code is null then
    return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'STAGE_ALREADY_COMPLETED', 'message', 'Todas as etapas obrigatorias desta reposicao ja foram concluidas.');
  end if;

  select min(route.ord)::integer into v_current_position
  from (
    select public.normalize_replacement_step_code(step) as code, ord
    from unnest(v_route) with ordinality route_step(step, ord)
  ) route
  where route.code = v_current_code;

  if v_current_position is null then
    return jsonb_build_object(
      'success', false, 'result_status', 'blocked', 'reason_code', 'STAGE_NOT_IN_ROUTE',
      'expected_stage', v_expected_label, 'expected_cell', v_expected_label,
      'message', format('A celula %s nao pertence a rota desta peca.', v_cell.name)
    );
  end if;
  if v_current_code <> v_expected_code then
    return jsonb_build_object(
      'success', false,
      'result_status', 'blocked',
      'reason_code', case when v_current_position > v_expected_position then 'PREVIOUS_STAGE_PENDING' else 'WRONG_CELL' end,
      'expected_stage', v_expected_label,
      'expected_cell', v_expected_label,
      'message', format('Etapa anterior pendente. A proxima baixa obrigatoria e %s.', v_expected_label)
    );
  end if;

  if exists (select 1 from public.production_stage_readings where client_event_id = p_client_event_id::text) then
    select event.result_payload into v_existing_result
    from public.production_collection_events event
    where event.client_event_id = p_client_event_id::text;
    return coalesce(v_existing_result, jsonb_build_object(
      'success', true, 'result_status', 'approved', 'reason_code', 'IDEMPOTENT_EVENT',
      'replacement_order_id', v_order.id, 'completed_stage', v_expected_label,
      'message', 'Evento ja confirmado anteriormente.'
    )) || jsonb_build_object('idempotent', true);
  end if;

  select route.code, public.canonical_stage_label(route.step)
  into v_next_code, v_next_label
  from (
    select step, public.normalize_replacement_step_code(step) as code, ord
    from unnest(v_route) with ordinality route_step(step, ord)
  ) route
  where route.ord > v_expected_position
    and not exists (
      select 1 from unnest(v_completed) completed_step
      where public.normalize_replacement_step_code(completed_step) = route.code
    )
  order by route.ord
  limit 1;
  v_is_last := v_next_code is null;

  insert into public.production_stage_readings (
    lot_id, piece_id, item_id, tag_value, reader_type, step_name, cell_name,
    station_name, machine_id, machine_name, operator, operator_id,
    operator_name_snapshot, user_id, shift, date, hour, status, event_type,
    client_event_id, notes, created_at, quantity, production_order_id,
    lot_code, order_number, customer_name, environment_name, operation_name,
    piece_code, traceability_type, general_lot_code
  ) values (
    v_replacement_piece.lot_id,
    v_replacement_piece.id,
    v_replacement_piece.legacy_production_lot_item_id,
    v_code,
    'keyboard_barcode',
    v_expected_code,
    v_cell.name,
    coalesce(v_session.station_name_snapshot, 'Posto de Reposicao'),
    v_machine.id,
    v_machine.name,
    v_operator.name,
    v_operator.id,
    v_operator.name,
    v_auth_user_id,
    coalesce(v_session.shift_snapshot, v_operator.shift, '1'),
    current_date,
    to_char(v_now, 'HH24:MI'),
    'approved',
    'replacement_approval',
    p_client_event_id::text,
    format('Baixa real da reposicao %s em %s.', coalesce(v_order.replacement_code, v_order.id::text), v_expected_label),
    v_now,
    1,
    v_replacement_piece.production_order_id,
    coalesce(v_replacement_piece.lot_code, v_order.lot_code),
    coalesce(v_replacement_piece.order_number, v_order.order_number),
    coalesce(v_replacement_piece.customer_name, v_order.customer_name),
    coalesce(v_replacement_piece.environment_name, v_order.environment_name),
    v_expected_code,
    case when v_is_last then 'approved_via_replacement' else 'replacement_stage' end,
    coalesce(v_replacement_piece.general_lot_code, v_order.general_lot_code)
  ) returning id into v_reading_id;

  update public.production_pieces
  set completed_steps = array_append(v_completed, v_expected_code),
      current_stage = coalesce(v_next_code, 'completed'),
      status = case when v_is_last then 'completed' else 'in_production' end,
      replacement_status = case when v_is_last then 'replaced' else 'in_production' end,
      updated_at = v_now
  where id = v_replacement_piece.id;

  update public.production_pieces
  set status = case when v_is_last then 'replaced' else 'rejected' end,
      replacement_status = case when v_is_last then 'replaced' else 'in_production' end,
      updated_at = v_now
  where id = v_original_piece.id;

  update public.replacement_orders
  set status = case when v_is_last then 'completed' else 'in_production' end,
      completed_at = case when v_is_last then coalesce(completed_at, v_now) else completed_at end,
      updated_at = v_now
  where id = v_order.id;

  if v_is_last then
    update public.quality_nonconformities
    set status = 'resolved',
        closed_at = coalesce(closed_at, v_now),
        closed_by = coalesce(closed_by, v_auth_user_id),
        updated_at = v_now
    where related_replacement_id = v_order.id
       or piece_id = v_original_piece.id;
  end if;

  v_lot_result := public.recalculate_replacement_lot_v2(v_replacement_piece.lot_id);
  if v_is_last and coalesce((v_lot_result ->> 'lot_completed')::boolean, false) then
    update public.production_stage_readings
    set notes = concat_ws(' ', notes, v_lot_result ->> 'message')
    where id = v_reading_id;
  end if;

  v_result := jsonb_build_object(
    'success', true,
    'result_status', 'approved',
    'reason_code', 'STAGE_COLLECTED_SUCCESSFULLY',
    'client_event_id', p_client_event_id,
    'reading_id', v_reading_id,
    'replacement_order_id', v_order.id,
    'replacement_piece_id', v_replacement_piece.id,
    'replacement_code', v_order.replacement_code,
    'completed_stage', v_expected_label,
    'next_stage', v_next_label,
    'is_last_stage', v_is_last,
    'replacement_completed', v_is_last,
    'lot', v_lot_result,
    'message', case
      when v_is_last then format('%s concluida. Reposicao finalizada com rastreabilidade.', v_expected_label)
      else format('%s concluida. Peca liberada para %s.', v_expected_label, v_next_label)
    end
  );

  insert into public.production_collection_events (
    client_event_id, raw_value, normalized_value, reader_type, operator_id,
    operator_name, cell_name, cell_id, shift, date, hour, status, result_status,
    reading_id, lot_id, production_order_id, payload, result_payload,
    created_at_client, processed_at, operator_session_id, device_id, piece_id,
    machine_id, machine_name, station_name, operation_name, lot_code,
    order_number, customer_name, environment_name, piece_code, general_lot_code
  ) values (
    p_client_event_id::text, v_code, upper(v_code), 'keyboard_barcode', v_operator.id,
    v_operator.name, v_cell.name, v_cell.id, coalesce(v_session.shift_snapshot, v_operator.shift),
    current_date, to_char(v_now, 'HH24:MI'), 'synced', 'approved',
    v_reading_id, v_replacement_piece.lot_id, v_replacement_piece.production_order_id,
    coalesce(p_payload, '{}'::jsonb) || jsonb_build_object('event_kind', 'replacement_stage'),
    v_result, coalesce(p_created_at_client, v_now), v_now, v_session.id, v_device_id,
    v_replacement_piece.id, v_machine.id, v_machine.name,
    coalesce(v_session.station_name_snapshot, 'Posto de Reposicao'), v_expected_code,
    coalesce(v_replacement_piece.lot_code, v_order.lot_code),
    coalesce(v_replacement_piece.order_number, v_order.order_number),
    coalesce(v_replacement_piece.customer_name, v_order.customer_name),
    coalesce(v_replacement_piece.environment_name, v_order.environment_name),
    v_replacement_piece.piece_code,
    coalesce(v_replacement_piece.general_lot_code, v_order.general_lot_code)
  );

  insert into public.system_audit_logs (
    user_id, user_name, action, entity, entity_id, page, route, device_id,
    session_id, success, metadata
  ) values (
    v_auth_user_id, v_operator.name,
    case when v_is_last then 'replacement_completed_via_station' else 'replacement_stage_collected_v2' end,
    'replacement_orders', v_order.id::text, 'Posto de Reposicao', '/reposicao/posto',
    v_device_id, v_session.id::text, true,
    jsonb_build_object(
      'operator_id', v_operator.id,
      'cell_id', v_cell.id,
      'cell_name', v_cell.name,
      'machine_id', v_machine.id,
      'machine_name', v_machine.name,
      'shift', v_session.shift_snapshot,
      'barcode', v_code,
      'client_event_id', p_client_event_id,
      'completed_stage', v_expected_label,
      'next_stage', v_next_label,
      'lot_result', v_lot_result
    )
  );

  perform realtime.send(
    jsonb_build_object(
      'replacement_order_id', v_order.id,
      'replacement_code', v_order.replacement_code,
      'lot_code', coalesce(v_order.lot_code, v_replacement_piece.lot_code),
      'completed_stage', v_expected_label,
      'next_stage', v_next_label,
      'message', v_result ->> 'message'
    ),
    'replacement_queue_updated',
    format('replacement:cell:%s', v_cell.id),
    true
  );

  if v_next_code is not null then
    select cell.id into v_next_cell_id
    from public.cells cell
    where cell.active = true
      and public.normalize_replacement_step_code(cell.name) = v_next_code
    order by cell.name
    limit 1;
    if v_next_cell_id is not null and v_next_cell_id <> v_cell.id then
      perform realtime.send(
        jsonb_build_object(
          'replacement_order_id', v_order.id,
          'replacement_code', v_order.replacement_code,
          'lot_code', coalesce(v_order.lot_code, v_replacement_piece.lot_code),
          'completed_stage', v_expected_label,
          'next_stage', v_next_label,
          'message', format('Nova reposicao disponivel na sua celula: %s - Lote %s.', coalesce(v_order.replacement_code, 'REP'), coalesce(v_order.lot_code, v_replacement_piece.lot_code, '-'))
        ),
        'replacement_available',
        format('replacement:cell:%s', v_next_cell_id),
        true
      );
    end if;
  end if;

  return v_result;
exception
  when unique_violation then
    select event.result_payload into v_existing_result
    from public.production_collection_events event
    where event.client_event_id = p_client_event_id::text;
    if v_existing_result is not null then
      return v_existing_result || jsonb_build_object('idempotent', true);
    end if;
    return jsonb_build_object(
      'success', false,
      'result_status', 'blocked',
      'reason_code', 'STAGE_ALREADY_COMPLETED',
      'expected_stage', v_expected_label,
      'message', 'A etapa foi concluida simultaneamente em outro posto. Atualize a fila.'
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.collect_replacement_stage_v3(p_session_token text, p_barcode text, p_client_event_id uuid, p_device_id text, p_created_at_client timestamp with time zone, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
declare
  v_access jsonb;
begin
  v_access := private.validate_replacement_operator_session_v2(p_session_token, p_device_id, true);
  if coalesce((v_access ->> 'success')::boolean, false) is not true then
    return v_access || jsonb_build_object('result_status', 'blocked');
  end if;

  return public.collect_replacement_stage_v2(
    p_session_token,
    p_barcode,
    p_client_event_id,
    p_device_id,
    p_created_at_client,
    coalesce(p_payload, '{}'::jsonb)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.commit_pcp_import(p_batch_id uuid, p_order_code text, p_lot_code text, p_customer text, p_project_name text, p_mapping_profile text, p_mapping_version integer, p_rows jsonb, p_finalize boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET statement_timeout TO '55s'
AS $function$
DECLARE
  v_row jsonb;
  v_current_user uuid := auth.uid();
  v_order_id uuid;
  v_first_order_id uuid;
  v_lot_id uuid;
  v_piece_id uuid;
  v_lot_item_id uuid;
  v_route_steps text[];
  v_row_order_code text;
  v_row_general_lot_code text;
  v_row_lot_code text;
  v_row_customer text;
  v_row_project text;
  v_barcode text;
  v_check_barcode text;
  v_route text;
  v_piece_code text;
  v_piece_name text;
  v_manual_joinery boolean;
  v_quantity integer;
  v_material text;
  v_color text;
  v_thickness numeric;
  v_width numeric;
  v_height numeric;
  v_environment text;
  v_module text;
  v_piece_uid text;
  v_suffix text;
  v_inserted_pieces integer := 0;
  v_inserted_rows integer := 0;
  v_order_count integer := 0;
  v_lot_count integer := 0;
  v_customer_count integer := 0;
  v_total_batch_pieces integer := 0;
  v_total_batch_rows integer := 0;
  v_existing_batch_id uuid;
  v_batch_general_lot_code text;
  v_existing_lot_batch_id uuid;
  v_existing_lot_customer text;
  i integer;
BEGIN
  IF v_current_user IS NULL OR public.get_my_role() NOT IN ('admin','manager','supervisor') THEN
    RAISE EXCEPTION 'Usuário sem permissão para confirmar importação PCP.' USING ERRCODE = '42501';
  END IF;

  SELECT general_lot_code INTO v_batch_general_lot_code
  FROM public.promob_import_batches
  WHERE id = p_batch_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Lote de importação % não localizado.', p_batch_id USING ERRCODE = 'P0008';
  END IF;

  IF p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array' OR jsonb_array_length(p_rows) = 0 THEN
    RAISE EXCEPTION 'A importação PCP não contém linhas válidas.' USING ERRCODE = 'P0009';
  END IF;

  FOR v_row IN SELECT value FROM jsonb_array_elements(p_rows) LOOP
    v_row_order_code := COALESCE(NULLIF(TRIM(v_row->>'orderCode'), ''), NULLIF(TRIM(p_order_code), ''), 'PED-' || p_batch_id::text);
    v_row_general_lot_code := COALESCE(NULLIF(TRIM(v_row->>'generalLotCode'), ''), NULLIF(TRIM(p_lot_code), ''));
    v_row_lot_code := NULLIF(TRIM(v_row->>'clientLotCode'), '');
    v_row_customer := COALESCE(NULLIF(TRIM(v_row->>'customer'), ''), NULLIF(TRIM(p_customer), ''), 'Cliente não informado');
    v_row_project := COALESCE(NULLIF(TRIM(v_row->>'projectName'), ''), NULLIF(TRIM(p_project_name), ''), '');
    v_barcode := UPPER(TRIM(COALESCE(v_row->>'barcode', '')));
    v_check_barcode := UPPER(TRIM(COALESCE(v_row->>'checkBarcode', '')));
    v_route := TRIM(COALESCE(v_row->>'route', ''));
    v_piece_code := COALESCE(NULLIF(TRIM(v_row->>'pieceCode'), ''), v_barcode);
    v_piece_name := COALESCE(NULLIF(TRIM(v_row->>'pieceName'), ''), 'Sem nome');
    v_manual_joinery := COALESCE((v_row->>'manualJoinery')::boolean, false);
    v_quantity := 1;
    v_material := NULLIF(TRIM(v_row->>'material'), '');
    v_color := NULLIF(TRIM(v_row->>'color'), '');
    v_thickness := NULLIF(REPLACE(v_row->>'thickness', ',', '.'), '')::numeric;
    v_width := NULLIF(REPLACE(v_row->>'width', ',', '.'), '')::numeric;
    v_height := NULLIF(REPLACE(v_row->>'height', ',', '.'), '')::numeric;
    v_environment := NULLIF(TRIM(v_row->>'environmentName'), '');
    v_module := NULLIF(TRIM(v_row->>'moduleName'), '');

    IF v_barcode = '' THEN
      RAISE EXCEPTION 'Linha % sem código de barras.', COALESCE((v_row->>'row_number')::integer, v_inserted_rows + 1);
    END IF;
    IF v_row_general_lot_code IS NULL THEN
      RAISE EXCEPTION 'Linha % sem lote geral PCP.', COALESCE((v_row->>'row_number')::integer, v_inserted_rows + 1);
    END IF;
    IF v_batch_general_lot_code IS NULL OR v_batch_general_lot_code = '' THEN
      v_batch_general_lot_code := v_row_general_lot_code;
      UPDATE public.promob_import_batches
      SET general_lot_code = v_batch_general_lot_code
      WHERE id = p_batch_id;
    ELSIF v_batch_general_lot_code <> v_row_general_lot_code THEN
      RAISE EXCEPTION 'Linha % pertence ao lote geral %, mas esta importação é do lote geral %.',
        COALESCE((v_row->>'row_number')::integer, v_inserted_rows + 1),
        v_row_general_lot_code,
        v_batch_general_lot_code;
    END IF;
    IF v_row_lot_code IS NULL THEN
      RAISE EXCEPTION 'Linha % sem lote do cliente.', COALESCE((v_row->>'row_number')::integer, v_inserted_rows + 1);
    END IF;
    IF v_check_barcode <> '' AND v_check_barcode <> v_barcode THEN
      RAISE EXCEPTION 'Linha % com divergência entre código e conferência (% <> %).',
        COALESCE((v_row->>'row_number')::integer, v_inserted_rows + 1), v_barcode, v_check_barcode;
    END IF;

    INSERT INTO public.production_orders (
      order_code, system_order_number, order_number, customer_name,
      customer_legal_name, promob_project_name, status, created_by
    ) VALUES (
      v_row_order_code, v_row_order_code, v_row_order_code, v_row_customer,
      v_row_customer, v_row_project, 'planned', v_current_user
    )
    ON CONFLICT (order_code) DO UPDATE
    SET customer_name = CASE
          WHEN public.production_orders.customer_name = '' THEN EXCLUDED.customer_name
          ELSE public.production_orders.customer_name
        END,
        customer_legal_name = COALESCE(public.production_orders.customer_legal_name, EXCLUDED.customer_legal_name),
        promob_project_name = COALESCE(public.production_orders.promob_project_name, EXCLUDED.promob_project_name),
        updated_at = now()
    RETURNING id INTO v_order_id;

    v_first_order_id := COALESCE(v_first_order_id, v_order_id);

    SELECT l.id, l.pcp_import_batch_id,
           (SELECT pli.customer_name FROM public.production_lot_items pli WHERE pli.lot_id = l.id AND pli.customer_name IS NOT NULL LIMIT 1)
    INTO v_lot_id, v_existing_lot_batch_id, v_existing_lot_customer
    FROM public.production_lots l
    WHERE upper(l.lot_code) = upper(v_row_lot_code)
    FOR UPDATE;

    IF v_lot_id IS NULL THEN
      INSERT INTO public.production_lots (
        lot_code, order_id, production_order_id, order_number, customer_name,
        status, created_by, pcp_import_batch_id, actual_start
      ) VALUES (
        v_row_lot_code, v_order_id, v_order_id, v_row_order_code, v_row_customer,
        'planned', v_current_user, p_batch_id, NULL
      ) RETURNING id INTO v_lot_id;
    ELSE
      IF v_existing_lot_batch_id IS NOT NULL AND v_existing_lot_batch_id <> p_batch_id THEN
        RAISE EXCEPTION 'Lote do cliente % já pertence a outro lote geral PCP.', v_row_lot_code;
      END IF;
      IF v_existing_lot_customer IS NOT NULL AND lower(v_existing_lot_customer) <> lower(v_row_customer) THEN
        RAISE EXCEPTION 'Lote do cliente % está vinculado a % e não pode receber peças de %.',
          v_row_lot_code, v_existing_lot_customer, v_row_customer;
      END IF;
      UPDATE public.production_lots
      SET pcp_import_batch_id = p_batch_id,
          customer_name = COALESCE(NULLIF(customer_name, ''), v_row_customer),
          order_number = COALESCE(NULLIF(order_number, ''), v_row_order_code),
          updated_at = now()
      WHERE id = v_lot_id;
    END IF;

    INSERT INTO public.pcp_import_rows (
      batch_id, row_number, raw_cells, normalized_payload, barcode_raw,
      barcode_normalized, validation_status, validation_errors,
      mapping_version, row_hash
    ) VALUES (
      p_batch_id,
      COALESCE((v_row->>'row_number')::integer, v_inserted_rows + 1),
      COALESCE(v_row->'raw_cells', '[]'::jsonb),
      v_row,
      v_barcode,
      v_barcode,
      'valid',
      '[]'::jsonb,
      COALESCE(p_mapping_version, 1),
      md5(p_batch_id::text || ':' || v_row::text)
    )
    ON CONFLICT (batch_id, row_number) DO UPDATE
    SET raw_cells = EXCLUDED.raw_cells,
        normalized_payload = EXCLUDED.normalized_payload,
        barcode_raw = EXCLUDED.barcode_raw,
        barcode_normalized = EXCLUDED.barcode_normalized,
        validation_status = EXCLUDED.validation_status,
        validation_errors = EXCLUDED.validation_errors,
        mapping_version = EXCLUDED.mapping_version,
        row_hash = EXCLUDED.row_hash;

    v_route_steps := public.parse_pcp_route_tokens(v_route);
    IF v_manual_joinery THEN
      v_route_steps := array_prepend('joinery', array_remove(v_route_steps, 'joinery'));
    END IF;

    FOR i IN 1..v_quantity LOOP
      v_suffix := CASE WHEN v_quantity > 1 THEN '-' || i::text ELSE '' END;
      v_piece_uid := v_barcode || v_suffix;

      SELECT pcp_import_batch_id INTO v_existing_batch_id
      FROM public.production_pieces
      WHERE piece_uid = v_piece_uid;

      IF FOUND THEN
        IF v_existing_batch_id = p_batch_id THEN
          CONTINUE;
        END IF;
        RAISE EXCEPTION 'Código de barras % já pertence a outra importação PCP.', v_piece_uid;
      END IF;

      INSERT INTO public.production_lot_items (
        lot_id, item_code, product_code, product_name, current_step, status,
        lot_code, load_number, order_number, customer_name, environment_name,
        pieces_quantity
      ) VALUES (
        v_lot_id, v_piece_uid, v_piece_code, v_piece_name,
        COALESCE(v_route_steps[1], 'Importado'), 'pending',
        v_row_lot_code, NULL, v_row_order_code, v_row_customer, v_environment, 1
      ) RETURNING id INTO v_lot_item_id;

      v_piece_id := NULL;
      SELECT id INTO v_piece_id
      FROM public.production_pieces
      WHERE legacy_production_lot_item_id = v_lot_item_id
      ORDER BY created_at, id
      LIMIT 1
      FOR UPDATE;

      IF v_piece_id IS NULL THEN
        INSERT INTO public.production_pieces (
          piece_uid, traceability_code, production_order_id, lot_id,
          module_name, environment, piece_name, material, color,
          thickness, width, height, length, requires_joinery, manual_joinery,
          manual_joinery_reason, current_stage, status,
          source_origin, legacy_production_lot_item_id, route_steps,
          pcp_import_batch_id, created_by
        ) VALUES (
          v_piece_uid, v_piece_uid, v_order_id, v_lot_id,
          v_module, v_environment, v_piece_name, v_material, v_color,
          v_thickness, v_width, v_height, v_height, v_manual_joinery, v_manual_joinery,
          NULLIF(TRIM(v_row->>'manualJoineryReason'), ''),
          COALESCE(v_route_steps[1], 'created'), 'planned',
          CASE
            WHEN lower(COALESCE(v_row->>'sourceFormat', p_mapping_profile, '')) LIKE '%csv%' THEN 'csv'
            ELSE 'xlsx'
          END,
          v_lot_item_id, v_route_steps, p_batch_id, v_current_user
        ) RETURNING id INTO v_piece_id;
      ELSE
        UPDATE public.production_pieces
        SET piece_uid = v_piece_uid,
            traceability_code = v_piece_uid,
            production_order_id = v_order_id,
            lot_id = v_lot_id,
            module_name = v_module,
            environment = v_environment,
            piece_name = v_piece_name,
            material = v_material,
            color = v_color,
            thickness = v_thickness,
            width = v_width,
            height = v_height,
            length = v_height,
            requires_joinery = v_manual_joinery,
            manual_joinery = v_manual_joinery,
            manual_joinery_reason = NULLIF(TRIM(v_row->>'manualJoineryReason'), ''),
            current_stage = COALESCE(v_route_steps[1], 'created'),
            status = 'planned',
            source_origin = CASE
              WHEN lower(COALESCE(v_row->>'sourceFormat', p_mapping_profile, '')) LIKE '%csv%' THEN 'csv'
              ELSE 'xlsx'
            END,
            route_steps = v_route_steps,
            pcp_import_batch_id = p_batch_id,
            created_by = v_current_user,
            updated_at = now()
        WHERE id = v_piece_id;

        UPDATE public.production_events
        SET traceability_code = v_piece_uid,
            production_order_id = v_order_id,
            event_type = 'note',
            from_stage = NULL,
            to_stage = COALESCE(v_route_steps[1], 'created'),
            notes = 'Peça criada pela importação PCP.',
            metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
              'source', 'pcp_import',
              'pcp_import_batch_id', p_batch_id,
              'general_lot_code', v_row_general_lot_code,
              'client_lot_code', v_row_lot_code
            )
        WHERE piece_id = v_piece_id
          AND event_type = 'reading'
          AND operator_id IS NULL
          AND legacy_stage_reading_id IS NULL;
      END IF;

      INSERT INTO public.production_tags (
        lot_id, item_id, piece_id, tag_value, tag_type, active
      ) VALUES (
        v_lot_id, v_lot_item_id, v_piece_id, v_piece_uid,
        CASE WHEN v_manual_joinery THEN 'manual' ELSE 'barcode' END,
        true
      );

      v_inserted_pieces := v_inserted_pieces + 1;
    END LOOP;

    v_inserted_rows := v_inserted_rows + 1;
  END LOOP;

  SELECT count(*),
         count(DISTINCT p.production_order_id),
         count(DISTINCT p.lot_id),
         count(DISTINCT NULLIF(TRIM(l.customer_name), ''))
  INTO v_total_batch_pieces, v_order_count, v_lot_count, v_customer_count
  FROM public.production_pieces p
  LEFT JOIN public.production_lots l ON l.id = p.lot_id
  WHERE p.pcp_import_batch_id = p_batch_id;

  SELECT count(*) INTO v_total_batch_rows
  FROM public.pcp_import_rows
  WHERE batch_id = p_batch_id;

  SELECT production_order_id INTO v_first_order_id
  FROM public.production_pieces
  WHERE pcp_import_batch_id = p_batch_id
    AND production_order_id IS NOT NULL
  ORDER BY created_at, id
  LIMIT 1;

  UPDATE public.production_lots l
  SET planned_quantity = x.piece_count,
      pending_quantity = x.piece_count,
      progress_percent = 0,
      updated_at = now()
  FROM (
    SELECT lot_id, count(*)::numeric AS piece_count
    FROM public.production_pieces
    WHERE pcp_import_batch_id = p_batch_id
    GROUP BY lot_id
  ) x
  WHERE l.id = x.lot_id;

  UPDATE public.promob_import_batches
  SET status = CASE WHEN p_finalize THEN 'processed' ELSE 'parsed' END,
      imported_at = CASE WHEN p_finalize THEN now() ELSE imported_at END,
      validated_at = CASE WHEN p_finalize THEN now() ELSE validated_at END,
      customer_name = CASE WHEN v_order_count > 1 THEN 'Múltiplos clientes' ELSE p_customer END,
      promob_project_name = p_project_name,
      order_code = CASE WHEN v_order_count > 1 THEN 'Múltiplos pedidos' ELSE p_order_code END,
      generated_op_id = CASE WHEN v_order_count = 1 THEN v_first_order_id ELSE NULL END,
      total_parts = v_total_batch_pieces,
      client_lots_count = v_lot_count,
      customers_count = v_customer_count,
      source_format = p_mapping_profile,
      mapping_profile = p_mapping_profile,
      mapping_version = COALESCE(p_mapping_version, 1),
      total_lines = v_total_batch_rows,
      valid_lines = v_total_batch_rows,
      empty_lines = 0,
      duplicate_lines = 0,
      notes = format(
        'PCP consolidado: %s peças, %s pedido(s), %s lote(s).',
        v_total_batch_pieces, v_order_count, v_lot_count
      )
  WHERE id = p_batch_id;

  PERFORM public.refresh_pcp_batch_progress(p_batch_id);

  IF p_finalize THEN
    -- Gerar capas automaticamente ao finalizar
    PERFORM public.create_customer_covers_for_batch(p_batch_id);

    INSERT INTO public.pcp_import_logs (
      import_file_id, user_id, action, message, severity, metadata_json
    ) VALUES (
      p_batch_id,
      v_current_user,
      'PCP_IMPORT',
      format(
        'Importação PCP finalizada: %s peças, %s pedido(s), %s lote(s).',
        v_total_batch_pieces, v_order_count, v_lot_count
      ),
      'info',
      jsonb_build_object(
        'pieces_created', v_total_batch_pieces,
        'source_rows', v_total_batch_rows,
        'orders', v_order_count,
        'lots', v_lot_count,
        'pcp_import_batch_id', p_batch_id
      )
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'batch_id', p_batch_id,
    'pieces_created', v_total_batch_pieces,
    'pieces_created_in_chunk', v_inserted_pieces,
    'rows_imported', v_total_batch_rows,
    'rows_imported_in_chunk', v_inserted_rows,
    'orders', v_order_count,
    'lots', v_lot_count,
    'finalized', p_finalize
  );
EXCEPTION WHEN OTHERS THEN
  UPDATE public.promob_import_batches
  SET status = 'error', error_message = SQLERRM
  WHERE id = p_batch_id;
  RAISE;
END;
$function$

CREATE OR REPLACE FUNCTION public.complete_piece_replacement_impl(p_order_id uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  v_order record;
  v_user_id uuid := auth.uid();
BEGIN
  SELECT * INTO v_order FROM public.replacement_orders WHERE id = p_order_id;
  IF v_order IS NULL THEN RAISE EXCEPTION 'Ordem de reposicao nao encontrada.'; END IF;
  IF v_order.status = 'completed' THEN RETURN jsonb_build_object('success',true,'already_completed',true); END IF;
  UPDATE public.replacement_orders SET status='completed',completed_at=now(),updated_at=now() WHERE id=p_order_id;
  IF v_order.original_piece_id IS NOT NULL THEN
    UPDATE public.production_pieces SET status='replaced',updated_at=now() WHERE id=v_order.original_piece_id;
  END IF;
  IF v_order.replacement_piece_id IS NOT NULL THEN
    UPDATE public.production_pieces SET status='completed',updated_at=now() WHERE id=v_order.replacement_piece_id;
  END IF;
  UPDATE public.quality_nonconformities SET status='closed',closed_at=now(),closed_by=v_user_id WHERE related_replacement_id=p_order_id AND status!='closed';
  RETURN jsonb_build_object('success',true,'status','completed');
END;
$function$

CREATE OR REPLACE FUNCTION public.complete_piece_replacement(p_order_id uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if not (select public.can_manage_quality()) then
    raise exception 'QUALITY_PERMISSION_REQUIRED' using errcode = '42501';
  end if;
  return public.complete_piece_replacement_impl(p_order_id, p_payload);
end;
$function$

CREATE OR REPLACE FUNCTION public.compute_report_next_run(p_frequency text, p_time_local time without time zone, p_timezone text DEFAULT 'America/Sao_Paulo'::text, p_from timestamp with time zone DEFAULT now())
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_local_now timestamp := p_from AT TIME ZONE p_timezone;
  v_candidate timestamp;
BEGIN
  v_candidate := date_trunc('day', v_local_now) + p_time_local;

  IF p_frequency = 'monthly' THEN
    IF v_candidate <= v_local_now THEN
      v_candidate := v_candidate + interval '1 month';
    END IF;
  ELSIF p_frequency = 'weekly' THEN
    IF v_candidate <= v_local_now THEN
      v_candidate := v_candidate + interval '7 days';
    END IF;
  ELSE
    IF v_candidate <= v_local_now THEN
      v_candidate := v_candidate + interval '1 day';
    END IF;
    IF p_frequency = 'workdays' THEN
      WHILE extract(isodow FROM v_candidate) IN (6, 7) LOOP
        v_candidate := v_candidate + interval '1 day';
      END LOOP;
    END IF;
  END IF;

  RETURN v_candidate AT TIME ZONE p_timezone;
END;
$function$

CREATE OR REPLACE FUNCTION public.control_capacity_test_run(p_run_id text, p_action text)
 RETURNS public.capacity_test_runs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  v_status text;
  v_row public.capacity_test_runs;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.profiles profile
    WHERE profile.id = auth.uid() AND profile.active IS TRUE AND profile.role = 'admin'
  ) THEN
    RAISE EXCEPTION 'ADMIN_REQUIRED' USING ERRCODE = '42501';
  END IF;
  v_status := CASE p_action
    WHEN 'pause' THEN 'paused'
    WHEN 'resume' THEN 'requested'
    WHEN 'cancel' THEN 'cancel_requested'
    WHEN 'emergency_stop' THEN 'emergency_stopped'
    ELSE NULL
  END;
  IF v_status IS NULL THEN
    RAISE EXCEPTION 'CAPACITY_TEST_ACTION_INVALID' USING ERRCODE = '22023';
  END IF;

  UPDATE public.capacity_test_runs
  SET status = v_status,
      finished_at = CASE WHEN v_status = 'emergency_stopped' THEN clock_timestamp() ELSE finished_at END,
      updated_at = clock_timestamp()
  WHERE run_id = p_run_id
    AND status NOT IN ('completed', 'failed', 'emergency_stopped')
  RETURNING * INTO v_row;
  IF NOT FOUND THEN RAISE EXCEPTION 'CAPACITY_TEST_RUN_NOT_CONTROLLABLE' USING ERRCODE = '55000'; END IF;
  RETURN v_row;
END;
$function$

CREATE OR REPLACE FUNCTION public.correct_production_downtime_impl(p_occurrence_id uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  v_started_at timestamptz := (p_payload->>'started_at')::timestamptz;
  v_ended_at timestamptz := (p_payload->>'ended_at')::timestamptz;
  v_duration numeric;
BEGIN
  IF v_started_at IS NOT NULL AND v_ended_at IS NOT NULL THEN
    IF v_ended_at <= v_started_at THEN
      RAISE EXCEPTION 'Horário final deve ser maior que o horário inicial.';
    END IF;
    v_duration := ROUND(EXTRACT(EPOCH FROM (v_ended_at - v_started_at)) / 60.0, 2);
  ELSE
    v_duration := (p_payload->>'duration_minutes')::numeric;
  END IF;

  UPDATE public.occurrences
  SET started_at = COALESCE(v_started_at, started_at),
      ended_at = COALESCE(v_ended_at, ended_at),
      duration_minutes = COALESCE(v_duration, duration_minutes),
      downtime = COALESCE(v_duration, downtime),
      reason = COALESCE(p_payload->>'reason', reason),
      notes = COALESCE(p_payload->>'notes', notes),
      updated_at = now()
  WHERE id = p_occurrence_id;

  RETURN jsonb_build_object('success', true, 'occurrence_id', p_occurrence_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.correct_production_downtime(p_occurrence_id uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
declare
  v_cell_name text;
begin
  if coalesce(auth.role(), '') <> 'service_role' and not public.can_manage_occurrences() then
    raise exception 'OCCURRENCE_PERMISSION_REQUIRED' using errcode = '42501';
  end if;
  select coalesce(cell.name, occurrence.cell)
    into v_cell_name
  from public.occurrences occurrence
  left join public.cells cell on cell.id = occurrence.cell_id
  where occurrence.id = p_occurrence_id
    and occurrence.occurrence_type = 'downtime';
  if v_cell_name is null then
    raise exception 'DOWNTIME_OCCURRENCE_NOT_FOUND' using errcode = 'P0002';
  end if;
  if coalesce(auth.role(), '') <> 'service_role' and not public.profile_can_access_cell(v_cell_name) then
    raise exception 'OCCURRENCE_OUTSIDE_CELL_SCOPE' using errcode = '42501';
  end if;
  return public.correct_production_downtime_impl(p_occurrence_id, coalesce(p_payload, '{}'::jsonb));
end;
$function$

CREATE OR REPLACE FUNCTION public.create_customer_covers_for_batch_impl(p_batch_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_batch_code text;
  v_rec record;
  v_cover_id uuid;
  v_hash text;
  v_cover_code text;
  v_customer_clean text;
BEGIN
  -- Obter o código do lote geral/batch
  SELECT general_lot_code INTO v_batch_code
  FROM public.promob_import_batches
  WHERE id = p_batch_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Lote de importação % não encontrado.', p_batch_id;
  END IF;

  -- Percorrer os clientes do lote
  FOR v_rec IN 
    SELECT DISTINCT customer_name 
    FROM public.production_lots 
    WHERE pcp_import_batch_id = p_batch_id
  LOOP
    v_customer_clean := btrim(v_rec.customer_name);

    -- Ignorar clientes vazios ou não informados agrupados (isolamos por lote de forma controlada)
    IF v_customer_clean IS NULL OR v_customer_clean = '' OR v_customer_clean = 'Cliente não informado' THEN
      -- Criar uma capa exclusiva para cada lote individual sem cliente válido
      FOR v_rec IN 
        SELECT id, lot_code, customer_name
        FROM public.production_lots 
        WHERE pcp_import_batch_id = p_batch_id
          AND (customer_name IS NULL OR btrim(customer_name) = '' OR btrim(customer_name) = 'Cliente não informado')
      LOOP
        v_customer_clean := COALESCE(NULLIF(btrim(v_rec.customer_name), ''), 'Cliente não informado');
        v_hash := substring(md5(p_batch_id::text || ':' || v_rec.lot_code), 1, 8);
        v_cover_code := 'CAP-' || COALESCE(v_batch_code, 'PCP') || '-' || v_hash;

        INSERT INTO public.customer_covers (
          pcp_import_batch_id, general_lot_code, customer_name_exact, cover_code, status
        ) VALUES (
          p_batch_id, COALESCE(v_batch_code, 'PCP'), v_customer_clean || ' (' || v_rec.lot_code || ')', v_cover_code, 'planned'
        )
        ON CONFLICT (pcp_import_batch_id, customer_name_exact) DO UPDATE
        SET general_lot_code = EXCLUDED.general_lot_code
        RETURNING id INTO v_cover_id;

        UPDATE public.production_lots
        SET customer_cover_id = v_cover_id
        WHERE id = v_rec.id;
      END LOOP;
    ELSE
      -- Gerar hash determinístico baseado no batch e no nome do cliente
      v_hash := substring(md5(p_batch_id::text || ':' || v_customer_clean), 1, 8);
      v_cover_code := 'CAP-' || COALESCE(v_batch_code, 'PCP') || '-' || v_hash;

      INSERT INTO public.customer_covers (
        pcp_import_batch_id, general_lot_code, customer_name_exact, cover_code, status
      ) VALUES (
        p_batch_id, COALESCE(v_batch_code, 'PCP'), v_customer_clean, v_cover_code, 'planned'
      )
      ON CONFLICT (pcp_import_batch_id, customer_name_exact) DO UPDATE
      SET general_lot_code = EXCLUDED.general_lot_code
      RETURNING id INTO v_cover_id;

      -- Associar os lotes correspondentes a essa capa
      UPDATE public.production_lots
      SET customer_cover_id = v_cover_id
      WHERE pcp_import_batch_id = p_batch_id
        AND btrim(customer_name) = v_customer_clean;

      -- Registrar evento
      INSERT INTO public.customer_cover_events (cover_id, event_type, metadata)
      VALUES (v_cover_id, 'created', jsonb_build_object('auto_created', true));
    END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_customer_covers_for_batch(p_batch_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if auth.role() <> 'service_role'
