CREATE OR REPLACE FUNCTION public.delete_traceability_test_data()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_deleted_readings integer := 0;
  v_deleted_entries integer := 0;
  v_deleted_occurrences integer := 0;
  v_deleted_tags integer := 0;
  v_deleted_items integer := 0;
  v_deleted_routes integer := 0;
  v_deleted_lots integer := 0;
  v_deleted_orders integer := 0;
  v_deleted_logs integer := 0;
BEGIN
  -- 1. Verificar permissão (apenas admins e gestores)
  IF auth.uid() IS NULL OR get_my_role() NOT IN ('admin','manager') THEN
    RETURN jsonb_build_object('success', false, 'message', 'Usuário sem permissão para apagar dados de teste.');
  END IF;

  -- 2. Apagar leituras de produção vinculadas a tags de teste ou lotes de teste
  DELETE FROM production_stage_readings 
  WHERE tag_value LIKE 'BARCODE-TEST-%' 
     OR tag_value LIKE 'QRCODE-TEST-%' 
     OR tag_value LIKE 'RFID-TEST-%'
     OR lot_id IN (
       SELECT id FROM production_lots WHERE lot_code LIKE 'LOTE-TEST-%'
     );
  GET DIAGNOSTICS v_deleted_readings = ROW_COUNT;

  -- 3. Apagar ocorrências vinculadas aos lotes de teste
  DELETE FROM occurrences 
  WHERE notes LIKE '%LOTE-TEST-%' 
     OR notes LIKE '%PECA-TEST-%' 
     OR lot_id IN (
       SELECT id FROM production_lots WHERE lot_code LIKE 'LOTE-TEST-%'
     );
  GET DIAGNOSTICS v_deleted_occurrences = ROW_COUNT;

  -- 4. Apagar entradas de produção geradas automaticamente
  DELETE FROM production_entries 
  WHERE notes LIKE 'Coleta produtiva - tag BARCODE-TEST-%' 
     OR notes LIKE 'Coleta produtiva - tag QRCODE-TEST-%' 
     OR notes LIKE 'Coleta produtiva - tag RFID-TEST-%' 
     OR notes LIKE 'Reprovação vinculada a tag BARCODE-TEST-%'
     OR notes LIKE 'Reprovação vinculada a tag QRCODE-TEST-%'
     OR notes LIKE 'Reprovação vinculada a tag RFID-TEST-%'
     OR notes LIKE '%PECA-TEST-%' 
     OR notes LIKE '%LOTE-TEST-%';
  GET DIAGNOSTICS v_deleted_entries = ROW_COUNT;

  -- 5. Apagar logs de rastreabilidade
  DELETE FROM traceability_logs 
  WHERE details->>'tag' LIKE 'BARCODE-TEST-%' 
     OR details->>'tag' LIKE 'QRCODE-TEST-%' 
     OR details->>'tag' LIKE 'RFID-TEST-%'
     OR entity_id IN (
       SELECT id FROM production_lot_items WHERE item_code LIKE 'PECA-TEST-%'
     );
  GET DIAGNOSTICS v_deleted_logs = ROW_COUNT;

  -- 6. Apagar tags de teste
  DELETE FROM production_tags 
  WHERE tag_value LIKE 'BARCODE-TEST-%' 
     OR tag_value LIKE 'QRCODE-TEST-%' 
     OR tag_value LIKE 'RFID-TEST-%'
     OR lot_id IN (
       SELECT id FROM production_lots WHERE lot_code LIKE 'LOTE-TEST-%'
     );
  GET DIAGNOSTICS v_deleted_tags = ROW_COUNT;

  -- 7. Apagar itens do lote de teste
  DELETE FROM production_lot_items 
  WHERE item_code LIKE 'PECA-TEST-%' 
     OR lot_id IN (
       SELECT id FROM production_lots WHERE lot_code LIKE 'LOTE-TEST-%'
     );
  GET DIAGNOSTICS v_deleted_items = ROW_COUNT;

  -- 8. Apagar rotas de teste
  DELETE FROM production_routes 
  WHERE lot_id IN (
     SELECT id FROM production_lots WHERE lot_code LIKE 'LOTE-TEST-%'
  );
  GET DIAGNOSTICS v_deleted_routes = ROW_COUNT;

  -- 9. Apagar lotes de teste
  DELETE FROM production_lots 
  WHERE lot_code LIKE 'LOTE-TEST-%';
  GET DIAGNOSTICS v_deleted_lots = ROW_COUNT;

  -- 10. Apagar ordens de teste
  DELETE FROM production_orders 
  WHERE order_code LIKE 'ORDEM-TEST-%';
  GET DIAGNOSTICS v_deleted_orders = ROW_COUNT;

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Dados de teste limpos com sucesso.',
    'deleted_readings', v_deleted_readings,
    'deleted_entries', v_deleted_entries,
    'deleted_occurrences', v_deleted_occurrences,
    'deleted_tags', v_deleted_tags,
    'deleted_items', v_deleted_items,
    'deleted_routes', v_deleted_routes,
    'deleted_lots', v_deleted_lots,
    'deleted_orders', v_deleted_orders,
    'deleted_logs', v_deleted_logs
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_user_from_auth(target_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_target_role text;
  v_target_active boolean;
begin
  if auth.uid() is null or public.get_my_role() <> 'admin' then
    raise exception 'Apenas administradores ativos podem excluir usuários do sistema.'
      using errcode = '42501';
  end if;

  if target_user_id = auth.uid() then
    raise exception 'Não é permitido excluir a própria conta administrativa.'
      using errcode = '42501';
  end if;

  select role, active
    into v_target_role, v_target_active
  from public.profiles
  where id = target_user_id;

  if not found then
    raise exception 'Usuário não encontrado.' using errcode = 'P0002';
  end if;

  if v_target_role = 'admin'
     and v_target_active is true
     and (
       select count(*)
       from public.profiles
       where role = 'admin' and active is true
     ) <= 1 then
    raise exception 'O sistema deve manter ao menos um administrador ativo.'
      using errcode = '42501';
  end if;

  delete from public.report_schedule_recipients where profile_id = target_user_id;
  delete from public.email_recipient_group_members where profile_id = target_user_id;
  update public.alert_logs set created_by = null where created_by = target_user_id;
  update public.alert_logs set resolved_by = null where resolved_by = target_user_id;
  update public.report_schedule_runs set requested_by = null where requested_by = target_user_id;
  update public.report_deliveries set profile_id = null where profile_id = target_user_id;
  delete from auth.users where id = target_user_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_piece_route_state()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  v_completed text[] := '{}'::text[]; v_next_step text;
  v_route_size integer := cardinality(COALESCE(NEW.route_steps,'{}'::text[])); v_special_status boolean;
BEGIN
  IF v_route_size=0 THEN RETURN NEW; END IF;
  IF TG_OP='UPDATE' AND NEW.completed_steps IS NOT DISTINCT FROM OLD.completed_steps
     AND COALESCE(NEW.current_stage,'') NOT IN ('Concluída','completed')
     AND COALESCE(NEW.status,'') <> 'completed' THEN RETURN NEW; END IF;
  SELECT COALESCE(array_agg(route_step ORDER BY ord),'{}'::text[]) INTO v_completed
  FROM unnest(NEW.route_steps) WITH ORDINALITY route(route_step,ord)
  WHERE EXISTS (SELECT 1 FROM public.production_stage_readings reading
    WHERE reading.piece_id=NEW.id AND reading.status='approved'
      AND public.normalize_route_step_code(reading.step_name)=route_step);
  IF COALESCE(NEW.is_replacement,false)=false AND NEW.status='replaced' AND NEW.replacement_status='replaced' THEN v_completed:=NEW.route_steps; END IF;
  NEW.completed_steps:=v_completed;
  SELECT route_step INTO v_next_step FROM unnest(NEW.route_steps) WITH ORDINALITY route(route_step,ord)
  WHERE NOT (route_step=ANY(v_completed)) ORDER BY ord LIMIT 1;
  v_special_status:=COALESCE(NEW.status,'') IN ('rejected','blocked','replaced','replacement_requested','replacement_in_production','rework_pending','rework_in_progress','cancelled');
  IF v_next_step IS NULL THEN NEW.current_stage:='Concluída'; IF NOT v_special_status THEN NEW.status:='completed'; END IF;
  ELSE NEW.current_stage:=v_next_step; IF NOT v_special_status AND NEW.status<>'planned' THEN NEW.status:='in_progress'; END IF; END IF;
  RETURN NEW;
END; $function$

