CREATE OR REPLACE FUNCTION public.enrich_production_entry_context()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tag text;
  v_lot production_lots%ROWTYPE;
  v_order production_orders%ROWTYPE;
  v_item production_order_items%ROWTYPE;
BEGIN
  NEW.production_order_id := COALESCE(NEW.production_order_id, NEW.order_id);
  NEW.order_id := COALESCE(NEW.order_id, NEW.production_order_id);
  IF NEW.lot_id IS NULL AND NEW.notes ~* 'tag ' THEN
    v_tag := UPPER(TRIM(regexp_replace(NEW.notes, '^.*tag ', '', 'i')));
    SELECT pl.* INTO v_lot FROM production_tags pt JOIN production_lots pl ON pl.id = pt.lot_id
    WHERE pt.tag_value = v_tag LIMIT 1;
    NEW.lot_id := COALESCE(NEW.lot_id, v_lot.id);
  END IF;
  IF NEW.lot_id IS NOT NULL THEN
    SELECT * INTO v_lot FROM production_lots WHERE id = NEW.lot_id;
    NEW.production_order_id := COALESCE(NEW.production_order_id, v_lot.production_order_id, v_lot.order_id);
    NEW.order_id := COALESCE(NEW.order_id, NEW.production_order_id);
    NEW.lot_code := COALESCE(NULLIF(NEW.lot_code,''), v_lot.lot_code);
    NEW.product_code := COALESCE(NULLIF(NEW.product_code,''), v_lot.product_code);
    NEW.product_name := COALESCE(NULLIF(NEW.product_name,''), v_lot.product_name);
    NEW.product_description := COALESCE(NULLIF(NEW.product_description,''), v_lot.product_description);
    NEW.process_step := COALESCE(NULLIF(NEW.process_step,''), v_lot.current_step, v_lot.current_stage);
  END IF;
  IF NEW.production_order_id IS NOT NULL THEN
    SELECT * INTO v_order FROM production_orders WHERE id = NEW.production_order_id;
    NEW.system_order_number := COALESCE(NULLIF(NEW.system_order_number,''), v_order.system_order_number);
    NEW.customer_order_number := COALESCE(NULLIF(NEW.customer_order_number,''), v_order.customer_order_number);
    NEW.order_number := COALESCE(NULLIF(NEW.order_number,''), v_order.order_number, v_order.order_code);
    NEW.load_number := COALESCE(NULLIF(NEW.load_number,''), v_order.load_number);
    NEW.customer_code := COALESCE(NULLIF(NEW.customer_code,''), v_order.customer_code);
    NEW.customer_legal_name := COALESCE(NULLIF(NEW.customer_legal_name,''), v_order.customer_legal_name, v_order.customer_name);
    NEW.customer_trade_name := COALESCE(NULLIF(NEW.customer_trade_name,''), v_order.customer_trade_name, v_order.customer_name);
    NEW.customer_name := COALESCE(NULLIF(NEW.customer_name,''), v_order.customer_trade_name, v_order.customer_name);
    NEW.cnpj := COALESCE(NULLIF(NEW.cnpj,''), v_order.cnpj);
    NEW.finalization_date := COALESCE(NEW.finalization_date, v_order.finalization_date);
    NEW.city := COALESCE(NULLIF(NEW.city,''), v_order.city);
    NEW.state := COALESCE(NULLIF(NEW.state,''), v_order.state);
    NEW.delivery_region := COALESCE(NULLIF(NEW.delivery_region,''), v_order.delivery_region);
  END IF;
  IF NEW.order_item_id IS NOT NULL THEN
    SELECT * INTO v_item FROM production_order_items WHERE id = NEW.order_item_id;
    NEW.product_code := COALESCE(NULLIF(NEW.product_code,''), v_item.product_code);
    NEW.product_name := COALESCE(NULLIF(NEW.product_name,''), v_item.product_name);
    NEW.product_description := COALESCE(NULLIF(NEW.product_description,''), v_item.product_description);
    NEW.route_code := COALESCE(NULLIF(NEW.route_code,''), v_item.route_code);
    NEW.route_name := COALESCE(NULLIF(NEW.route_name,''), v_item.route_name);
    NEW.mirror_quantity := COALESCE(NEW.mirror_quantity, v_item.mirror_quantity, 0);
    NEW.pallet_number := COALESCE(NULLIF(NEW.pallet_number,''), v_item.pallet_number);
  END IF;
  NEW.traceability_status := CASE WHEN COALESCE(NEW.production_order_id, NEW.lot_id, NEW.order_item_id) IS NULL THEN 'limited' ELSE 'resolved' END;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enrich_production_entry_metric()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
DECLARE
  v_item_id uuid;
  v_item_sheet numeric := 0;
  v_item_edge numeric := 0;
  v_item_pieces numeric := 0;
  v_item_covers numeric := 0;
  v_inferred_unit text;
  v_unit text;
  v_realized numeric;
  v_base numeric;
BEGIN
  SELECT pli.id, pli.sheet_count, pli.edge_meters, pli.pieces_quantity, pli.covers_quantity
  INTO v_item_id, v_item_sheet, v_item_edge, v_item_pieces, v_item_covers
  FROM public.production_stage_readings psr
  JOIN public.production_lot_items pli ON pli.id = psr.item_id
  WHERE psr.client_event_id IS NOT NULL
    AND psr.client_event_id = NEW.client_event_id
  ORDER BY psr.created_at DESC
  LIMIT 1;

  IF v_item_id IS NULL AND NEW.order_item_id IS NOT NULL THEN
    SELECT id, sheet_count, edge_meters, pieces_quantity, covers_quantity
    INTO v_item_id, v_item_sheet, v_item_edge, v_item_pieces, v_item_covers
    FROM public.production_order_items
    WHERE id = NEW.order_item_id
    LIMIT 1;
  END IF;

  v_inferred_unit := public.production_metric_unit_for_cell(
    NEW.cell,
    COALESCE(NEW.operation_name, NEW.process_step),
    NEW.operation_name
  );

  v_unit := CASE
    WHEN NEW.metric_unit IN ('sheets','meters','covers') THEN NEW.metric_unit
    WHEN NEW.metric_unit = 'pieces' AND v_inferred_unit = 'pieces' THEN 'pieces'
    ELSE v_inferred_unit
  END;

  NEW.metric_unit := v_unit;
  NEW.metric_unit_label := public.production_metric_unit_label(v_unit);
  NEW.metric_name := COALESCE(NULLIF(NEW.metric_name, ''), public.production_metric_name_for_unit(v_unit, NEW.cell));
  NEW.planned_target := COALESCE(NULLIF(NEW.planned_target, 0), NEW.target, 0);
  NEW.planned_capacity := COALESCE(NEW.planned_capacity, 0);

  v_realized := COALESCE(NULLIF(NEW.realized_quantity, 0), 0);

  IF v_realized = 0 THEN
    IF v_unit = 'meters' THEN
      v_realized := COALESCE(NULLIF(NEW.edge_meters, 0), NULLIF(v_item_edge, 0), GREATEST(COALESCE(NEW.produced, 0), 1));
      NEW.edge_meters := COALESCE(NULLIF(NEW.edge_meters, 0), NULLIF(v_item_edge, 0), v_realized);
    ELSIF v_unit = 'sheets' THEN
      v_realized := COALESCE(NULLIF(NEW.sheet_count, 0), NULLIF(v_item_sheet, 0), COALESCE(NEW.produced, 1));
      NEW.sheet_count := COALESCE(NULLIF(NEW.sheet_count, 0), NULLIF(v_item_sheet, 0), v_realized);
    ELSIF v_unit = 'covers' THEN
      v_realized := COALESCE(NULLIF(NEW.covers_quantity, 0), NULLIF(v_item_covers, 0), COALESCE(NEW.produced, 0));
      NEW.covers_quantity := COALESCE(NULLIF(NEW.covers_quantity, 0), NULLIF(v_item_covers, 0), v_realized);
    ELSE
      v_realized := COALESCE(NULLIF(NEW.pieces_quantity, 0), NULLIF(v_item_pieces, 0), COALESCE(NEW.produced, 0));
      NEW.pieces_quantity := COALESCE(NULLIF(NEW.pieces_quantity, 0), NULLIF(v_item_pieces, 0), v_realized);
    END IF;
  END IF;

  NEW.realized_quantity := COALESCE(v_realized, 0);
  v_base := COALESCE(NULLIF(NEW.planned_target, 0), NULLIF(NEW.planned_capacity, 0), 0);
  NEW.difference_quantity := NEW.realized_quantity - v_base;
  NEW.efficiency_percent := CASE WHEN COALESCE(NEW.planned_target, 0) > 0
    THEN ROUND((NEW.realized_quantity / NEW.planned_target) * 100, 1)
    ELSE 0
  END;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enrich_rejected_reading_context()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_piece public.production_pieces%ROWTYPE;
  v_lot public.production_lots%ROWTYPE;
  v_order public.production_orders%ROWTYPE;
  v_event public.production_collection_events%ROWTYPE;
BEGIN
  IF NEW.status <> 'rejected' OR NEW.piece_id IS NULL THEN RETURN NEW; END IF;
  SELECT * INTO v_piece FROM public.production_pieces WHERE id = NEW.piece_id;
  SELECT * INTO v_lot FROM public.production_lots WHERE id = v_piece.lot_id;
  SELECT * INTO v_order FROM public.production_orders
  WHERE id = COALESCE(v_piece.production_order_id, v_lot.production_order_id, v_lot.order_id);
  SELECT * INTO v_event FROM public.production_collection_events
  WHERE piece_id = v_piece.id ORDER BY created_at DESC LIMIT 1;
  NEW.event_type := 'rejected_scan';
  NEW.tag_value := COALESCE(NULLIF(NEW.tag_value, ''), v_piece.traceability_code, v_piece.piece_uid);
  NEW.piece_code := COALESCE(NULLIF(NEW.piece_code, ''), v_piece.piece_code,
                             v_piece.traceability_code, v_piece.piece_uid);
  NEW.lot_id := COALESCE(NEW.lot_id, v_piece.lot_id);
  NEW.production_order_id := COALESCE(NEW.production_order_id, v_piece.production_order_id,
                                      v_lot.production_order_id, v_lot.order_id);
  NEW.lot_code := COALESCE(NULLIF(NEW.lot_code, ''), NULLIF(v_piece.lot_code, ''),
                           NULLIF(v_event.lot_code, ''), v_lot.lot_code);
  NEW.order_number := COALESCE(NULLIF(NEW.order_number, ''), NULLIF(v_piece.order_number, ''),
                                NULLIF(v_event.order_number, ''), v_order.order_number, v_order.order_code);
  NEW.customer_name := COALESCE(NULLIF(NEW.customer_name, ''), NULLIF(v_piece.customer_name, ''),
                                 NULLIF(v_event.customer_name, ''), v_order.customer_name);
  NEW.environment_name := COALESCE(NULLIF(NEW.environment_name, ''),
                                    NULLIF(v_piece.environment_name, ''),
                                    NULLIF(v_piece.environment, ''),
                                    NULLIF(v_event.environment_name, ''), 'Geral / Produção');
  NEW.step_name := COALESCE(NULLIF(NEW.step_name, ''), NULLIF(v_event.operation_name, ''),
                            NULLIF(v_piece.current_stage, ''), 'Coleta');
  NEW.operation_name := COALESCE(NULLIF(NEW.operation_name, ''), NEW.step_name);
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enrich_replacement_order_context()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_piece public.production_pieces%ROWTYPE;
  v_lot public.production_lots%ROWTYPE;
  v_order public.production_orders%ROWTYPE;
  v_event public.production_collection_events%ROWTYPE;
  v_stage text;
  v_general_lot text;
BEGIN
  IF NEW.original_piece_id IS NULL THEN RETURN NEW; END IF;
  SELECT * INTO v_piece FROM public.production_pieces WHERE id = NEW.original_piece_id;
  IF v_piece.id IS NULL THEN RETURN NEW; END IF;
  SELECT * INTO v_lot FROM public.production_lots WHERE id = v_piece.lot_id;
  SELECT * INTO v_order FROM public.production_orders
  WHERE id = COALESCE(v_piece.production_order_id, v_lot.production_order_id, v_lot.order_id);
  SELECT * INTO v_event FROM public.production_collection_events
  WHERE piece_id = v_piece.id ORDER BY created_at DESC LIMIT 1;
  SELECT r.step_name INTO v_stage
  FROM public.production_stage_readings r
  WHERE r.piece_id = v_piece.id
    AND r.status IN ('pending_review', 'rejected', 'approved')
  ORDER BY CASE r.status WHEN 'pending_review' THEN 0 WHEN 'rejected' THEN 1 ELSE 2 END,
           r.created_at DESC LIMIT 1;
  v_general_lot := NULLIF(v_event.general_lot_code, '');
  IF v_general_lot IS NULL AND v_piece.pcp_import_batch_id IS NOT NULL THEN
    SELECT general_lot_code INTO v_general_lot
    FROM public.promob_import_batches WHERE id = v_piece.pcp_import_batch_id;
  END IF;
  NEW.lot_id := COALESCE(NEW.lot_id, v_piece.lot_id);
  NEW.production_order_id := COALESCE(NEW.production_order_id, v_piece.production_order_id,
                                      v_lot.production_order_id, v_lot.order_id);
  NEW.lot_code := COALESCE(NULLIF(NEW.lot_code, ''), NULLIF(v_piece.lot_code, ''),
                           NULLIF(v_event.lot_code, ''), v_lot.lot_code);
  NEW.general_lot_code := COALESCE(NULLIF(NEW.general_lot_code, ''), v_general_lot);
  NEW.order_number := COALESCE(NULLIF(NEW.order_number, ''), NULLIF(v_piece.order_number, ''),
                                NULLIF(v_event.order_number, ''), v_order.order_number, v_order.order_code);
  NEW.customer_name := COALESCE(NULLIF(NEW.customer_name, ''), NULLIF(v_piece.customer_name, ''),
                                 NULLIF(v_event.customer_name, ''), v_order.customer_name);
  NEW.environment_name := COALESCE(NULLIF(NEW.environment_name, ''),
                                    NULLIF(v_piece.environment_name, ''),
                                    NULLIF(v_piece.environment, ''),
                                    NULLIF(v_event.environment_name, ''), 'Geral / Produção');
  NEW.operator_id := COALESCE(NEW.operator_id, v_event.operator_id);
  NEW.operator_name := COALESCE(NULLIF(NEW.operator_name, ''), NULLIF(v_event.operator_name, ''));
  NEW.origin_cell_name := COALESCE(NULLIF(NEW.origin_cell_name, ''), NULLIF(v_event.cell_name, ''));
  NEW.rejection_stage := CASE
    WHEN NEW.rejection_stage IS NULL
      OR lower(NEW.rejection_stage) IN ('concluída', 'concluida', 'completed', 'created')
      THEN COALESCE(NULLIF(v_stage, ''), NULLIF(v_event.operation_name, ''),
                    NULLIF(v_piece.current_stage, ''), 'Corte')
    ELSE NEW.rejection_stage
  END;
  NEW.updated_at := now();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enrich_stage_reading_context()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  SELECT COALESCE(production_order_id, order_id) INTO NEW.production_order_id FROM production_lots WHERE id = NEW.lot_id;
  IF NEW.order_item_id IS NULL THEN
    SELECT poi.id INTO NEW.order_item_id FROM production_order_items poi
    LEFT JOIN production_lot_items pli ON pli.id = NEW.item_id
    WHERE poi.lot_id = NEW.lot_id AND (pli.id IS NULL OR poi.product_code = pli.product_code OR poi.product_name = pli.product_name)
    ORDER BY poi.created_at LIMIT 1;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.finalize_collection_realtime(p_client_event_id text, p_result jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'realtime', 'pg_temp'
AS $function$
DECLARE
  v_event public.production_collection_events%ROWTYPE;
  v_snapshot jsonb;
  v_result jsonb := coalesce(p_result, '{}'::jsonb);
  v_cell_id uuid;
  v_lot_version bigint;
  v_payload jsonb;
BEGIN
  IF nullif(btrim(p_client_event_id), '') IS NULL THEN
    RETURN v_result;
  END IF;

  SELECT * INTO v_event
  FROM public.production_collection_events event
  WHERE event.client_event_id = p_client_event_id
  FOR UPDATE;

  IF v_event.id IS NULL THEN
    RETURN v_result;
  END IF;

  IF v_event.broadcasted_at IS NOT NULL
     AND v_event.result_payload IS NOT NULL
     AND v_event.result_payload <> '{}'::jsonb THEN
    RETURN v_event.result_payload;
  END IF;

  IF v_event.result_status = 'approved'
     AND v_event.lot_id IS NOT NULL
     AND v_event.reading_id IS NOT NULL THEN
    v_snapshot := public.refresh_collection_lot_state(v_event.lot_id, v_event.reading_id);
    v_lot_version := nullif(v_snapshot ->> 'state_version', '')::bigint;
    v_result := v_result || jsonb_build_object(
      'lot', v_snapshot,
      'lot_snapshot', v_snapshot,
      'lot_version', coalesce(v_lot_version, 0)
    );
  ELSIF v_event.lot_id IS NOT NULL THEN
    SELECT state_version INTO v_lot_version
    FROM public.production_lots
    WHERE id = v_event.lot_id;
  END IF;

  v_cell_id := v_event.cell_id;
  IF v_cell_id IS NULL AND nullif(btrim(v_event.cell_name), '') IS NOT NULL THEN
    SELECT id INTO v_cell_id
    FROM public.cells
    WHERE lower(btrim(name)) = lower(btrim(v_event.cell_name))
    ORDER BY created_at
    LIMIT 1;
  END IF;

  v_result := v_result || jsonb_build_object(
    'collection_event_id', v_event.id,
    'client_event_id', v_event.client_event_id,
    'lot_version', coalesce(v_lot_version, 0)
  );

  v_payload := jsonb_build_object(
    'event_id', v_event.id,
    'client_event_id', v_event.client_event_id,
    'lot_id', v_event.lot_id,
    'pcp_import_batch_id', v_event.pcp_import_batch_id,
    'piece_id', v_event.piece_id,
    'cell_id', v_cell_id,
    'cell_name', v_event.cell_name,
    'machine_id', v_event.machine_id,
    'status', v_event.result_status,
    'reason_code', coalesce(v_event.reason_code, v_result ->> 'reason_code'),
    'lot_version', coalesce(v_lot_version, 0),
    'occurred_at', coalesce(
      v_event.occurred_at,
      v_event.sync_finished_at,
      v_event.updated_at,
      clock_timestamp()
    )
  );

  UPDATE public.production_collection_events
  SET lot_state_version = v_lot_version,
      result_payload = v_result,
      reason_code = coalesce(
        reason_code,
        v_result ->> 'reason_code',
        CASE result_status
          WHEN 'duplicated' THEN 'DUPLICATE_PIECE_STAGE'
          WHEN 'wrong_step' THEN 'WRONG_PRODUCTION_STEP'
          WHEN 'wrong_cell' THEN 'WRONG_CELL'
          WHEN 'blocked' THEN 'PRODUCTION_BLOCKED'
          ELSE NULL
        END
      ),
      broadcast_error = NULL,
      updated_at = clock_timestamp()
  WHERE id = v_event.id;

  IF v_cell_id IS NOT NULL THEN
    BEGIN
      PERFORM realtime.send(
        v_payload,
        'collection_committed',
        'production:cell:' || v_cell_id::text,
        true
      );

      UPDATE public.production_collection_events
      SET broadcasted_at = clock_timestamp(),
          broadcast_error = NULL,
          updated_at = clock_timestamp()
      WHERE id = v_event.id;
    EXCEPTION WHEN OTHERS THEN
      UPDATE public.production_collection_events
      SET broadcast_error = left(SQLERRM, 500),
          updated_at = clock_timestamp()
      WHERE id = v_event.id;
    END;
  END IF;

  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.finish_production_downtime_impl(p_occurrence_id uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  v_occ record;
  v_ended_at timestamptz := COALESCE((p_payload->>'ended_at')::timestamptz, now());
  v_duration numeric;
  v_notes text := p_payload->>'notes';
BEGIN
  SELECT * INTO v_occ FROM public.occurrences WHERE id = p_occurrence_id;
  IF v_occ IS NULL THEN
    RAISE EXCEPTION 'Ocorrência de parada não encontrada.';
  END IF;

  IF v_occ.status = 'resolved' AND v_occ.ended_at IS NOT NULL THEN
    RETURN jsonb_build_object('success', true, 'already_finished', true, 'duration_minutes', v_occ.duration_minutes);
  END IF;

  v_duration := ROUND(EXTRACT(EPOCH FROM (v_ended_at - COALESCE(v_occ.started_at, v_occ.created_at))) / 60.0, 2);
  IF v_duration < 0 THEN
    v_duration := 0;
  END IF;

  UPDATE public.occurrences
  SET ended_at = v_ended_at,
      duration_minutes = v_duration,
      downtime = v_duration,
      status = 'resolved',
      notes = CASE WHEN v_notes IS NOT NULL THEN COALESCE(notes, '') || ' | Encerramento: ' || v_notes ELSE notes END,
      updated_at = now()
  WHERE id = p_occurrence_id;

  RETURN jsonb_build_object(
    'success', true,
    'occurrence_id', p_occurrence_id,
    'status', 'resolved',
    'duration_minutes', v_duration,
    'ended_at', v_ended_at
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.finish_production_downtime(p_occurrence_id uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
declare
  v_cell_name text;
begin
  if coalesce(auth.role(), '') <> 'service_role' and not public.can_manage_occurrences() then
    raise exception 'OCCURRENCE_PERMISSION_REQUIRED' using errcode = '42501';
  end if;
  select coalesce(cell.name, occurrence.cell)
    into v_cell_name
  from public.occurrences occurrence
  left join public.cells cell on cell.id = occurrence.cell_id
  where occurrence.id = p_occurrence_id
    and occurrence.occurrence_type = 'downtime';
  if v_cell_name is null then
    raise exception 'DOWNTIME_OCCURRENCE_NOT_FOUND' using errcode = 'P0002';
  end if;
  if coalesce(auth.role(), '') <> 'service_role' and not public.profile_can_access_cell(v_cell_name) then
    raise exception 'OCCURRENCE_OUTSIDE_CELL_SCOPE' using errcode = '42501';
  end if;
  return public.finish_production_downtime_impl(p_occurrence_id, coalesce(p_payload, '{}'::jsonb));
end;
$function$

CREATE OR REPLACE FUNCTION public.force_complete_piece_replacement_impl(p_order_id uuid, p_reason text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'realtime', 'pg_temp'
AS $function$
DECLARE
  v_order public.replacement_orders%ROWTYPE;
  v_original public.production_pieces%ROWTYPE;
  v_replacement public.production_pieces%ROWTYPE;
  v_user_id uuid := auth.uid();
  v_user_role text := public.get_my_role();
  v_user_name text := coalesce(
    nullif(current_setting('request.jwt.claims', true)::jsonb ->> 'email', ''),
    v_user_id::text,
    'service_role'
  );
  v_reason text := btrim(coalesce(p_reason, ''));
  v_route_codes text[] := '{}'::text[];
  v_route_value text;
  v_step_code text;
  v_cell public.cells%ROWTYPE;
  v_client_event_id text;
  v_approval_result jsonb;
  v_reading_count integer := 0;
BEGIN
  IF auth.role() <> 'service_role' AND v_user_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED' USING ERRCODE = '42501';
  END IF;

  IF NOT public.can_manage_replacement_actions() THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Qualidade, Supervisor/Líder, Gestor ou Administrador são obrigatórios para a conclusão forçada.'
    );
  END IF;

  IF v_reason = '' THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'É obrigatório informar a justificativa para a conclusão forçada.'
    );
  END IF;

  SELECT * INTO v_order
  FROM public.replacement_orders
  WHERE id = p_order_id
  FOR UPDATE;

  IF v_order.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Ordem de reposição não localizada.');
  END IF;

  IF v_order.status = 'completed' THEN
    RETURN jsonb_build_object(
      'success', true,
      'already_completed', true,
      'order_id', v_order.id,
      'status', 'completed'
    );
  END IF;

  IF v_order.status = 'cancelled' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Uma reposição cancelada não pode ser concluída.');
  END IF;

  IF v_order.replacement_piece_id IS NULL THEN
    v_approval_result := public.approve_piece_replacement(
      p_order_id,
      jsonb_build_object('priority', coalesce(v_order.priority, 'normal'))
    );

    IF NOT coalesce((v_approval_result ->> 'success')::boolean, false) THEN
      RETURN v_approval_result;
    END IF;

    SELECT * INTO v_order
    FROM public.replacement_orders
    WHERE id = p_order_id
    FOR UPDATE;
  END IF;

  SELECT * INTO v_original
  FROM public.production_pieces
  WHERE id = v_order.original_piece_id
  FOR UPDATE;

  SELECT * INTO v_replacement
  FROM public.production_pieces
  WHERE id = v_order.replacement_piece_id
  FOR UPDATE;

  IF v_replacement.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Peça substituta não localizada após a aprovação.');
  END IF;

  FOREACH v_route_value IN ARRAY coalesce(v_replacement.route_steps, '{}'::text[]) LOOP
    v_step_code := public.normalize_replacement_step_code(v_route_value);
    IF v_step_code IS NOT NULL AND NOT (v_step_code = ANY(v_route_codes)) THEN
      v_route_codes := array_append(v_route_codes, v_step_code);
    END IF;
  END LOOP;

  IF cardinality(v_route_codes) = 0 THEN
    IF coalesce(v_replacement.requires_cut, false) THEN v_route_codes := array_append(v_route_codes, 'cut'); END IF;
    IF coalesce(v_replacement.requires_edge, false) THEN v_route_codes := array_append(v_route_codes, 'edge'); END IF;
    IF coalesce(v_replacement.requires_cnc, false) THEN v_route_codes := array_append(v_route_codes, 'cnc'); END IF;
    IF coalesce(v_replacement.requires_joinery, false) THEN v_route_codes := array_append(v_route_codes, 'joinery'); END IF;
    IF coalesce(v_replacement.requires_separation, false) THEN v_route_codes := array_append(v_route_codes, 'separation'); END IF;
    IF coalesce(v_replacement.requires_packaging, false) THEN v_route_codes := array_append(v_route_codes, 'packaging'); END IF;
  END IF;

  IF cardinality(v_route_codes) = 0 THEN
    v_route_codes := ARRAY['cut'];
  END IF;

  FOREACH v_step_code IN ARRAY v_route_codes LOOP
    IF NOT EXISTS (
      SELECT 1
      FROM public.production_stage_readings reading
      WHERE reading.piece_id = v_replacement.id
        AND reading.status = 'approved'
        AND public.normalize_replacement_step_code(reading.step_name) = v_step_code
    ) THEN
      SELECT * INTO v_cell
      FROM public.cells cell
      WHERE cell.active IS TRUE
        AND public.replacement_cell_matches_step(cell.name, v_step_code)
      ORDER BY cell.name
      LIMIT 1;

      v_client_event_id := 'replacement-force:' || v_order.id::text || ':' || v_step_code;

      INSERT INTO public.production_stage_readings (
        client_event_id, tag_value, tag_type, reader_type,
        station_name, cell_name, operator, operator_name_snapshot,
        user_id, operator_id, shift, date, hour,
        item_id, piece_id, lot_id, production_order_id,
        step_name, operation_name, quantity, status, event_type,
        notes, lot_code, order_number, customer_name, environment_name,
        piece_code, production_cycle, entry_type, traceability_type,
        is_manual, unit_of_measure, general_lot_code, created_at
      ) VALUES (
        v_client_event_id,
        coalesce(v_order.replacement_barcode, v_replacement.piece_code, v_replacement.traceability_code),
        'barcode', 'api',
        'Conclusão Forçada de Reposição',
        coalesce(v_cell.name, v_step_code),
        v_user_name, v_user_name,
        v_user_id, v_order.operator_id,
        'Conclusão forçada', current_date, to_char(clock_timestamp(), 'HH24:MI'),
        coalesce(v_replacement.legacy_production_lot_item_id, v_replacement.lot_item_id),
        v_replacement.id, v_replacement.lot_id, v_replacement.production_order_id,
        v_step_code, v_step_code, 1, 'approved', 'manual_adjustment',
        'Conclusão forçada auditada — ' || v_reason,
        coalesce(v_order.lot_code, v_replacement.lot_code),
        coalesce(v_order.order_number, v_replacement.order_number),
        coalesce(v_order.customer_name, v_replacement.customer_name),
        coalesce(v_order.environment_name, v_replacement.environment_name, v_replacement.environment),
        coalesce(v_order.replacement_barcode, v_replacement.piece_code),
        1, 'conclusao_forcada_reposicao', 'unitaria', true, 'pecas',
        v_order.general_lot_code, clock_timestamp()
      )
      ON CONFLICT DO NOTHING;

      GET DIAGNOSTICS v_reading_count = ROW_COUNT;
    END IF;
  END LOOP;

  UPDATE public.production_pieces
  SET completed_steps = v_route_codes,
      status = 'completed',
      production_status = 'completed',
      replacement_status = 'replaced',
      current_stage = 'Concluída',
      updated_at = clock_timestamp()
  WHERE id = v_replacement.id;

  IF v_original.id IS NOT NULL THEN
    UPDATE public.production_pieces
    SET status = 'replaced',
        replacement_status = 'replaced',
        updated_at = clock_timestamp()
    WHERE id = v_original.id;
  END IF;

  UPDATE public.replacement_orders
  SET status = 'completed',
      completed_at = clock_timestamp(),
      notes = concat_ws(
        ' ',
        nullif(notes, ''),
        '[Conclusão forçada: ' || v_reason || ']'
      ),
      updated_at = clock_timestamp()
  WHERE id = v_order.id;

  UPDATE public.quality_nonconformities
  SET status = 'closed',
      closed_at = clock_timestamp(),
      closed_by = v_user_id
  WHERE related_replacement_id = p_order_id
    AND status <> 'closed';

  INSERT INTO public.replacement_action_audit_logs (
    replacement_order_id, replacement_code, action,
    performed_by, performed_by_name, performed_by_role,
    reason, status_before, status_after,
    original_piece_id, replacement_piece_id,
    current_stage_before, current_stage_after,
    metadata
  ) VALUES (
    v_order.id, v_order.replacement_code, 'force_completed',
    v_user_id, v_user_name, v_user_role,
    v_reason, v_order.status, 'completed',
    v_order.original_piece_id, v_order.replacement_piece_id,
    v_replacement.current_stage, 'Concluída',
    jsonb_build_object(
      'forced_stage_facts_created', v_reading_count,
      'route_steps', to_jsonb(v_route_codes),
      'payload', coalesce(p_payload, '{}'::jsonb),
      'source', 'replacement_force_completion'
    )
  );

  BEGIN
    FOREACH v_step_code IN ARRAY v_route_codes LOOP
      SELECT * INTO v_cell
      FROM public.cells cell
      WHERE cell.active IS TRUE
        AND public.replacement_cell_matches_step(cell.name, v_step_code)
      ORDER BY cell.name
      LIMIT 1;

      IF v_cell.id IS NOT NULL THEN
        PERFORM public.recalculate_cell_lot_state(
          v_replacement.lot_id,
          v_cell.name,
          v_step_code,
          NULL::uuid,
          NULL::uuid
        );
      END IF;
    END LOOP;

    PERFORM public.refresh_collection_lot_state(
      v_replacement.lot_id,
      v_replacement.pcp_import_batch_id
    );
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  BEGIN
    PERFORM realtime.send(
      jsonb_build_object(
        'replacement_order_id', v_order.id,
        'replacement_piece_id', v_replacement.id,
        'replacement_code', v_order.replacement_code,
        'status', 'completed',
        'forced', true,
        'occurred_at', clock_timestamp()
      ),
      'replacement_force_completed',
      'replacement:global',
      true
    );
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  RETURN jsonb_build_object(
    'success', true,
    'order_id', v_order.id,
    'status', 'completed',
    'forced', true,
    'reason', v_reason,
    'message', 'Conclusão forçada registrada com sucesso e auditada.'
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_piece_uid()
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_date  text := to_char(now(), 'YYYYMMDD');
  v_rand  text := upper(substring(encode(extensions.gen_random_bytes(4), 'hex') FROM 1 FOR 6));
  v_uid   text;
BEGIN
  v_uid := 'PC-' || v_date || '-' || v_rand;
  WHILE EXISTS (SELECT 1 FROM production_pieces WHERE piece_uid = v_uid) LOOP
    v_rand := upper(substring(encode(extensions.gen_random_bytes(4), 'hex') FROM 1 FOR 6));
    v_uid  := 'PC-' || v_date || '-' || v_rand;
  END LOOP;
  RETURN v_uid;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_acprod_capacity_health()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'storage'
AS $function$
declare
  v_database_bytes bigint := 0;
  v_audit_bytes bigint := 0;
  v_collection_bytes bigint := 0;
  v_storage_bytes bigint := 0;
  v_storage_objects bigint := 0;
  v_pending_archives bigint := 0;
  v_failed_archives bigint := 0;
  v_oldest_pending timestamptz;
  v_verified_archives bigint := 0;
  v_events_today bigint := 0;
  v_events_month bigint := 0;
  v_projected_events bigint := 0;
  v_estimated_messages bigint := 0;
  v_days_elapsed numeric := greatest(extract(day from now()), 1);
  v_days_in_month numeric := extract(
    day from (date_trunc('month', now()) + interval '1 month - 1 day')
  );
  v_assumed_listeners integer := 10;
  v_collection_count_30d bigint := 0;
  v_collection_errors_30d bigint := 0;
  v_active_devices_24h bigint := 0;
  v_latency_p50 numeric;
  v_latency_p95 numeric;
  v_latency_p99 numeric;
  v_latency_max numeric;
  v_active_connections integer := 0;
  v_max_connections integer := 0;
  v_pending_import_chunks bigint := 0;
  v_failed_import_chunks bigint := 0;
  v_last_verified_backup timestamptz;
  v_database_status text;
  v_realtime_status text;
begin
  if (select auth.uid()) is null or not exists (
    select 1
    from public.profiles profile
    where profile.id = (select auth.uid())
      and profile.active is distinct from false
      and profile.role in ('admin', 'manager')
  ) then
    raise exception 'CAPACITY_PERMISSION_REQUIRED'
      using errcode = '42501';
  end if;

  select pg_database_size(current_database())
  into v_database_bytes;

  select pg_total_relation_size('public.system_audit_logs'::regclass)
  into v_audit_bytes;

  select
    pg_total_relation_size('public.production_collection_events'::regclass)
    + pg_total_relation_size('public.production_stage_readings'::regclass)
    + pg_total_relation_size('public.production_pieces'::regclass)
  into v_collection_bytes;

  select
    coalesce(sum(nullif(object.metadata ->> 'size', '')::bigint), 0),
    count(*)
  into v_storage_bytes, v_storage_objects
  from storage.objects object;

  select
    count(*) filter (where job.status in ('pending', 'processing')),
    count(*) filter (where job.status = 'failed'),
    min(job.created_at) filter (where job.status in ('pending', 'processing', 'failed'))
  into v_pending_archives, v_failed_archives, v_oldest_pending
  from public.production_archive_jobs job;

  select count(*)
  into v_verified_archives
  from public.production_archive_manifests manifest
  where manifest.status in ('verified', 'purged');

  select
    count(*) filter (where event.broadcasted_at >= date_trunc('day', now())),
    count(*) filter (where event.broadcasted_at >= date_trunc('month', now()))
  into v_events_today, v_events_month
  from public.production_collection_events event
  where event.broadcasted_at >= date_trunc('month', now());

  v_projected_events := ceil((v_events_month::numeric / v_days_elapsed) * v_days_in_month);
  v_estimated_messages := v_projected_events * v_assumed_listeners;

  with recent as (
    select
      coalesce(
        event.sync_duration_ms,
        extract(epoch from (event.processed_at - event.server_received_at)) * 1000
      )::numeric as latency_ms,
      event.status,
      event.device_id,
      event.created_at
    from public.production_collection_events event
    where event.created_at >= now() - interval '30 days'
  )
  select
    count(*),
    count(*) filter (where status in ('error', 'failed')),
    count(distinct device_id) filter (
      where device_id is not null
        and created_at >= now() - interval '24 hours'
    ),
    round((percentile_cont(0.50) within group (order by latency_ms)
      filter (where latency_ms is not null))::numeric, 2),
    round((percentile_cont(0.95) within group (order by latency_ms)
      filter (where latency_ms is not null))::numeric, 2),
    round((percentile_cont(0.99) within group (order by latency_ms)
      filter (where latency_ms is not null))::numeric, 2),
    round(max(latency_ms), 2)
  into
    v_collection_count_30d,
    v_collection_errors_30d,
    v_active_devices_24h,
    v_latency_p50,
    v_latency_p95,
    v_latency_p99,
    v_latency_max
  from recent;

  select
    count(*) filter (where chunk.status in ('pending', 'upload_verified', 'processing')),
    count(*) filter (where chunk.status = 'error')
  into v_pending_import_chunks, v_failed_import_chunks
  from public.pcp_import_chunks chunk;

  select greatest(
    (select max(manifest.verified_at)
     from public.pcp_import_manifests manifest
     where manifest.status = 'verified'),
    (select max(backup.generated_at)
     from public.backup_files backup
     where backup.status in ('available', 'verified'))
  )
  into v_last_verified_backup;

  select
    count(*) filter (where activity.backend_type = 'client backend'),
    current_setting('max_connections')::integer
  into v_active_connections, v_max_connections
  from pg_stat_activity activity;

  v_database_status := case
    when v_database_bytes >= 7516192768 then 'critical'
    when v_database_bytes >= 6442450944 then 'controlled'
    when v_database_bytes >= 5368709120 then 'archive_required'
    when v_database_bytes >= 4294967296 then 'attention'
    else 'healthy'
  end;

  v_realtime_status := case
    when v_estimated_messages >= 5000000 then 'critical'
    when v_estimated_messages >= 4000000 then 'attention'
    else 'healthy'
  end;

  return jsonb_build_object(
    'captured_at', now(),
    'database', jsonb_build_object(
      'bytes', v_database_bytes,
      'gigabytes', round(v_database_bytes::numeric / 1073741824, 3),
      'included_bytes', 8589934592,
      'attention_bytes', 4294967296,
      'archive_required_bytes', 5368709120,
      'controlled_bytes', 6442450944,
      'critical_bytes', 7516192768,
      'status', v_database_status
    ),
    'storage', jsonb_build_object(
      'bytes', v_storage_bytes,
      'gigabytes', round(v_storage_bytes::numeric / 1073741824, 3),
      'objects', v_storage_objects
    ),
    'hot_tables', jsonb_build_object(
      'audit_bytes', v_audit_bytes,
      'collection_bytes', v_collection_bytes
    ),
    'realtime', jsonb_build_object(
      'logical_events_today', v_events_today,
      'logical_events_month', v_events_month,
      'projected_logical_events_month', v_projected_events,
      'assumed_average_listeners', v_assumed_listeners,
      'projected_messages_month', v_estimated_messages,
      'included_messages', 5000000,
      'internal_target_messages', 4000000,
      'status', v_realtime_status
    ),
    'collection', jsonb_build_object(
      'events_30d', v_collection_count_30d,
      'infrastructure_errors_30d', v_collection_errors_30d,
      'error_rate_percent', case
        when v_collection_count_30d = 0 then 0
        else round(v_collection_errors_30d::numeric * 100 / v_collection_count_30d, 3)
      end,
      'active_devices_24h', v_active_devices_24h,
      'latency_ms', jsonb_build_object(
        'p50', v_latency_p50,
        'p95', v_latency_p95,
        'p99', v_latency_p99,
        'max', v_latency_max
      )
    ),
    'connections', jsonb_build_object(
      'active', v_active_connections,
      'configured_max', v_max_connections,
      'percent', case
        when v_max_connections = 0 then 0
        else round(v_active_connections::numeric * 100 / v_max_connections, 2)
      end
    ),
    'archives', jsonb_build_object(
      'pending', v_pending_archives,
      'failed', v_failed_archives,
      'verified', v_verified_archives,
      'oldest_pending_at', v_oldest_pending
    ),
    'imports', jsonb_build_object(
      'pending_chunks', v_pending_import_chunks,
      'failed_chunks', v_failed_import_chunks,
      'last_verified_backup_at', v_last_verified_backup,
      'default_chunk_size', 500,
      'piece_limit', null
    ),
    'operational_policy', jsonb_build_object(
      'hot_detail_days', 90,
      'audit_hot_days', 90,
      'retention_months', 36,
      'collection_priority', 1,
      'blocking_rules', false,
      'realtime_recommendation', case
        when v_realtime_status = 'healthy' then 'segmented_broadcast'
        else 'poll_nonessential_dashboards'
      end
    ),
    'platform_metrics', jsonb_build_object(
      'cpu', 'Supabase Dashboard',
      'memory', 'Supabase Dashboard',
      'egress', 'Supabase Dashboard',
      'edge_invocations', 'Supabase Dashboard'
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.get_ai_capability_context()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_role text;
  v_permissions jsonb := '{}'::jsonb;
  v_capabilities jsonb;
begin
  if auth.uid() is null then
    raise exception 'AUTH_REQUIRED';
  end if;

  select p.role, coalesce(p.permissions, '{}'::jsonb)
  into v_role, v_permissions
  from public.profiles p
  where p.id = auth.uid()
    and p.active is distinct from false;

  if v_role is null then
    raise exception 'ACCESS_DENIED';
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'code', c.code,
        'label', c.label,
        'description', c.description,
        'actions', c.actions,
        'routes', c.routes,
        'metadata', c.metadata
      )
      order by c.code
    ),
    '[]'::jsonb
  )
  into v_capabilities
  from public.ai_capabilities c
  where c.active
    and (
      v_role in ('admin', 'manager')
      or cardinality(c.required_permissions) = 0
      or exists (
        select 1
        from unnest(c.required_permissions) permission_name
        where lower(coalesce(v_permissions ->> permission_name, 'false')) in ('true', '1')
      )
    );

  return jsonb_build_object(
    'generatedAt', now(),
    'role', v_role,
    'capabilities', v_capabilities
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.get_client_lot_progress(p_lot_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_lot record;
  v_total_parts bigint := 0;
  v_completed_parts bigint := 0;
  v_total_operations bigint := 0;
  v_completed_operations bigint := 0;
  v_progress_percent numeric(5,2) := 0;
BEGIN
  SELECT * INTO v_lot FROM public.production_lots WHERE id = p_lot_id;
  IF v_lot.id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT
    count(*),
    count(*) FILTER (WHERE p.status IN ('completed','packed','inspected','ready_for_shipping','shipped')),
    COALESCE(sum(cardinality(COALESCE(p.route_steps, '{}'::text[]))), 0),
    COALESCE(sum(cardinality(ARRAY(
      SELECT DISTINCT step
      FROM unnest(COALESCE(p.route_steps, '{}'::text[])) AS step
      WHERE step = ANY(COALESCE(p.completed_steps, '{}'::text[]))
    ))), 0)
  INTO v_total_parts, v_completed_parts, v_total_operations, v_completed_operations
  FROM public.production_pieces p
  WHERE p.lot_id = p_lot_id
    AND p.status NOT IN ('cancelled','replaced');

  v_progress_percent := CASE
    WHEN v_total_operations > 0 THEN ROUND((v_completed_operations::numeric / v_total_operations::numeric) * 100, 2)
    ELSE 0.0
  END;

  RETURN jsonb_build_object(
    'lot_id', p_lot_id,
    'lot_code', v_lot.lot_code,
    'total_parts', v_total_parts,
    'completed_parts', v_completed_parts,
    'pending_parts', GREATEST(v_total_parts - v_completed_parts, 0),
    'total_operations', v_total_operations,
    'completed_operations', v_completed_operations,
    'progress_percent', LEAST(GREATEST(v_progress_percent, 0), 100)
  );
END;
$function$

