CREATE OR REPLACE FUNCTION public.get_general_lot_tracking(p_batch_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 25)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  payload jsonb;
  route_progress jsonb;
  general_lots jsonb := '[]'::jsonb;
  client_lots jsonb;
  general_lot jsonb;
  client_lot jsonb;
  lot_stages jsonb;
  traceable_required integer;
  traceable_completed integer;
  route_complete boolean;
begin
  payload := public.get_general_lot_tracking_base(p_batch_id, p_limit);

  -- A listagem geral não traz lotes de clientes e deve continuar leve. A rota
  -- completa é anexada apenas quando um lote geral é aberto.
  if p_batch_id is null then
    return payload;
  end if;

  for general_lot in
    select item.value
    from jsonb_array_elements(
      coalesce(payload->'general_lots', '[]'::jsonb)
    ) item(value)
  loop
    route_progress := public.get_lot_route_stage_progress(
      (general_lot->>'batch_id')::uuid
    );
    client_lots := '[]'::jsonb;

    for client_lot in
      select item.value
      from jsonb_array_elements(
        coalesce(general_lot->'client_lots', '[]'::jsonb)
      ) item(value)
    loop
      lot_stages := coalesce(
        route_progress->'lot_stages'->(client_lot->>'lot_id'),
        '[]'::jsonb
      );

      if jsonb_array_length(lot_stages) > 0 then
        select
          coalesce(sum(
            coalesce((stage.value->>'required_pieces')::integer, 0)
          ) filter (
            where coalesce(
              (stage.value->>'traceable_collection_required')::boolean,
              true
            )
          ), 0)::integer,
          coalesce(sum(
            least(
              coalesce((stage.value->>'required_pieces')::integer, 0),
              coalesce(
                (stage.value->>'effective_completed_pieces')::integer,
                (stage.value->>'completed_pieces')::integer,
                0
              )
            )
          ) filter (
            where coalesce(
              (stage.value->>'traceable_collection_required')::boolean,
              true
            )
          ), 0)::integer,
          coalesce(bool_and(
            case
              when coalesce(
                (stage.value->>'traceable_collection_required')::boolean,
                true
              )
              and coalesce((stage.value->>'required_pieces')::integer, 0) > 0
              then coalesce(
                (stage.value->>'effective_completed_pieces')::integer,
                (stage.value->>'completed_pieces')::integer,
                0
              ) >= coalesce((stage.value->>'required_pieces')::integer, 0)
              else true
            end
          ), false)
          into traceable_required, traceable_completed, route_complete
        from jsonb_array_elements(lot_stages) stage(value);

        client_lot := client_lot || jsonb_build_object(
          'stages', lot_stages,
          'total_operations', traceable_required,
          'completed_operations', traceable_completed,
          'progress_percent', case
            when traceable_required > 0
              then round(100.0 * traceable_completed / traceable_required, 2)
            else 100.0
          end,
          'ready_for_separation', route_complete
        );
      end if;

      client_lots := client_lots || jsonb_build_array(client_lot);
    end loop;

    select
      coalesce(sum(
        coalesce((stage.value->>'required_pieces')::integer, 0)
      ) filter (
        where coalesce(
          (stage.value->>'traceable_collection_required')::boolean,
          true
        )
      ), 0)::integer,
      coalesce(sum(
        least(
          coalesce((stage.value->>'required_pieces')::integer, 0),
          coalesce(
            (stage.value->>'effective_completed_pieces')::integer,
            (stage.value->>'completed_pieces')::integer,
            0
          )
        )
      ) filter (
        where coalesce(
          (stage.value->>'traceable_collection_required')::boolean,
          true
        )
      ), 0)::integer,
      coalesce(bool_and(
        case
          when coalesce(
            (stage.value->>'traceable_collection_required')::boolean,
            true
          )
          and coalesce((stage.value->>'required_pieces')::integer, 0) > 0
          then coalesce(
            (stage.value->>'effective_completed_pieces')::integer,
            (stage.value->>'completed_pieces')::integer,
            0
          ) >= coalesce((stage.value->>'required_pieces')::integer, 0)
          else true
        end
      ), false)
      into traceable_required, traceable_completed, route_complete
    from jsonb_array_elements(
      coalesce(route_progress->'batch_stages', '[]'::jsonb)
    ) stage(value);

    general_lot := general_lot || jsonb_build_object(
      'stages', coalesce(route_progress->'batch_stages', '[]'::jsonb),
      'client_lots', client_lots,
      'total_operations', traceable_required,
      'completed_operations', traceable_completed,
      'progress_percent', case
        when traceable_required > 0
          then round(100.0 * traceable_completed / traceable_required, 2)
        else 100.0
      end,
      'ready_for_separation', route_complete
    );

    general_lots := general_lots || jsonb_build_array(general_lot);
  end loop;

  return jsonb_set(payload, '{general_lots}', general_lots, true);
end;
$function$

CREATE OR REPLACE FUNCTION public.get_operator_shift_kpis_v2(p_operator_id uuid, p_reference_time timestamp with time zone DEFAULT clock_timestamp())
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_window jsonb;
  v_start timestamptz;
  v_end timestamptz;
  v_inside boolean;
  v_approved bigint := 0;
  v_rejected bigint := 0;
  v_blocked bigint := 0;
BEGIN
  IF auth.uid() IS NULL OR p_operator_id IS NULL THEN
    RAISE EXCEPTION 'OPERATOR_SESSION_REQUIRED' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.operator_sessions session
    WHERE session.operator_id = p_operator_id
      AND session.auth_user_id = auth.uid()
      AND session.ended_at IS NULL
      AND session.revoked_at IS NULL
      AND session.expires_at > clock_timestamp()
  ) THEN
    RAISE EXCEPTION 'OPERATOR_SESSION_INVALID' USING ERRCODE = '42501';
  END IF;

  v_window := public.resolve_operator_shift_window(p_operator_id, p_reference_time);
  v_inside := coalesce((v_window ->> 'is_inside_shift')::boolean, false);
  v_start := (v_window ->> 'shift_started_at')::timestamptz;
  v_end := (v_window ->> 'shift_ends_at')::timestamptz;

  IF v_inside THEN
    SELECT
      count(DISTINCT coalesce(event.client_event_id, event.id::text))
        FILTER (WHERE event.result_status = 'approved'),
      count(DISTINCT coalesce(event.client_event_id, event.id::text))
        FILTER (WHERE event.result_status = 'rejected'),
      count(DISTINCT coalesce(event.client_event_id, event.id::text))
        FILTER (WHERE event.result_status IN ('blocked', 'duplicated'))
    INTO v_approved, v_rejected, v_blocked
    FROM public.production_collection_events event
    WHERE event.operator_id = p_operator_id
      AND event.occurred_at >= v_start
      AND event.occurred_at < v_end;
  END IF;

  RETURN jsonb_build_object(
    'operator_id', p_operator_id,
    'shift_work_date', v_window ->> 'shift_work_date',
    'shift_started_at', v_start,
    'shift_ends_at', v_end,
    'is_inside_shift', v_inside,
    'approved', v_approved,
    'produced_this_shift', v_approved,
    'rejected', v_rejected,
    'blocked', v_blocked,
    'server_time', clock_timestamp()
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.get_operator_shift_kpis_v2(p_operator_session_token text, p_reference_time timestamp with time zone DEFAULT clock_timestamp())
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_session public.operator_sessions%ROWTYPE;
  v_window jsonb;
  v_start timestamptz;
  v_end timestamptz;
  v_inside boolean;
  v_approved bigint := 0;
