 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
DECLARE
  secret_id uuid;
  decrypted text;
BEGIN
  SELECT token_reference::uuid INTO secret_id FROM promob_integrations WHERE id = integration_id;

