CREATE OR REPLACE FUNCTION public.handle_alert_logs_after()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
DECLARE
  v_action text;
  v_user_id uuid;
  v_note text;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_action := 'create';
    v_user_id := NEW.created_by;
    v_note := 'Alerta registrado pelo sistema.';
  ELSIF COALESCE(OLD.resolved, false) = false AND NEW.resolved = true THEN
    IF NEW.resolution_source = 'automatic' THEN
      v_action := 'resolve_auto';
      v_note := 'Resolvido automaticamente (condicao normalizada).';
    ELSE
      v_action := 'resolve_manual';
      v_user_id := NEW.resolved_by;
      v_note := COALESCE(NEW.resolution_note, 'Resolvido manualmente.');
    END IF;
  ELSIF OLD.resolved = true AND COALESCE(NEW.resolved, false) = false THEN
    v_action := 'reopen';
    v_note := 'Alerta reaberto apos nova ocorrencia da condicao.';
  ELSE
    RETURN NEW;
  END IF;

  INSERT INTO public.alert_action_history (
    alert_id,
    action,
    user_id,
    note,
    metadata
  ) VALUES (
    NEW.id,
    v_action,
    v_user_id,
    v_note,
    jsonb_build_object(
      'signature', NEW.signature,
      'cell', NEW.cell,
      'message', NEW.message,
      'severity', NEW.severity,
      'occurrence_count', NEW.occurrence_count,
      'condition_active', NEW.condition_active,
      'metadata', COALESCE(NEW.metadata, '{}'::jsonb)
    )
  );

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.handle_alert_logs_before()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
BEGIN
  NEW.source := COALESCE(NEW.source, 'mes_diagnostic');

  IF TG_OP = 'INSERT' THEN
    NEW.condition_active := COALESCE(NEW.condition_active, true);
    NEW.first_triggered_at := COALESCE(NEW.first_triggered_at, NEW.triggered_at, now());
    NEW.last_detected_at := COALESCE(NEW.last_detected_at, NEW.triggered_at, now());
    NEW.occurrence_count := GREATEST(COALESCE(NEW.occurrence_count, 1), 1);
    NEW.resolved := COALESCE(NEW.resolved, false);
    RETURN NEW;
  END IF;

  IF COALESCE(NEW.resolved, false) = false THEN
    NEW.condition_active := true;
    NEW.last_detected_at := now();

    IF COALESCE(OLD.resolved, false) = true THEN
      IF COALESCE(OLD.condition_active, true) = true
         AND COALESCE(OLD.resolution_source, 'manual') <> 'automatic' THEN
        -- E a mesma ocorrencia ainda ativa. Preserva integralmente a baixa manual.
        NEW.resolved := true;
        NEW.resolved_at := OLD.resolved_at;
        NEW.resolved_by := OLD.resolved_by;
        NEW.resolution_source := COALESCE(OLD.resolution_source, 'manual');
        NEW.resolution_note := OLD.resolution_note;
        NEW.triggered_at := OLD.triggered_at;
        NEW.first_triggered_at := OLD.first_triggered_at;
        NEW.occurrence_count := COALESCE(OLD.occurrence_count, 1);
      ELSE
        -- A condicao ja havia normalizado e voltou: nova ocorrencia legitima.
        NEW.resolved := false;
        NEW.resolved_at := NULL;
        NEW.resolved_by := NULL;
        NEW.resolution_source := NULL;
        NEW.resolution_note := NULL;
        NEW.triggered_at := now();
        NEW.first_triggered_at := COALESCE(OLD.first_triggered_at, OLD.triggered_at, now());
        NEW.occurrence_count := COALESCE(OLD.occurrence_count, 1) + 1;
      END IF;
    ELSE
      -- Continua sendo a mesma ocorrencia aberta.
      NEW.triggered_at := OLD.triggered_at;
      NEW.first_triggered_at := COALESCE(OLD.first_triggered_at, OLD.triggered_at, now());
      NEW.occurrence_count := COALESCE(OLD.occurrence_count, 1);
    END IF;
  ELSIF COALESCE(OLD.resolved, false) = false THEN
    -- Transicao aberta -> resolvida.
    NEW.resolved_at := COALESCE(NEW.resolved_at, now());
    NEW.resolution_source := COALESCE(NEW.resolution_source, 'manual');
    IF NEW.resolution_source = 'automatic' THEN
      NEW.condition_active := false;
    ELSE
      NEW.condition_active := COALESCE(OLD.condition_active, true);
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.handle_notification_config_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
BEGIN
  IF NEW.daily_closure_enabled = true THEN
    IF EXISTS (SELECT 1 FROM cron.job WHERE jobname = 'send-daily-closure-cron') THEN
      PERFORM cron.unschedule('send-daily-closure-cron');
    END IF;
    PERFORM cron.schedule(
      'send-daily-closure-cron',
      '0 6 * * *',
      $cron$
        SELECT net.http_post(
          url := 'https://uozuzdfvnufsjsonswag.supabase.co/functions/v1/sendDailyClosure',
          headers := '{"Content-Type": "application/json"}'::jsonb,
          body := '{}'::jsonb,
          timeout_milliseconds := 15000
        );
      $cron$
    );
  ELSE
    IF EXISTS (SELECT 1 FROM cron.job WHERE jobname = 'send-daily-closure-cron') THEN
      PERFORM cron.unschedule('send-daily-closure-cron');
    END IF;
  END IF;
  RETURN NEW;
EXCEPTION
  WHEN OTHERS THEN
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.has_permission(p_permission_key text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_role text;
  v_permissions jsonb;
  v_active boolean;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN false;
  END IF;

  SELECT role, permissions, active INTO v_role, v_permissions, v_active
  FROM public.profiles
  WHERE id = auth.uid();

  IF v_active = false THEN
    RETURN false;
  END IF;

  IF v_role = 'admin' THEN
    RETURN true;
  END IF;

  RETURN COALESCE((v_permissions ->> p_permission_key)::boolean, false);
END;
$function$

CREATE OR REPLACE FUNCTION public.heartbeat_operator_session(p_session_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_token_hash text := encode(extensions.digest(coalesce(p_session_token, ''), 'sha256'), 'hex');
  v_session public.operator_sessions%ROWTYPE;
  v_new_expires_at timestamptz;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('success', false, 'reason_code', 'AUTH_REQUIRED', 'error', 'Autenticação expirada.');
  END IF;

  SELECT *
  INTO v_session
  FROM public.operator_sessions
  WHERE token_hash = v_token_hash
    AND auth_user_id = auth.uid()
    AND ended_at IS NULL
    AND revoked_at IS NULL
    AND expires_at > clock_timestamp()
    AND sync_grace_until > clock_timestamp()
  FOR UPDATE;

  IF v_session.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'reason_code', 'SESSION_EXPIRED', 'error', 'Sessão expirada ou encerrada.');
  END IF;

  IF v_session.shift_ends_at IS NOT NULL
     AND clock_timestamp() >= v_session.shift_ends_at + interval '30 minutes' THEN
    RETURN jsonb_build_object(
      'success', false,
      'reason_code', 'SHIFT_ENDED',
      'error', 'O turno deste operador foi encerrado.',
      'shift_ends_at', v_session.shift_ends_at
    );
  END IF;

  v_new_expires_at := least(
    clock_timestamp() + interval '8 hours',
    coalesce(v_session.shift_ends_at + interval '30 minutes', clock_timestamp() + interval '8 hours')
  );

  UPDATE public.operator_sessions
  SET last_seen_at = clock_timestamp(),
      expires_at = v_new_expires_at
  WHERE id = v_session.id;

  RETURN jsonb_build_object(
    'success', true,
    'expires_at', v_new_expires_at,
    'shift_ends_at', v_session.shift_ends_at
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.logout_operator_session(p_session_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
declare
  v_token_hash text := encode(extensions.digest(coalesce(p_session_token, ''), 'sha256'), 'hex');
  v_session_id uuid;
begin
  if auth.uid() is null then
    return jsonb_build_object('success', false, 'reason_code', 'AUTH_REQUIRED', 'error', 'Autenticacao expirada.');
  end if;

  update public.operator_sessions
  set ended_at = clock_timestamp(), end_reason = 'user_logout'
  where token_hash = v_token_hash
    and auth_user_id = auth.uid()
    and ended_at is null
  returning id into v_session_id;

  return jsonb_build_object('success', true, 'session_id', v_session_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.mark_production_lot_retention()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF NEW.status IN ('closed', 'shipped', 'cancelled')
     AND (
       OLD.status IS DISTINCT FROM NEW.status
       OR NEW.closed_at IS NULL
     ) THEN
    NEW.closed_at := COALESCE(NEW.closed_at, NEW.actual_end, now());
    NEW.retention_until := COALESCE(
      NEW.retention_until,
      NEW.closed_at + interval '36 months'
    );
  ELSIF NEW.status NOT IN ('closed', 'shipped', 'cancelled')
        AND OLD.status IS DISTINCT FROM NEW.status THEN
    NEW.closed_at := NULL;
    NEW.retention_until := NULL;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.mask_registration(p_reg text)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
BEGIN
  IF p_reg IS NULL THEN RETURN NULL; END IF;
  IF length(p_reg) <= 2 THEN RETURN '**'; END IF;
  RETURN repeat('*', length(p_reg) - 2) || right(p_reg, 2);
END;
$function$

CREATE OR REPLACE FUNCTION public.normalize_collection_event_time()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE v_received timestamptz := COALESCE(NEW.server_received_at, NEW.created_at, clock_timestamp());
BEGIN
  IF NEW.occurred_at IS NULL THEN
    IF NEW.created_at_client IS NOT NULL AND NEW.created_at_client <= v_received + interval '5 minutes' AND NEW.created_at_client >= v_received - interval '32 hours' THEN
      NEW.occurred_at := NEW.created_at_client; NEW.timestamp_adjusted := false;
    ELSE
      NEW.occurred_at := v_received; NEW.timestamp_adjusted := NEW.created_at_client IS NOT NULL;
    END IF;
  END IF;
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.operator_login_v2(p_login_name text, p_registration text, p_device_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_auth_user_id uuid := auth.uid();
  v_login text := lower(btrim(coalesce(p_login_name, '')));
  v_registration text := btrim(coalesce(p_registration, ''));
  v_device_id text := btrim(coalesce(p_device_id, ''));
  v_operator public.operators%ROWTYPE;
  v_failed_count integer;
  v_token text;
  v_token_hash text;
  v_session_id uuid;
  v_window jsonb;
  v_shift_started_at timestamptz;
  v_shift_ends_at timestamptz;
  v_shift_work_date date;
  v_expires_at timestamptz;
  v_sync_grace_until timestamptz;
  v_cells jsonb;
  v_machines jsonb;
BEGIN
  IF v_auth_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'reason_code', 'AUTH_REQUIRED', 'error', 'Autenticação do sistema expirada. Entre novamente.');
  END IF;

  IF v_login = '' OR v_registration = '' OR v_device_id = '' THEN
    RETURN jsonb_build_object('success', false, 'reason_code', 'INVALID_CREDENTIALS', 'error', 'Login, matrícula e dispositivo são obrigatórios.');
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.profiles profile
    WHERE profile.id = v_auth_user_id
      AND profile.active IS DISTINCT FROM false
  ) THEN
    RETURN jsonb_build_object('success', false, 'reason_code', 'AUTH_USER_INACTIVE', 'error', 'Usuário do sistema inativo ou sem perfil operacional.');
  END IF;

  SELECT count(*) INTO v_failed_count
  FROM public.operator_access_attempts attempt
  WHERE attempt.login_name_input = v_login
    AND attempt.success = false
    AND attempt.created_at > clock_timestamp() - interval '10 minutes';

  IF v_failed_count >= 5 THEN
    INSERT INTO public.operator_access_attempts (login_name_input, success, failure_reason, device_id)
    VALUES (v_login, false, 'rate_limit_locked', v_device_id);
    RETURN jsonb_build_object('success', false, 'reason_code', 'LOGIN_RATE_LIMITED', 'error', 'Tentativas excedidas. Aguarde 10 minutos ou solicite o desbloqueio.');
  END IF;

  SELECT operator_row.*
  INTO v_operator
  FROM public.operators operator_row
  WHERE operator_row.active = true
    AND coalesce(operator_row.login_enabled, true) = true
    AND operator_row.deactivated_at IS NULL
    AND (
      lower(btrim(operator_row.login_name)) = v_login
      OR lower(btrim(operator_row.name)) = v_login
    )
  ORDER BY operator_row.created_at
  LIMIT 1;

  IF v_operator.id IS NULL
     OR v_operator.credential_hash IS NULL
     OR extensions.crypt(v_registration, v_operator.credential_hash) IS DISTINCT FROM v_operator.credential_hash THEN
    IF v_operator.id IS NOT NULL THEN
      UPDATE public.operators
      SET failed_login_count = failed_login_count + 1,
          locked_until = CASE
            WHEN failed_login_count + 1 >= 5 THEN clock_timestamp() + interval '10 minutes'
          END
      WHERE id = v_operator.id;
    END IF;

    INSERT INTO public.operator_access_attempts (login_name_input, success, failure_reason, device_id)
    VALUES (v_login, false, 'invalid_credentials', v_device_id);

    RETURN jsonb_build_object('success', false, 'reason_code', 'INVALID_CREDENTIALS', 'error', 'Operador não encontrado ou credenciais inválidas.');
  END IF;

  IF v_operator.locked_until IS NOT NULL
     AND v_operator.locked_until > clock_timestamp() THEN
    INSERT INTO public.operator_access_attempts (login_name_input, success, failure_reason, device_id)
    VALUES (v_login, false, 'locked_until_active', v_device_id);
    RETURN jsonb_build_object('success', false, 'reason_code', 'OPERATOR_LOCKED', 'error', 'Conta bloqueada temporariamente.');
  END IF;

  SELECT jsonb_agg(
           jsonb_build_object('id', cell.id, 'name', cell.name, 'is_primary', assignment.is_primary)
           ORDER BY assignment.is_primary DESC, cell.name
         )
  INTO v_cells
  FROM public.operator_cell_assignments assignment
  JOIN public.cells cell
    ON cell.id = assignment.cell_id
   AND cell.active = true
  WHERE assignment.operator_id = v_operator.id
    AND assignment.active = true
    AND assignment.valid_from <= clock_timestamp()
    AND (assignment.valid_until IS NULL OR assignment.valid_until > clock_timestamp());

  IF v_cells IS NULL OR jsonb_array_length(v_cells) = 0 THEN
    RETURN jsonb_build_object('success', false, 'reason_code', 'OPERATOR_WITHOUT_CELL', 'error', 'Operador sem célula de trabalho autorizada.');
  END IF;

  SELECT jsonb_agg(
           jsonb_build_object(
             'id', machine.id,
             'name', machine.name,
             'cell_id', cell.id,
             'cell_name', cell.name,
             'is_primary', coalesce(machine_assignment.is_primary, false),
             'allows_replacement', machine.allows_replacement
           )
           ORDER BY coalesce(machine_assignment.is_primary, false) DESC, cell.name, machine.name
         )
  INTO v_machines
  FROM public.production_machines machine
  JOIN public.cells cell
    ON lower(btrim(cell.name)) = lower(btrim(machine.cell_name))
  JOIN public.operator_cell_assignments cell_assignment
    ON cell_assignment.operator_id = v_operator.id
   AND cell_assignment.cell_id = cell.id
   AND cell_assignment.active = true
   AND cell_assignment.valid_from <= clock_timestamp()
   AND (cell_assignment.valid_until IS NULL OR cell_assignment.valid_until > clock_timestamp())
  LEFT JOIN public.operator_machine_assignments machine_assignment
    ON machine_assignment.operator_id = v_operator.id
   AND machine_assignment.machine_id = machine.id
   AND machine_assignment.active = true
   AND machine_assignment.valid_from <= clock_timestamp()
   AND (machine_assignment.valid_until IS NULL OR machine_assignment.valid_until > clock_timestamp())
  WHERE machine.active = true
    AND (
      machine_assignment.id IS NOT NULL
      OR NOT EXISTS (
        SELECT 1
        FROM public.operator_machine_assignments explicit_assignment
        WHERE explicit_assignment.operator_id = v_operator.id
          AND explicit_assignment.active = true
          AND explicit_assignment.valid_from <= clock_timestamp()
          AND (explicit_assignment.valid_until IS NULL OR explicit_assignment.valid_until > clock_timestamp())
      )
    );

  v_window := public.resolve_operator_shift_window(v_operator.id, clock_timestamp());
  v_shift_started_at := (v_window ->> 'shift_started_at')::timestamptz;
  v_shift_ends_at := (v_window ->> 'shift_ends_at')::timestamptz;
  v_shift_work_date := (v_window ->> 'shift_work_date')::date;

  v_expires_at := CASE
    WHEN coalesce((v_window ->> 'is_inside_shift')::boolean, false)
      THEN least(clock_timestamp() + interval '8 hours', v_shift_ends_at + interval '30 minutes')
    ELSE clock_timestamp() + interval '1 hour'
  END;
  v_sync_grace_until := greatest(v_shift_ends_at + interval '24 hours', v_expires_at);

  UPDATE public.operator_sessions
  SET ended_at = clock_timestamp(), end_reason = 'operator_switch'
  WHERE auth_user_id = v_auth_user_id
    AND device_id = v_device_id
    AND ended_at IS NULL
    AND revoked_at IS NULL;

  UPDATE public.operators
  SET failed_login_count = 0,
      locked_until = NULL,
      last_login_at = clock_timestamp()
  WHERE id = v_operator.id;

  v_token := encode(gen_random_bytes(32), 'hex');
  v_token_hash := encode(extensions.digest(v_token, 'sha256'), 'hex');

  INSERT INTO public.operator_sessions (
    operator_id, auth_user_id, token_hash, device_id, expires_at,
    sync_grace_until, shift_snapshot,
    shift_start_time_snapshot, shift_end_time_snapshot,
    shift_started_at, shift_ends_at, shift_work_date, timezone_snapshot
  ) VALUES (
    v_operator.id, v_auth_user_id, v_token_hash, v_device_id, v_expires_at,
    v_sync_grace_until, v_operator.shift,
    v_operator.shift_start_time, v_operator.shift_end_time,
    v_shift_started_at, v_shift_ends_at, v_shift_work_date, v_operator.timezone
  )
  RETURNING id INTO v_session_id;

  INSERT INTO public.operator_access_attempts (login_name_input, success, device_id)
  VALUES (v_login, true, v_device_id);

  INSERT INTO public.system_audit_logs (
    user_id, user_name, action, entity, entity_id, device_id, session_id, success, metadata
  ) VALUES (
    v_auth_user_id, v_operator.name, 'operator_session_started', 'operator_sessions',
    v_session_id::text, v_device_id, v_session_id::text, true,
    jsonb_build_object(
      'operator_id', v_operator.id,
      'shift', v_operator.shift,
      'shift_work_date', v_shift_work_date,
      'shift_started_at', v_shift_started_at,
      'shift_ends_at', v_shift_ends_at,
      'timezone', v_operator.timezone,
      'inside_shift', coalesce((v_window ->> 'is_inside_shift')::boolean, false)
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'session_id', v_session_id,
    'session_token', v_token,
    'expires_at', v_expires_at,
    'shift_window', v_window,
    'operator', jsonb_build_object(
      'id', v_operator.id,
      'name', v_operator.name,
      'login_name', v_operator.login_name,
      'registration_masked', public.mask_registration(v_operator.registration),
      'shift', v_operator.shift,
      'shift_start_time', v_operator.shift_start_time,
      'shift_end_time', v_operator.shift_end_time,
      'timezone', v_operator.timezone,
      'primary_cell_id', v_operator.primary_cell_id,
      'primary_machine_id', v_operator.primary_machine_id,
      'cells', coalesce(v_cells, '[]'::jsonb),
      'machines', coalesce(v_machines, '[]'::jsonb)
    )
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.operator_login_v3(p_login_name text, p_registration text, p_device_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE v_result jsonb; v_operator_id uuid; v_session_id uuid; v_window jsonb; v_operator_patch jsonb;
BEGIN
  v_result:=public.operator_login_v2(p_login_name,p_registration,p_device_id);
  IF COALESCE((v_result->>'success')::boolean,false) IS NOT TRUE THEN RETURN v_result; END IF;
  v_operator_id:=NULLIF(v_result #>> '{operator,id}','')::uuid; v_session_id:=NULLIF(v_result->>'session_id','')::uuid;
  v_window:=public.resolve_operator_shift_window(v_operator_id,clock_timestamp());
  UPDATE public.operator_sessions SET shift_start_time_snapshot=(v_window->>'shift_start_time')::time,shift_end_time_snapshot=(v_window->>'shift_end_time')::time,timezone_snapshot=v_window->>'timezone',shift_work_date=(v_window->>'shift_work_date')::date,shift_started_at=(v_window->>'shift_started_at')::timestamptz,shift_ends_at=(v_window->>'shift_ends_at')::timestamptz WHERE id=v_session_id AND auth_user_id=auth.uid();
  v_operator_patch:=COALESCE(v_result->'operator','{}'::jsonb)||jsonb_build_object('shift_start_time',v_window->>'shift_start_time','shift_end_time',v_window->>'shift_end_time','timezone',v_window->>'timezone','shift_work_date',v_window->>'shift_work_date','shift_started_at',v_window->>'shift_started_at','shift_ends_at',v_window->>'shift_ends_at','is_inside_shift',(v_window->>'is_inside_shift')::boolean);
  RETURN jsonb_set(v_result||jsonb_build_object('shift_window',v_window),'{operator}',v_operator_patch,true);
END; $function$

CREATE OR REPLACE FUNCTION public.operator_login(p_name text, p_registration text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_name text := LOWER(TRIM(COALESCE(p_name, '')));
  v_reg  text := TRIM(COALESCE(p_registration, ''));
  op     operators%ROWTYPE;
BEGIN
  IF v_name = '' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Informe o nome do operador.');
  END IF;
  IF v_reg = '' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Informe a matrícula.');
  END IF;

  SELECT * INTO op FROM operators
  WHERE active = true
    AND login_enabled = true
    AND (LOWER(TRIM(login_name)) = v_name OR LOWER(TRIM(name)) = v_name)
    AND TRIM(registration) = v_reg
  LIMIT 1;

  IF op.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Operador não encontrado ou credenciais inválidas.');
  END IF;

  -- Registrar ultimo login
  UPDATE operators SET last_login_at = now() WHERE id = op.id;

  RETURN jsonb_build_object(
    'success',       true,
    'id',            op.id,
    'name',          op.name,
    'registration',  op.registration,
    'primary_cell',  op.primary_cell,
    'cells',         op.cells,
    'shift',         op.shift,
    'login_enabled', op.login_enabled
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.parse_pcp_route_tokens(p_route_text text)
 RETURNS text[]
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
DECLARE
  v_route_clean text;
  v_tokens text[];
  v_token text;
  v_stages text[] := '{}'::text[];
  v_ordered text[] := ARRAY['cut', 'edge', 'drill', 'cnc', 'canal', 'maranello', 'portajoias', 'sorrento', 'usi_especial', 'rasgo_freggio', 'joinery', 'separation', 'packaging'];
  v_result text[] := '{}'::text[];
  v_stage text;
BEGIN
  -- Normaliza tokens compostos antes do split
  v_route_clean := UPPER(COALESCE(p_route_text, ''));
  v_route_clean := REPLACE(v_route_clean, 'USI ESPECIAL', 'USIESPECIAL');
  v_route_clean := REPLACE(v_route_clean, 'PORTA JOIAS', 'PORTAJOIAS');
  v_route_clean := REPLACE(v_route_clean, 'RASGO FREGGIO', 'RASGOFREGGIO');

  -- Divide o texto por delimitadores comuns
  v_tokens := regexp_split_to_array(v_route_clean, '[\s,;/+\-]+');

  FOREACH v_token IN ARRAY v_tokens LOOP
    v_token := TRIM(v_token);
    IF v_token = 'CORTAR' OR v_token = 'CORTE' THEN
      v_stages := array_append(v_stages, 'cut');
    ELSIF v_token = 'BORDEAR' OR v_token = 'BORDO' OR v_token = 'BORDA' OR v_token = 'EDGE' THEN
      v_stages := array_append(v_stages, 'edge');
    ELSIF v_token = 'FURAR' OR v_token = 'FURAÇÃO' OR v_token = 'DRILL' THEN
      v_stages := array_append(v_stages, 'drill');
    ELSIF v_token = 'USINAGEM' OR v_token = 'CNC' OR v_token = 'USINAR' THEN
      v_stages := array_append(v_stages, 'cnc');
    ELSIF v_token = 'CANAL' THEN
      v_stages := array_append(v_stages, 'canal');
    ELSIF v_token = 'MARANELLO' THEN
      v_stages := array_append(v_stages, 'maranello');
    ELSIF v_token = 'PORTAJOIAS' THEN
      v_stages := array_append(v_stages, 'portajoias');
    ELSIF v_token = 'SORRENTO' THEN
      v_stages := array_append(v_stages, 'sorrento');
    ELSIF v_token = 'USIESPECIAL' THEN
      v_stages := array_append(v_stages, 'usi_especial');
    ELSIF v_token = 'RASGOFREGGIO' THEN
      v_stages := array_append(v_stages, 'rasgo_freggio');
    ELSIF v_token = 'MARCENARIA' OR v_token = 'JOINERY' THEN
      v_stages := array_append(v_stages, 'joinery');
    END IF;
  END LOOP;

  -- Garante Separação e Embalagem ao final de todas as rotas
  v_stages := array_append(v_stages, 'separation');
  v_stages := array_append(v_stages, 'packaging');

  -- Ordena de forma determinística canônica e remove duplicados
  FOREACH v_stage IN ARRAY v_ordered LOOP
    IF v_stage = ANY(v_stages) THEN
      v_result := array_append(v_result, v_stage);
    END IF;
  END LOOP;

  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.piece_requires_step(p_source_lot_item_id uuid, p_step_name text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
DECLARE
  v_item record;
  v_clean_step text := lower(p_step_name);
BEGIN
  SELECT * INTO v_item FROM public.lot_items WHERE id = p_source_lot_item_id;
  IF NOT FOUND THEN
    RETURN true; -- fallback
  END IF;

  IF v_clean_step = 'corte' THEN
    RETURN COALESCE(v_item.requires_cut, true);
  ELSIF v_clean_step = 'bordo' OR v_clean_step = 'bordeamento' THEN
    RETURN COALESCE(v_item.requires_edge, false);
  ELSIF v_clean_step = 'usinagem' THEN
    RETURN COALESCE(v_item.requires_cnc, false);
  ELSIF v_clean_step = 'marcenaria' THEN
    RETURN COALESCE(v_item.requires_joinery, false);
  ELSIF v_clean_step = 'separação' OR v_clean_step = 'separacao' THEN
    RETURN COALESCE(v_item.requires_separation, true);
  ELSIF v_clean_step = 'embalagem' THEN
    RETURN COALESCE(v_item.requires_packaging, true);
  ELSIF v_clean_step = 'expedição' OR v_clean_step = 'expedicao' THEN
    RETURN COALESCE(v_item.requires_shipping, true);
  ELSE
    RETURN true; -- Qualquer outra etapa é considerada requerida por padrão
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.prevent_backup_early_deletion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
DECLARE
  caller_role text;
BEGIN
  SELECT role INTO caller_role FROM profiles WHERE id = auth.uid() LIMIT 1;
  IF caller_role IS DISTINCT FROM 'admin' AND OLD.expires_at > now() THEN
    RAISE EXCEPTION 'Backup não pode ser excluído antes de %.
      Apenas administradores podem forçar exclusão antecipada.',
      to_char(OLD.expires_at, 'DD/MM/YYYY');
  END IF;
  RETURN OLD;
END;
$function$

CREATE OR REPLACE FUNCTION public.process_coleta_producao_ingress()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_auth_user_id uuid := auth.uid();
  v_token text;
  v_payload jsonb;
  v_now timestamptz := clock_timestamp();
BEGIN
  IF v_auth_user_id IS NULL THEN
    RAISE EXCEPTION 'AUTHENTICATED_EDGE_SESSION_REQUIRED'
      USING ERRCODE = '42501',
            HINT = 'Autentique o equipamento antes de enviar a coleta.';
  END IF;

  IF NEW.auth_user_id IS NOT NULL AND NEW.auth_user_id <> v_auth_user_id THEN
    RAISE EXCEPTION 'COLLECTION_INGRESS_USER_MISMATCH'
      USING ERRCODE = '42501';
  END IF;

  v_payload := coalesce(NEW.payload, '{}'::jsonb);

  IF NEW.pipeline_version = 3 THEN
    IF current_setting('acprod.collection_v3_ingress_batch', true)
       IS DISTINCT FROM NEW.batch_id::text THEN
      RAISE EXCEPTION 'COLLECTION_V3_RPC_REQUIRED'
        USING ERRCODE = '42501',
              HINT = 'Use ingest_collection_batch_v3 para eventos pipeline_version=3.';
    END IF;

    NEW.id := coalesce(NEW.id, gen_random_uuid());
    NEW.auth_user_id := v_auth_user_id;
    NEW.client_event_id := btrim(NEW.client_event_id);
    NEW.tag_lida := btrim(NEW.tag_lida);
    NEW.event_kind := 'production_stage';
    NEW.reader_type := lower(coalesce(nullif(btrim(NEW.reader_type), ''), 'keyboard_barcode'));
    NEW.status_sincronizacao := 'recebida';
    NEW.resultado := NULL;
    NEW.erro := NULL;
    NEW.retryable := false;
    NEW.server_received_at := v_now;
    NEW.received_at_db := v_now;
    NEW.enqueued_at := v_now;
    NEW.processado_em := NULL;
    NEW.processing_duration_ms := NULL;
    NEW.queue_delay_ms := NULL;
    NEW.attempt_count := 0;
    NEW.next_attempt_at := v_now;
    NEW.lease_expires_at := NULL;
    NEW.worker_id := NULL;
    NEW.last_error_code := NULL;
    NEW.last_error_at := NULL;
    NEW.updated_at := v_now;
    NEW.payload := v_payload
      - 'operatorSessionToken'
      - 'operator_session_token'
      - 'session_token'
      - 'jwt'
      - 'access_token';
    RETURN NEW;
  END IF;

  v_token := coalesce(
    nullif(btrim(v_payload ->> 'operatorSessionToken'), ''),
    nullif(btrim(v_payload ->> 'operator_session_token'), ''),
    nullif(btrim(v_payload ->> 'session_token'), '')
  );

  IF v_token IS NULL THEN
    RAISE EXCEPTION 'OPERATOR_SESSION_REQUIRED'
      USING ERRCODE = '42501',
            HINT = 'Faça o login operacional antes de coletar.';
  END IF;

  NEW.id := coalesce(NEW.id, gen_random_uuid());
  NEW.auth_user_id := v_auth_user_id;
  NEW.client_event_id := btrim(NEW.client_event_id);
  NEW.tag_lida := btrim(NEW.tag_lida);
  NEW.event_kind := 'production_stage';
  NEW.reader_type := lower(coalesce(nullif(btrim(NEW.reader_type), ''), 'keyboard_barcode'));
  NEW.status_sincronizacao := 'recebida';
  NEW.resultado := NULL;
  NEW.erro := NULL;
  NEW.retryable := false;
  NEW.server_received_at := v_now;
  NEW.received_at_db := v_now;
  NEW.enqueued_at := v_now;
  NEW.processado_em := NULL;
  NEW.processing_duration_ms := NULL;
  NEW.queue_delay_ms := NULL;
  NEW.attempt_count := 0;
  NEW.next_attempt_at := v_now;
  NEW.lease_expires_at := NULL;
  NEW.worker_id := NULL;
  NEW.last_error_code := NULL;
  NEW.last_error_at := NULL;
  NEW.updated_at := v_now;
  NEW.payload := v_payload
    - 'operatorSessionToken'
    - 'operator_session_token'
    - 'session_token';

  INSERT INTO private.coleta_producao_credentials (
    coleta_id, auth_user_id, session_token, created_at, expires_at
  ) VALUES (
    NEW.id, v_auth_user_id, v_token, v_now, v_now + interval '2 days'
  )
  ON CONFLICT (coleta_id) DO UPDATE
  SET auth_user_id = excluded.auth_user_id,
      session_token = excluded.session_token,
      created_at = excluded.created_at,
      expires_at = excluded.expires_at;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.process_collection_inbox_item(p_coleta_id uuid, p_worker_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'extensions', 'realtime', 'pg_temp'
AS $function$
DECLARE
  v_row public.coletas_producao%ROWTYPE;
  v_secret private.coleta_producao_credentials%ROWTYPE;
  v_payload jsonb;
  v_result jsonb;
  v_started_at timestamptz := clock_timestamp();
  v_finished_at timestamptz;
  v_sqlstate text;
  v_message text;
  v_retryable boolean;
  v_delay_seconds numeric;
BEGIN
  SELECT * INTO v_row
  FROM public.coletas_producao inbox
  WHERE inbox.id = p_coleta_id
  FOR UPDATE;

  IF v_row.id IS NULL THEN
    RETURN jsonb_build_object('processed', false, 'reason', 'not_found');
  END IF;

  IF v_row.status_sincronizacao IN ('sincronizada', 'erro') THEN
    RETURN jsonb_build_object(
      'processed', false,
      'reason', 'already_final',
      'status_sincronizacao', v_row.status_sincronizacao,
      'client_event_id', v_row.client_event_id,
      'resultado', v_row.resultado
    );
  END IF;

  IF v_row.status_sincronizacao = 'processando'
     AND v_row.worker_id IS DISTINCT FROM p_worker_id
     AND coalesce(v_row.lease_expires_at, '-infinity'::timestamptz) > clock_timestamp() THEN
    RETURN jsonb_build_object('processed', false, 'reason', 'leased');
  END IF;

  SELECT * INTO v_secret
  FROM private.coleta_producao_credentials credential
  WHERE credential.coleta_id = v_row.id;

  IF v_secret.coleta_id IS NULL OR v_secret.expires_at <= clock_timestamp() THEN
    v_finished_at := clock_timestamp();
    UPDATE public.coletas_producao
    SET status_sincronizacao = 'erro',
        retryable = false,
        erro = 'Credencial operacional ausente ou expirada.',
        last_error_code = 'OPERATOR_SESSION_CREDENTIAL_MISSING',
        last_error_at = v_finished_at,
        resultado = jsonb_build_object(
          'success', false,
          'status', 'error',
          'reason_code', 'OPERATOR_SESSION_CREDENTIAL_MISSING',
          'message', 'Faça novamente o login operacional para reenviar esta leitura.',
          'client_event_id', v_row.client_event_id
        ),
        processado_em = v_finished_at,
        processing_duration_ms = extract(epoch from (v_finished_at - v_started_at)) * 1000,
        queue_delay_ms = extract(epoch from (v_started_at - v_row.server_received_at)) * 1000,
        lease_expires_at = NULL,
        worker_id = NULL,
        updated_at = v_finished_at
    WHERE id = v_row.id;
    DELETE FROM private.coleta_producao_credentials WHERE coleta_id = v_row.id;
    RETURN jsonb_build_object('processed', true, 'status', 'error', 'client_event_id', v_row.client_event_id);
  END IF;

  UPDATE public.coletas_producao
  SET status_sincronizacao = 'processando',
      worker_id = p_worker_id,
      lease_expires_at = clock_timestamp() + interval '45 seconds',
      updated_at = clock_timestamp()
  WHERE id = v_row.id;

  PERFORM set_config('request.jwt.claim.sub', v_row.auth_user_id::text, true);
  PERFORM set_config('request.jwt.claim.role', 'authenticated', true);
  PERFORM set_config(
    'request.jwt.claims',
    jsonb_build_object('sub', v_row.auth_user_id, 'role', 'authenticated')::text,
    true
  );

  v_payload := coalesce(v_row.payload, '{}'::jsonb) || jsonb_build_object(
    'client_event_id', v_row.client_event_id,
    'rawValue', v_row.tag_lida,
    'raw_value', v_row.tag_lida,
    'readerType', v_row.reader_type,
    'reader_type', v_row.reader_type,
    'createdAtClient', v_row.timestamp_leitura,
    'created_at_client', v_row.timestamp_leitura,
    'deviceId', v_row.device_id,
    'device_id', v_row.device_id,
    'operatorSessionToken', v_secret.session_token,
    'operator_session_token', v_secret.session_token,
    'serverAsyncWorker', true,
    'server_async_worker', true
  );

  BEGIN
    v_result := public.process_production_reading_v2(v_payload);
  EXCEPTION
    WHEN query_canceled THEN
      v_sqlstate := SQLSTATE;
      v_message := SQLERRM;
    WHEN OTHERS THEN
      v_sqlstate := SQLSTATE;
      v_message := SQLERRM;
  END;

  IF v_sqlstate IS NULL THEN
    v_finished_at := clock_timestamp();
    UPDATE public.coletas_producao
    SET status_sincronizacao = 'sincronizada',
        retryable = false,
        resultado = coalesce(v_result, jsonb_build_object(
          'success', false,
          'status', 'error',
          'reason_code', 'EMPTY_COLLECTION_RESULT',
          'message', 'O processador não retornou um resultado.',
          'client_event_id', v_row.client_event_id
        )),
        erro = NULL,
        last_error_code = NULL,
        last_error_at = NULL,
        processado_em = v_finished_at,
        processing_duration_ms = extract(epoch from (v_finished_at - v_started_at)) * 1000,
        queue_delay_ms = extract(epoch from (v_started_at - v_row.server_received_at)) * 1000,
        lease_expires_at = NULL,
        worker_id = NULL,
        updated_at = v_finished_at
    WHERE id = v_row.id;
    DELETE FROM private.coleta_producao_credentials WHERE coleta_id = v_row.id;
    RETURN jsonb_build_object(
      'processed', true,
      'status', 'sincronizada',
      'client_event_id', v_row.client_event_id,
      'resultado', v_result
    );
  END IF;

  v_retryable := left(v_sqlstate, 2) = '08'
    OR v_sqlstate IN ('40001', '40P01', '55P03', '57014', '57P01', '53300');
  v_finished_at := clock_timestamp();

  IF v_retryable AND v_row.attempt_count < 12 THEN
    v_delay_seconds := least(60, greatest(1, power(2::numeric, greatest(v_row.attempt_count - 1, 0))));
    UPDATE public.coletas_producao
    SET status_sincronizacao = 'recebida',
        retryable = true,
        erro = left(v_message, 1000),
        last_error_code = v_sqlstate,
        last_error_at = v_finished_at,
        next_attempt_at = v_finished_at + make_interval(secs => v_delay_seconds::double precision),
        lease_expires_at = NULL,
        worker_id = NULL,
        updated_at = v_finished_at
    WHERE id = v_row.id;
    RETURN jsonb_build_object(
      'processed', false,
      'status', 'retry_scheduled',
      'client_event_id', v_row.client_event_id,
      'reason_code', v_sqlstate,
      'retry_in_seconds', v_delay_seconds
    );
  END IF;

  UPDATE public.coletas_producao
  SET status_sincronizacao = 'erro',
      retryable = false,
      erro = left(v_message, 1000),
      last_error_code = coalesce(v_sqlstate, 'COLLECTION_WORKER_ERROR'),
      last_error_at = v_finished_at,
      resultado = jsonb_build_object(
        'success', false,
        'status', 'error',
        'reason_code', coalesce(v_sqlstate, 'COLLECTION_WORKER_ERROR'),
        'message', left(v_message, 1000),
        'client_event_id', v_row.client_event_id,
        'retryable', false
      ),
      processado_em = v_finished_at,
      processing_duration_ms = extract(epoch from (v_finished_at - v_started_at)) * 1000,
      queue_delay_ms = extract(epoch from (v_started_at - v_row.server_received_at)) * 1000,
      lease_expires_at = NULL,
      worker_id = NULL,
      updated_at = v_finished_at
  WHERE id = v_row.id;
  DELETE FROM private.coleta_producao_credentials WHERE coleta_id = v_row.id;

  RETURN jsonb_build_object(
    'processed', true,
    'status', 'error',
    'client_event_id', v_row.client_event_id,
    'reason_code', coalesce(v_sqlstate, 'COLLECTION_WORKER_ERROR')
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.process_production_reading_impl_v2(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_auth_user_id uuid := auth.uid();
  v_session_token text := nullif(btrim(p_payload ->> 'operatorSessionToken'), '');
  v_client_event_id text := coalesce(
    nullif(btrim(p_payload ->> 'client_event_id'), ''),
    gen_random_uuid()::text
  );
  v_tag_value text := upper(btrim(coalesce(
    p_payload ->> 'rawValue',
    p_payload ->> 'raw_value',
    p_payload ->> 'tagValue',
    ''
  )));
  v_reader_type text := coalesce(
    nullif(p_payload ->> 'readerType', ''),
    nullif(p_payload ->> 'reader_type', ''),
    'keyboard_barcode'
  );
  v_client_time timestamptz := coalesce(
    nullif(p_payload ->> 'createdAtClient', '')::timestamptz,
    nullif(p_payload ->> 'created_at_client', '')::timestamptz,
    clock_timestamp()
  );
  v_device_id text := nullif(btrim(coalesce(p_payload ->> 'deviceId', p_payload ->> 'device_id', '')), '');
  v_enqueue_duration_ms numeric := coalesce(nullif(p_payload ->> 'enqueue_duration_ms', '')::numeric, 0);
  v_quantity integer := greatest(coalesce(nullif(p_payload ->> 'quantity', '')::integer, 1), 1);

  v_now timestamptz := clock_timestamp();
  v_token_hash text;
  v_session public.operator_sessions%ROWTYPE;
  v_operator public.operators%ROWTYPE;
  v_window jsonb;
  v_shift_start timestamptz;
  v_shift_end timestamptz;
  v_timezone text;
  v_occurred_at timestamptz;
  v_timestamp_adjusted boolean := false;
  v_local_occurred timestamp;
  v_date date;
  v_hour text;
  v_cell text;
  v_station text;
  v_shift text;

  v_event public.production_collection_events%ROWTYPE;
  v_piece public.production_pieces%ROWTYPE;
  v_lot public.production_lots%ROWTYPE;
  v_order public.production_orders%ROWTYPE;
  v_reading public.production_stage_readings%ROWTYPE;
  v_existing_reading public.production_stage_readings%ROWTYPE;
  v_entry_id uuid;
  v_target_step_code text;
  v_validation jsonb;
  v_result jsonb;
  v_context_result jsonb;
  v_cell_state jsonb;
  v_new_completed_steps text[];
  v_next_step text;
  v_current_cycle integer := 1;
  v_reason_code text;
  v_step text;
BEGIN
  IF v_reader_type NOT IN (
    'keyboard_barcode','camera_qrcode','camera_barcode','manual',
    'rfid_fixed','rfid_handheld','api'
  ) THEN
    v_reader_type := 'keyboard_barcode';
  END IF;

  IF v_auth_user_id IS NULL OR v_session_token IS NULL THEN
    RAISE EXCEPTION 'OPERATOR_SESSION_REQUIRED'
      USING ERRCODE = '42501', HINT = 'Faça o login operacional antes de coletar.';
  END IF;

  v_token_hash := encode(extensions.digest(v_session_token, 'sha256'), 'hex');

  SELECT session.*
  INTO v_session
  FROM public.operator_sessions session
  JOIN public.operators operator ON operator.id = session.operator_id
  WHERE session.token_hash = v_token_hash
    AND session.auth_user_id = v_auth_user_id
    AND session.ended_at IS NULL
    AND session.revoked_at IS NULL
    AND session.sync_grace_until > v_now
    AND operator.active IS TRUE
    AND coalesce(operator.login_enabled, true) IS TRUE;

  IF v_session.id IS NULL THEN
    RAISE EXCEPTION 'OPERATOR_SESSION_INVALID'
      USING ERRCODE = '42501', HINT = 'Entre novamente com o operador autorizado.';
  END IF;

  SELECT * INTO v_operator
  FROM public.operators
  WHERE id = v_session.operator_id;

  IF v_session.cell_id IS NULL OR nullif(btrim(v_session.cell_name_snapshot), '') IS NULL THEN
    RAISE EXCEPTION 'OPERATOR_CONTEXT_REQUIRED'
      USING ERRCODE = '42501', HINT = 'Selecione a célula de trabalho antes de coletar.';
  END IF;

  IF v_session.shift_started_at IS NULL OR v_session.shift_ends_at IS NULL THEN
    v_window := public.resolve_operator_shift_window(v_operator.id, v_now);
    v_shift_start := (v_window ->> 'shift_started_at')::timestamptz;
    v_shift_end := (v_window ->> 'shift_ends_at')::timestamptz;
    v_timezone := coalesce(v_window ->> 'timezone', 'America/Sao_Paulo');
  ELSE
    v_shift_start := v_session.shift_started_at;
    v_shift_end := v_session.shift_ends_at;
    v_timezone := coalesce(nullif(v_session.timezone_snapshot, ''), v_operator.timezone, 'America/Sao_Paulo');
  END IF;

  IF v_client_time >= v_shift_start
     AND v_client_time < v_shift_end
     AND v_client_time <= v_now + interval '5 minutes'
     AND v_now <= v_session.sync_grace_until THEN
    v_occurred_at := v_client_time;
  ELSIF v_now >= v_shift_start AND v_now < v_shift_end THEN
    v_occurred_at := v_now;
    v_timestamp_adjusted := true;
  ELSE
    v_occurred_at := v_now;
    v_timestamp_adjusted := true;
  END IF;

  v_local_occurred := v_occurred_at AT TIME ZONE v_timezone;
  v_date := v_local_occurred::date;
  v_hour := to_char(v_local_occurred, 'HH24:MI');
  v_cell := v_session.cell_name_snapshot;
  v_station := coalesce(nullif(btrim(v_session.station_name_snapshot), ''), 'Coletor Chão de Fábrica');
  v_shift := coalesce(v_session.shift_snapshot, v_operator.shift, 'Turno não informado');

  INSERT INTO public.production_collection_events (
    client_event_id, raw_value, normalized_value, reader_type,
    operator_id, operator_name, registration, cell_name, shift, date, hour,
    status, created_at_client, occurred_at, timestamp_adjusted,
    payload, machine_id, machine_name, station_name,
    device_id, enqueue_duration_ms, sync_started_at, attempt_count, last_attempt_at,
    operator_session_id, cell_id, operator_registration_snapshot,
    operator_name_snapshot, machine_name_snapshot, station_name_snapshot,
    shift_snapshot, server_received_at
  ) VALUES (
    v_client_event_id, v_tag_value, v_tag_value, v_reader_type,
    v_operator.id, v_operator.name, v_operator.registration, v_cell, v_shift, v_date, v_hour,
    'processing', v_client_time, v_occurred_at, v_timestamp_adjusted,
    p_payload, v_session.machine_id, v_session.machine_name_snapshot, v_station,
    coalesce(v_device_id, v_session.device_id), v_enqueue_duration_ms,
    v_now, 1, v_now,
    v_session.id, v_session.cell_id, public.mask_registration(v_operator.registration),
    v_operator.name, v_session.machine_name_snapshot, v_station,
    v_shift, v_now
  )
  ON CONFLICT (client_event_id) DO NOTHING
  RETURNING * INTO v_event;

  IF v_event.id IS NULL THEN
    SELECT * INTO v_event
    FROM public.production_collection_events event
    WHERE event.client_event_id = v_client_event_id
    FOR UPDATE;

    UPDATE public.production_collection_events
    SET attempt_count = attempt_count + 1,
        last_attempt_at = v_now
    WHERE id = v_event.id;

    IF v_event.result_payload IS NOT NULL
       AND v_event.result_payload <> '{}'::jsonb
       AND v_event.status IN ('synced','ignored','error') THEN
      RETURN v_event.result_payload;
    END IF;

    IF v_event.status = 'processing'
       AND v_event.sync_started_at > v_now - interval '30 seconds' THEN
      RAISE EXCEPTION 'COLLECTION_EVENT_PROCESSING'
        USING ERRCODE = '40001', HINT = 'O mesmo evento ainda está sendo confirmado.';
    END IF;

    UPDATE public.production_collection_events
    SET status = 'processing',
        payload = p_payload,
        sync_started_at = v_now,
        sync_finished_at = NULL,
        error_message = NULL,
        updated_at = v_now
    WHERE id = v_event.id
    RETURNING * INTO v_event;
  END IF;

  IF NOT (
    (v_now >= v_shift_start AND v_now < v_shift_end)
    OR (v_client_time >= v_shift_start AND v_client_time < v_shift_end AND v_now <= v_session.sync_grace_until)
  ) THEN
    v_result := jsonb_build_object(
      'success', false,
      'status', 'blocked',
      'reason_code', 'SHIFT_OUTSIDE_WINDOW',
      'alert_level', 'yellow',
      'message', 'ENTRADA BLOQUEADA: o horário de trabalho configurado para este operador foi encerrado.',
      'shift_started_at', v_shift_start,
      'shift_ends_at', v_shift_end
    );

    UPDATE public.production_collection_events
    SET reason_code = 'SHIFT_OUTSIDE_WINDOW'
    WHERE id = v_event.id;

    RETURN public.finish_collection_event(
      v_event.id, 'ignored', 'blocked', v_result, NULL, NULL, v_result ->> 'message'
    );
  END IF;

  IF v_tag_value = '' THEN
    v_result := jsonb_build_object(
      'success', false,
      'status', 'invalid',
      'reason_code', 'INVALID_IDENTIFIER',
      'alert_level', 'red',
      'message', 'Informe uma identificação produtiva válida.'
    );
    UPDATE public.production_collection_events SET reason_code = 'INVALID_IDENTIFIER' WHERE id = v_event.id;
    RETURN public.finish_collection_event(v_event.id, 'ignored', 'invalid', v_result, NULL, NULL, v_result ->> 'message');
  END IF;

  BEGIN
    v_piece := public.resolve_piece_by_identifier(v_tag_value);
  EXCEPTION WHEN OTHERS THEN
    v_result := jsonb_build_object(
      'success', false,
      'status', 'not_found',
      'reason_code', 'PIECE_NOT_FOUND',
      'alert_level', 'red',
      'message', SQLERRM
    );
    UPDATE public.production_collection_events SET reason_code = 'PIECE_NOT_FOUND' WHERE id = v_event.id;
    RETURN public.finish_collection_event(v_event.id, 'ignored', 'not_found', v_result, NULL, NULL, SQLERRM);
  END;

  PERFORM pg_advisory_xact_lock(hashtextextended('production-piece:' || v_piece.id::text, 0));

  SELECT * INTO v_piece
  FROM public.production_pieces
  WHERE id = v_piece.id
  FOR UPDATE;

  SELECT * INTO v_lot
  FROM public.production_lots
  WHERE id = v_piece.lot_id;

  SELECT * INTO v_order
  FROM public.production_orders
  WHERE id = coalesce(v_piece.production_order_id, v_lot.production_order_id, v_lot.order_id);

  v_target_step_code := coalesce(
    public.resolve_production_stage_for_cell(v_session.cell_id, v_cell),
    '__unmapped_cell__'
  );

  UPDATE public.production_collection_events
  SET piece_id = v_piece.id,
      pcp_import_batch_id = coalesce(v_piece.pcp_import_batch_id, v_lot.pcp_import_batch_id),
      lot_id = v_piece.lot_id,
      production_order_id = coalesce(v_piece.production_order_id, v_lot.production_order_id, v_lot.order_id),
      lot_code = v_lot.lot_code,
      general_lot_code = coalesce(v_piece.general_lot_code, v_lot.general_lot_code),
      load_number = v_order.load_number,
      order_number = coalesce(v_order.order_number, v_order.order_code),
      customer_name = v_order.customer_name,
      environment_name = coalesce(v_piece.environment_name, v_piece.environment),
      piece_code = v_piece.traceability_code,
      operation_name = v_target_step_code,
      updated_at = v_now
  WHERE id = v_event.id;

  v_validation := public.validar_fluxo_da_peca(v_piece.id, v_target_step_code);

  SELECT coalesce(max(reading.production_cycle), 1)
  INTO v_current_cycle
  FROM public.production_stage_readings reading
  WHERE reading.piece_id = v_piece.id;

  IF NOT coalesce((v_validation ->> 'success')::boolean, false)
     OR v_validation ->> 'status' = 'duplicated' THEN
    v_reason_code := CASE v_validation ->> 'status'
      WHEN 'duplicated' THEN 'DUPLICATE_PIECE_STAGE'
      WHEN 'wrong_step' THEN 'PREVIOUS_STAGE_REQUIRED'
      ELSE 'FLOW_BLOCKED'
    END;

    INSERT INTO public.production_stage_readings (
      client_event_id, tag_value, tag_type, reader_type,
      station_name, cell_name, operator, operator_name_snapshot,
      user_id, operator_id, shift, date, hour,
      item_id, piece_id, lot_id, production_order_id,
      step_name, operation_name, quantity, status, event_type,
      machine_id, machine_name, lot_code, load_number, order_number,
      customer_name, environment_name, piece_code, production_cycle,
      entry_type, traceability_type, is_manual, unit_of_measure,
      general_lot_code, created_at
    ) VALUES (
      v_client_event_id, v_piece.piece_uid,
      CASE WHEN v_reader_type = 'manual' THEN 'manual' ELSE 'barcode' END,
      v_reader_type, v_station, v_cell, v_operator.name, v_operator.name,
      v_auth_user_id, v_operator.id, v_shift, v_date, v_hour,
      v_piece.legacy_production_lot_item_id, v_piece.id, v_piece.lot_id,
      coalesce(v_piece.production_order_id, v_lot.production_order_id, v_lot.order_id),
      v_target_step_code, v_target_step_code, v_quantity,
      CASE WHEN v_validation ->> 'status' = 'duplicated' THEN 'duplicated' ELSE 'blocked' END,
      CASE WHEN v_validation ->> 'status' = 'duplicated' THEN 'duplicated_scan' ELSE 'wrong_step' END,
      v_session.machine_id, v_session.machine_name_snapshot,
      v_lot.lot_code, v_order.load_number, coalesce(v_order.order_number, v_order.order_code),
      v_order.customer_name, coalesce(v_piece.environment_name, v_piece.environment),
      v_piece.traceability_code, v_current_cycle,
      'coleta_fisica', 'unitaria', v_reader_type = 'manual', 'pecas',
      coalesce(v_piece.general_lot_code, v_lot.general_lot_code), v_occurred_at
    )
    RETURNING * INTO v_reading;

    v_result := jsonb_build_object(
      'success', false,
      'status', 'blocked',
      'legacy_status', coalesce(v_validation ->> 'status', 'blocked'),
      'reason_code', v_reason_code,
      'alert_level', coalesce(v_validation ->> 'alert_level', 'yellow'),
      'message', coalesce(v_validation ->> 'message', 'Entrada bloqueada.'),
      'lot', to_jsonb(v_lot),
      'order', to_jsonb(v_order),
      'item', to_jsonb(v_piece),
      'reading', to_jsonb(v_reading)
    );

    UPDATE public.production_collection_events
    SET reason_code = v_reason_code
    WHERE id = v_event.id;

    RETURN public.finish_collection_event(
      v_event.id,
      'ignored',
      CASE WHEN v_validation ->> 'status' = 'duplicated' THEN 'duplicated' ELSE 'blocked' END,
      v_result,
      v_reading.id,
      NULL,
      v_result ->> 'message'
    );
  END IF;

  BEGIN
    INSERT INTO public.production_stage_readings (
      client_event_id, tag_value, tag_type, reader_type,
      station_name, cell_name, operator, operator_name_snapshot,
      user_id, operator_id, shift, date, hour,
      item_id, piece_id, lot_id, production_order_id,
      step_name, operation_name, quantity, status, event_type,
      machine_id, machine_name, lot_code, load_number, order_number,
      customer_name, environment_name, piece_code, production_cycle,
      entry_type, traceability_type, is_manual, unit_of_measure,
      general_lot_code, created_at
    ) VALUES (
      v_client_event_id, v_piece.piece_uid,
      CASE WHEN v_reader_type = 'manual' THEN 'manual' ELSE 'barcode' END,
      v_reader_type, v_station, v_cell, v_operator.name, v_operator.name,
      v_auth_user_id, v_operator.id, v_shift, v_date, v_hour,
      v_piece.legacy_production_lot_item_id, v_piece.id, v_piece.lot_id,
      coalesce(v_piece.production_order_id, v_lot.production_order_id, v_lot.order_id),
      v_target_step_code, v_target_step_code, v_quantity,
      'approved', 'approved_scan',
      v_session.machine_id, v_session.machine_name_snapshot,
      v_lot.lot_code, v_order.load_number, coalesce(v_order.order_number, v_order.order_code),
      v_order.customer_name, coalesce(v_piece.environment_name, v_piece.environment),
      v_piece.traceability_code, v_current_cycle,
      'coleta_fisica', 'unitaria', v_reader_type = 'manual', 'pecas',
      coalesce(v_piece.general_lot_code, v_lot.general_lot_code), v_occurred_at
    )
    RETURNING * INTO v_reading;
  EXCEPTION WHEN unique_violation THEN
    SELECT * INTO v_existing_reading
    FROM public.production_stage_readings reading
    WHERE reading.piece_id = v_piece.id
      AND lower(btrim(reading.step_name)) = lower(btrim(v_target_step_code))
      AND reading.status = 'approved'
    ORDER BY reading.created_at DESC
    LIMIT 1;

    INSERT INTO public.production_stage_readings (
      client_event_id, tag_value, tag_type, reader_type,
      station_name, cell_name, operator, operator_name_snapshot,
      user_id, operator_id, shift, date, hour,
      item_id, piece_id, lot_id, production_order_id,
      step_name, operation_name, quantity, status, event_type,
      machine_id, machine_name, lot_code, load_number, order_number,
      customer_name, environment_name, piece_code, production_cycle,
      entry_type, traceability_type, is_manual, unit_of_measure,
      general_lot_code, created_at
    ) VALUES (
      v_client_event_id, v_piece.piece_uid,
      CASE WHEN v_reader_type = 'manual' THEN 'manual' ELSE 'barcode' END,
      v_reader_type, v_station, v_cell, v_operator.name, v_operator.name,
      v_auth_user_id, v_operator.id, v_shift, v_date, v_hour,
      v_piece.legacy_production_lot_item_id, v_piece.id, v_piece.lot_id,
      coalesce(v_piece.production_order_id, v_lot.production_order_id, v_lot.order_id),
      v_target_step_code, v_target_step_code, v_quantity,
      'duplicated', 'duplicated_scan',
      v_session.machine_id, v_session.machine_name_snapshot,
      v_lot.lot_code, v_order.load_number, coalesce(v_order.order_number, v_order.order_code),
      v_order.customer_name, coalesce(v_piece.environment_name, v_piece.environment),
      v_piece.traceability_code, v_current_cycle,
      'coleta_fisica', 'unitaria', v_reader_type = 'manual', 'pecas',
      coalesce(v_piece.general_lot_code, v_lot.general_lot_code), v_occurred_at
    )
    RETURNING * INTO v_reading;

    v_result := jsonb_build_object(
      'success', false,
      'status', 'blocked',
      'legacy_status', 'duplicated',
      'reason_code', 'DUPLICATE_PIECE_STAGE',
      'alert_level', 'yellow',
      'message', 'ENTRADA BLOQUEADA: esta numeração já foi aprovada nesta célula.',
      'lot', to_jsonb(v_lot),
      'order', to_jsonb(v_order),
      'item', to_jsonb(v_piece),
      'reading', to_jsonb(v_reading),
      'existing_reading_id', v_existing_reading.id
    );

    UPDATE public.production_collection_events
    SET reason_code = 'DUPLICATE_PIECE_STAGE'
    WHERE id = v_event.id;

    RETURN public.finish_collection_event(
      v_event.id, 'ignored', 'duplicated', v_result, v_reading.id, NULL, v_result ->> 'message'
    );
  END;

  INSERT INTO public.production_entries (
    date, shift, cell, hour, produced, target, scrap, downtime,
    operator, operator_id, operator_name_snapshot, notes,
    created_by, client_event_id,
    order_id, production_order_id, lot_id,
    order_number, lot_code, load_number, customer_name,
    environment_name, operation_name, step_code,
    machine_id, machine_name, pcp_import_batch_id,
    entry_mode, source, approval_status,
    is_manual, unit_of_measure,
    created_at
  ) VALUES (
    v_date, v_shift, v_cell, v_hour, v_quantity, 0, 0, 0,
    v_operator.name, v_operator.id, v_operator.name,
    'Coleta MES validada — Peça: ' || v_piece.traceability_code,
    v_auth_user_id, v_client_event_id,
    v_order.id, v_order.id, v_lot.id,
    coalesce(v_order.order_number, v_order.order_code), v_lot.lot_code,
    v_order.load_number, v_order.customer_name,
    coalesce(v_piece.environment_name, v_piece.environment), v_target_step_code, v_target_step_code,
    v_session.machine_id, v_session.machine_name_snapshot,
    coalesce(v_piece.pcp_import_batch_id, v_lot.pcp_import_batch_id),
    'scan', 'coleta_scan', 'valid',
    v_reader_type = 'manual', 'pecas',
    v_occurred_at
  )
  RETURNING id INTO v_entry_id;

  UPDATE public.production_stage_readings
  SET production_entry_id = v_entry_id
  WHERE id = v_reading.id;

  v_new_completed_steps := coalesce(v_piece.completed_steps, '{}'::text[]);
  IF NOT (v_target_step_code = ANY(v_new_completed_steps)) THEN
    v_new_completed_steps := array_append(v_new_completed_steps, v_target_step_code);
  END IF;

  v_next_step := NULL;
  IF cardinality(coalesce(v_piece.route_steps, '{}'::text[])) > 0 THEN
    FOREACH v_step IN ARRAY v_piece.route_steps LOOP
      IF NOT (v_step = ANY(v_new_completed_steps)) THEN
        v_next_step := v_step;
        EXIT;
      END IF;
    END LOOP;
  END IF;

  UPDATE public.production_pieces piece
  SET completed_steps = v_new_completed_steps,
      current_stage = coalesce(v_next_step, 'Concluída'),
      status = CASE WHEN v_next_step IS NULL THEN 'completed' ELSE 'in_progress' END,
      production_status = CASE WHEN v_next_step IS NULL THEN 'completed' ELSE 'approved' END,
      rework_status = CASE
        WHEN coalesce(piece.is_rework, false) AND v_next_step IS NULL THEN 'completed'
        ELSE piece.rework_status
      END,
      replacement_status = CASE
        WHEN coalesce(piece.is_replacement, false) AND v_next_step IS NULL THEN 'replaced'
        ELSE piece.replacement_status
      END,
      is_blocked = false,
      block_reason = NULL,
      updated_at = v_now
  WHERE piece.id = v_piece.id
  RETURNING * INTO v_piece;

  IF coalesce(v_piece.is_replacement, false)
     AND v_piece.original_piece_id IS NOT NULL
     AND v_next_step IS NULL THEN
    UPDATE public.production_pieces
    SET status = 'replaced',
        replacement_status = 'replaced',
        updated_at = v_now
    WHERE id = v_piece.original_piece_id;

    UPDATE public.replacement_orders
    SET status = 'completed',
        completed_at = coalesce(completed_at, v_now),
        updated_at = v_now
    WHERE replacement_piece_id = v_piece.id
      AND status NOT IN ('completed','cancelled','Finalizada','Cancelada');
  END IF;

  IF v_piece.legacy_production_lot_item_id IS NOT NULL THEN
    UPDATE public.production_lot_items
    SET current_step = coalesce(v_next_step, 'completed'),
        current_cell = v_cell,
        status = CASE WHEN v_next_step IS NULL THEN 'completed' ELSE 'in_progress' END,
        updated_at = v_now
    WHERE id = v_piece.legacy_production_lot_item_id;
  END IF;

  v_context_result := public.switch_cell_active_lot_context(
    v_cell,
    v_target_step_code,
    v_session.machine_id,
    v_lot.id,
    coalesce(v_piece.pcp_import_batch_id, v_lot.pcp_import_batch_id),
    v_occurred_at,
    v_client_event_id
  );

  v_cell_state := public.recalculate_cell_lot_state(
    v_lot.id,
    v_cell,
    v_target_step_code,
    v_session.machine_id,
    v_operator.id
  );

  v_result := jsonb_build_object(
    'success', true,
    'status', 'approved',
    'alert_level', 'green',
    'message', 'Baixa de etapa registrada com sucesso.',
    'lot', to_jsonb(v_lot),
    'order', to_jsonb(v_order),
    'item', to_jsonb(v_piece),
    'reading', to_jsonb(v_reading),
    'route', jsonb_build_object(
      'step_name', v_target_step_code,
      'cell_name', v_cell,
      'next_step', v_next_step
    ),
    'active_context', v_context_result -> 'active_context',
    'context_changed', coalesce((v_context_result ->> 'changed')::boolean, false),
    'context_stale_event_ignored', coalesce((v_context_result ->> 'ignored_stale_event')::boolean, false),
    'cell_state', v_cell_state
  );

  RETURN public.finish_collection_event(
    v_event.id, 'synced', 'approved', v_result, v_reading.id, v_entry_id, NULL
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.process_production_reading_impl(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_session_token text := NULLIF(TRIM(p_payload->>'operatorSessionToken'), '');
  v_client_event_id text := NULLIF(TRIM(p_payload->>'client_event_id'), '');
  v_tag_value text := UPPER(TRIM(COALESCE(p_payload->>'rawValue', p_payload->>'raw_value', p_payload->>'tagValue', '')));
  v_reader_type text := COALESCE(NULLIF(p_payload->>'readerType', ''), NULLIF(p_payload->>'reader_type', ''), 'keyboard_barcode');
  v_cell text := NULLIF(TRIM(COALESCE(p_payload->>'cellName', p_payload->>'cell_name', '')), '');
  v_station text := NULLIF(TRIM(COALESCE(p_payload->>'stationName', p_payload->>'station_name', '')), '');
  v_step_input text := NULLIF(TRIM(COALESCE(p_payload->>'stepName', p_payload->>'step_name', '')), '');
  v_operator text := NULLIF(TRIM(COALESCE(p_payload->>'operator', '')), '');
  v_shift text := NULLIF(TRIM(COALESCE(p_payload->>'shift', '')), '');
  v_date date := COALESCE(NULLIF(p_payload->>'date', '')::date, current_date);
  v_hour text := COALESCE(NULLIF(p_payload->>'hour', ''), to_char(now(), 'HH24:MI'));
  v_quantity integer := GREATEST(COALESCE(NULLIF(p_payload->>'quantity', '')::integer, 1), 1);
  v_created_at_client timestamptz := COALESCE(
    NULLIF(p_payload->>'createdAtClient', '')::timestamptz,
    NULLIF(p_payload->>'created_at_client', '')::timestamptz,
    now()
  );
  v_device_id text := NULLIF(TRIM(COALESCE(p_payload->>'deviceId', p_payload->>'device_id', '')), '');
  v_enqueue_duration_ms numeric := COALESCE(NULLIF(p_payload->>'enqueue_duration_ms', '')::numeric, 0);

  v_token_hash text;
  v_session public.operator_sessions%ROWTYPE;
  v_op public.operators%ROWTYPE;
  v_event public.production_collection_events%ROWTYPE;
  v_piece public.production_pieces%ROWTYPE;
  v_lot public.production_lots%ROWTYPE;
  v_order public.production_orders%ROWTYPE;
  v_reading public.production_stage_readings%ROWTYPE;
  v_entry_id uuid;
  v_result jsonb;
  v_val_res jsonb;
  v_target_step_code text;
  v_new_completed_steps text[];
  v_next_step text;
  v_found_next boolean := false;
  v_total_pieces bigint := 0;
  v_completed_pieces bigint := 0;
  v_total_steps bigint := 0;
  v_completed_steps_count bigint := 0;
  v_general_lot_progress_percent numeric(5,2) := 0;
  i integer;
BEGIN
  -- Derivar sessão se token fornecido
  IF v_session_token IS NOT NULL THEN
    v_token_hash := encode(digest(v_session_token, 'sha256'), 'hex');
    SELECT * INTO v_session FROM public.operator_sessions
    WHERE token_hash = v_token_hash AND ended_at IS NULL AND revoked_at IS NULL AND expires_at > now();

    IF v_session.id IS NOT NULL THEN
      SELECT * INTO v_op FROM public.operators WHERE id = v_session.operator_id;
      v_cell := COALESCE(v_session.cell_name_snapshot, v_cell);
      v_station := COALESCE(v_session.station_name_snapshot, v_station);
      v_operator := COALESCE(v_op.name, v_operator);
      v_shift := COALESCE(v_session.shift_snapshot, v_shift);
    END IF;
  END IF;

  v_cell := COALESCE(v_cell, 'Corte');
  v_operator := COALESCE(v_operator, 'Operador Coleta');
  v_shift := COALESCE(v_shift, '1º Turno');
  v_station := COALESCE(v_station, 'Coletor Chão de Fábrica');
  v_client_event_id := COALESCE(v_client_event_id, gen_random_uuid()::text);

  -- Claim do evento de coleta
  INSERT INTO public.production_collection_events (
    client_event_id, raw_value, normalized_value, reader_type,
    operator_id, operator_name, registration, cell_name, shift, date, hour,
    status, created_at_client, payload, machine_id, machine_name, station_name,
    device_id, enqueue_duration_ms, sync_started_at, attempt_count, last_attempt_at,
    operator_session_id, cell_id, operator_registration_snapshot, machine_name_snapshot,
    station_name_snapshot, shift_snapshot
  ) VALUES (
    v_client_event_id, v_tag_value, v_tag_value, v_reader_type,
    v_op.id, v_operator, COALESCE(v_op.registration, 'OP-001'), v_cell, v_shift, v_date, v_hour,
    'processing', v_created_at_client, p_payload, v_session.machine_id, v_session.machine_name_snapshot, v_station,
    v_device_id, v_enqueue_duration_ms, now(), 1, now(),
    v_session.id, v_session.cell_id, COALESCE(public.mask_registration(v_op.registration), 'OP-***'), v_session.machine_name_snapshot,
    v_station, v_shift
  )
  ON CONFLICT (client_event_id) DO NOTHING
  RETURNING * INTO v_event;

  IF NOT FOUND THEN
    SELECT * INTO v_event
    FROM public.production_collection_events
    WHERE client_event_id = v_client_event_id;

    UPDATE public.production_collection_events
    SET attempt_count = attempt_count + 1,
        last_attempt_at = now()
    WHERE id = v_event.id;

    IF v_event.result_payload IS NOT NULL AND v_event.result_payload <> '{}'::jsonb
       AND v_event.status IN ('synced', 'ignored', 'error') THEN
      RETURN v_event.result_payload;
    END IF;

    UPDATE public.production_collection_events
    SET status = 'processing',
        payload = p_payload,
        sync_started_at = now(),
        sync_finished_at = NULL,
        error_message = NULL,
        updated_at = now()
    WHERE id = v_event.id
    RETURNING * INTO v_event;
  END IF;

  IF v_tag_value = '' THEN
    v_result := jsonb_build_object(
      'success', false,
      'status', 'invalid',
      'alert_level', 'red',
      'message', 'Informe uma identificação produtiva válida.'
    );
    RETURN public.finish_collection_event(v_event.id, 'ignored', 'invalid', v_result, NULL, NULL, v_result->>'message');
  END IF;

  BEGIN
    v_piece := public.resolve_piece_by_identifier(v_tag_value);
  EXCEPTION WHEN OTHERS THEN
    v_result := jsonb_build_object(
      'success', false,
      'status', 'not_found',
      'alert_level', 'red',
      'message', SQLERRM
    );
    RETURN public.finish_collection_event(v_event.id, 'ignored', 'not_found', v_result, NULL, NULL, SQLERRM);
  END;

  SELECT * INTO v_piece FROM public.production_pieces WHERE id = v_piece.id FOR UPDATE;
  SELECT * INTO v_lot FROM public.production_lots WHERE id = v_piece.lot_id;
  SELECT * INTO v_order FROM public.production_orders WHERE id = COALESCE(v_piece.production_order_id, v_lot.production_order_id, v_lot.order_id);

  UPDATE public.production_collection_events SET
    piece_id = v_piece.id,
    pcp_import_batch_id = v_piece.pcp_import_batch_id,
    lot_id = v_piece.lot_id,
    production_order_id = v_piece.production_order_id,
    lot_code = v_lot.lot_code,
    load_number = v_order.load_number,
    order_number = COALESCE(v_order.order_number, v_order.order_code),
    customer_name = v_order.customer_name,
    environment_name = v_piece.environment,
    piece_code = v_piece.traceability_code,
    updated_at = now()
  WHERE id = v_event.id;

  IF v_step_input IS NOT NULL THEN
    v_target_step_code := COALESCE(
      public.resolve_production_stage_for_cell(NULL, v_step_input),
      lower(trim(v_step_input))
    );
  ELSE
    v_target_step_code := public.resolve_production_stage_for_cell(v_session.cell_id, v_cell);
  END IF;

  -- Uma célula desconhecida deve bloquear claramente. Usar current_stage como
  -- fallback fazia "Fura" virar "Concluída" e rejeitava uma rota válida.
  v_target_step_code := COALESCE(v_target_step_code, '__unmapped_cell__');

  UPDATE public.production_collection_events SET
    operation_name = v_target_step_code
  WHERE id = v_event.id;

  -- Validar sequenciamento
  v_val_res := public.validar_fluxo_da_peca(v_piece.id, v_target_step_code);

  IF NOT COALESCE((v_val_res->>'success')::boolean, false) OR v_val_res->>'status' = 'duplicated' THEN
    IF v_piece.lot_id IS NOT NULL THEN
      INSERT INTO public.production_stage_readings (
        client_event_id, tag_value, tag_type, reader_type, station_name, cell_name,
        operator, shift, date, hour, item_id, piece_id, lot_id, production_order_id,
        step_name, quantity, status, event_type, operator_id, machine_id, machine_name,
        lot_code, load_number, order_number, customer_name, environment_name,
        operation_name, piece_code, created_at
      ) VALUES (
        v_client_event_id, v_piece.piece_uid,
        CASE WHEN v_reader_type = 'manual' THEN 'manual' ELSE 'barcode' END,
        v_reader_type, v_station, v_cell,
        v_operator, v_shift, v_date, v_hour, v_piece.legacy_production_lot_item_id, v_piece.id,
        v_piece.lot_id, v_piece.production_order_id, v_target_step_code, v_quantity,
        CASE WHEN v_val_res->>'status' = 'duplicated' THEN 'duplicated' ELSE 'blocked' END,
        CASE WHEN v_val_res->>'status' = 'duplicated' THEN 'duplicated_scan' ELSE 'wrong_step' END,
        v_op.id, v_session.machine_id, v_session.machine_name_snapshot, v_lot.lot_code, v_order.load_number,
        COALESCE(v_order.order_number, v_order.order_code), v_order.customer_name,
        v_piece.environment, v_target_step_code, v_piece.traceability_code, v_created_at_client
      ) RETURNING * INTO v_reading;
    END IF;

    v_result := jsonb_build_object(
      'success', false,
      'status', COALESCE(v_val_res->>'status', 'blocked'),
      'alert_level', COALESCE(v_val_res->>'alert_level', 'red'),
      'message', COALESCE(v_val_res->>'message', 'Entrada bloqueada.'),
      'lot', to_jsonb(v_lot),
      'order', to_jsonb(v_order),
      'item', to_jsonb(v_piece),
      'reading', CASE WHEN v_reading.id IS NULL THEN NULL ELSE to_jsonb(v_reading) END
    );
    RETURN public.finish_collection_event(v_event.id, 'ignored', v_val_res->>'status', v_result, v_reading.id, NULL, v_result->>'message');
  END IF;

  -- Registra Baixa Aprovada na tabela de leituras
  INSERT INTO public.production_stage_readings (
    client_event_id, tag_value, tag_type, reader_type, station_name, cell_name,
    operator, shift, date, hour, item_id, piece_id, lot_id, production_order_id,
    step_name, quantity, status, event_type, operator_id, machine_id, machine_name,
    lot_code, load_number, order_number, customer_name, environment_name,
    operation_name, piece_code, production_cycle, created_at
  ) VALUES (
    v_client_event_id, v_piece.piece_uid,
    CASE WHEN v_reader_type = 'manual' THEN 'manual' ELSE 'barcode' END,
    v_reader_type, v_station, v_cell,
    v_operator, v_shift, v_date, v_hour, v_piece.legacy_production_lot_item_id, v_piece.id,
    v_piece.lot_id, v_piece.production_order_id, v_target_step_code, v_quantity,
    'approved', 'approved_scan', v_op.id, v_session.machine_id, v_session.machine_name_snapshot,
    v_lot.lot_code, v_order.load_number, COALESCE(v_order.order_number, v_order.order_code),
    v_order.customer_name, v_piece.environment, v_target_step_code,
    v_piece.traceability_code, 1, v_created_at_client
  ) RETURNING * INTO v_reading;

  -- Registra Apontamento em production_entries
  INSERT INTO public.production_entries (
    date, shift, cell, hour, produced, target, scrap, downtime,
    operator, notes, order_number, lot_code, entry_mode, source, created_at
  ) VALUES (
    v_date, v_shift, v_cell, v_hour, v_quantity, 0, 0, 0,
    v_operator, 'Coleta MES - Peça ' || v_piece.traceability_code,
    COALESCE(v_order.order_number, v_order.order_code), v_lot.lot_code,
    'scan', 'coleta_scan', now()
  ) RETURNING id INTO v_entry_id;

  -- Atualizar etapas completas da peça
  v_new_completed_steps := COALESCE(v_piece.completed_steps, '{}'::text[]);
  IF NOT (v_target_step_code = ANY(v_new_completed_steps)) THEN
    v_new_completed_steps := array_append(v_new_completed_steps, v_target_step_code);
  END IF;

  UPDATE public.production_pieces
  SET completed_steps = v_new_completed_steps,
      current_stage = COALESCE(v_next_step, 'Concluída'),
      status = CASE WHEN v_next_step IS NULL THEN 'completed' ELSE 'in_progress' END,
      updated_at = now()
  WHERE id = v_piece.id
  RETURNING * INTO v_piece;

  v_result := jsonb_build_object(
    'success', true,
    'status', 'approved',
    'alert_level', 'green',
    'message', 'Leitura aprovada com sucesso.',
    'lot', to_jsonb(v_lot),
    'order', to_jsonb(v_order),
    'item', to_jsonb(v_piece),
    'reading', to_jsonb(v_reading)
  );

  RETURN public.finish_collection_event(v_event.id, 'synced', 'approved', v_result, v_reading.id, v_entry_id, NULL);
END;
$function$

CREATE OR REPLACE FUNCTION public.process_production_reading_v2(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'realtime', 'pg_temp'
AS $function$
DECLARE
  v_payload jsonb := coalesce(p_payload, '{}'::jsonb);
  v_result jsonb;
  v_client_event_id text;
  v_reader_type text := lower(coalesce(
    nullif(btrim(v_payload ->> 'readerType'), ''),
    nullif(btrim(v_payload ->> 'reader_type'), ''),
    'keyboard_barcode'
  ));
  v_raw_value text := coalesce(
    v_payload ->> 'rawValue',
    v_payload ->> 'raw_value',
    v_payload ->> 'tagValue',
    ''
  );
  v_scan_code text;
  v_digit_count integer;
BEGIN
  v_client_event_id := nullif(btrim(v_payload ->> 'client_event_id'), '');

  IF v_reader_type IN ('keyboard_barcode', 'camera_qrcode', 'camera_barcode', 'manual') THEN
    v_scan_code := public.normalize_collection_scan_code(v_raw_value);
    v_digit_count := length(regexp_replace(coalesce(v_raw_value, ''), '[^0-9]', '', 'g'));

    IF v_scan_code IS NULL THEN
      RETURN jsonb_build_object(
        'success', false,
        'status', 'invalid',
        'reason_code', 'INVALID_CODE_LENGTH',
        'alert_level', 'red',
        'message', CASE
          WHEN v_digit_count > 8 THEN 'ENTRADA BLOQUEADA: a numeração excedeu o limite de 8 dígitos.'
          WHEN v_digit_count < 8 THEN format(
            'ENTRADA BLOQUEADA: informe exatamente 8 dígitos. Recebidos: %s.',
            v_digit_count
          )
          ELSE 'ENTRADA BLOQUEADA: a numeração deve conter somente 8 dígitos numéricos.'
        END,
        'expected_code_length', 8,
        'received_digit_count', v_digit_count,
        'client_event_id', v_client_event_id
      );
    END IF;

    v_payload := jsonb_set(v_payload, '{rawValue}', to_jsonb(v_scan_code), true);
    v_payload := jsonb_set(v_payload, '{raw_value}', to_jsonb(v_scan_code), true);
    v_payload := jsonb_set(v_payload, '{exactDigitCapture}', 'true'::jsonb, true);
    v_payload := jsonb_set(v_payload, '{expectedCodeLength}', '8'::jsonb, true);
  END IF;

  v_result := public.process_production_reading_impl_v2(v_payload);
  v_client_event_id := coalesce(
    nullif(btrim(v_payload ->> 'client_event_id'), ''),
    nullif(v_result ->> 'client_event_id', ''),
    nullif(v_result #>> '{reading,client_event_id}', '')
  );
  RETURN public.finalize_collection_realtime(v_client_event_id, v_result);
END;
$function$

CREATE OR REPLACE FUNCTION public.production_metric_unit_for_cell(p_cell text DEFAULT NULL::text, p_step text DEFAULT NULL::text, p_operation text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
DECLARE
  v_text text := lower(concat_ws(' ', p_cell, p_step, p_operation));
BEGIN
  IF v_text ILIKE '%corte%' OR v_text ILIKE '%seccion%' THEN
    RETURN 'sheets';
  END IF;
  IF v_text ILIKE '%bord%' OR v_text ILIKE '%coladeira%' THEN
    RETURN 'meters';
  END IF;
  IF v_text ILIKE '%usin%' OR v_text ILIKE '%fura%' OR v_text ILIKE '%cnc%' THEN
    RETURN 'pieces';
  END IF;
  IF v_text ILIKE '%marcen%' OR v_text ILIKE '%embalag%' OR v_text ILIKE '%expedi%' THEN
    RETURN 'pieces';
  END IF;
  RETURN 'pieces';
END;
$function$

CREATE OR REPLACE FUNCTION public.profile_can_access_cell(p_cell text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_role text;
  v_cell text;
  v_managed_cells text[];
  v_active boolean;
BEGIN
  IF auth.uid() IS NULL OR NULLIF(btrim(p_cell), '') IS NULL THEN
    RETURN false;
  END IF;

  SELECT role, cell, managed_cells, active
  INTO v_role, v_cell, v_managed_cells, v_active
  FROM public.profiles
  WHERE id = auth.uid();

  IF COALESCE(v_active, false) = false THEN
    RETURN false;
  END IF;

  IF v_role = 'admin' THEN
    RETURN true;
  END IF;

  v_managed_cells := COALESCE(v_managed_cells, '{}'::text[]);
  IF array_length(v_managed_cells, 1) IS NULL AND NULLIF(btrim(v_cell), '') IS NOT NULL THEN
    v_managed_cells := ARRAY[v_cell];
  END IF;

  IF v_role = 'operator' THEN
    RETURN p_cell = ANY(v_managed_cells);
  END IF;

  -- Gestores, supervisores e visualizadores sem escopo explícito mantêm visão global.
  RETURN array_length(v_managed_cells, 1) IS NULL OR p_cell = ANY(v_managed_cells);
END;
$function$

CREATE OR REPLACE FUNCTION public.purge_archived_production_lot_detail(p_job_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_manifest public.production_archive_manifests%ROWTYPE;
  v_lot public.production_lots%ROWTYPE;
  v_piece_count bigint := 0;
  v_reading_count bigint := 0;
  v_event_count bigint := 0;
BEGIN
  SELECT *
  INTO v_manifest
  FROM public.production_archive_manifests manifest
  WHERE manifest.job_id = p_job_id
  FOR UPDATE;

  IF NOT FOUND
     OR v_manifest.verified_at IS NULL
     OR v_manifest.sha256 IS NULL
     OR v_manifest.object_size_bytes <= 0
     OR v_manifest.legal_hold IS TRUE THEN
    RAISE EXCEPTION 'ARCHIVE_NOT_VERIFIED_OR_HELD'
      USING ERRCODE = '55000';
  END IF;

  SELECT *
  INTO v_lot
  FROM public.production_lots lot
  WHERE lot.id = v_manifest.lot_id
  FOR UPDATE;

  IF NOT FOUND
     OR v_lot.legal_hold IS TRUE
     OR v_lot.closed_at IS NULL
     OR v_lot.closed_at > now() - interval '90 days' THEN
    RAISE EXCEPTION 'LOT_NOT_PURGEABLE'
      USING ERRCODE = '55000';
  END IF;

  SELECT count(*) INTO v_piece_count
  FROM public.production_pieces piece
  WHERE piece.lot_id = v_lot.id;

  SELECT count(*) INTO v_reading_count
  FROM public.production_stage_readings reading
  WHERE reading.lot_id = v_lot.id;

  SELECT count(*) INTO v_event_count
  FROM public.production_collection_events event
  WHERE event.lot_id = v_lot.id;

  -- Ordem de exclusão respeita as FKs e mantém o resumo do lote.
  DELETE FROM public.production_collection_events
  WHERE lot_id = v_lot.id;

  DELETE FROM public.production_stage_readings
  WHERE lot_id = v_lot.id;

  DELETE FROM public.production_entries
  WHERE lot_id = v_lot.id
     OR (lot_id IS NULL AND lot_code = v_lot.lot_code);

  DELETE FROM public.production_events
  WHERE lot_id = v_lot.id;

  DELETE FROM public.lot_step_events
  WHERE lot_id = v_lot.id;

  DELETE FROM public.production_lot_items
  WHERE lot_id = v_lot.id;

  DELETE FROM public.lot_items
  WHERE lot_id = v_lot.id;

  DELETE FROM public.production_routes
  WHERE lot_id = v_lot.id;

  DELETE FROM public.production_realtime_counters
  WHERE lot_id = v_lot.id;

  DELETE FROM public.production_lot_stage_aggregates
  WHERE lot_id = v_lot.id;

  -- FKs das tabelas de embalagem, ocorrências e expedição usam CASCADE ou
  -- SET NULL; os seus resumos continuam disponíveis sem reter a peça quente.
  DELETE FROM public.production_pieces
  WHERE lot_id = v_lot.id;

  UPDATE public.production_archive_manifests
  SET status = 'purged',
      purged_at = now(),
      updated_at = now()
  WHERE id = v_manifest.id;

  UPDATE public.production_archive_jobs
  SET status = 'purged',
      finished_at = now(),
      lock_token = NULL,
      locked_at = NULL,
      updated_at = now()
  WHERE id = p_job_id;

  UPDATE public.production_lots
  SET detail_archived_at = now(),
      archive_manifest_id = v_manifest.id,
      archive_storage_path = v_manifest.storage_path,
      updated_at = now()
  WHERE id = v_lot.id;

  RETURN jsonb_build_object(
    'success', true,
    'lot_id', v_lot.id,
    'pieces_purged', v_piece_count,
    'readings_purged', v_reading_count,
    'events_purged', v_event_count,
    'manifest_id', v_manifest.id
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.reconcile_replacement_piece_trail(p_piece_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_piece public.production_pieces%rowtype;
  v_route text[] := '{}'::text[];
  v_completed text[] := '{}'::text[];
  v_next_step text;
  v_is_complete boolean := false;
begin
  if p_piece_id is null then return; end if;

  select * into v_piece from public.production_pieces where id = p_piece_id for update;
  if v_piece.id is null or coalesce(v_piece.is_replacement, false) is false then return; end if;

  select coalesce(array_agg(route.step_code order by route.first_position), '{}'::text[])
    into v_route
  from (
    select normalized.step_code, min(normalized.position) as first_position
    from (
      select public.normalize_replacement_step_code(source.raw_step) as step_code, source.position
      from unnest(coalesce(v_piece.route_steps, '{}'::text[])) with ordinality as source(raw_step, position)
    ) normalized
    where normalized.step_code is not null
    group by normalized.step_code
  ) route;

  if cardinality(v_route) = 0 then return; end if;

  select coalesce(array_agg(route.step_code order by route.position), '{}'::text[])
    into v_completed
  from unnest(v_route) with ordinality as route(step_code, position)
  where exists (
    select 1 from public.production_stage_readings reading
    where reading.piece_id = v_piece.id and reading.status = 'approved'
      and public.normalize_replacement_step_code(reading.step_name) = route.step_code
  );

  select route.step_code into v_next_step
  from unnest(v_route) with ordinality as route(step_code, position)
  where not (route.step_code = any(v_completed))
  order by route.position limit 1;

  v_is_complete := v_next_step is null;

  update public.production_pieces
  set completed_steps = v_completed, current_stage = coalesce(v_next_step, 'Concluída'),
      status = case when v_is_complete then 'completed' else 'in_progress' end,
      production_status = case when v_is_complete then 'completed' else 'approved' end,
      replacement_status = case when v_is_complete then 'replaced' else 'in_production' end,
      updated_at = now()
  where id = v_piece.id;

  update public.replacement_orders
  set status = case when v_is_complete then 'completed' else 'in_production' end,
      completed_at = case when v_is_complete then coalesce(completed_at, now()) else null end,
      updated_at = now()
  where replacement_piece_id = v_piece.id and status <> 'cancelled';

  update public.production_pieces original
  set replacement_status = case when v_is_complete then 'replaced' else 'in_production' end,
      status = case when v_is_complete then 'replaced' else original.status end,
      updated_at = now()
  where original.id = v_piece.original_piece_id;

  perform public.reconcile_general_lot_completion(v_piece.pcp_import_batch_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.recover_collection_projection_42703_v3(p_run_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pgmq', 'pg_temp'
AS $function$
DECLARE
  v_outbox record;
  v_message_id bigint;
  v_requeued integer := 0;
  v_skipped integer := 0;
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION 'SERVICE_ROLE_REQUIRED' USING ERRCODE = '42501';
  END IF;
  IF p_run_id !~ '^CAPTEST_[0-9]{8}_[0-9]{6}_[A-Z0-9]{8}$' THEN
    RAISE EXCEPTION 'CAPACITY_RUN_ID_INVALID' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (
    SELECT 1 FROM private.collection_pipeline_flags
    WHERE flag_name = 'collection_pipeline_v3_projection' AND enabled IS TRUE
  ) THEN
    RAISE EXCEPTION 'PAUSE_COLLECTION_V3_PROJECTION_BEFORE_RECOVERY' USING ERRCODE = '55000';
  END IF;

  FOR v_outbox IN
    SELECT outbox.*
    FROM public.collection_projection_outbox outbox
    WHERE outbox.projected_at IS NULL
      AND outbox.dead_lettered_at IS NOT NULL
      AND outbox.last_error_code = '42703'
    ORDER BY outbox.created_at, outbox.id
    FOR UPDATE
  LOOP
    IF EXISTS (
      SELECT 1 FROM public.collection_projection_applied applied
      WHERE applied.outbox_id = v_outbox.id
    ) OR EXISTS (
      SELECT 1 FROM public.production_entries entry
      WHERE entry.client_event_id = v_outbox.client_event_id
    ) THEN
      INSERT INTO private.collection_projection_recovery_audit (
        run_id, outbox_id, client_event_id, original_error_code, status, detail
      ) VALUES (
        p_run_id, v_outbox.id, v_outbox.client_event_id, '42703', 'skipped',
        'canonical projection already exists'
      ) ON CONFLICT (run_id, outbox_id) DO NOTHING;
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;

    SELECT pgmq.send(
      'collection_projection_v3',
      jsonb_build_object(
        'outbox_id', v_outbox.id,
        'client_event_id', v_outbox.client_event_id,
        'projection_revision', v_outbox.projection_revision,
        'recovery_run_id', p_run_id
      )
    ) INTO v_message_id;

    UPDATE public.collection_projection_outbox
    SET available_at = clock_timestamp(),
        dead_lettered_at = NULL,
        last_error_code = NULL
    WHERE id = v_outbox.id;

    PERFORM pgmq.archive('collection_dead_letter_v3', queue.msg_id)
    FROM pgmq.q_collection_dead_letter_v3 queue
    WHERE queue.message ->> 'kind' = 'projection'
      AND queue.message ->> 'sqlstate' = '42703'
      AND private.try_collection_uuid_v3(queue.message ->> 'outbox_id') = v_outbox.id;

    INSERT INTO private.collection_projection_recovery_audit (
      run_id, outbox_id, client_event_id, original_error_code,
      recovery_message_id, status, detail
    ) VALUES (
      p_run_id, v_outbox.id, v_outbox.client_event_id, '42703',
      v_message_id, 'requeued', 'schema contract restored; same outbox and client_event_id'
    ) ON CONFLICT (run_id, outbox_id) DO NOTHING;
    v_requeued := v_requeued + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'run_id', p_run_id,
    'requeued', v_requeued,
    'skipped', v_skipped,
    'recovered_at', clock_timestamp()
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.refresh_collection_lot_state(p_lot_id uuid, p_reading_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_lot public.production_lots%ROWTYPE;
  v_metrics jsonb;
  v_existing_version bigint;
  v_new_version bigint;
  v_is_complete boolean;
  v_completed_operations bigint;
  v_current_stage text;
  v_current_stage_label text;
BEGIN
  IF p_lot_id IS NULL THEN
    RETURN NULL;
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('production-lot:' || p_lot_id::text, 0));

  IF p_reading_id IS NOT NULL THEN
    SELECT reading.lot_state_version
    INTO v_existing_version
    FROM public.production_stage_readings reading
    WHERE reading.id = p_reading_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RETURN NULL;
    END IF;

    IF v_existing_version IS NOT NULL THEN
      RETURN public.get_collection_lot_snapshot(p_lot_id);
    END IF;
  END IF;

  SELECT * INTO v_lot
  FROM public.production_lots
  WHERE id = p_lot_id
  FOR UPDATE;

  IF v_lot.id IS NULL THEN
    RETURN NULL;
  END IF;

  v_metrics := public.get_collection_lot_route_metrics(p_lot_id);
  v_is_complete := coalesce((v_metrics ->> 'is_complete')::boolean, false);
  v_completed_operations := coalesce((v_metrics ->> 'completed_operations')::bigint, 0);
  v_current_stage := v_metrics ->> 'current_stage';
  v_current_stage_label := v_metrics ->> 'current_stage_label';

  UPDATE public.production_lots lot
  SET state_version = lot.state_version + 1,
      planned_quantity = coalesce((v_metrics ->> 'total_parts')::integer, lot.planned_quantity),
      progress_percent = coalesce((v_metrics ->> 'progress_percent')::numeric, 0),
      produced_quantity = coalesce((v_metrics ->> 'completed_parts')::numeric, 0),
      approved_quantity = coalesce((v_metrics ->> 'completed_parts')::numeric, 0),
      rejected_quantity = coalesce((v_metrics ->> 'rejected')::numeric, 0),
      pending_quantity = coalesce((v_metrics ->> 'pending_parts')::numeric, 0),
      missing_count = coalesce((v_metrics ->> 'pending_parts')::integer, 0),
      rework_count = coalesce((v_metrics ->> 'rework')::integer, 0),
      status = CASE
        WHEN v_is_complete THEN 'closed'
        WHEN v_completed_operations > 0 THEN 'in_progress'
        WHEN lot.status IN ('closed','shipped') THEN 'planned'
        ELSE lot.status
      END,
      current_status = CASE
        WHEN v_is_complete THEN 'completed'
        WHEN v_completed_operations > 0 THEN 'in_progress'
        ELSE coalesce(lot.current_status, lot.status)
      END,
      current_stage = coalesce(v_current_stage, lot.current_stage),
      current_step = coalesce(v_current_stage, lot.current_step),
      current_cell = coalesce(v_current_stage_label, lot.current_cell),
      actual_start = CASE
        WHEN v_completed_operations > 0 THEN coalesce(lot.actual_start, clock_timestamp())
        ELSE lot.actual_start
      END,
      actual_end = CASE WHEN v_is_complete THEN coalesce(lot.actual_end, clock_timestamp()) ELSE NULL END,
      closed_at = CASE WHEN v_is_complete THEN coalesce(lot.closed_at, clock_timestamp()) ELSE NULL END,
      updated_at = clock_timestamp()
  WHERE lot.id = p_lot_id
  RETURNING lot.state_version INTO v_new_version;

  IF p_reading_id IS NOT NULL THEN
    UPDATE public.production_stage_readings
    SET lot_state_version = v_new_version
    WHERE id = p_reading_id;
  END IF;

  IF v_lot.pcp_import_batch_id IS NOT NULL THEN
    PERFORM public.refresh_pcp_batch_progress(v_lot.pcp_import_batch_id);
  END IF;

  RETURN public.get_collection_lot_snapshot(p_lot_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.refresh_production_search_index()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_order_id uuid;
  v_order production_orders%ROWTYPE;
  v_lots text;
  v_products text;
  v_pallets text;
  v_routes text;
BEGIN
  IF TG_TABLE_NAME = 'production_orders' THEN
    v_order_id := NEW.id;
  ELSIF TG_TABLE_NAME = 'production_lots' THEN
    v_order_id := COALESCE(NEW.production_order_id, NEW.order_id);
  ELSE
    v_order_id := NEW.production_order_id;
  END IF;
  SELECT * INTO v_order FROM production_orders WHERE id = v_order_id;
  IF v_order.id IS NULL THEN RETURN NEW; END IF;
  SELECT string_agg(lot_code, ' | ') INTO v_lots FROM production_lots WHERE COALESCE(production_order_id,order_id)=v_order_id;
  SELECT string_agg(concat_ws(' ',product_code,product_name,product_description), ' | '),
         string_agg(pallet_number, ' | '), string_agg(concat_ws(' ',route_code,route_name), ' | ')
  INTO v_products,v_pallets,v_routes FROM production_order_items WHERE production_order_id=v_order_id;
  INSERT INTO production_search_index(entity_type,entity_id,search_text,keywords_json,status,updated_at)
  VALUES ('production_order',v_order_id,concat_ws(' | ',v_order.order_code,v_order.system_order_number,v_order.customer_order_number,v_order.order_number,v_order.load_number,v_order.customer_code,v_order.customer_legal_name,v_order.customer_trade_name,v_order.cnpj,v_order.city,v_order.state,v_order.delivery_region,v_order.finalization_date::text,v_lots,v_products,v_pallets,v_routes),
    jsonb_build_object('pedido',v_order.order_number,'carga',v_order.load_number,'cliente',v_order.customer_trade_name,'razao_social',v_order.customer_legal_name,'lotes',v_lots,'produtos',v_products,'pallets',v_pallets,'roteiros',v_routes,'finalizacao',v_order.finalization_date),v_order.status,now())
  ON CONFLICT(entity_type,entity_id) DO UPDATE SET search_text=EXCLUDED.search_text,keywords_json=EXCLUDED.keywords_json,status=EXCLUDED.status,updated_at=now();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.register_independent_finish(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_piece_uid text := UPPER(TRIM(p_payload->>'piece_uid'));
  v_piece_name text := COALESCE(NULLIF(TRIM(p_payload->>'piece_name'), ''), 'Peça Avulsa / Sem Registro');
  v_lot_code text := UPPER(TRIM(COALESCE(p_payload->>'lot_code', 'LOT-AVULSO')));
  v_customer_name text := COALESCE(NULLIF(TRIM(p_payload->>'customer_name'), ''), 'Consumidor Final');
  v_cell_name text := COALESCE(NULLIF(TRIM(p_payload->>'cell_name'), ''), 'Coleta');
  v_operator_name text := COALESCE(NULLIF(TRIM(p_payload->>'operator_name'), ''), 'Operador');
  v_operator_id uuid := NULLIF(p_payload->>'operator_id', '')::uuid;
  v_notes text := COALESCE(NULLIF(TRIM(p_payload->>'notes'), ''), 'Finalização avulsa/atraso');

  v_lot record;
  v_piece record;
  v_order record;
  v_reading record;
  v_step_code text;
BEGIN
  -- 1. Verificar permissões
  IF auth.uid() IS NULL OR get_my_role() NOT IN ('admin','manager','supervisor','operator') THEN
    RETURN jsonb_build_object('success', false, 'message', 'Usuário sem permissão.');
  END IF;

  IF v_piece_uid = '' THEN
    RETURN jsonb_build_object('success', false, 'message', 'Código de barras/UID inválido.');
  END IF;

  -- 2. Resolver ou Criar Lote Avulso se necessário
  SELECT * INTO v_lot FROM public.production_lots WHERE UPPER(lot_code) = v_lot_code LIMIT 1;
  IF v_lot.id IS NULL THEN
    -- Criar um novo pedido avulso para associar ao lote
    INSERT INTO public.production_orders (
      order_code, order_number, customer_name, status
    ) VALUES (
      v_lot_code, v_lot_code, v_customer_name, 'in_production'
    ) RETURNING * INTO v_order;

    INSERT INTO public.production_lots (
      lot_code, status, current_status, produced_quantity, approved_quantity, pending_quantity, progress_percent, production_order_id
    ) VALUES (
      v_lot_code, 'in_progress', 'in_progress', 0, 0, 1, 0, v_order.id
    ) RETURNING * INTO v_lot;
  ELSE
    SELECT * INTO v_order FROM public.production_orders WHERE id = v_lot.production_order_id;
  END IF;

  -- 3. Buscar peça existente
  SELECT * INTO v_piece FROM public.production_pieces WHERE piece_uid = v_piece_uid OR traceability_code = v_piece_uid LIMIT 1 FOR UPDATE;

  -- Resolver código da etapa
  SELECT code INTO v_step_code FROM public.routing_steps WHERE name = v_cell_name OR code = lower(v_cell_name) LIMIT 1;
  v_step_code := COALESCE(v_step_code, lower(v_cell_name));

  IF v_piece.id IS NOT NULL THEN
    -- Peça existe: atualizar status
    UPDATE public.production_pieces
    SET status = 'completed',
        is_replacement = true,
        replacement_status = 'in_production',
        completed_steps = array_append(array_remove(completed_steps, v_step_code), v_step_code),
        current_stage = 'Concluída',
        updated_at = now()
    WHERE id = v_piece.id
    RETURNING * INTO v_piece;
  ELSE
    -- Peça não existe: criar uma nova com status completed
    INSERT INTO public.production_pieces (
      piece_uid, traceability_code, piece_name, status, is_replacement, replacement_status,
      completed_steps, route_steps, current_stage, lot_id, production_order_id, environment
    ) VALUES (
      v_piece_uid, v_piece_uid, v_piece_name, 'completed', true, 'in_production',
      ARRAY[v_step_code], ARRAY[v_step_code], 'Concluída', v_lot.id, v_lot.production_order_id, 'Avulso'
    ) RETURNING * INTO v_piece;
  END IF;

  -- ─── EVITAR DUPLICIDADE E CONFLICT DA CONSTRAINT uq_approved_item_step ───
  -- Estorna qualquer leitura aprovada anterior para esta mesma etapa e peça/item
  IF v_piece.legacy_production_lot_item_id IS NOT NULL OR v_piece.id IS NOT NULL THEN
    UPDATE public.production_stage_readings
    SET status = 'pending_review',
        notes = concat_ws(E'\n', NULLIF(notes, ''), 'Estornada por nova entrada/reposição avulsa (' || to_char(now(), 'YYYY-MM-DD HH24:MI:SS') || ')')
    WHERE (item_id = v_piece.legacy_production_lot_item_id OR piece_id = v_piece.id)
      AND step_name = v_step_code
      AND status = 'approved';
  END IF;

  -- 4. Registrar leitura na etapa (agora incluindo piece_id explicitamente)
  INSERT INTO public.production_stage_readings (
    lot_id, item_id, piece_id, tag_value, reader_type, step_name, cell_name, operator, user_id, date, hour, status, event_type, quantity, notes,
    lot_code, customer_name, piece_code, production_order_id, is_rework
  ) VALUES (
    v_lot.id, v_piece.legacy_production_lot_item_id, v_piece.id, v_piece_uid, 'manual', v_step_code, v_cell_name, v_operator_name, auth.uid(), current_date, to_char(now(), 'HH24:MI'), 'approved', 'approved_scan', 1, v_notes,
    v_lot.lot_code, v_customer_name, v_piece_uid, v_lot.production_order_id, false
  ) RETURNING * INTO v_reading;

  -- 5. Registrar entrada MES
  INSERT INTO public.production_entries (
    date, shift, cell, hour, produced, target, scrap, downtime, operator, notes, created_by,
    operator_id, order_id, production_order_id, lot_id, lot_code, customer_name, operation_name
  ) VALUES (
    current_date, 'Não informado', v_cell_name, to_char(now(), 'HH24:MI'), 1, 0, 0, 0, v_operator_name, v_notes, auth.uid(),
    v_operator_id, v_lot.production_order_id, v_lot.production_order_id, v_lot.id, v_lot.lot_code, v_customer_name, v_step_code
  );

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Peça finalizada e registrada com sucesso como reposição!',
    'piece', to_jsonb(v_piece),
    'reading', to_jsonb(v_reading)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.register_production_downtime_impl(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_started_at timestamptz := (p_payload->>'started_at')::timestamptz;
  v_ended_at timestamptz := (p_payload->>'ended_at')::timestamptz;
  v_duration numeric;
  v_reason_id uuid;
  v_reason_name text;
  v_reason_code text;
  v_cell_id uuid;
  v_machine_id uuid;
  v_operator_id uuid;
  v_client_event_id uuid;
  v_existing_id uuid;
  v_occurrence_id uuid;
BEGIN
  IF v_started_at IS NULL OR v_ended_at IS NULL THEN
    RAISE EXCEPTION 'Início e fim da parada são obrigatórios para lançamentos passados.';
  END IF;

  IF v_ended_at <= v_started_at THEN
    RAISE EXCEPTION 'O horário final da parada deve ser maior que o horário inicial.';
  END IF;

  v_duration := ROUND(EXTRACT(EPOCH FROM (v_ended_at - v_started_at)) / 60.0, 2);

  IF p_payload->>'downtime_reason_id' IS NOT NULL AND p_payload->>'downtime_reason_id' != '' THEN
    BEGIN
      v_reason_id := (p_payload->>'downtime_reason_id')::uuid;
      SELECT name, code INTO v_reason_name, v_reason_code FROM public.downtime_reason_catalog WHERE id = v_reason_id;
    EXCEPTION WHEN OTHERS THEN
      v_reason_id := NULL;
    END;
  END IF;

  IF p_payload->>'cell_id' IS NOT NULL AND p_payload->>'cell_id' != '' THEN
    BEGIN v_cell_id := (p_payload->>'cell_id')::uuid; EXCEPTION WHEN OTHERS THEN v_cell_id := NULL; END;
  END IF;
  IF p_payload->>'machine_id' IS NOT NULL AND p_payload->>'machine_id' != '' THEN
    BEGIN v_machine_id := (p_payload->>'machine_id')::uuid; EXCEPTION WHEN OTHERS THEN v_machine_id := NULL; END;
  END IF;
  IF p_payload->>'operator_id' IS NOT NULL AND p_payload->>'operator_id' != '' THEN
    BEGIN v_operator_id := (p_payload->>'operator_id')::uuid; EXCEPTION WHEN OTHERS THEN v_operator_id := NULL; END;
  END IF;

  IF p_payload->>'client_event_id' IS NOT NULL AND p_payload->>'client_event_id' != '' THEN
    BEGIN
      v_client_event_id := (p_payload->>'client_event_id')::uuid;
      SELECT id INTO v_existing_id FROM public.occurrences WHERE client_event_id = v_client_event_id;
      IF v_existing_id IS NOT NULL THEN
        RETURN jsonb_build_object('success', true, 'idempotent', true, 'occurrence_id', v_existing_id);
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_client_event_id := NULL;
    END;
  END IF;

  INSERT INTO public.occurrences (
    date, shift, cell, reason, downtime, operator, notes,
    created_by, severity, status, occurrence_type,
    downtime_reason_id, downtime_reason_code, started_at, ended_at,
    duration_minutes, cell_id, machine_id, operator_id, client_event_id
  ) VALUES (
    v_started_at::date,
    COALESCE(p_payload->>'shift', '1'),
    COALESCE(p_payload->>'cell_name', 'Geral'),
    COALESCE(v_reason_name, p_payload->>'reason', 'Parada Registrada'),
    v_duration,
    COALESCE(p_payload->>'operator_name', 'Operador'),
    COALESCE(p_payload->>'notes', ''),
    v_user_id,
    'medium',
    'resolved',
    'downtime',
    v_reason_id,
    v_reason_code,
    v_started_at,
    v_ended_at,
    v_duration,
    v_cell_id,
    v_machine_id,
    v_operator_id,
    v_client_event_id
  ) RETURNING id INTO v_occurrence_id;

  RETURN jsonb_build_object(
    'success', true,
    'occurrence_id', v_occurrence_id,
    'duration_minutes', v_duration
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.register_production_downtime(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
declare
  v_cell record;
  v_sanitized jsonb := coalesce(p_payload, '{}'::jsonb);
begin
  if coalesce(auth.role(), '') <> 'service_role' and not public.can_manage_occurrences() then
    raise exception 'OCCURRENCE_PERMISSION_REQUIRED' using errcode = '42501';
  end if;
  select * into v_cell from public.resolve_downtime_target_cell(v_sanitized);
  if coalesce(auth.role(), '') <> 'service_role' and not public.profile_can_access_cell(v_cell.cell_name) then
    raise exception 'OCCURRENCE_OUTSIDE_CELL_SCOPE' using errcode = '42501';
  end if;
  v_sanitized := jsonb_set(v_sanitized, '{cell_name}', to_jsonb(v_cell.cell_name), true);
  v_sanitized := jsonb_set(v_sanitized, '{cell_id}', to_jsonb(v_cell.cell_id::text), true);
  return public.register_production_downtime_impl(v_sanitized);
end;
$function$

CREATE OR REPLACE FUNCTION public.register_quality_rejection_impl(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_piece_id uuid;
  v_traceability_code text;
  v_reason text;
  v_notes text;
  v_disposition text;
  v_requires_replacement boolean;
  v_defect_id_raw text;
  v_defect_id_uuid uuid;
  v_defect_code text;
  v_defect_name text;
  v_six_m_category text;
  v_severity text;
  v_operator_id uuid;
  v_operator_name text;
  v_cell_id uuid;
  v_cell_name text;
  v_machine_id uuid;
  v_client_event_id uuid;

  v_piece record;
  v_reading_id uuid;
  v_occurrence_id uuid;
  v_nc_id uuid;
  v_nc_code text;
  v_replacement_order_id uuid;
  v_existing_repl_id uuid;
  v_shift text;
  v_reversed_reading_id uuid;
BEGIN
  -- 1. Parse do payload
  v_traceability_code  := NULLIF(TRIM(p_payload->>'traceability_code'), '');
  v_reason             := COALESCE(NULLIF(TRIM(p_payload->>'reason'), ''), 'Não conformidade registrada');
  v_notes              := COALESCE(p_payload->>'notes', '');
  v_disposition        := COALESCE(p_payload->>'disposition', 'scrap');
  v_requires_replacement := COALESCE((p_payload->>'requires_replacement')::boolean, true);
  v_defect_id_raw      := NULLIF(TRIM(p_payload->>'defect_id'), '');
  v_defect_code        := NULLIF(TRIM(p_payload->>'defect_code'), '');
  v_defect_name        := NULLIF(TRIM(p_payload->>'defect_name'), '');
  v_six_m_category     := COALESCE(p_payload->>'six_m_category', 'Método');
  v_severity           := COALESCE(p_payload->>'severity', 'medium');
  v_operator_name      := COALESCE(NULLIF(p_payload->>'operator_name', ''), 'Operador');
  v_cell_name          := NULLIF(p_payload->>'cell_name', '');

  -- Safe UUID parsing for client_event_id
  IF p_payload->>'client_event_id' IS NOT NULL AND p_payload->>'client_event_id' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_client_event_id := (p_payload->>'client_event_id')::uuid;
  ELSE
    v_client_event_id := gen_random_uuid();
  END IF;

  -- Safe UUID parsing for defect_id
  IF v_defect_id_raw IS NOT NULL AND v_defect_id_raw ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_defect_id_uuid := v_defect_id_raw::uuid;
  ELSE
    v_defect_id_uuid := NULL;
  END IF;

  -- Safe UUID parsing for operator_id, machine_id, cell_id
  IF p_payload->>'operator_id' IS NOT NULL AND p_payload->>'operator_id' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_operator_id := (p_payload->>'operator_id')::uuid;
  END IF;

  IF p_payload->>'machine_id' IS NOT NULL AND p_payload->>'machine_id' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_machine_id := (p_payload->>'machine_id')::uuid;
  END IF;

  IF p_payload->>'cell_id' IS NOT NULL AND p_payload->>'cell_id' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_cell_id := (p_payload->>'cell_id')::uuid;
  ELSIF v_cell_name IS NOT NULL THEN
    SELECT id INTO v_cell_id FROM public.cells WHERE name ILIKE v_cell_name LIMIT 1;
  END IF;

  -- 2. Calcular Turno Atual
  v_shift := CASE 
    WHEN EXTRACT(HOUR FROM now()) BETWEEN 6 AND 13 THEN '1º Turno'
    WHEN EXTRACT(HOUR FROM now()) BETWEEN 14 AND 21 THEN '2º Turno'
    ELSE '3º Turno'
  END;

  -- 3. Carregar Peça
  IF p_payload->>'piece_id' IS NOT NULL AND p_payload->>'piece_id' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_piece_id := (p_payload->>'piece_id')::uuid;
    SELECT * INTO v_piece FROM public.production_pieces WHERE id = v_piece_id FOR UPDATE;
  ELSE
    SELECT * INTO v_piece FROM public.production_pieces 
    WHERE piece_uid = v_traceability_code 
       OR traceability_code = v_traceability_code 
       OR piece_code = v_traceability_code 
       OR id::text = v_traceability_code
    LIMIT 1 FOR UPDATE;
    IF v_piece.id IS NOT NULL THEN v_piece_id := v_piece.id; END IF;
  END IF;

  IF v_piece.id IS NULL AND v_piece_id IS NULL THEN
    RAISE EXCEPTION 'Peça não encontrada para o código/ID fornecido: %', COALESCE(v_traceability_code, (p_payload->>'piece_id'));
  END IF;

  -- 4. Carregar metadados do defeito
  IF v_defect_id_raw IS NOT NULL THEN
    SELECT code, name, six_m_category INTO v_defect_code, v_defect_name, v_six_m_category
    FROM public.quality_defect_catalog 
    WHERE id::text = v_defect_id_raw OR code = v_defect_id_raw LIMIT 1;
  END IF;
  v_defect_name := COALESCE(v_defect_name, p_payload->>'defect_name', v_reason);
  v_defect_code := COALESCE(v_defect_code, p_payload->>'defect_code', 'DEF-GENERIC');

  -- 5. Estorno da Aprovação Anterior
  SELECT id INTO v_reversed_reading_id
  FROM public.production_stage_readings
  WHERE piece_id = v_piece_id AND status = 'approved'
  ORDER BY created_at DESC LIMIT 1;

  IF v_reversed_reading_id IS NOT NULL THEN
    UPDATE public.production_stage_readings
    SET status = 'pending_review',
        notes = CONCAT(COALESCE(notes, ''), ' [Estornado por Reprovação]')
    WHERE id = v_reversed_reading_id;
  END IF;

  -- 6. Atualizar Peça Canônica
  UPDATE public.production_pieces
  SET status = CASE WHEN v_disposition = 'hold' THEN 'blocked' ELSE 'rejected' END,
      replacement_status = CASE WHEN v_requires_replacement THEN 'requested' ELSE NULL END,
      updated_at = now()
  WHERE id = v_piece_id;

  -- 7. Criar Leitura de Reprovação (rejected_scan)
  INSERT INTO public.production_stage_readings (
    tag_value, step_name, cell_name, machine_id, operator_id, operator,
    status, notes, lot_id, production_order_id, piece_id, piece_code, client_event_id, created_at
  )
  VALUES (
    COALESCE(v_traceability_code, v_piece.piece_uid),
    COALESCE(v_piece.current_stage, 'Coleta'),
    COALESCE(v_cell_name, 'Geral'),
    v_machine_id, v_operator_id, v_operator_name,
    'rejected', CONCAT(v_reason, ' - ', v_notes),
    v_piece.lot_id, v_piece.production_order_id, v_piece_id, v_piece.piece_code, v_client_event_id::text, now()
  ) RETURNING id INTO v_reading_id;

  -- 8. Criar Ocorrência de Qualidade
  INSERT INTO public.occurrences (
    date, shift, cell, reason, downtime, operator, notes, created_by,
    lot_id, production_order_id, severity, status, stage_reading_id
  )
  VALUES (
    CURRENT_DATE, v_shift, COALESCE(v_cell_name, 'Geral'), v_reason, 0,
    v_operator_name, v_notes, v_user_id, v_piece.lot_id, v_piece.production_order_id,
    v_severity, 'open', v_reading_id
  ) RETURNING id INTO v_occurrence_id;

  -- 9. Criar Não Conformidade (quality_nonconformity)
  v_nc_code := 'NC-' || to_char(now(), 'YYYY') || '-' || lpad(floor(random()*89999+10000)::text, 5, '0');
  INSERT INTO public.quality_nonconformities (
    nc_code, piece_id, reading_id, occurrence_id, defect_id, defect_code, defect_name,
    six_m_category, quantity, severity, disposition, status, lot_id, lot_code,
    production_order_id, order_number, customer_name, environment_name, cell_id, cell_name,
    stage_name, machine_id, operator_id, operator_name, notes, client_event_id, created_by
  )
  VALUES (
    v_nc_code, v_piece_id, v_reading_id, v_occurrence_id, v_defect_id_uuid, v_defect_code, v_defect_name,
    v_six_m_category, 1, v_severity, v_disposition, 'open', v_piece.lot_id, v_piece.lot_code,
    v_piece.production_order_id, v_piece.order_number, v_piece.customer_name, v_piece.environment_name,
    v_cell_id, v_cell_name, COALESCE(v_piece.current_stage, 'Coleta'), v_machine_id, v_operator_id,
    v_operator_name, v_notes, v_client_event_id, v_user_id
  ) RETURNING id INTO v_nc_id;

  -- 10. Criar Ordem de Reposição (se v_requires_replacement = true)
  IF v_requires_replacement AND v_piece_id IS NOT NULL THEN
    SELECT id INTO v_existing_repl_id 
    FROM public.replacement_orders 
    WHERE original_piece_id = v_piece_id AND status NOT IN ('completed', 'cancelled')
    LIMIT 1;

    IF v_existing_repl_id IS NULL THEN
      INSERT INTO public.replacement_orders (
        replacement_code, original_piece_id, reason, priority, lot_id, production_order_id,
        status, created_by, defect_id, defect_name, origin_cell_id, origin_cell_name,
        rejection_stage, lot_code, order_number, customer_name, environment_name, requester_id, notes
      )
      VALUES (
        'REP-' || to_char(now(), 'YYYYMMDD') || '-' || lpad(floor(random()*8999+1000)::text, 4, '0'),
        v_piece_id, v_reason,
        CASE WHEN v_severity = 'critical' THEN 'critical' WHEN v_severity = 'high' THEN 'high' ELSE 'normal' END,
        v_piece.lot_id, v_piece.production_order_id, 'requested', v_user_id, v_defect_id_uuid, v_defect_name,
        v_cell_id, v_cell_name, COALESCE(v_piece.current_stage, 'Coleta'), v_piece.lot_code,
        v_piece.order_number, v_piece.customer_name, v_piece.environment_name, v_user_id, v_notes
      ) RETURNING id INTO v_replacement_order_id;
    ELSE
      v_replacement_order_id := v_existing_repl_id;
    END IF;

    UPDATE public.quality_nonconformities SET related_replacement_id = v_replacement_order_id WHERE id = v_nc_id;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'nonconformity_id', v_nc_id,
    'nc_code', v_nc_code,
    'occurrence_id', v_occurrence_id,
    'reading_id', v_reading_id,
    'reversed_reading_id', v_reversed_reading_id,
    'replacement_order_id', v_replacement_order_id,
    'piece_id', v_piece_id
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.register_quality_rejection(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
declare
  v_piece_id uuid;
  v_piece_stage text;
  v_lot_id uuid;
  v_requested_cell text := nullif(btrim(p_payload->>'cell_name'), '');
  v_authoritative_cell text;
  v_cell_id uuid;
  v_sanitized_payload jsonb := coalesce(p_payload, '{}'::jsonb);
begin
  if coalesce(auth.role(), '') <> 'service_role' and not public.can_manage_quality() then
    raise exception 'QUALITY_PERMISSION_REQUIRED' using errcode = '42501';
  end if;

  if coalesce(p_payload->>'piece_id', '') ~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    v_piece_id := (p_payload->>'piece_id')::uuid;
  end if;

  select piece.id, piece.current_stage, piece.lot_id
    into v_piece_id, v_piece_stage, v_lot_id
  from public.production_pieces piece
  where (v_piece_id is not null and piece.id = v_piece_id)
     or (
       v_piece_id is null
       and nullif(btrim(p_payload->>'traceability_code'), '') is not null
       and (
         piece.piece_uid = p_payload->>'traceability_code'
         or piece.traceability_code = p_payload->>'traceability_code'
         or piece.piece_code = p_payload->>'traceability_code'
         or piece.id::text = p_payload->>'traceability_code'
       )
     )
  order by case when v_piece_id is not null and piece.id = v_piece_id then 0 else 1 end
  limit 1;

  if v_piece_id is null then
    raise exception 'QUALITY_PIECE_NOT_FOUND' using errcode = 'P0002';
  end if;

  select cell.id, cell.name
    into v_cell_id, v_authoritative_cell
  from public.production_stage_readings reading
  join public.cells cell
    on coalesce(cell.active, true)
   and public.normalize_production_name(cell.name) =
       public.normalize_production_name(reading.cell_name)
  where reading.piece_id = v_piece_id
    and nullif(btrim(reading.cell_name), '') is not null
  order by reading.created_at desc, reading.id desc
  limit 1;

  if v_authoritative_cell is null and v_lot_id is not null then
    select nullif(btrim(lot.current_cell), '')
      into v_authoritative_cell
    from public.production_lots lot
    where lot.id = v_lot_id;
  end if;

  if v_authoritative_cell is null and nullif(btrim(v_piece_stage), '') is not null then
    select cell.name, cell.id
      into v_authoritative_cell, v_cell_id
    from public.routing_steps step
    join public.cells cell on cell.id = step.cell_id
    where coalesce(step.active, true)
      and coalesce(cell.active, true)
      and (
        step.code = v_piece_stage
        or public.normalize_production_name(step.name) = public.normalize_production_name(v_piece_stage)
      )
    order by step.sequence nulls last, step.id
    limit 1;
  end if;

  if v_authoritative_cell is not null then
    select cell.id, cell.name
      into v_cell_id, v_authoritative_cell
    from public.cells cell
    where coalesce(cell.active, true)
      and public.normalize_production_name(cell.name) =
          public.normalize_production_name(v_authoritative_cell)
    order by cell.created_at, cell.id
    limit 1;
  end if;

  if v_authoritative_cell is null then
    raise exception 'QUALITY_CELL_UNRESOLVED' using errcode = '42501';
  end if;

  if v_requested_cell is not null
     and public.normalize_production_name(v_requested_cell) <>
         public.normalize_production_name(v_authoritative_cell) then
    raise exception 'QUALITY_CELL_MISMATCH' using errcode = '42501';
  end if;

  if coalesce(auth.role(), '') <> 'service_role'
     and not public.profile_can_access_cell(v_authoritative_cell) then
    raise exception 'QUALITY_OUTSIDE_CELL_SCOPE' using errcode = '42501';
  end if;

  v_sanitized_payload := jsonb_set(
    v_sanitized_payload,
    '{cell_name}',
    to_jsonb(v_authoritative_cell),
    true
  );
  if v_cell_id is not null then
    v_sanitized_payload := jsonb_set(
      v_sanitized_payload,
      '{cell_id}',
      to_jsonb(v_cell_id::text),
      true
    );
  else
    v_sanitized_payload := v_sanitized_payload - 'cell_id';
  end if;

  return public.register_quality_rejection_impl(v_sanitized_payload);
end;
$function$

CREATE OR REPLACE FUNCTION public.register_reading_occurrence(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_cell text := coalesce(nullif(p_payload->>'cell_name', ''), nullif(p_payload->>'cellName', ''));
  v_reading_id uuid;
begin
  if v_cell is null and nullif(p_payload->>'stage_reading_id', '') is not null then
    v_reading_id := (p_payload->>'stage_reading_id')::uuid;
    select cell_name into v_cell
    from public.production_stage_readings
    where id = v_reading_id;
  end if;

  if auth.role() <> 'service_role'
     and not (
       public.has_permission('manage_occurrences')
       or public.has_permission('register_production')
     ) then
    raise exception 'OCCURRENCE_MANAGE_PERMISSION_REQUIRED' using errcode = '42501';
  end if;

  if auth.role() <> 'service_role'
     and (v_cell is null or not public.profile_can_access_cell(v_cell)) then
    raise exception 'OCCURRENCE_OUTSIDE_CELL_SCOPE' using errcode = '42501';
  end if;

  return public.register_reading_occurrence_impl(p_payload);
end;
$function$

CREATE OR REPLACE FUNCTION public.register_replacement_label_print(p_replacement_request_id uuid, p_reprint_reason text DEFAULT NULL::text, p_reprint_reason_details text DEFAULT NULL::text, p_printer_name text DEFAULT 'Impressora Padrao'::text, p_user_name text DEFAULT 'Operador MES'::text, p_client_event_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_user_name text;
  v_order public.replacement_orders%rowtype;
  v_orig_piece public.production_pieces%rowtype;
  v_repl_piece public.production_pieces%rowtype;
  v_label public.replacement_labels%rowtype;
  v_existing_print public.replacement_label_prints%rowtype;
  v_trace_code text;
  v_orig_code text;
  v_print_count integer;
  v_is_reprint boolean;
  v_print_id uuid;
  v_template_id uuid;
begin
  if v_user_id is null then
    raise exception 'Sessao expirada. Entre novamente para imprimir a etiqueta.'
      using errcode = '42501';
  end if;

  select profile.name
    into v_user_name
  from public.profiles profile
  where profile.id = v_user_id
    and coalesce(profile.active, true)
  limit 1;

  if v_user_name is null then
    raise exception 'Usuario inativo ou sem perfil para registrar a impressao.'
      using errcode = '42501';
  end if;

  if p_client_event_id is not null then
    select *
      into v_existing_print
    from public.replacement_label_prints
    where client_event_id = p_client_event_id;

    if found then
      select * into v_label
      from public.replacement_labels
      where id = v_existing_print.label_id;

      return jsonb_build_object(
        'success', true,
        'idempotent', true,
        'print_id', v_existing_print.id,
        'label_id', v_existing_print.label_id,
        'copy_number', v_existing_print.copy_number,
        'is_reprint', v_existing_print.is_reprint,
        'via_label', case
          when v_existing_print.copy_number = 1 then '1a VIA'
          else v_existing_print.copy_number || 'a VIA'
        end,
        'replacement_trace_code', v_label.replacement_trace_code
      );
    end if;
  end if;

  select * into v_order
  from public.replacement_orders
  where id = p_replacement_request_id;

  if not found then
    return jsonb_build_object('success', false, 'error', 'Ordem de reposicao nao encontrada.');
  end if;

  if v_order.status = 'cancelled' then
    return jsonb_build_object('success', false, 'error', 'Etiqueta bloqueada. A ordem de reposicao foi cancelada.');
  end if;

  select * into v_orig_piece
  from public.production_pieces
  where id = v_order.original_piece_id;

  if v_order.replacement_piece_id is not null then
    select * into v_repl_piece
    from public.production_pieces
    where id = v_order.replacement_piece_id;
  end if;

  v_orig_code := coalesce(
    nullif(trim(v_orig_piece.piece_code), ''),
    nullif(trim(v_orig_piece.traceability_code), ''),
    nullif(trim(v_orig_piece.piece_uid), ''),
    '00000000'
  );

  v_trace_code := coalesce(
    nullif(trim(v_repl_piece.traceability_code), ''),
    nullif(trim(v_repl_piece.piece_uid), ''),
    v_orig_code || '-REP-R01'
  );

  select id into v_template_id
  from public.label_templates
  where is_default and is_active
  order by created_at
  limit 1;

  insert into public.replacement_labels (
    replacement_request_id,
    replacement_piece_id,
    original_piece_id,
    promob_original_code,
    replacement_trace_code,
    template_id,
    print_status,
    current_copy_number
  ) values (
    p_replacement_request_id,
    v_order.replacement_piece_id,
    v_order.original_piece_id,
    v_orig_code,
    v_trace_code,
    v_template_id,
    'pending',
    0
  )
  on conflict (replacement_request_id) do update
  set replacement_piece_id = excluded.replacement_piece_id,
      original_piece_id = excluded.original_piece_id,
      promob_original_code = excluded.promob_original_code,
      replacement_trace_code = excluded.replacement_trace_code,
      template_id = coalesce(public.replacement_labels.template_id, excluded.template_id),
      updated_at = now();

  select * into v_label
  from public.replacement_labels
  where replacement_request_id = p_replacement_request_id
  for update;

  v_print_count := coalesce(v_label.current_copy_number, 0) + 1;
  v_is_reprint := v_print_count > 1;

  if v_is_reprint and nullif(trim(p_reprint_reason), '') is null then
    return jsonb_build_object(
      'success', false,
      'error', 'Toda reimpressao (2a via em diante) exige motivo obrigatorio.'
    );
  end if;

  update public.replacement_labels
  set current_copy_number = v_print_count,
      print_status = 'printed',
      last_printed_at = now(),
      updated_at = now()
  where id = v_label.id;

  insert into public.replacement_label_prints (
    label_id,
    replacement_request_id,
    replacement_piece_id,
    print_sequence,
    copy_number,
    is_reprint,
    reprint_reason,
    reprint_reason_details,
    printer_name,
    printed_by,
    printed_by_name,
    printed_at,
    client_event_id
  ) values (
    v_label.id,
    p_replacement_request_id,
    v_order.replacement_piece_id,
    v_print_count,
    v_print_count,
    v_is_reprint,
    nullif(trim(p_reprint_reason), ''),
    nullif(trim(p_reprint_reason_details), ''),
    coalesce(nullif(trim(p_printer_name), ''), 'Impressora Padrao'),
    v_user_id,
    coalesce(v_user_name, nullif(trim(p_user_name), ''), 'Operador MES'),
    now(),
    p_client_event_id
  )
  returning id into v_print_id;

  return jsonb_build_object(
    'success', true,
    'print_id', v_print_id,
    'label_id', v_label.id,
    'copy_number', v_print_count,
    'is_reprint', v_is_reprint,
    'via_label', case when v_print_count = 1 then '1a VIA' else v_print_count || 'a VIA' end,
    'replacement_trace_code', v_trace_code
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.register_traceability_rejection(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_item public.production_lot_items%ROWTYPE;
  v_tag public.production_tags%ROWTYPE;
  v_lot public.production_lots%ROWTYPE;
  v_occurrence public.occurrences%ROWTYPE;
  v_reading public.production_stage_readings%ROWTYPE;
  v_prior_reading public.production_stage_readings%ROWTYPE;
  v_quantity integer := GREATEST(COALESCE(NULLIF(p_payload->>'quantity','')::integer, 1), 1);
  v_date date := COALESCE(NULLIF(p_payload->>'date','')::date, current_date);
  v_hour text := COALESCE(NULLIF(p_payload->>'hour',''), to_char(now(), 'HH24:MI'));
  v_shift text := COALESCE(NULLIF(p_payload->>'shift',''), 'Não informado');
  v_cell text := NULLIF(TRIM(COALESCE(p_payload->>'cellName', '')), '');
  v_operator text := NULLIF(TRIM(COALESCE(p_payload->>'operator', '')), '');
  v_operator_id uuid := NULLIF(p_payload->>'operatorId', '')::uuid;
  v_step text := NULLIF(TRIM(COALESCE(p_payload->>'stepName', '')), '');
  v_reason text := COALESCE(NULLIF(p_payload->>'reason',''), 'Reprovação registrada na coleta produtiva');
  v_defect_type text := NULLIF(p_payload->>'defectType', '');
  v_notes text := NULLIF(p_payload->>'notes', '');
  v_tag_value text := UPPER(TRIM(COALESCE(p_payload->>'tagValue', p_payload->>'rawValue', '')));
  v_reader_type text := COALESCE(NULLIF(p_payload->>'readerType', ''), 'manual');
  v_station text := NULLIF(TRIM(COALESCE(p_payload->>'stationName', '')), '');
  v_machine_id uuid := NULLIF(p_payload->>'machineId', '')::uuid;
  v_machine_name text := NULLIF(TRIM(p_payload->>'machineName'), '');
  v_release_for_rework boolean := COALESCE(NULLIF(p_payload->>'releaseForRework','')::boolean, true);
  v_message text;
BEGIN
  IF auth.uid() IS NULL OR get_my_role() NOT IN ('admin','manager','operator') THEN
    RETURN jsonb_build_object('success', false, 'status', 'forbidden', 'message', 'Usuário sem permissão para reprovar peças.');
  END IF;

  SELECT * INTO v_item
  FROM public.production_lot_items
  WHERE id = NULLIF(p_payload->>'itemId','')::uuid
  FOR UPDATE;

  IF v_item.id IS NULL THEN
    -- Fallback: busca pelo código da peça
    SELECT i.* INTO v_item
    FROM public.production_lot_items i
    JOIN public.production_pieces p ON p.legacy_production_lot_item_id = i.id
    WHERE p.piece_uid = v_tag_value OR p.traceability_code = v_tag_value
    LIMIT 1;
  END IF;

  IF v_item.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'status', 'not_found', 'message', 'Peça não localizada para reprovar.');
  END IF;

  SELECT * INTO v_lot
  FROM public.production_lots
  WHERE id = COALESCE(NULLIF(p_payload->>'lotId','')::uuid, v_item.lot_id)
  FOR UPDATE;

  IF v_lot.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'status', 'not_found', 'message', 'Lote não localizado para reprovar.');
  END IF;

  IF NULLIF(p_payload->>'tagId','') IS NOT NULL THEN
    SELECT * INTO v_tag FROM public.production_tags WHERE id = NULLIF(p_payload->>'tagId','')::uuid;
  END IF;

  IF v_tag.id IS NULL AND v_tag_value <> '' THEN
    SELECT * INTO v_tag FROM public.production_tags WHERE tag_value = v_tag_value AND active = true LIMIT 1;
  END IF;

  v_tag_value := COALESCE(NULLIF(v_tag.tag_value, ''), NULLIF(v_tag_value, ''), v_item.item_code);
  v_cell := COALESCE(v_cell, v_item.current_cell, 'Não informada');
  v_step := COALESCE(v_step, v_item.current_step);

  SELECT * INTO v_prior_reading
  FROM public.production_stage_readings
  WHERE item_id = v_item.id
    AND step_name IS NOT DISTINCT FROM v_step
    AND status = 'approved'
  ORDER BY created_at DESC
  LIMIT 1
  FOR UPDATE;

  INSERT INTO public.occurrences (
    date, shift, cell, reason, downtime, operator, notes, created_by,
    lot_id, lot_item_id, production_order_id, stage_reading_id, tag_value, lot_code,
    severity, status, load_number, order_number, customer_name, environment_name,
    piece_code, operation_name
  ) VALUES (
    v_date, v_shift, v_cell, v_reason, 0, v_operator,
    concat_ws(' | ', v_defect_type, v_notes, 'Tag: ' || v_tag_value, CASE WHEN v_release_for_rework THEN 'Liberada para retrabalho' ELSE 'Bloqueada' END),
    auth.uid(), v_lot.id, v_item.source_lot_item_id,
    COALESCE(v_lot.production_order_id, v_lot.order_id),
    NULL, v_tag_value, v_lot.lot_code, 'high', 'open',
    v_item.load_number, v_item.order_number, v_item.customer_name, v_item.environment_name,
    v_item.item_code, v_step
  ) RETURNING * INTO v_occurrence;

  INSERT INTO public.production_stage_readings (
    lot_id, item_id, tag_id, tag_value, reader_type, station_name, step_name, cell_name,
    operator, user_id, shift, date, hour, status, event_type, quantity, occurrence_id, notes,
    lot_code, load_number, order_number, customer_name, environment_name, operation_name, piece_code,
    production_order_id, machine_id, machine_name, rework_reason
  ) VALUES (
    v_lot.id, v_item.id, v_tag.id, v_tag_value, v_reader_type, v_station, v_step, v_cell,
    v_operator, auth.uid(), v_shift, v_date, v_hour, 'rejected', 'rejected_scan', v_quantity, v_occurrence.id,
    concat_ws(' | ', v_defect_type, v_notes),
    v_lot.lot_code, v_item.load_number, v_item.order_number, v_item.customer_name, v_item.environment_name, v_step, v_item.item_code,
    COALESCE(v_lot.production_order_id, v_lot.order_id), v_machine_id, v_machine_name, v_reason
  ) RETURNING * INTO v_reading;

  UPDATE public.occurrences
  SET stage_reading_id = v_reading.id
  WHERE id = v_occurrence.id
  RETURNING * INTO v_occurrence;

  -- Estorna a leitura anterior para possibilitar nova entrada (recoleta/reposição)
  IF v_prior_reading.id IS NOT NULL THEN
    UPDATE public.production_stage_readings
    SET status = 'pending_review',
        notes = concat_ws(E'\n', NULLIF(notes, ''), 'Estornada por reprovação: ' || v_reason),
        rework_reason = v_reason
    WHERE id = v_prior_reading.id;

    IF v_release_for_rework THEN
      UPDATE public.production_entries
      SET approval_status = 'reversed',
          correction_reason = concat_ws(' | ', 'Estorno automático por retrabalho', v_reason),
          corrected_by = COALESCE(v_operator, auth.uid()::text),
          corrected_at = now(),
          updated_at = now()
      WHERE (v_prior_reading.production_entry_id IS NOT NULL AND id = v_prior_reading.production_entry_id)
         OR (
           v_prior_reading.production_entry_id IS NULL
           AND v_prior_reading.client_event_id IS NOT NULL
           AND client_event_id = v_prior_reading.client_event_id
         );
    END IF;
  END IF;

  IF v_release_for_rework THEN
    UPDATE public.production_lot_items
    SET status = 'rework',
        current_step = COALESCE(v_step, current_step),
        current_cell = COALESCE(v_cell, current_cell),
        rework_count = COALESCE(rework_count, 0) + v_quantity,
        last_rejection_reading_id = v_reading.id,
        last_rejection_reason = v_reason,
        updated_at = now()
    WHERE id = v_item.id
    RETURNING * INTO v_item;

    UPDATE public.production_lots
    SET scrap_count = COALESCE(scrap_count, 0) + v_quantity,
        rework_count = COALESCE(rework_count, 0) + v_quantity,
        rejected_quantity = COALESCE(rejected_quantity, 0) + v_quantity,
        current_status = CASE WHEN current_status IN ('completed','shipped') THEN current_status ELSE 'in_progress' END,
        status = CASE WHEN status = 'shipped' THEN status ELSE 'in_progress' END,
        updated_at = now()
    WHERE id = v_lot.id
    RETURNING * INTO v_lot;

    v_message := 'Peça reprovada, liberada para retrabalho e pronta para recoleta.';
  ELSE
    UPDATE public.production_lot_items
    SET status = 'blocked',
        last_rejection_reading_id = v_reading.id,
        last_rejection_reason = v_reason,
        updated_at = now()
    WHERE id = v_item.id
    RETURNING * INTO v_item;

    UPDATE public.production_lots
    SET scrap_count = COALESCE(scrap_count, 0) + v_quantity,
        rejected_quantity = COALESCE(rejected_quantity, 0) + v_quantity,
        current_status = 'blocked',
        updated_at = now()
    WHERE id = v_lot.id
    RETURNING * INTO v_lot;

    v_message := 'Peça reprovada, bloqueada e ocorrência vinculada.';
  END IF;

  -- ─── NOVO: Atualizar status e completed_steps na tabela production_pieces ───
  UPDATE public.production_pieces
  SET status = 'rejected',
      completed_steps = array_remove(completed_steps, v_step),
      updated_at = now()
  WHERE piece_uid = v_tag_value OR legacy_production_lot_item_id = v_item.id;

  INSERT INTO public.production_entries (
    date, shift, cell, hour, produced, target, scrap, downtime, operator, notes, created_by,
    operator_id, order_id, production_order_id, lot_id, lot_code, load_number, order_number,
    customer_name, customer_legal_name, environment_name, operation_name, machine_id, machine_name,
    rework_reason
  ) VALUES (
    v_date, v_shift, v_cell, v_hour, 0, 0, v_quantity, 0, v_operator,
    CASE WHEN v_release_for_rework THEN 'Reprovação liberada para retrabalho - tag ' || v_tag_value ELSE 'Reprovação vinculada a tag ' || v_tag_value END,
    auth.uid(), v_operator_id, COALESCE(v_lot.production_order_id, v_lot.order_id), COALESCE(v_lot.production_order_id, v_lot.order_id),
    v_lot.id, v_lot.lot_code, v_item.load_number, v_item.order_number,
    v_item.customer_name, v_item.customer_name, v_item.environment_name, v_step, v_machine_id, v_machine_name,
    CASE WHEN v_release_for_rework THEN v_reason ELSE NULL END
  );

  INSERT INTO public.traceability_logs (user_id, action, entity, entity_id, details)
  VALUES (
    auth.uid(), 'rejected_scan', 'production_lot_item', v_item.id,
    jsonb_build_object(
      'reading_id', v_reading.id,
      'occurrence_id', v_occurrence.id,
      'reason', v_reason,
      'release_for_rework', v_release_for_rework,
      'previous_approved_reading_id', CASE WHEN v_prior_reading.id IS NULL THEN NULL ELSE v_prior_reading.id END
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'status', CASE WHEN v_release_for_rework THEN 'rework' ELSE 'rejected' END,
    'message', v_message,
    'lot', to_jsonb(v_lot),
    'item', to_jsonb(v_item),
    'reading', to_jsonb(v_reading),
    'occurrence', to_jsonb(v_occurrence)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.register_untraceable_stage_quantity_impl(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_role text := public.get_my_role();
  v_general_lot_code text := upper(trim(coalesce(p_payload->>'general_lot_code', '')));
  v_requested_cell text := trim(coalesce(p_payload->>'cell_name', ''));
  v_requested_batch_id uuid;
  v_stage_code text;
  v_cell_id uuid;
  v_cell_name text;
  v_shift text := coalesce(nullif(trim(p_payload->>'shift'), ''), '1º Turno');
  v_operator text := coalesce(nullif(trim(p_payload->>'operator'), ''), 'Operador Manual');
  v_quantity integer;
  v_unit text := 'pieces';
  v_notes text := nullif(trim(coalesce(p_payload->>'notes', '')), '');
  v_production_date date := coalesce(nullif(p_payload->>'date', '')::date, current_date);
  v_client_event_id text := coalesce(
    nullif(trim(p_payload->>'client_event_id'), ''),
    'manual-untraceable-' || extensions.gen_random_uuid()::text
  );
  v_batch_id uuid;
  v_batch_status text;
  v_lot_id uuid;
  v_entry_id uuid;
  v_record_id uuid;
  v_created_at timestamptz := now();
  v_progress jsonb;
  v_stage_progress jsonb;
  v_required integer;
  v_traceable integer;
  v_manual integer;
  v_remaining integer;
  v_effective_goal numeric := 0;
  v_metric_name text;
  v_batch_completed boolean := false;
  v_total_operations integer := 0;
  v_completed_operations integer := 0;
  v_closed_lot_count integer := 0;
  v_completed_parts integer := 0;
begin
  if v_user_id is null
     or not (
       v_role in ('admin', 'manager', 'supervisor')
       or public.has_permission('register_manual_production')
     )
  then
    raise exception 'Você não possui permissão para registrar baixa manual de produção.';
  end if;

  if v_general_lot_code = '' then
    raise exception 'Selecione um Lote Geral ativo.';
  end if;

  begin
    v_requested_batch_id := nullif(p_payload->>'pcp_import_batch_id', '')::uuid;
  exception when others then
    raise exception 'O identificador do Lote Geral ativo é inválido.';
  end;

  if v_requested_batch_id is null then
    raise exception 'Selecione um Lote Geral ativo na lista.';
  end if;

  begin
    v_quantity := (p_payload->>'quantity')::integer;
  exception when others then
    v_quantity := null;
  end;

  if v_quantity is null or v_quantity <= 0 then
    raise exception 'A quantidade produzida deve ser um número inteiro maior que zero.';
  end if;

  select record.id, record.production_entry_id
    into v_record_id, v_entry_id
  from public.manual_production_records record
  where record.client_event_id = v_client_event_id;

  if v_record_id is not null then
    return jsonb_build_object(
      'success', true,
      'duplicated', true,
      'record_id', v_record_id,
      'production_entry_id', v_entry_id,
      'general_lot_code', v_general_lot_code,
      'quantity', v_quantity,
      'traceability_type', 'aggregate_untraceable'
    );
  end if;

  select batch.id, batch.status
    into v_batch_id, v_batch_status
  from public.promob_import_batches batch
  where batch.id = v_requested_batch_id
    and upper(trim(coalesce(batch.general_lot_code, ''))) = v_general_lot_code
    and batch.status not in ('cancelled', 'error', 'duplicated', 'failed_validation')
  for update;

  if v_batch_id is null then
    raise exception 'O Lote Geral selecionado não está mais ativo. Atualize a lista e tente novamente.';
  end if;

  v_stage_code := public.resolve_production_stage_for_cell(null, v_requested_cell);
  if v_stage_code is null then
    raise exception 'A célula selecionada não está vinculada a uma etapa produtiva.';
  end if;

  if not coalesce((
    select policy.manual_quantity_allowed
    from public.production_stage_policies policy
    where policy.stage_code = v_stage_code
  ), false) then
    raise exception 'A baixa por volume está desativada para esta etapa. Use a coleta individual por código de barras.';
  end if;

  select cell.id, cell.name
    into v_cell_id, v_cell_name
  from public.cells cell
  where coalesce(cell.active, true)
    and public.resolve_production_stage_for_cell(cell.id, cell.name) = v_stage_code
  order by
    case when public.normalize_production_name(cell.name) = public.normalize_production_name(v_requested_cell) then 0 else 1 end,
    cell.created_at
  limit 1;

  if v_cell_id is null then
    raise exception 'Nenhuma célula ativa está vinculada à etapa solicitada.';
  end if;

  v_progress := public.get_lot_route_stage_progress(v_batch_id);
  select stage.value
    into v_stage_progress
  from jsonb_array_elements(coalesce(v_progress->'batch_stages', '[]'::jsonb)) stage(value)
  where stage.value->>'stage_code' = v_stage_code
  limit 1;

  if v_stage_progress is null then
    raise exception 'A etapa selecionada não faz parte da rota deste Lote Geral.';
  end if;

  v_required := coalesce((v_stage_progress->>'required_pieces')::integer, 0);
  v_traceable := coalesce((v_stage_progress->>'traceable_completed_pieces')::integer, 0);
  v_manual := coalesce((v_stage_progress->>'manual_quantity')::integer, 0);
  v_remaining := greatest(v_required - v_traceable - v_manual, 0);

  if v_required <= 0 then
    raise exception 'Este Lote Geral não possui peças previstas para a etapa %.', v_cell_name;
  end if;

  if v_remaining <= 0 then
    raise exception 'A etapa % já está concluída para este Lote Geral.', v_cell_name;
  end if;

  if v_quantity > v_remaining then
    raise exception 'Quantidade acima do saldo da etapa. Saldo disponível: % peça(s).', v_remaining;
  end if;

  select lot.id
    into v_lot_id
  from public.production_lots lot
  where lot.pcp_import_batch_id = v_batch_id
  order by lot.created_at, lot.id
  limit 1;

  select coalesce(goal.target, goal.capacity, 0)
    into v_effective_goal
  from public.production_daily_goals goal
  where goal.date <= v_production_date
    and goal.shift = v_shift
    and public.normalize_production_name(goal.cell_name) = public.normalize_production_name(v_cell_name)
    and goal.metric_unit = v_unit
  order by goal.date desc, goal.updated_at desc
  limit 1;

  v_metric_name := case v_stage_code
    when 'separation' then 'Peças separadas'
    when 'packaging' then 'Peças embaladas'
    else 'Peças produzidas'
  end;

  insert into public.production_entries (
    date,
    shift,
    cell,
    hour,
    produced,
    target,
    scrap,
    downtime,
    operator,
    notes,
    created_by,
    created_at,
    lot_id,
    step_code,
    order_number,
    lot_code,
    process_step,
    entry_mode,
    source,
    approval_status,
    traceability_status,
    client_event_id,
    metric_unit,
    metric_unit_label,
    metric_name,
    planned_target,
    realized_quantity,
    pieces_quantity,
    pcp_import_batch_id,
    is_manual,
    unit_of_measure
  )
  values (
    v_production_date,
    v_shift,
    v_cell_name,
    to_char(v_created_at at time zone 'America/Sao_Paulo', 'HH24:MI'),
    v_quantity,
    round(v_effective_goal)::integer,
    0,
    0,
    v_operator,
    coalesce(v_notes, 'Baixa por volume sem rastreabilidade individual'),
    v_user_id,
    v_created_at,
    v_lot_id,
    v_stage_code,
    v_general_lot_code,
    v_general_lot_code,
    v_stage_code,
    'manual_volume',
    'manual_untraceable_stage',
    'valid',
    'limited',
    v_client_event_id,
    v_unit,
    'peças',
    v_metric_name,
    v_effective_goal,
    v_quantity,
    v_quantity,
    v_batch_id,
    true,
    'pecas'
  )
  returning id into v_entry_id;

  insert into public.manual_production_records (
    type,
    general_lot_code,
    cell_name,
    shift,
    operator,
    quantity,
    unit_of_measure,
    cascade_all_cells,
    notes,
    status,
    created_at,
    production_date,
    stage_code,
    traceability_type,
    created_by,
    client_event_id,
    pcp_import_batch_id,
    production_entry_id,
    metadata
  )
  values (
    'baixa_por_volume',
    v_general_lot_code,
    v_cell_name,
    v_shift,
    v_operator,
    v_quantity,
    'pecas',
    false,
    v_notes,
    'approved',
    v_created_at,
    v_production_date,
    v_stage_code,
    'aggregate_untraceable',
    v_user_id,
    v_client_event_id,
    v_batch_id,
    v_entry_id,
    jsonb_build_object(
      'individual_pieces_changed', false,
      'collection_event_created', false,
      'physical_traceability', false,
      'remaining_before', v_remaining,
      'remaining_after', v_remaining - v_quantity
    )
  )
  returning id into v_record_id;

  v_progress := public.get_lot_route_stage_progress(v_batch_id);
  v_batch_completed := coalesce((v_progress->>'batch_completed')::boolean, false);

  with lot_progress as (
    select
      lot.id,
      not exists (
        select 1
        from jsonb_array_elements(
          coalesce(v_progress->'lot_stages'->(lot.id::text), '[]'::jsonb)
        ) stage(value)
        where coalesce((stage.value->>'required_pieces')::integer, 0) > 0
          and coalesce((stage.value->>'remaining_pieces')::integer, 0) > 0
      ) as is_complete
    from public.production_lots lot
    where lot.pcp_import_batch_id = v_batch_id
  )
  update public.production_lots lot
  set status = 'closed',
      current_status = 'completed',
      current_stage = 'completed',
      current_step = 'completed',
      current_cell = v_cell_name,
      progress_percent = 100,
      produced_quantity = coalesce(nullif(lot.planned_quantity, 0), lot.produced_quantity),
      approved_quantity = coalesce(nullif(lot.planned_quantity, 0), lot.approved_quantity),
      pending_quantity = 0,
      actual_end = coalesce(lot.actual_end, v_created_at),
      closed_at = coalesce(lot.closed_at, v_created_at),
      updated_at = v_created_at
  from lot_progress progress
  where lot.id = progress.id
    and progress.is_complete
    and lot.status not in ('closed', 'shipped', 'cancelled');

  select
    coalesce(sum((stage.value->>'required_pieces')::integer), 0),
    coalesce(sum((stage.value->>'effective_completed_pieces')::integer), 0)
    into v_total_operations, v_completed_operations
  from jsonb_array_elements(coalesce(v_progress->'batch_stages', '[]'::jsonb)) stage(value);

  select
    count(*) filter (where lot.status in ('closed', 'shipped')),
    coalesce(sum(
      case when lot.status in ('closed', 'shipped')
        then coalesce(nullif(lot.planned_quantity, 0), 0)
        else 0
      end
    ), 0)::integer
    into v_closed_lot_count, v_completed_parts
  from public.production_lots lot
  where lot.pcp_import_batch_id = v_batch_id;

  update public.promob_import_batches batch
  set completed_operations = v_completed_operations,
      total_operations = greatest(coalesce(batch.total_operations, 0), v_total_operations),
      progress_percent = case when v_total_operations > 0
        then round((100.0 * v_completed_operations / v_total_operations)::numeric, 2)
        else coalesce(batch.progress_percent, 0)
      end,
      completed_parts = case when v_batch_completed
        then coalesce(batch.total_parts, v_completed_parts)
        else greatest(coalesce(batch.completed_parts, 0), least(v_completed_parts, coalesce(batch.total_parts, v_completed_parts)))
      end,
      pending_parts = case when v_batch_completed
        then 0
        else greatest(coalesce(batch.total_parts, 0) - greatest(coalesce(batch.completed_parts, 0), v_completed_parts), 0)
      end
  where batch.id = v_batch_id;

  perform pg_notify(
    'production_events',
    jsonb_build_object(
      'event', 'manual_volume_registered',
      'batch_id', v_batch_id,
      'general_lot_code', v_general_lot_code,
      'stage_code', v_stage_code,
      'cell_name', v_cell_name,
      'quantity', v_quantity
    )::text
  );

  return jsonb_build_object(
    'success', true,
    'duplicated', false,
    'record_id', v_record_id,
    'production_entry_id', v_entry_id,
    'batch_id', v_batch_id,
    'lot_id', v_lot_id,
    'general_lot_code', v_general_lot_code,
    'stage_code', v_stage_code,
    'cell_name', v_cell_name,
    'quantity', v_quantity,
    'unit_of_measure', 'pecas',
    'production_date', v_production_date,
    'traceability_type', 'aggregate_untraceable',
    'individual_pieces_changed', false,
    'remaining_before', v_remaining,
    'remaining_after', v_remaining - v_quantity,
    'stage_completed', v_remaining - v_quantity = 0,
    'batch_completed', v_batch_completed,
    'closed_lot_count', v_closed_lot_count,
    'progress', v_progress
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.register_untraceable_stage_quantity(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
declare
  v_requested_cell text := nullif(btrim(p_payload->>'cell_name'), '');
  v_stage_code text;
  v_cell_id uuid;
  v_cell_name text;
  v_role text := public.get_my_role();
  v_sanitized jsonb := coalesce(p_payload, '{}'::jsonb);
begin
  if coalesce(auth.role(), '') <> 'service_role' and (
    auth.uid() is null
    or not (
      v_role in ('admin', 'manager', 'supervisor')
      or public.has_permission('register_manual_production')
    )
  ) then
    raise exception 'MANUAL_PRODUCTION_PERMISSION_REQUIRED' using errcode = '42501';
  end if;

  if v_requested_cell is null then
    raise exception 'MANUAL_PRODUCTION_CELL_REQUIRED' using errcode = '22023';
  end if;

  v_stage_code := public.resolve_production_stage_for_cell(null, v_requested_cell);
  select cell.id, cell.name
    into v_cell_id, v_cell_name
  from public.cells cell
  where coalesce(cell.active, true)
    and public.resolve_production_stage_for_cell(cell.id, cell.name) = v_stage_code
  order by
    case when public.normalize_production_name(cell.name) =
                   public.normalize_production_name(v_requested_cell) then 0 else 1 end,
    cell.created_at,
    cell.id
  limit 1;

  if v_cell_id is null then
    raise exception 'MANUAL_PRODUCTION_CELL_NOT_FOUND' using errcode = 'P0002';
  end if;

  if coalesce(auth.role(), '') <> 'service_role' and not public.profile_can_access_cell(v_cell_name) then
    raise exception 'MANUAL_PRODUCTION_OUTSIDE_CELL_SCOPE' using errcode = '42501';
  end if;

  v_sanitized := jsonb_set(v_sanitized, '{cell_name}', to_jsonb(v_cell_name), true);
  return public.register_untraceable_stage_quantity_impl(v_sanitized);
end;
$function$

CREATE OR REPLACE FUNCTION public.release_collection_worker_lease_v3(p_worker_kind text, p_lease_owner text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private', 'pg_temp'
AS $function$
DECLARE
  v_rows integer;
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION 'SERVICE_ROLE_REQUIRED' USING ERRCODE = '42501';
  END IF;
  DELETE FROM private.collection_worker_leases_v3
  WHERE worker_kind = p_worker_kind
    AND lease_owner = left(btrim(coalesce(p_lease_owner, '')), 160);
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  RETURN v_rows = 1;
END;
$function$

CREATE OR REPLACE FUNCTION public.release_piece_replacement_impl(p_order_id uuid, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_order public.replacement_orders%rowtype;
begin
  select * into v_order
  from public.replacement_orders
  where id = p_order_id
  for update;

  if v_order.id is null then
    raise exception 'Ordem de reposição não encontrada.';
  end if;
  if v_order.replacement_piece_id is null then
    raise exception 'Aprovação incompleta: a peça substituta ainda não foi criada.';
  end if;
  if v_order.status not in ('approved', 'released', 'in_production') then
    raise exception 'Status atual inválido para liberação: %', v_order.status;
  end if;
  if v_order.status = 'in_production' then
    return jsonb_build_object(
      'success', true,
      'idempotent', true,
      'status', v_order.status,
      'replacement_piece_id', v_order.replacement_piece_id
    );
  end if;

  update public.replacement_orders
  set status = 'in_production',
      released_at = coalesce(released_at, now()),
      updated_at = now()
  where id = p_order_id;

  update public.production_pieces
  set status = case when status = 'completed' then status else 'in_progress' end,
      replacement_status = case when replacement_status = 'replaced' then replacement_status else 'in_production' end,
      updated_at = now()
  where id = v_order.replacement_piece_id;

  return jsonb_build_object(
    'success', true,
    'status', 'in_production',
    'replacement_piece_id', v_order.replacement_piece_id
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.release_piece_replacement(p_order_id uuid, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  v_origin_cell text;
BEGIN
  SELECT origin_cell_name
  INTO v_origin_cell
  FROM public.replacement_orders
  WHERE id = p_order_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Ordem de reposição não encontrada.';
  END IF;

  IF auth.role() <> 'service_role'
     AND NOT public.current_profile_can_decide_replacement() THEN
    RAISE EXCEPTION 'REPLACEMENT_MANAGE_ROLE_REQUIRED'
      USING ERRCODE = '42501';
  END IF;

  IF auth.role() <> 'service_role'
     AND v_origin_cell IS NOT NULL
     AND NOT public.profile_can_access_cell(v_origin_cell) THEN
    RAISE EXCEPTION 'REPLACEMENT_OUTSIDE_CELL_SCOPE'
      USING ERRCODE = '42501';
  END IF;

  RETURN public.release_piece_replacement_impl(
    p_order_id,
    coalesce(p_payload, '{}'::jsonb)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.replacement_operator_login_v2(p_login_name text, p_registration text, p_device_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
declare
  v_result jsonb;
  v_operator_id uuid;
  v_session_id uuid;
  v_enabled boolean;
begin
  v_result := public.operator_login_v2(p_login_name, p_registration, p_device_id);
  if coalesce((v_result ->> 'success')::boolean, false) is not true then
    return v_result;
  end if;

  v_operator_id := nullif(v_result #>> '{operator,id}', '')::uuid;
  v_session_id := nullif(v_result ->> 'session_id', '')::uuid;

  select operator_row.replacement_enabled
  into v_enabled
  from public.operators operator_row
  where operator_row.id = v_operator_id
    and operator_row.active is true
    and coalesce(operator_row.login_enabled, true) is true;

  if coalesce(v_enabled, false) is not true then
    update public.operator_sessions
    set ended_at = clock_timestamp(), end_reason = 'replacement_access_denied'
    where id = v_session_id;

    insert into public.system_audit_logs (
      user_id, user_name, action, entity, entity_id, device_id, session_id, success, metadata
    ) values (
      auth.uid(), v_result #>> '{operator,name}', 'replacement_operator_login_denied',
      'operators', v_operator_id::text, btrim(coalesce(p_device_id, '')),
      v_session_id::text, false,
      jsonb_build_object('reason_code', 'REPLACEMENT_ACCESS_DENIED')
    );

    return jsonb_build_object(
      'success', false,
      'reason_code', 'REPLACEMENT_ACCESS_DENIED',
      'error', 'Colaborador sem liberacao para realizar baixas de reposicao. Solicite a liberacao no cadastro de colaboradores.'
    );
  end if;

  return jsonb_set(
    jsonb_set(v_result, '{scope}', '"replacement"'::jsonb, true),
    '{operator,replacement_enabled}', 'true'::jsonb, true
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.request_capacity_test_run(p_run_id text, p_config jsonb, p_confirmation text)
 RETURNS public.capacity_test_runs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  v_row public.capacity_test_runs;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.profiles profile
    WHERE profile.id = auth.uid() AND profile.active IS TRUE AND profile.role = 'admin'
  ) THEN
    RAISE EXCEPTION 'ADMIN_REQUIRED' USING ERRCODE = '42501';
  END IF;
  IF p_confirmation IS DISTINCT FROM 'INICIAR TESTE CONTROLADO' THEN
    RAISE EXCEPTION 'CAPACITY_TEST_CONFIRMATION_REQUIRED' USING ERRCODE = '22023';
  END IF;
  IF p_run_id !~ '^CAPTEST_[0-9]{8}_[0-9]{6}_[A-Z0-9]{8}$'
     OR jsonb_typeof(p_config) <> 'object' THEN
    RAISE EXCEPTION 'CAPACITY_TEST_CONFIG_INVALID' USING ERRCODE = '22023';
  END IF;
  IF coalesce((p_config ->> 'devices')::integer, 0) NOT BETWEEN 1 AND 100
     OR coalesce((p_config ->> 'operators')::integer, 0) NOT BETWEEN 1 AND 14
     OR coalesce((p_config ->> 'pieces')::integer, 0) NOT BETWEEN 1 AND 18000
     OR coalesce((p_config ->> 'duration_minutes')::integer, 0) NOT BETWEEN 1 AND 60 THEN
    RAISE EXCEPTION 'CAPACITY_TEST_LIMIT_EXCEEDED' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.capacity_test_runs (run_id, config, app_version)
  VALUES (p_run_id, p_config, left(p_config ->> 'app_version', 80))
  RETURNING * INTO v_row;
  RETURN v_row;
END;
$function$

CREATE OR REPLACE FUNCTION public.request_piece_replacement_impl(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_original_piece_id uuid;
  v_piece record;
  v_reason text;
  v_priority text;
  v_notes text;
  v_replacement_code text;
  v_order_id uuid;
  v_existing_id uuid;
  v_route text[];
BEGIN
  v_original_piece_id := (p_payload->>'original_piece_id')::uuid;
  v_reason := COALESCE(p_payload->>'reason', 'Solicitação de reposição');
  v_priority := COALESCE(p_payload->>'priority', 'high');
  v_notes := p_payload->>'notes';

  IF v_original_piece_id IS NULL THEN
    RAISE EXCEPTION 'original_piece_id é obrigatório';
  END IF;

  SELECT * INTO v_piece FROM public.production_pieces WHERE id = v_original_piece_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Peça não encontrada: %', v_original_piece_id; END IF;

  SELECT id INTO v_existing_id FROM public.replacement_orders
  WHERE original_piece_id = v_original_piece_id AND status NOT IN ('completed','cancelled') LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    SELECT replacement_code INTO v_replacement_code FROM public.replacement_orders WHERE id = v_existing_id;
    RETURN jsonb_build_object('success',true,'idempotent',true,'replacement_order_id',v_existing_id,'replacement_code',v_replacement_code);
  END IF;

  -- Definir rota completa para a nova peça de reposição (sequência lógica completa)
  IF v_piece.route_steps IS NOT NULL AND array_length(v_piece.route_steps, 1) > 0 THEN
    v_route := v_piece.route_steps;
  ELSE
    v_route := ARRAY['Corte', 'Borda', 'Furação', 'Separação', 'Embalagem'];
  END IF;

  -- Marcar status da peça original como reposição solicitada
  UPDATE public.production_pieces
  SET status = 'replacement_requested',
      replacement_status = 'requested',
      updated_at = now()
  WHERE id = v_original_piece_id;

  v_replacement_code := 'REP-' || to_char(now(),'YYYYMMDD') || '-' || lpad(floor(random()*8999+1000)::text,4,'0');

  INSERT INTO public.replacement_orders (
    replacement_code, original_piece_id, reason, priority, lot_id, production_order_id,
    status, created_by, lot_code, order_number, customer_name, environment_name, requester_id, notes, route_steps
  ) VALUES (
    v_replacement_code, v_original_piece_id, v_reason, v_priority, v_piece.lot_id,
    v_piece.production_order_id, 'requested', v_user_id, v_piece.lot_code, v_piece.order_number,
    v_piece.customer_name, v_piece.environment_name, v_user_id, v_notes, v_route
  ) RETURNING id INTO v_order_id;

  RETURN jsonb_build_object('success',true,'replacement_order_id',v_order_id,'replacement_code',v_replacement_code);
END;
$function$

CREATE OR REPLACE FUNCTION public.request_piece_replacement(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if not ((select public.can_register_production()) or (select public.can_manage_quality())) then
    raise exception 'PRODUCTION_PERMISSION_REQUIRED' using errcode = '42501';
  end if;
  return public.request_piece_replacement_impl(p_payload);
end;
$function$

CREATE OR REPLACE FUNCTION public.reset_production_data_impl()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  -- Verificar se o usuário que chamou é admin
  IF NOT EXISTS (
    SELECT 1 FROM public.profiles
    WHERE id = auth.uid() AND role = 'admin'
  ) THEN
    RAISE EXCEPTION 'Permissão insuficiente. Apenas administradores podem zerar os dados de produção.';
  END IF;

  -- 1. Desativar trigger de retenção de backups caso exista
  IF EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'trg_backup_files_no_early_delete') THEN
    ALTER TABLE public.backup_files DISABLE TRIGGER trg_backup_files_no_early_delete;
  END IF;

  -- 2. Limpar instantaneamente todas as tabelas de lotes, ordens, peças e apontamentos de PCP
  -- utilizando TRUNCATE TABLE ... RESTART IDENTITY CASCADE para evitar locks e statement timeouts.
  TRUNCATE TABLE
    public.alert_action_history,
    public.alert_logs,
    public.backup_files,
    public.customer_cover_events,
    public.customer_covers,
    public.flow_exceptions,
    public.integration_inbox,
    public.integration_outbox,
    public.lot_items,
    public.lot_step_events,
    public.manual_production_records,
    public.occurrences,
    public.offline_event_queue,
    public.package_items,
    public.packages,
    public.packing_scans,
    public.packing_volume_items,
    public.packing_volumes,
    public.pcp_import_logs,
    public.pcp_import_rows,
    public.piece_instances,
    public.production_collection_events,
    public.production_entries,
    public.production_events,
    public.production_lot_items,
    public.production_lots,
    public.production_order_items,
    public.production_orders,
    public.production_pieces,
    public.production_realtime_counters,
    public.production_routes,
    public.production_search_index,
    public.production_stage_readings,
    public.production_tags,
    public.promob_import_batches,
    public.promob_import_differences,
    public.quality_nonconformities,
    public.replacement_orders,
    public.rework_orders,
    public.shipment_exceptions,
    public.shipment_items,
    public.shipment_scans,
    public.shipments,
    public.traceability_logs
  RESTART IDENTITY CASCADE;

  -- 3. Reativar trigger de retenção de backups caso exista
  IF EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'trg_backup_files_no_early_delete') THEN
    ALTER TABLE public.backup_files ENABLE TRIGGER trg_backup_files_no_early_delete;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Dados dos Lotes importados do PCP e apontamentos operacionais zerados com sucesso! Usuários, operadores, células e máquinas foram mantidos.'
  );
EXCEPTION WHEN OTHERS THEN
  IF EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'trg_backup_files_no_early_delete') THEN
    BEGIN
      ALTER TABLE public.backup_files ENABLE TRIGGER trg_backup_files_no_early_delete;
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END IF;
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.reset_production_data()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
begin
  if public.get_my_role() is distinct from 'admin' then
    raise exception 'ACTIVE_ADMIN_REQUIRED' using errcode = '42501';
  end if;
  return public.reset_production_data_impl();
end;
$function$

CREATE OR REPLACE FUNCTION public.resolve_downtime_target_cell(p_payload jsonb)
 RETURNS TABLE(cell_id uuid, cell_name text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
declare
  v_requested_cell_id uuid;
  v_machine_id uuid;
  v_requested_name text := nullif(btrim(p_payload->>'cell_name'), '');
  v_cell_by_id_id uuid;
  v_cell_by_id_name text;
  v_cell_by_name_id uuid;
  v_cell_by_name_name text;
  v_machine_cell text;
begin
  begin
    v_requested_cell_id := nullif(p_payload->>'cell_id', '')::uuid;
  exception when invalid_text_representation then
    raise exception 'DOWNTIME_CELL_INVALID' using errcode = '22023';
  end;

  begin
    v_machine_id := nullif(p_payload->>'machine_id', '')::uuid;
  exception when invalid_text_representation then
    raise exception 'DOWNTIME_MACHINE_INVALID' using errcode = '22023';
  end;

  if v_requested_cell_id is not null then
    select cell.id, cell.name into v_cell_by_id_id, v_cell_by_id_name
    from public.cells cell
    where cell.id = v_requested_cell_id and coalesce(cell.active, true);
    if v_cell_by_id_id is null then
      raise exception 'DOWNTIME_CELL_NOT_FOUND' using errcode = 'P0002';
    end if;
  end if;

  if v_requested_name is not null then
    select cell.id, cell.name into v_cell_by_name_id, v_cell_by_name_name
    from public.cells cell
    where coalesce(cell.active, true)
      and public.normalize_production_name(cell.name) =
          public.normalize_production_name(v_requested_name)
    order by cell.created_at, cell.id
    limit 1;
    if v_cell_by_name_id is null then
      raise exception 'DOWNTIME_CELL_NOT_FOUND' using errcode = 'P0002';
    end if;
  end if;

  if v_machine_id is not null then
    select nullif(btrim(machine.cell_name), '') into v_machine_cell
    from public.production_machines machine
    where machine.id = v_machine_id and coalesce(machine.active, true);
    if v_machine_cell is null then
      raise exception 'DOWNTIME_MACHINE_NOT_FOUND' using errcode = 'P0002';
    end if;
  end if;

  if v_cell_by_id_id is not null and v_cell_by_name_id is not null
     and v_cell_by_id_id <> v_cell_by_name_id then
    raise exception 'DOWNTIME_CELL_MISMATCH' using errcode = '42501';
  end if;

  cell_id := coalesce(v_cell_by_id_id, v_cell_by_name_id);
  cell_name := coalesce(v_cell_by_id_name, v_cell_by_name_name, v_machine_cell);

  if v_machine_cell is not null and cell_name is not null
     and public.normalize_production_name(v_machine_cell) <>
         public.normalize_production_name(cell_name) then
    raise exception 'DOWNTIME_MACHINE_CELL_MISMATCH' using errcode = '42501';
  end if;

  if cell_id is null and v_machine_cell is not null then
    select cell.id, cell.name into cell_id, cell_name
    from public.cells cell
    where coalesce(cell.active, true)
      and public.normalize_production_name(cell.name) =
          public.normalize_production_name(v_machine_cell)
    order by cell.created_at, cell.id
    limit 1;
  end if;

  if cell_id is null or cell_name is null then
    raise exception 'DOWNTIME_CELL_REQUIRED' using errcode = '22023';
  end if;

  return next;
end;
$function$

CREATE OR REPLACE FUNCTION public.resolve_mes_alert(p_alert_id uuid, p_resolution_note text)
 RETURNS public.alert_logs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_alert public.alert_logs%ROWTYPE;
  v_user_id uuid := (SELECT auth.uid());
BEGIN
  IF v_user_id IS NULL OR NOT public.has_permission('resolve_mes_alerts') THEN
    RAISE EXCEPTION 'MES_ALERT_RESOLUTION_PERMISSION_REQUIRED'
      USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_alert
  FROM public.alert_logs
  WHERE id = p_alert_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Alerta não localizado ou fora do escopo.'
      USING ERRCODE = 'P0012';
  END IF;

  IF NOT (
    public.current_profile_has_global_cell_access()
    OR public.profile_can_access_cell(v_alert.cell)
  ) THEN
    RAISE EXCEPTION 'Alerta não localizado ou fora do escopo.'
      USING ERRCODE = '42501';
  END IF;

  UPDATE public.alert_logs
  SET resolved = true,
      resolved_at = now(),
      resolved_by = v_user_id,
      resolution_source = 'manual',
      resolution_note = p_resolution_note,
      updated_at = now()
  WHERE id = p_alert_id
  RETURNING * INTO v_alert;

  RETURN v_alert;
END;
$function$

CREATE OR REPLACE FUNCTION public.resolve_operator_shift_window(p_operator_id uuid, p_reference_time timestamp with time zone DEFAULT clock_timestamp())
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_op public.operators%ROWTYPE;
  v_tz text;
  v_local_ref timestamp;
  v_local_date date;
  v_local_time time;
  v_work_date date;
  v_start_local timestamp;
  v_end_local timestamp;
  v_inside boolean := false;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_op
  FROM public.operators
  WHERE id = p_operator_id;

  IF v_op.id IS NULL THEN
    RAISE EXCEPTION 'OPERATOR_NOT_FOUND' USING ERRCODE = '22023';
  END IF;

  v_tz := coalesce(nullif(v_op.timezone, ''), 'America/Sao_Paulo');
  BEGIN
    v_local_ref := p_reference_time AT TIME ZONE v_tz;
  EXCEPTION WHEN invalid_parameter_value THEN
    v_tz := 'America/Sao_Paulo';
    v_local_ref := p_reference_time AT TIME ZONE v_tz;
  END;

  v_local_date := v_local_ref::date;
  v_local_time := v_local_ref::time;

  IF v_op.shift_start_time < v_op.shift_end_time THEN
    v_work_date := v_local_date;
    v_start_local := v_local_date + v_op.shift_start_time;
    v_end_local := v_local_date + v_op.shift_end_time;
    v_inside := v_local_time >= v_op.shift_start_time
      AND v_local_time < v_op.shift_end_time;
  ELSE
    IF v_local_time >= v_op.shift_start_time THEN
      v_work_date := v_local_date;
      v_start_local := v_local_date + v_op.shift_start_time;
      v_end_local := (v_local_date + 1) + v_op.shift_end_time;
      v_inside := true;
    ELSIF v_local_time < v_op.shift_end_time THEN
      v_work_date := v_local_date - 1;
      v_start_local := (v_local_date - 1) + v_op.shift_start_time;
      v_end_local := v_local_date + v_op.shift_end_time;
      v_inside := true;
    ELSE
      v_work_date := v_local_date;
      v_start_local := v_local_date + v_op.shift_start_time;
      v_end_local := (v_local_date + 1) + v_op.shift_end_time;
      v_inside := false;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'operator_id', v_op.id,
    'shift_name', v_op.shift,
    'shift_start_time', v_op.shift_start_time,
    'shift_end_time', v_op.shift_end_time,
    'timezone', v_tz,
    'shift_work_date', v_work_date,
    'shift_started_at', v_start_local AT TIME ZONE v_tz,
    'shift_ends_at', v_end_local AT TIME ZONE v_tz,
    'is_inside_shift', v_inside
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.resolve_piece_by_identifier(p_identifier text)
 RETURNS public.production_pieces
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_normalized text := trim(p_identifier);
  v_piece public.production_pieces;
  v_count integer;
BEGIN
  IF v_normalized IS NULL OR v_normalized = '' THEN
    RAISE EXCEPTION 'Identificador vazio' USING ERRCODE = 'P0001';
  END IF;

  SELECT count(DISTINCT t.piece_id)
  INTO v_count
  FROM public.production_tags t
  WHERE upper(t.tag_value) = upper(v_normalized)
    AND t.active IS TRUE
    AND t.piece_id IS NOT NULL;

  IF v_count = 1 THEN
    SELECT t.piece_id
    INTO v_piece.id
    FROM public.production_tags t
    WHERE upper(t.tag_value) = upper(v_normalized)
      AND t.active IS TRUE
      AND t.piece_id IS NOT NULL
    ORDER BY t.updated_at DESC, t.created_at DESC
    LIMIT 1;

    SELECT * INTO v_piece FROM public.production_pieces WHERE id = v_piece.id;
    RETURN v_piece;
  ELSIF v_count > 1 THEN
    RAISE EXCEPTION 'Identificador % ambíguo (múltiplas tags ativas)', p_identifier USING ERRCODE = 'P0004';
  END IF;

  SELECT count(*)
  INTO v_count
  FROM public.production_pieces p
  WHERE upper(p.piece_uid) = upper(v_normalized)
     OR upper(p.traceability_code) = upper(v_normalized);

  IF v_count = 0 THEN
    SELECT count(*) INTO v_count
    FROM public.production_tags t
    WHERE upper(t.tag_value) = upper(v_normalized)
      AND t.active IS FALSE;

    IF v_count > 0 THEN
      RAISE EXCEPTION 'Identificador % inativo no sistema', p_identifier USING ERRCODE = 'P0003';
    END IF;
    RAISE EXCEPTION 'Peça não localizada para o identificador %', p_identifier USING ERRCODE = 'P0002';
  ELSIF v_count > 1 THEN
    RAISE EXCEPTION 'Identificador % ambíguo (múltiplas peças encontradas)', p_identifier USING ERRCODE = 'P0004';
  END IF;

  SELECT p.id
  INTO v_piece.id
  FROM public.production_pieces p
  WHERE upper(p.piece_uid) = upper(v_normalized)
     OR upper(p.traceability_code) = upper(v_normalized)
  ORDER BY p.updated_at DESC, p.created_at DESC
  LIMIT 1;

  SELECT * INTO v_piece FROM public.production_pieces WHERE id = v_piece.id;
  RETURN v_piece;
END;
$function$

CREATE OR REPLACE FUNCTION public.resolve_production_context(p_input text, p_hint text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v text := UPPER(TRIM(COALESCE(p_input,'')));
  h text := LOWER(TRIM(COALESCE(p_hint,'')));
  o production_orders%ROWTYPE;
  l production_lots%ROWTYPE;
  i production_order_items%ROWTYPE;
  li production_lot_items%ROWTYPE;
  r production_routes%ROWTYPE;
  t production_tags%ROWTYPE;
  v_piece production_pieces%ROWTYPE;
  matched text;
BEGIN
  IF auth.uid() IS NULL THEN RETURN jsonb_build_object('contextFound',false,'warnings',jsonb_build_array('Autenticacao obrigatoria.')); END IF;
  IF v = '' THEN RETURN jsonb_build_object('contextFound',false,'warnings',jsonb_build_array('Informe Pedido, Lote, Carga, Pallet ou etiqueta.')); END IF;

  IF h IN ('','tag','scanner','camera','rfid') THEN
    BEGIN
      -- Resolver via resolvedor canônico
      v_piece := public.resolve_piece_by_identifier(p_input);
      IF v_piece.id IS NOT NULL THEN
        SELECT * INTO l FROM production_lots WHERE id = v_piece.lot_id;
        SELECT * INTO li FROM production_lot_items WHERE id = v_piece.legacy_production_lot_item_id;
        matched := 'tag';
      END IF;
    EXCEPTION WHEN OTHERS THEN
      -- Fallback legada em caso de erro no resolvedor
      SELECT * INTO t FROM production_tags WHERE active AND UPPER(tag_value)=v LIMIT 1;
      IF t.id IS NOT NULL THEN
        SELECT * INTO l FROM production_lots WHERE id=t.lot_id;
        SELECT * INTO li FROM production_lot_items WHERE id=t.item_id;
        matched:='tag';
      END IF;
    END;
  END IF;

  IF l.id IS NULL AND h IN ('','lot','lote') THEN SELECT * INTO l FROM production_lots WHERE UPPER(lot_code)=v LIMIT 1; IF l.id IS NOT NULL THEN matched:='lot'; END IF; END IF;
  IF l.id IS NOT NULL THEN
    SELECT * INTO o FROM production_orders WHERE id=COALESCE(l.production_order_id,l.order_id);
    SELECT * INTO i FROM production_order_items WHERE lot_id=l.id AND (li.id IS NULL OR product_code=li.product_code OR product_name=li.product_name) ORDER BY created_at LIMIT 1;
  END IF;
  IF i.id IS NULL AND h IN ('','pallet','palete') THEN
    SELECT * INTO i FROM production_order_items WHERE UPPER(COALESCE(pallet_number,''))=v ORDER BY created_at DESC LIMIT 1;
    IF i.id IS NOT NULL THEN SELECT * INTO o FROM production_orders WHERE id=i.production_order_id; SELECT * INTO l FROM production_lots WHERE id=i.lot_id; matched:='pallet'; END IF;
  END IF;
  IF o.id IS NULL AND h IN ('','order','pedido') THEN
    SELECT * INTO o FROM production_orders WHERE UPPER(COALESCE(system_order_number,''))=v OR UPPER(COALESCE(customer_order_number,''))=v OR UPPER(COALESCE(order_number,''))=v OR UPPER(order_code)=v ORDER BY created_at DESC LIMIT 1;
    IF o.id IS NOT NULL THEN matched:='order'; END IF;
  END IF;
  IF o.id IS NULL AND h IN ('','load','carga') THEN SELECT * INTO o FROM production_orders WHERE UPPER(COALESCE(load_number,''))=v ORDER BY created_at DESC LIMIT 1; IF o.id IS NOT NULL THEN matched:='load'; END IF; END IF;
  IF o.id IS NULL AND h IN ('','product','produto') THEN
    SELECT * INTO i FROM production_order_items WHERE UPPER(COALESCE(product_code,''))=v OR UPPER(COALESCE(product_name,''))=v ORDER BY created_at DESC LIMIT 1;
    IF i.id IS NOT NULL THEN SELECT * INTO o FROM production_orders WHERE id=i.production_order_id; SELECT * INTO l FROM production_lots WHERE id=i.lot_id; matched:='product'; END IF;
  END IF;
  IF o.id IS NULL AND h IN ('','customer','cliente') THEN
    SELECT * INTO o FROM production_orders WHERE UPPER(COALESCE(customer_code,''))=v OR UPPER(COALESCE(customer_legal_name,''))=v OR UPPER(COALESCE(customer_trade_name,''))=v OR UPPER(customer_name)=v ORDER BY created_at DESC LIMIT 1;
    IF o.id IS NOT NULL THEN matched:='customer'; END IF;
  END IF;
  IF o.id IS NOT NULL AND l.id IS NULL THEN SELECT * INTO l FROM production_lots WHERE COALESCE(production_order_id,order_id)=o.id ORDER BY created_at DESC LIMIT 1; END IF;
  IF l.id IS NOT NULL AND i.id IS NULL THEN SELECT * INTO i FROM production_order_items WHERE lot_id=l.id ORDER BY created_at LIMIT 1; END IF;
  IF l.id IS NOT NULL THEN SELECT * INTO r FROM production_routes WHERE lot_id=l.id AND required AND status NOT IN ('completed','skipped') ORDER BY step_order LIMIT 1; END IF;

  RETURN jsonb_build_object(
    'productionOrder',CASE WHEN o.id IS NULL THEN NULL ELSE to_jsonb(o) END,
    'lot',CASE WHEN l.id IS NULL THEN NULL ELSE to_jsonb(l) END,
    'item',CASE WHEN i.id IS NULL THEN CASE WHEN li.id IS NULL THEN NULL ELSE to_jsonb(li) END ELSE to_jsonb(i) END,
    'route',CASE WHEN r.id IS NULL THEN NULL ELSE to_jsonb(r) END,
    'contextFound',o.id IS NOT NULL OR l.id IS NOT NULL OR i.id IS NOT NULL,
    'matchedBy',matched,
    'warnings',CASE WHEN o.id IS NULL AND l.id IS NULL AND i.id IS NULL THEN jsonb_build_array('Contexto produtivo nao localizado. Rastreabilidade limitada.') WHEN i.id IS NULL THEN jsonb_build_array('Contexto localizado sem item comercial vinculado.') ELSE '[]'::jsonb END
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.reverse_production_entry_after_rejection()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_entry_id uuid;
BEGIN
  IF NEW.status <> 'pending_review' OR OLD.status <> 'approved' THEN RETURN NEW; END IF;
  v_entry_id := NEW.production_entry_id;
  IF v_entry_id IS NULL THEN
    SELECT production_entry_id INTO v_entry_id
    FROM public.production_collection_events
    WHERE reading_id = NEW.id
    ORDER BY created_at DESC LIMIT 1;
  END IF;
  IF v_entry_id IS NOT NULL THEN
    UPDATE public.production_entries
    SET approval_status = 'reversed',
        correction_reason = COALESCE(NULLIF(correction_reason, ''),
          'Estorno automático: leitura colocada em revisão por reprovação'),
        corrected_by = COALESCE(NULLIF(corrected_by, ''), 'quality_rejection'),
        corrected_at = COALESCE(corrected_at, now())
    WHERE id = v_entry_id
      AND approval_status IS DISTINCT FROM 'reversed';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.scan_piece_to_volume(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_volume_id          uuid := (p_payload->>'volume_id')::uuid;
  v_barcode            text := p_payload->>'barcode';
  v_operator_id        uuid := (p_payload->>'operator_id')::uuid;
  v_device_id          text := p_payload->>'device_id';

  v_volume             public.packing_volumes%ROWTYPE;
  v_piece              public.production_pieces%ROWTYPE;
  v_already_packed     public.packing_volume_items%ROWTYPE;
  v_scan_id            uuid;
BEGIN
  -- Buscar volume
  SELECT * INTO v_volume FROM public.packing_volumes WHERE id = v_volume_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Volume não encontrado.');
  END IF;

  IF v_volume.status = 'closed' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Não é possível adicionar peças a um volume já fechado.');
  END IF;

  -- Buscar peça pelo resolvedor canônico
  BEGIN
    v_piece := public.resolve_piece_by_identifier(v_barcode);
    IF v_piece.status = 'cancelled' THEN
      RAISE EXCEPTION 'Peça foi cancelada no sistema' USING ERRCODE = 'P0005';
    END IF;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO public.packing_scans (volume_id, piece_id, scan_result, error_reason, operator_id, device_id)
    VALUES (v_volume_id, NULL, 'rejected', SQLERRM, v_operator_id, v_device_id);

    RETURN jsonb_build_object('success', false, 'error', SQLERRM);
  END;

  -- Bloquear peça de outra capa (se o volume estiver associado a uma capa)
  IF v_volume.customer_cover_id IS NOT NULL THEN
    IF v_piece.customer_cover_id IS NULL OR v_piece.customer_cover_id <> v_volume.customer_cover_id THEN
      INSERT INTO public.packing_scans (volume_id, piece_id, scan_result, error_reason, operator_id, device_id)
      VALUES (v_volume_id, v_piece.id, 'rejected', 'Peça pertence a outra capa de cliente.', v_operator_id, v_device_id);

      RETURN jsonb_build_object('success', false, 'error', 'Bloqueio: Peça pertence a outra capa de cliente.');
    END IF;
  ELSE
    -- Bloquear peça de outro lote produtivo
    IF v_piece.lot_id <> v_volume.lot_id THEN
      INSERT INTO public.packing_scans (volume_id, piece_id, scan_result, error_reason, operator_id, device_id)
      VALUES (v_volume_id, v_piece.id, 'rejected', 'Peça pertence a outro lote produtivo.', v_operator_id, v_device_id);

      RETURN jsonb_build_object('success', false, 'error', 'Bloqueio: Peça pertence a outro lote produtivo.');
    END IF;
  END IF;

  -- Bloquear peça ainda não liberada para embalagem
  IF v_piece.current_stage IN ('Corte', 'Bordo', 'Usinagem', 'Marcenaria') AND v_piece.status <> 'completed' THEN
    INSERT INTO public.packing_scans (volume_id, piece_id, scan_result, error_reason, operator_id, device_id)
    VALUES (v_volume_id, v_piece.id, 'rejected', 'Peça ainda está na etapa ' || v_piece.current_stage, v_operator_id, v_device_id);

    RETURN jsonb_build_object('success', false, 'error', 'Peça não liberada para embalagem (ainda pendente em ' || v_piece.current_stage || ').');
  END IF;

  -- Bloquear peça já embalada em outro volume
  SELECT * INTO v_already_packed FROM public.packing_volume_items WHERE piece_id = v_piece.id;
  IF FOUND THEN
    INSERT INTO public.packing_scans (volume_id, piece_id, scan_result, error_reason, operator_id, device_id)
    VALUES (v_volume_id, v_piece.id, 'rejected', 'Peça já se encontra embalada em outro volume.', v_operator_id, v_device_id);

    RETURN jsonb_build_object('success', false, 'error', 'Peça já se encontra embalada em outro volume.');
  END IF;

  -- Inserir item no volume
  INSERT INTO public.packing_volume_items (volume_id, piece_id, traceability_code, scanned_by)
  VALUES (v_volume_id, v_piece.id, v_piece.traceability_code, auth.uid());

  -- Registrar scan de sucesso
  INSERT INTO public.packing_scans (volume_id, piece_id, scan_result, operator_id, device_id)
  VALUES (v_volume_id, v_piece.id, 'approved', v_operator_id, v_device_id);

  -- Atualizar estágio da peça
  UPDATE public.production_pieces 
  SET current_stage = 'Embalagem', status = 'in_progress'
  WHERE id = v_piece.id;

  -- Registrar evento
  INSERT INTO public.production_events (
    piece_id, traceability_code, production_order_id, lot_id,
    event_type, from_stage, to_stage, event_status
  ) VALUES (
    v_piece.id, v_piece.traceability_code, v_piece.production_order_id, v_piece.lot_id,
    'pack', v_piece.current_stage, 'Embalagem', 'accepted'
  );

  RETURN jsonb_build_object('success', true, 'piece_id', v_piece.id, 'piece_name', v_piece.piece_name);
END;
$function$

CREATE OR REPLACE FUNCTION public.scan_shipment_item(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_shipment_id        uuid := (p_payload->>'shipment_id')::uuid;
  v_barcode            text := p_payload->>'barcode';
  v_operator_id        uuid := (p_payload->>'operator_id')::uuid;
  v_device_id          text := p_payload->>'device_id';

  v_shipment           public.shipments%ROWTYPE;
  v_volume             public.packing_volumes%ROWTYPE;
  v_piece              public.production_pieces%ROWTYPE;
  v_checklist_item     public.shipment_items%ROWTYPE;
  v_is_volume          boolean := false;
BEGIN
  -- Buscar remessa
  SELECT * INTO v_shipment FROM public.shipments WHERE id = v_shipment_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Expedição/Remessa não encontrada.');
  END IF;

  IF v_shipment.status <> 'pending' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Remessa não está pendente para bipagem.');
  END IF;

  -- Tentar localizar volume
  SELECT * INTO v_volume FROM public.packing_volumes WHERE UPPER(volume_code) = UPPER(TRIM(v_barcode));
  IF FOUND THEN
    v_is_volume := true;
  ELSE
    -- Tentar localizar peça pelo resolvedor canônico
    BEGIN
      v_piece := public.resolve_piece_by_identifier(v_barcode);
      IF v_piece.status = 'cancelled' THEN
        v_piece.id := NULL;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_piece.id := NULL;
    END;
  END IF;

  IF v_volume.id IS NULL AND v_piece.id IS NULL THEN
    INSERT INTO public.shipment_scans (shipment_id, piece_id, volume_id, barcode_raw_value, scan_result, error_reason, operator_id, device_id)
    VALUES (v_shipment_id, NULL, NULL, v_barcode, 'rejected', 'Código desconhecido', v_operator_id, v_device_id);

    RETURN jsonb_build_object('success', false, 'error', 'Código não identificado como peça ou volume.');
  END IF;

  -- Se for volume
  IF v_is_volume THEN
    IF v_shipment.customer_cover_id IS NOT NULL THEN
      IF v_volume.customer_cover_id IS NULL OR v_volume.customer_cover_id <> v_shipment.customer_cover_id THEN
        INSERT INTO public.shipment_scans (shipment_id, piece_id, volume_id, barcode_raw_value, scan_result, error_reason, operator_id, device_id)
        VALUES (v_shipment_id, NULL, v_volume.id, v_barcode, 'rejected', 'Volume pertence a outra capa', v_operator_id, v_device_id);
        RETURN jsonb_build_object('success', false, 'error', 'Volume pertence a outra capa de cliente.');
      END IF;
    ELSE
      IF v_volume.lot_id <> v_shipment.lot_id THEN
        INSERT INTO public.shipment_scans (shipment_id, piece_id, volume_id, barcode_raw_value, scan_result, error_reason, operator_id, device_id)
        VALUES (v_shipment_id, NULL, v_volume.id, v_barcode, 'rejected', 'Volume pertence a outro lote', v_operator_id, v_device_id);
        RETURN jsonb_build_object('success', false, 'error', 'Volume pertence a outro lote produtiva.');
      END IF;
    END IF;

    IF v_volume.status <> 'closed' THEN
      RETURN jsonb_build_object('success', false, 'error', 'Volume não está fechado na embalagem.');
    END IF;

    -- Verificar checklist de expedição
    SELECT * INTO v_checklist_item FROM public.shipment_items 
    WHERE shipment_id = v_shipment_id AND volume_id = v_volume.id;

    IF NOT FOUND THEN
      INSERT INTO public.shipment_items (shipment_id, expected_type, volume_id, traceability_code, status, scanned_at, scanned_by)
      VALUES (v_shipment_id, 'volume', v_volume.id, v_volume.volume_code, 'scanned', now(), auth.uid())
      RETURNING * INTO v_checklist_item;
    ELSE
      UPDATE public.shipment_items 
      SET status = 'scanned', scanned_at = now(), scanned_by = auth.uid()
      WHERE id = v_checklist_item.id
      RETURNING * INTO v_checklist_item;
    END IF;

    INSERT INTO public.shipment_scans (shipment_id, volume_id, barcode_raw_value, scan_result, operator_id, device_id)
    VALUES (v_shipment_id, v_volume.id, v_barcode, 'approved', v_operator_id, v_device_id);

    -- Atualizar as peças deste volume para shipped e gravar evento
    UPDATE public.production_pieces 
    SET current_stage = 'Expedição', status = 'completed'
    WHERE id IN (SELECT piece_id FROM public.packing_volume_items WHERE volume_id = v_volume.id);

    INSERT INTO public.production_events (
      piece_id, traceability_code, production_order_id, lot_id,
      event_type, from_stage, to_stage, event_status
    )
    SELECT piece_id, traceability_code, production_order_id, lot_id,
      'ship', 'Embalagem', 'Expedição', 'accepted'
    FROM public.production_pieces WHERE id IN (SELECT piece_id FROM public.packing_volume_items WHERE volume_id = v_volume.id);

    RETURN jsonb_build_object('success', true, 'type', 'volume', 'id', v_volume.id, 'code', v_volume.volume_code);
  END IF;

  -- Se for peça avulsa
  IF v_shipment.customer_cover_id IS NOT NULL THEN
    IF v_piece.customer_cover_id IS NULL OR v_piece.customer_cover_id <> v_shipment.customer_cover_id THEN
      INSERT INTO public.shipment_scans (shipment_id, piece_id, barcode_raw_value, scan_result, error_reason, operator_id, device_id)
      VALUES (v_shipment_id, v_piece.id, v_barcode, 'rejected', 'Peça pertence a outra capa', v_operator_id, v_device_id);
      RETURN jsonb_build_object('success', false, 'error', 'Peça pertence a outra capa de cliente.');
    END IF;
  ELSE
    IF v_piece.lot_id <> v_shipment.lot_id THEN
      INSERT INTO public.shipment_scans (shipment_id, piece_id, barcode_raw_value, scan_result, error_reason, operator_id, device_id)
      VALUES (v_shipment_id, v_piece.id, v_barcode, 'rejected', 'Peça pertence a outro lote', v_operator_id, v_device_id);
      RETURN jsonb_build_object('success', false, 'error', 'Peça pertence a outro lote produtiva.');
    END IF;
  END IF;

  -- Verificar se já foi embalada em algum volume
  IF EXISTS (SELECT 1 FROM public.packing_volume_items WHERE piece_id = v_piece.id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Esta peça pertence a um volume fechado. Bipe a etiqueta do volume.');
  END IF;

  -- Verificar checklist de expedição
  SELECT * INTO v_checklist_item FROM public.shipment_items 
  WHERE shipment_id = v_shipment_id AND piece_id = v_piece.id;

  IF NOT FOUND THEN
    INSERT INTO public.shipment_items (shipment_id, expected_type, piece_id, traceability_code, status, scanned_at, scanned_by)
    VALUES (v_shipment_id, 'piece', v_piece.id, v_piece.traceability_code, 'scanned', now(), auth.uid())
    RETURNING * INTO v_checklist_item;
  ELSE
    UPDATE public.shipment_items 
    SET status = 'scanned', scanned_at = now(), scanned_by = auth.uid()
    WHERE id = v_checklist_item.id
    RETURNING * INTO v_checklist_item;
  END IF;

  INSERT INTO public.shipment_scans (shipment_id, piece_id, barcode_raw_value, scan_result, operator_id, device_id)
  VALUES (v_shipment_id, v_piece.id, v_barcode, 'approved', v_operator_id, v_device_id);

  UPDATE public.production_pieces 
  SET current_stage = 'Expedição', status = 'completed'
  WHERE id = v_piece.id;

  INSERT INTO public.production_events (
    piece_id, traceability_code, production_order_id, lot_id,
    event_type, from_stage, to_stage, event_status
  ) VALUES (
    v_piece.id, v_piece.traceability_code, v_piece.production_order_id, v_piece.lot_id,
    'ship', v_piece.current_stage, 'Expedição', 'accepted'
  );

  RETURN jsonb_build_object('success', true, 'type', 'piece', 'id', v_piece.id, 'name', v_piece.piece_name);
END;
$function$

CREATE OR REPLACE FUNCTION public.seed_capacity_fixture_v3(p_run_id text, p_piece_count integer, p_registration_seed text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_order_id uuid;
  v_lot_id uuid;
  v_operator_id uuid;
  v_machine_id uuid;
  v_cell_id uuid;
  v_cell_name text;
  v_stage text;
  v_registration text;
  v_code_base bigint;
  v_index integer;
  v_position integer;
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION 'SERVICE_ROLE_REQUIRED' USING ERRCODE = '42501';
  END IF;
  IF p_run_id !~ '^CAPTEST_[0-9]{8}_[0-9]{6}_[A-Z0-9]{8}$'
     OR p_piece_count NOT BETWEEN 100 AND 1000
     OR p_registration_seed !~ '^[0-9]{8,14}$' THEN
    RAISE EXCEPTION 'CAPACITY_FIXTURE_INPUT_INVALID' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (
    SELECT 1 FROM private.capacity_test_fixture_objects WHERE run_id = p_run_id
  ) THEN
    RAISE EXCEPTION 'CAPACITY_FIXTURE_ALREADY_EXISTS' USING ERRCODE = '23505';
  END IF;

  CREATE TEMP TABLE pg_temp.cap_cells (
    position integer PRIMARY KEY,
    cell_id uuid NOT NULL,
    cell_name text NOT NULL,
    stage text NOT NULL,
    primary_machine_id uuid
  ) ON COMMIT DROP;

  INSERT INTO pg_temp.cap_cells (position, cell_id, cell_name, stage)
  SELECT row_number() OVER (ORDER BY stage_order), cell_id, cell_name, stage
  FROM (
    SELECT cell.id cell_id, cell.name cell_name,
      public.resolve_production_stage_for_cell(cell.id, cell.name) stage,
      CASE public.resolve_production_stage_for_cell(cell.id, cell.name)
        WHEN 'cut' THEN 1 WHEN 'edge' THEN 2 WHEN 'cnc' THEN 3
        WHEN 'drill' THEN 4 WHEN 'joinery' THEN 5
        WHEN 'separation' THEN 6 WHEN 'packaging' THEN 7 ELSE 99
      END stage_order
    FROM public.cells cell
    WHERE cell.active IS TRUE
  ) selected
  WHERE selected.stage IN ('cut','edge','cnc','drill','joinery','separation','packaging')
  ORDER BY stage_order;

  IF (SELECT count(*) FROM pg_temp.cap_cells) <> 7 THEN
    RAISE EXCEPTION 'CAPACITY_FIXTURE_REQUIRES_SEVEN_ROUTE_CELLS' USING ERRCODE = '55000';
  END IF;

  FOR v_cell_id, v_cell_name, v_stage IN
    SELECT cell_id, cell_name, stage FROM pg_temp.cap_cells ORDER BY position
  LOOP
    SELECT machine.id INTO v_machine_id
    FROM public.production_machines machine
    WHERE machine.active IS TRUE
      AND public.normalize_production_name(machine.cell_name) = public.normalize_production_name(v_cell_name)
    ORDER BY machine.created_at, machine.id LIMIT 1;

    IF v_machine_id IS NULL THEN
      INSERT INTO public.production_machines (
        name, cell_name, station_name, active, description,
        allows_replacement, allows_normal_production, allows_rework,
        requires_piece_traceability, allows_offline_collection
      ) VALUES (
        left(p_run_id || '_MACHINE_' || upper(v_stage), 120), v_cell_name,
        left(p_run_id || '_STATION_' || upper(v_stage), 120), true,
        'CAPTEST_ capacity_test ' || p_run_id,
        true, true, true, true, true
      ) RETURNING id INTO v_machine_id;
      INSERT INTO private.capacity_test_fixture_objects(run_id, entity_kind, entity_id, metadata)
      VALUES (p_run_id, 'machine', v_machine_id, jsonb_build_object('cell', v_cell_name));
    ELSE
      INSERT INTO private.capacity_test_fixture_objects(run_id, entity_kind, entity_id, created_by_test, metadata)
      VALUES (p_run_id, 'machine_reference', v_machine_id, false, jsonb_build_object('cell', v_cell_name));
    END IF;

    UPDATE pg_temp.cap_cells SET primary_machine_id = v_machine_id WHERE cell_id = v_cell_id;
    INSERT INTO private.capacity_test_fixture_objects(run_id, entity_kind, entity_id, created_by_test, metadata)
    VALUES (p_run_id, 'cell_reference', v_cell_id, false, jsonb_build_object('name', v_cell_name));
  END LOOP;

  -- Registra também a segunda máquina da célula que possui duas máquinas reais.
  INSERT INTO private.capacity_test_fixture_objects(run_id, entity_kind, entity_id, created_by_test, metadata)
  SELECT p_run_id, 'machine_reference', machine.id, false, jsonb_build_object('cell', machine.cell_name)
  FROM public.production_machines machine
  JOIN pg_temp.cap_cells cell
    ON public.normalize_production_name(machine.cell_name) = public.normalize_production_name(cell.cell_name)
  WHERE machine.active IS TRUE
  ON CONFLICT DO NOTHING;

  FOR v_index IN 1..14 LOOP
    v_position := ((v_index - 1) % 7) + 1;
    SELECT cell_id, cell_name, primary_machine_id
    INTO v_cell_id, v_cell_name, v_machine_id
    FROM pg_temp.cap_cells WHERE position = v_position;
    v_registration := p_registration_seed || lpad(v_index::text, 2, '0');

    INSERT INTO public.operators (
      name, role, active, registration, registration_normalized,
      credential_hash, login_name, primary_cell, cells, shift,
      login_enabled, primary_cell_id, primary_machine_id,
      replacement_enabled, shift_start_time, shift_end_time, timezone
    ) VALUES (
      p_run_id || '_OP_' || lpad(v_index::text, 2, '0'), 'operator', true,
      v_registration, v_registration,
      crypt(v_registration, gen_salt('bf')),
      lower(p_run_id || '_op_' || lpad(v_index::text, 2, '0')),
      v_cell_name, ARRAY[v_cell_name], '1', true, v_cell_id, v_machine_id,
      v_index <= 7, '06:00', '14:00', 'America/Sao_Paulo'
    ) RETURNING id INTO v_operator_id;

    INSERT INTO public.operator_cell_assignments(operator_id, cell_id, is_primary, active)
    VALUES (v_operator_id, v_cell_id, true, true);
    INSERT INTO public.operator_machine_assignments(operator_id, machine_id, is_primary, active)
    VALUES (v_operator_id, v_machine_id, true, true);
    INSERT INTO private.capacity_test_fixture_objects(run_id, entity_kind, entity_id, metadata)
    VALUES (p_run_id, 'operator', v_operator_id, jsonb_build_object(
      'login_name', lower(p_run_id || '_op_' || lpad(v_index::text, 2, '0')),
      'cell_id', v_cell_id,
      'machine_id', v_machine_id,
      'operator_index', v_index,
      'replacement_enabled', v_index <= 7
    ));
  END LOOP;

  -- Cenário atômico: oito operadores possuem uma autorização adicional e
  -- explícita para disputar a mesma peça na primeira etapa (Corte).
  SELECT cell_id, primary_machine_id INTO v_cell_id, v_machine_id
  FROM pg_temp.cap_cells WHERE stage = 'cut';
  INSERT INTO public.operator_cell_assignments(operator_id, cell_id, is_primary, active)
  SELECT fixture.entity_id, v_cell_id, false, true
  FROM private.capacity_test_fixture_objects fixture
  WHERE fixture.run_id = p_run_id AND fixture.entity_kind = 'operator'
    AND (fixture.metadata ->> 'operator_index')::integer <= 8
    AND (fixture.metadata ->> 'cell_id')::uuid <> v_cell_id;
  INSERT INTO public.operator_machine_assignments(operator_id, machine_id, is_primary, active)
  SELECT fixture.entity_id, v_machine_id, false, true
  FROM private.capacity_test_fixture_objects fixture
  WHERE fixture.run_id = p_run_id AND fixture.entity_kind = 'operator'
    AND (fixture.metadata ->> 'operator_index')::integer <= 8
    AND (fixture.metadata ->> 'machine_id')::uuid <> v_machine_id;

  -- Autoriza o 8º contexto simultâneo na segunda máquina da célula multi-máquina.
  SELECT fixture.entity_id,
         (fixture.metadata ->> 'cell_id')::uuid,
         (fixture.metadata ->> 'machine_id')::uuid
  INTO v_operator_id, v_cell_id, v_machine_id
  FROM private.capacity_test_fixture_objects fixture
  WHERE fixture.run_id = p_run_id AND fixture.entity_kind = 'operator'
    AND (fixture.metadata ->> 'operator_index')::integer = 9;
  SELECT machine.id INTO v_machine_id
  FROM public.production_machines machine
  JOIN public.cells cell ON cell.id = v_cell_id
  WHERE machine.active IS TRUE
    AND machine.id <> v_machine_id
    AND public.normalize_production_name(machine.cell_name) = public.normalize_production_name(cell.name)
  ORDER BY machine.created_at, machine.id LIMIT 1;
  IF v_operator_id IS NOT NULL AND v_machine_id IS NOT NULL THEN
    INSERT INTO public.operator_machine_assignments(operator_id, machine_id, is_primary, active)
    VALUES (v_operator_id, v_machine_id, false, true);
  END IF;

  INSERT INTO public.production_orders (
    order_code, customer_name, source, status, notes,
    system_order_number, order_number, customer_legal_name
  ) VALUES (
    p_run_id, p_run_id || '_CUSTOMER', 'manual', 'released',
    'CAPTEST_ capacity_test UTC ' || clock_timestamp()::text,
    p_run_id, p_run_id, p_run_id || '_CUSTOMER'
  ) RETURNING id INTO v_order_id;
  INSERT INTO private.capacity_test_fixture_objects(run_id, entity_kind, entity_id)
  VALUES (p_run_id, 'production_order', v_order_id);

  INSERT INTO public.production_lots (
    order_id, production_order_id, lot_code, status, current_stage,
    planned_quantity, order_number, customer_name, product_code, product_name
  ) VALUES (
    v_order_id, v_order_id, p_run_id || '_LOT', 'planned', 'created',
    p_piece_count, p_run_id, p_run_id || '_CUSTOMER', p_run_id || '_PRODUCT', 'CAPTEST_ Produto'
  ) RETURNING id INTO v_lot_id;
  INSERT INTO private.capacity_test_fixture_objects(run_id, entity_kind, entity_id)
  VALUES (p_run_id, 'production_lot', v_lot_id);

  INSERT INTO public.production_routes(lot_id, step_order, step_name, cell_name, required)
  SELECT v_lot_id, position, stage, cell_name, true FROM pg_temp.cap_cells ORDER BY position;

  v_code_base := 1000000 + mod(abs(hashtextextended(p_run_id, 0)), 8000000);
  IF EXISTS (
    SELECT 1 FROM generate_series(1, p_piece_count) serial
    JOIN public.production_pieces piece
      ON piece.traceability_code = lpad((v_code_base + serial)::text, 8, '0')
  ) THEN
    RAISE EXCEPTION 'CAPACITY_FIXTURE_CODE_COLLISION' USING ERRCODE = '23505';
  END IF;

  INSERT INTO public.production_pieces (
    piece_uid, traceability_code, production_order_id, lot_id,
    piece_name, description, current_stage, status, source_origin,
    route_steps, completed_steps, lot_code, order_number, customer_name,
    sequence_number, total_in_lot, is_active,
    requires_cut, requires_edge, requires_cnc, requires_joinery,
    requires_separation, requires_packaging
  )
  SELECT
    p_run_id || ':piece:' || serial,
    lpad((v_code_base + serial)::text, 8, '0'),
    v_order_id, v_lot_id, p_run_id || '_PIECE_' || serial,
    'CAPTEST_ capacity_test ' || p_run_id, 'created', 'created', 'manual',
    ARRAY(SELECT stage FROM pg_temp.cap_cells ORDER BY position), '{}'::text[],
    p_run_id || '_LOT', p_run_id, p_run_id || '_CUSTOMER',
    serial, p_piece_count, true, true, true, true, true, true, true
  FROM generate_series(1, p_piece_count) serial;

  INSERT INTO private.capacity_test_fixture_objects(run_id, entity_kind, entity_id)
  SELECT p_run_id, 'production_piece', piece.id
  FROM public.production_pieces piece WHERE piece.piece_uid LIKE p_run_id || ':piece:%';

  RETURN jsonb_build_object(
    'run_id', p_run_id,
    'operators', 14,
    'cells', (SELECT count(*) FROM pg_temp.cap_cells),
    'machines', (SELECT count(distinct entity_id) FROM private.capacity_test_fixture_objects WHERE run_id=p_run_id AND entity_kind IN ('machine','machine_reference')),
    'pieces', p_piece_count,
    'route', (SELECT jsonb_agg(jsonb_build_object('order',position,'stage',stage,'cell_id',cell_id,'cell_name',cell_name,'machine_id',primary_machine_id) ORDER BY position) FROM pg_temp.cap_cells),
    'code_first', lpad((v_code_base + 1)::text, 8, '0'),
    'code_last', lpad((v_code_base + p_piece_count)::text, 8, '0')
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.select_route_template_for_piece(p_piece public.production_pieces)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
DECLARE
  v_template_id uuid;
  v_product_type text;
BEGIN
  -- Determina a categoria do roteiro com base nas flags de processo
  IF p_piece.requires_joinery = true THEN
    IF p_piece.requires_cnc = true THEN
      v_product_type := 'custom_refined';
    ELSE
      v_product_type := 'special_joinery';
    END IF;
  ELSE
    IF p_piece.requires_cnc = true THEN
      v_product_type := 'cnc';
    ELSIF p_piece.requires_edge = true THEN
      v_product_type := 'edge';
    ELSE
      v_product_type := 'standard';
    END IF;
  END IF;

  -- Tenta buscar o último roteiro ativo desse tipo
  SELECT id INTO v_template_id FROM public.route_templates 
  WHERE product_type = v_product_type AND active = true 
  ORDER BY created_at DESC LIMIT 1;

  -- Fallback para qualquer roteiro ativo se não localizar o tipo específico
  IF v_template_id IS NULL THEN
    SELECT id INTO v_template_id FROM public.route_templates 
    WHERE active = true 
    ORDER BY created_at ASC LIMIT 1;
  END IF;

  RETURN v_template_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_collection_pipeline_flag_v3(p_flag_name text, p_enabled boolean, p_rollout_scope jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
DECLARE
  v_flag_name text := btrim(coalesce(p_flag_name, ''));
  v_scope jsonb := coalesce(p_rollout_scope, '{}'::jsonb);
  v_guard_count integer;
  v_guard_runtime_ready boolean := false;
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION 'SERVICE_ROLE_REQUIRED'
      USING ERRCODE = '42501';
  END IF;

  IF v_flag_name NOT IN (
    'collection_pipeline_v3_ingress',
    'collection_pipeline_v3_worker',
    'collection_pipeline_v3_projection',
    'collection_pipeline_v3_broadcast'
  ) THEN
    RAISE EXCEPTION 'COLLECTION_PIPELINE_FLAG_INVALID'
      USING ERRCODE = '22023';
  END IF;

  IF jsonb_typeof(v_scope) <> 'object' THEN
    RAISE EXCEPTION 'COLLECTION_PIPELINE_ROLLOUT_SCOPE_INVALID'
      USING ERRCODE = '22023';
  END IF;

  SELECT count(*) INTO v_guard_count
  FROM private.collection_projection_trigger_registry registry
  WHERE registry.guard_installed IS TRUE;

  SELECT NOT EXISTS (
    SELECT 1
    FROM private.collection_projection_trigger_registry registry
    CROSS JOIN LATERAL unnest(registry.installed_trigger_names)
      AS installed(trigger_name)
    LEFT JOIN pg_trigger trigger_row
      ON trigger_row.tgrelid = registry.relation_name
     AND trigger_row.tgname = installed.trigger_name
     AND trigger_row.tgisinternal IS FALSE
     AND trigger_row.tgenabled <> 'D'
    WHERE registry.guard_installed IS TRUE
      AND trigger_row.oid IS NULL
  ) INTO v_guard_runtime_ready;

  IF p_enabled THEN
    IF v_guard_count <> 3 OR v_guard_runtime_ready IS NOT TRUE THEN
      RAISE EXCEPTION 'COLLECTION_V3_TRIGGER_GUARDS_NOT_READY'
        USING ERRCODE = '55000';
    END IF;

    IF v_flag_name = 'collection_pipeline_v3_ingress'
       AND to_regprocedure('public.ingest_collection_batch_v3(uuid,uuid,jsonb)') IS NULL THEN
      RAISE EXCEPTION 'COLLECTION_V3_INGRESS_NOT_READY'
        USING ERRCODE = '55000';
    END IF;

    IF v_flag_name = 'collection_pipeline_v3_worker' THEN
      IF NOT EXISTS (
        SELECT 1 FROM private.collection_pipeline_flags
        WHERE flag_name = 'collection_pipeline_v3_ingress' AND enabled IS TRUE
      ) OR to_regprocedure('public.process_collection_batch_v3(text,jsonb)') IS NULL THEN
        RAISE EXCEPTION 'ENABLE_COLLECTION_V3_INGRESS_BEFORE_WORKER'
          USING ERRCODE = '55000';
      END IF;
      IF NOT EXISTS (
        SELECT 1
        FROM vault.decrypted_secrets secret
        WHERE secret.name = 'acprod_collection_v3_decision_url'
          AND nullif(btrim(secret.decrypted_secret), '') IS NOT NULL
      ) OR NOT EXISTS (
        SELECT 1
        FROM vault.decrypted_secrets secret
        WHERE secret.name = 'acprod_collection_worker_secret'
          AND nullif(btrim(secret.decrypted_secret), '') IS NOT NULL
      ) THEN
        RAISE EXCEPTION 'COLLECTION_V3_DECISION_WAKEUP_NOT_READY'
          USING ERRCODE = '55000';
      END IF;
    END IF;

    IF v_flag_name = 'collection_pipeline_v3_projection' THEN
      IF NOT EXISTS (
        SELECT 1 FROM private.collection_pipeline_flags
        WHERE flag_name = 'collection_pipeline_v3_worker' AND enabled IS TRUE
      ) OR to_regprocedure('public.process_collection_projection_batch_v3(text,jsonb)') IS NULL THEN
        RAISE EXCEPTION 'ENABLE_COLLECTION_V3_WORKER_BEFORE_PROJECTION'
          USING ERRCODE = '55000';
      END IF;
      IF to_regprocedure('private.enqueue_collection_projection_correction_v3()') IS NULL
         OR to_regprocedure('public.switch_cell_active_lot_context(text,text,uuid,uuid,uuid,timestamptz,text)') IS NULL
         OR to_regprocedure('public.recalculate_cell_lot_state(uuid,text,text,uuid,uuid)') IS NULL
         OR to_regprocedure('public.refresh_collection_lot_state(uuid,uuid)') IS NULL
         OR NOT EXISTS (
           SELECT 1
           FROM pg_trigger trigger_row
           WHERE trigger_row.tgrelid = 'public.production_stage_readings'::regclass
             AND trigger_row.tgname = 'trg_collection_v3_projection_correction'
             AND trigger_row.tgenabled <> 'D'
             AND trigger_row.tgisinternal IS FALSE
         ) THEN
        RAISE EXCEPTION 'COLLECTION_V3_COMPATIBILITY_PROJECTION_NOT_READY'
          USING ERRCODE = '55000';
      END IF;
      IF NOT EXISTS (
        SELECT 1
        FROM vault.decrypted_secrets secret
        WHERE secret.name = 'acprod_collection_v3_projection_url'
          AND nullif(btrim(secret.decrypted_secret), '') IS NOT NULL
      ) THEN
        RAISE EXCEPTION 'COLLECTION_V3_PROJECTION_WAKEUP_NOT_READY'
          USING ERRCODE = '55000';
      END IF;
    END IF;

    IF v_flag_name = 'collection_pipeline_v3_broadcast' THEN
      IF NOT EXISTS (
        SELECT 1 FROM private.collection_pipeline_flags
        WHERE flag_name = 'collection_pipeline_v3_projection' AND enabled IS TRUE
      ) THEN
        RAISE EXCEPTION 'ENABLE_COLLECTION_V3_PROJECTION_BEFORE_BROADCAST'
          USING ERRCODE = '55000';
      END IF;
      IF NOT EXISTS (
         SELECT 1 FROM pg_policies policy
         WHERE policy.schemaname = 'realtime'
           AND policy.tablename = 'messages'
           AND policy.policyname IN (
             'collection_v3_device_broadcast_select',
             'collection_v3_cell_broadcast_select',
             'collection_v3_event_broadcast_select'
           )
         GROUP BY policy.schemaname, policy.tablename
         HAVING count(*) = 3
       ) THEN
        RAISE EXCEPTION 'COLLECTION_V3_BROADCAST_POLICIES_NOT_READY'
          USING ERRCODE = '55000';
      END IF;
    END IF;
  END IF;

  UPDATE private.collection_pipeline_flags
  SET enabled = coalesce(p_enabled, false),
      rollout_scope = v_scope,
      updated_at = clock_timestamp(),
      updated_by = auth.uid()
  WHERE flag_name = v_flag_name;

  RETURN public.get_collection_pipeline_flags_v3() -> v_flag_name;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_operator_session_context(p_session_token text, p_cell_id uuid, p_machine_id uuid, p_station_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
declare
  v_auth_user_id uuid := auth.uid();
  v_token_hash text := encode(extensions.digest(coalesce(p_session_token, ''), 'sha256'), 'hex');
  v_session public.operator_sessions%rowtype;
  v_cell_name text;
  v_machine_name text;
  v_has_explicit_machine_restriction boolean;
begin
  if v_auth_user_id is null then
    return jsonb_build_object('success', false, 'reason_code', 'AUTH_REQUIRED', 'error', 'Autenticacao do sistema expirada.');
  end if;

  select * into v_session
  from public.operator_sessions session_row
  where session_row.token_hash = v_token_hash
    and session_row.auth_user_id = v_auth_user_id
    and session_row.ended_at is null
    and session_row.revoked_at is null
    and session_row.expires_at > clock_timestamp()
  for update;

  if v_session.id is null then
    return jsonb_build_object('success', false, 'reason_code', 'SESSION_INVALID', 'error', 'Sessao invalida, expirada ou revogada.');
  end if;

  select cell.name into v_cell_name
  from public.cells cell
  join public.operator_cell_assignments assignment
    on assignment.cell_id = cell.id
   and assignment.operator_id = v_session.operator_id
   and assignment.active = true
   and assignment.valid_from <= clock_timestamp()
   and (assignment.valid_until is null or assignment.valid_until > clock_timestamp())
  where cell.id = p_cell_id and cell.active = true;

  if v_cell_name is null then
    return jsonb_build_object('success', false, 'reason_code', 'OPERATOR_UNAUTHORIZED', 'error', 'Celula nao vinculada a este operador.');
  end if;

  if p_machine_id is not null then
    select machine.name into v_machine_name
    from public.production_machines machine
    where machine.id = p_machine_id
      and machine.active = true
      and machine.allows_replacement = true
      and lower(btrim(machine.cell_name)) = lower(btrim(v_cell_name));

    if v_machine_name is null then
      return jsonb_build_object('success', false, 'reason_code', 'WRONG_MACHINE', 'error', 'Maquina inativa, nao habilitada ou fora da celula selecionada.');
    end if;

    select exists (
      select 1 from public.operator_machine_assignments assignment
      where assignment.operator_id = v_session.operator_id
        and assignment.active = true
        and assignment.valid_from <= clock_timestamp()
        and (assignment.valid_until is null or assignment.valid_until > clock_timestamp())
    ) into v_has_explicit_machine_restriction;

    if v_has_explicit_machine_restriction and not exists (
      select 1 from public.operator_machine_assignments assignment
      where assignment.operator_id = v_session.operator_id
        and assignment.machine_id = p_machine_id
        and assignment.active = true
        and assignment.valid_from <= clock_timestamp()
        and (assignment.valid_until is null or assignment.valid_until > clock_timestamp())
    ) then
      return jsonb_build_object('success', false, 'reason_code', 'OPERATOR_UNAUTHORIZED', 'error', 'Maquina nao vinculada a este operador.');
    end if;
  end if;

  update public.operator_sessions
  set cell_id = p_cell_id,
      machine_id = p_machine_id,
      cell_name_snapshot = v_cell_name,
      machine_name_snapshot = v_machine_name,
      station_name_snapshot = coalesce(nullif(btrim(p_station_name), ''), 'Posto de Reposicao'),
      last_seen_at = clock_timestamp()
  where id = v_session.id;

  insert into public.system_audit_logs (
    user_id, user_name, action, entity, entity_id, device_id, session_id, success, metadata
  )
  select v_auth_user_id, operator_row.name, 'operator_session_context_set', 'operator_sessions',
         v_session.id::text, v_session.device_id, v_session.id::text, true,
         jsonb_build_object(
           'operator_id', v_session.operator_id,
           'cell_id', p_cell_id,
           'cell_name', v_cell_name,
           'machine_id', p_machine_id,
           'machine_name', v_machine_name,
           'station_name', coalesce(nullif(btrim(p_station_name), ''), 'Posto de Reposicao'),
           'shift', v_session.shift_snapshot
         )
  from public.operators operator_row where operator_row.id = v_session.operator_id;

  return jsonb_build_object(
    'success', true,
    'cell_name', v_cell_name,
    'machine_name', v_machine_name
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.start_production_downtime_impl(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_reason_id uuid;
  v_reason_name text;
  v_reason_code text;
  v_cell_id uuid;
  v_cell_name text := p_payload->>'cell_name';
  v_machine_id uuid;
  v_operator_id uuid;
  v_operator_name text := p_payload->>'operator_name';
  v_shift text := COALESCE(p_payload->>'shift', '1');
  v_notes text := COALESCE(p_payload->>'notes', '');
  v_client_event_id uuid;
  v_existing_id uuid;
  v_occurrence_id uuid;
BEGIN
  IF p_payload->>'downtime_reason_id' IS NOT NULL AND p_payload->>'downtime_reason_id' != '' THEN
    BEGIN
      v_reason_id := (p_payload->>'downtime_reason_id')::uuid;
      SELECT name, code INTO v_reason_name, v_reason_code FROM public.downtime_reason_catalog WHERE id = v_reason_id;
    EXCEPTION WHEN OTHERS THEN
      v_reason_id := NULL;
    END;
  END IF;

  IF p_payload->>'cell_id' IS NOT NULL AND p_payload->>'cell_id' != '' THEN
    BEGIN v_cell_id := (p_payload->>'cell_id')::uuid; EXCEPTION WHEN OTHERS THEN v_cell_id := NULL; END;
  END IF;
  IF p_payload->>'machine_id' IS NOT NULL AND p_payload->>'machine_id' != '' THEN
    BEGIN v_machine_id := (p_payload->>'machine_id')::uuid; EXCEPTION WHEN OTHERS THEN v_machine_id := NULL; END;
  END IF;
  IF p_payload->>'operator_id' IS NOT NULL AND p_payload->>'operator_id' != '' THEN
    BEGIN v_operator_id := (p_payload->>'operator_id')::uuid; EXCEPTION WHEN OTHERS THEN v_operator_id := NULL; END;
  END IF;

  IF p_payload->>'client_event_id' IS NOT NULL AND p_payload->>'client_event_id' != '' THEN
    BEGIN
      v_client_event_id := (p_payload->>'client_event_id')::uuid;
      SELECT id INTO v_existing_id FROM public.occurrences WHERE client_event_id = v_client_event_id;
      IF v_existing_id IS NOT NULL THEN
        RETURN jsonb_build_object('success', true, 'idempotent', true, 'occurrence_id', v_existing_id);
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_client_event_id := NULL;
    END;
  END IF;

  -- Checar sobreposição de paradas abertas
  IF v_machine_id IS NOT NULL THEN
    SELECT id INTO v_existing_id FROM public.occurrences
    WHERE machine_id = v_machine_id AND status = 'open' AND occurrence_type = 'downtime';
    IF v_existing_id IS NOT NULL THEN
      RAISE EXCEPTION 'Já existe uma parada ativa para esta máquina (ID: %). Encerre a parada anterior primeiro.', v_existing_id;
    END IF;
  ELSIF v_cell_id IS NOT NULL THEN
    SELECT id INTO v_existing_id FROM public.occurrences
    WHERE cell_id = v_cell_id AND status = 'open' AND occurrence_type = 'downtime';
    IF v_existing_id IS NOT NULL THEN
      RAISE EXCEPTION 'Já existe uma parada ativa nesta célula (ID: %). Encerre a parada anterior primeiro.', v_existing_id;
    END IF;
  END IF;

  INSERT INTO public.occurrences (
    date, shift, cell, reason, downtime, operator, notes,
    created_by, severity, status, occurrence_type,
    downtime_reason_id, downtime_reason_code, started_at,
    cell_id, machine_id, operator_id, client_event_id
  ) VALUES (
    CURRENT_DATE, v_shift, COALESCE(v_cell_name, 'Geral'),
    COALESCE(v_reason_name, p_payload->>'reason', 'Parada Operacional'),
    0, v_operator_name, v_notes, v_user_id,
    'medium', 'open', 'downtime',
    v_reason_id, v_reason_code, now(),
    v_cell_id, v_machine_id, v_operator_id, v_client_event_id
  ) RETURNING id INTO v_occurrence_id;

  RETURN jsonb_build_object(
    'success', true,
    'occurrence_id', v_occurrence_id,
    'status', 'open',
    'started_at', now()
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.start_production_downtime(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
declare
  v_cell record;
  v_sanitized jsonb := coalesce(p_payload, '{}'::jsonb);
begin
  if coalesce(auth.role(), '') <> 'service_role' and not public.can_manage_occurrences() then
    raise exception 'OCCURRENCE_PERMISSION_REQUIRED' using errcode = '42501';
  end if;
  select * into v_cell from public.resolve_downtime_target_cell(v_sanitized);
  if coalesce(auth.role(), '') <> 'service_role' and not public.profile_can_access_cell(v_cell.cell_name) then
    raise exception 'OCCURRENCE_OUTSIDE_CELL_SCOPE' using errcode = '42501';
  end if;
  v_sanitized := jsonb_set(v_sanitized, '{cell_name}', to_jsonb(v_cell.cell_name), true);
  v_sanitized := jsonb_set(v_sanitized, '{cell_id}', to_jsonb(v_cell.cell_id::text), true);
  return public.start_production_downtime_impl(v_sanitized);
end;
$function$

CREATE OR REPLACE FUNCTION public.store_promob_token(integration_id uuid, token_text text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
DECLARE
  secret_id uuid;
  existing_ref text;
BEGIN
  -- Verificar se já existe uma referência
  SELECT token_reference INTO existing_ref FROM promob_integrations WHERE id = integration_id;

  IF existing_ref IS NOT NULL AND existing_ref <> '' THEN
    secret_id := existing_ref::uuid;
    -- Atualizar o segredo existente
    PERFORM vault.update_secret(secret_id, new_secret := token_text);
  ELSE
    -- Criar novo segredo no Vault
    secret_id := vault.create_secret(
      new_secret := token_text,
      new_name := 'promob_token_' || integration_id::text,
      new_description := 'Token da API Promob para integracao ' || integration_id::text
    );
    -- Atualizar a integração com a referência do segredo
    UPDATE promob_integrations SET token_reference = secret_id::text WHERE id = integration_id;
  END IF;

  RETURN secret_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_pcp_batch_progress_from_piece()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
    begin
      -- During PCP import a legacy piece is first created by the lot-item bridge
      -- and then attached to its import batch. The import RPC already performs
      -- one authoritative refresh after the chunk, so recalculating the entire
      -- batch once per initial assignment is redundant and quadratic.
      if old.pcp_import_batch_id is null
         and new.pcp_import_batch_id is not null then
        return new;
      end if;

      if old.pcp_import_batch_id is distinct from new.pcp_import_batch_id
         and old.pcp_import_batch_id is not null then
        perform public.refresh_pcp_batch_progress(old.pcp_import_batch_id);
      end if;

      if new.pcp_import_batch_id is not null then
        perform public.refresh_pcp_batch_progress(new.pcp_import_batch_id);
      end if;

      return new;
    end;
    $function$

CREATE OR REPLACE FUNCTION public.sync_production_lot_context()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
BEGIN
  NEW.production_order_id := COALESCE(NEW.production_order_id, NEW.order_id);
  NEW.order_id := COALESCE(NEW.order_id, NEW.production_order_id);
  NEW.current_step  := COALESCE(NULLIF(NEW.current_step, ''),  NULLIF(NEW.current_stage, ''), 'imported');
  NEW.current_stage := COALESCE(NULLIF(NEW.current_stage, ''), NEW.current_step);
  NEW.pending_quantity := GREATEST(COALESCE(NEW.planned_quantity, 0) - COALESCE(NEW.produced_quantity, 0), 0);
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_realtime_counter_from_production_entry()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_qty numeric;
BEGIN
  IF TG_OP IN ('UPDATE', 'DELETE') AND COALESCE(OLD.approval_status, 'valid') = 'valid' THEN
    v_qty := COALESCE(NULLIF(OLD.realized_quantity, 0), OLD.produced, 0);
    PERFORM public.adjust_production_realtime_counter(
      OLD.date, OLD.lot_id, OLD.lot_code, OLD.load_number, OLD.order_number,
      COALESCE(OLD.customer_name, OLD.customer_legal_name), OLD.environment_name,
      OLD.cell, OLD.machine_id, OLD.machine_name, OLD.metric_unit, OLD.metric_unit_label,
      0, -v_qty, 0, 0, 0
    );
  END IF;

  IF TG_OP IN ('INSERT', 'UPDATE') AND COALESCE(NEW.approval_status, 'valid') = 'valid' THEN
    v_qty := COALESCE(NULLIF(NEW.realized_quantity, 0), NEW.produced, 0);
    PERFORM public.adjust_production_realtime_counter(
      NEW.date, NEW.lot_id, NEW.lot_code, NEW.load_number, NEW.order_number,
      COALESCE(NEW.customer_name, NEW.customer_legal_name), NEW.environment_name,
      NEW.cell, NEW.machine_id, NEW.machine_name, NEW.metric_unit, NEW.metric_unit_label,
      0, v_qty, 0, 0, 0
    );
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_realtime_counter_from_stage_reading()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_unit text;
  v_label text;
  v_rejected numeric := 0;
  v_blocked numeric := 0;
  v_pending numeric := 0;
  v_qty numeric;
BEGIN
  IF TG_OP IN ('UPDATE', 'DELETE') AND OLD.status <> 'approved' THEN
    v_qty := GREATEST(COALESCE(OLD.quantity, 1), 1);
    v_unit := public.production_metric_unit_for_cell(OLD.cell_name, OLD.step_name, OLD.operation_name);
    v_label := public.production_metric_unit_label(v_unit);
    v_rejected := CASE WHEN OLD.status = 'rejected' THEN -v_qty ELSE 0 END;
    v_blocked := CASE WHEN OLD.status IN ('blocked', 'duplicated') THEN -v_qty ELSE 0 END;
    v_pending := CASE WHEN OLD.status = 'pending_review' THEN -v_qty ELSE 0 END;

    PERFORM public.adjust_production_realtime_counter(
      OLD.date, OLD.lot_id, OLD.lot_code, OLD.load_number, OLD.order_number,
      OLD.customer_name, OLD.environment_name, OLD.cell_name, OLD.machine_id, OLD.machine_name,
      v_unit, v_label, 0, 0, v_rejected, v_blocked, v_pending
    );
  END IF;

  IF TG_OP IN ('INSERT', 'UPDATE') AND NEW.status <> 'approved' THEN
    v_qty := GREATEST(COALESCE(NEW.quantity, 1), 1);
    v_unit := public.production_metric_unit_for_cell(NEW.cell_name, NEW.step_name, NEW.operation_name);
    v_label := public.production_metric_unit_label(v_unit);
    v_rejected := CASE WHEN NEW.status = 'rejected' THEN v_qty ELSE 0 END;
    v_blocked := CASE WHEN NEW.status IN ('blocked', 'duplicated') THEN v_qty ELSE 0 END;
    v_pending := CASE WHEN NEW.status = 'pending_review' THEN v_qty ELSE 0 END;

    PERFORM public.adjust_production_realtime_counter(
      NEW.date, NEW.lot_id, NEW.lot_code, NEW.load_number, NEW.order_number,
      NEW.customer_name, NEW.environment_name, NEW.cell_name, NEW.machine_id, NEW.machine_name,
      v_unit, v_label, 0, 0, v_rejected, v_blocked, v_pending
    );
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_replacement_trail_from_reading()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if tg_op = 'UPDATE' and old.piece_id is distinct from new.piece_id then
    perform public.reconcile_replacement_piece_trail(old.piece_id);
  end if;

  perform public.reconcile_replacement_piece_trail(
    case when tg_op = 'DELETE' then old.piece_id else new.piece_id end
  );
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_report_schedule_recipients()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
BEGIN
  -- 1. Remover destinatários antigos
  DELETE FROM public.report_schedule_recipients WHERE schedule_id = NEW.id;

  -- 2. Inserir profiles vinculados
  IF NEW.recipient_profile_ids IS NOT NULL AND array_length(NEW.recipient_profile_ids, 1) > 0 THEN
    FOR i IN 1..array_length(NEW.recipient_profile_ids, 1) LOOP
      DECLARE
        v_prof_id uuid := NEW.recipient_profile_ids[i]::uuid;
        v_email text;
      BEGIN
        SELECT email INTO v_email FROM public.profiles WHERE id = v_prof_id;
        IF v_email IS NOT NULL THEN
          INSERT INTO public.report_schedule_recipients (schedule_id, profile_id, recipient_name_snapshot, recipient_email_snapshot, active)
          VALUES (NEW.id, v_prof_id, v_email, v_email, true)
          ON CONFLICT DO NOTHING;
        END IF;
      EXCEPTION WHEN OTHERS THEN
        -- Ignorar erros de UUID/profile inválido
      END;
    END LOOP;
  END IF;

  -- 3. Inserir emails adicionais
  IF NEW.extra_emails IS NOT NULL AND array_length(NEW.extra_emails, 1) > 0 THEN
    FOR i IN 1..array_length(NEW.extra_emails, 1) LOOP
      DECLARE
        v_email text := TRIM(NEW.extra_emails[i]);
      BEGIN
        IF v_email IS NOT NULL AND v_email LIKE '%@%' THEN
          INSERT INTO public.report_schedule_recipients (schedule_id, external_email, recipient_name_snapshot, recipient_email_snapshot, active)
          VALUES (NEW.id, v_email, v_email, v_email, true)
          ON CONFLICT DO NOTHING;
        END IF;
      END;
    END LOOP;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_fn_populate_piece_route()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
DECLARE
  v_template_id uuid;
  v_steps text[];
BEGIN
  -- Só popula se route_steps estiver vazio
  IF NEW.route_steps IS NULL OR array_length(NEW.route_steps, 1) IS NULL THEN
    v_template_id := public.select_route_template_for_piece(NEW);

    SELECT array_agg(step_code ORDER BY sequence) INTO v_steps
    FROM public.route_template_steps
    WHERE route_template_id = v_template_id;

    NEW.route_template_id := v_template_id;
    NEW.route_steps := v_steps;
    NEW.current_stage := COALESCE(v_steps[1], 'created');
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_operators_credential_hash()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
BEGIN
  IF NEW.registration IS NOT NULL AND (TG_OP = 'INSERT' OR NEW.registration <> OLD.registration OR NEW.credential_hash IS NULL) THEN
    NEW.registration_normalized := TRIM(NEW.registration);
    NEW.credential_hash := crypt(NEW.registration_normalized, gen_salt('bf', 10));
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_production_lot_status_safely_impl(p_lot_id uuid, p_new_status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_lot record;
  v_allowed boolean := false;
BEGIN
  SELECT * INTO v_lot FROM public.production_lots WHERE id = p_lot_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Lote não localizado.');
  END IF;

  IF p_new_status = v_lot.status THEN
    RETURN jsonb_build_object('success', true, 'message', 'Status já atualizado.');
  END IF;

  -- Validar transições seguras
  IF p_new_status = 'in_progress' THEN
    v_allowed := true;
  ELSIF p_new_status = 'ready_to_pack' OR p_new_status = 'waiting_packaging' THEN
    v_allowed := true;
  ELSIF p_new_status = 'packed' OR p_new_status = 'waiting_shipping' THEN
    v_allowed := true;
  ELSIF p_new_status = 'shipped' THEN
    v_allowed := true; -- Validado na expedição
  ELSIF p_new_status = 'cancelled' THEN
    v_allowed := true;
  END IF;

  IF NOT v_allowed THEN
    RETURN jsonb_build_object('success', false, 'error', 'Transição de status inválida para ' || p_new_status);
  END IF;

  UPDATE public.production_lots
  SET status = p_new_status,
      updated_at = now()
  WHERE id = p_lot_id;

  -- Se for shipped, atualizar também o production_orders associado se todos os lotes dele estiverem shipped
  IF p_new_status = 'shipped' THEN
    UPDATE public.production_lots SET actual_end = now() WHERE id = p_lot_id;
    IF v_lot.production_order_id IS NOT NULL THEN
      IF NOT EXISTS (
        SELECT 1 FROM public.production_lots 
        WHERE production_order_id = v_lot.production_order_id AND status <> 'shipped'
      ) THEN
        UPDATE public.production_orders 
        SET status = 'shipped', finalization_date = now()::date 
        WHERE id = v_lot.production_order_id;
      END IF;
    END IF;
  END IF;

  RETURN jsonb_build_object('success', true, 'new_status', p_new_status);
END;
$function$

CREATE OR REPLACE FUNCTION public.update_production_lot_status_safely(p_lot_id uuid, p_new_status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_required_permission text;
  v_required_cell text;
begin
  if not exists (select 1 from public.production_lots where id = p_lot_id) then
    return jsonb_build_object('success', false, 'error', 'Lote não localizado.');
  end if;

  v_required_permission := case
    when p_new_status = 'shipped' then 'manage_shipping'
    when p_new_status in ('packed', 'waiting_shipping', 'waiting_packaging', 'ready_to_pack') then 'manage_packaging'
    when p_new_status = 'cancelled' then 'manage_pcp'
    else 'register_production'
  end;

  if auth.role() <> 'service_role'
     and not public.has_permission(v_required_permission) then
    raise exception 'LOT_STATUS_PERMISSION_REQUIRED:%', v_required_permission using errcode = '42501';
  end if;

  if p_new_status = 'shipped' then
    select name into v_required_cell
    from public.cells
    where active is true and lower(btrim(name)) like 'expedi%'
    order by name
    limit 1;
  elsif p_new_status in ('packed', 'waiting_shipping', 'waiting_packaging', 'ready_to_pack') then
    select name into v_required_cell
    from public.cells
    where active is true and lower(btrim(name)) like 'embalag%'
    order by name
    limit 1;
  end if;

  if auth.role() <> 'service_role'
     and v_required_cell is not null
     and not public.profile_can_access_cell(v_required_cell) then
    raise exception 'LOT_OUTSIDE_CELL_SCOPE' using errcode = '42501';
  end if;

  return public.update_production_lot_status_safely_impl(p_lot_id, p_new_status);
end;
$function$

